def _http_bucketed(*, slow_count: int = 0) -> bool:
    """Fast/slow HTTP queues when QUICKJOBS_HTTP_BUCKETED=1 or slow ATS sources are present."""
    raw = os.environ.get("QUICKJOBS_HTTP_BUCKETED", "").strip().lower()
    if raw in ("1", "true", "yes"):
        return True
    if raw in ("0", "false", "no"):
        return False
    return slow_count > 0


