def _coerce_positive_int(value: Any, default: int) -> int:
    """Normalize timeout/cap env or config values; tolerate numeric tuples from bad config."""
    if isinstance(value, bool):
        return max(1, int(default))
    if isinstance(value, int):
        return max(1, value)
    if isinstance(value, float):
        return max(1, int(value))
    if isinstance(value, (tuple, list)):
        nums = [_coerce_positive_int(item, 0) for item in value]
        nums = [n for n in nums if n > 0]
        return max(nums) if nums else max(1, int(default))
    if isinstance(value, str):
        raw = value.strip()
        if raw.isdigit():
            return max(1, int(raw))
    return max(1, int(default))


def _http_socket_timeout(read_timeout: int | None = None) -> float:
    """Socket timeout for urllib (connect + read share one cap on all supported Pythons)."""
    if read_timeout is None:
        return float(_http_read_timeout_sec())
    return float(_coerce_positive_int(read_timeout, _http_read_timeout_sec()))


