def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def pacific_local(moment: datetime) -> datetime:
    """Convert an aware (or naive-as-UTC) instant to America/Los_Angeles."""
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    try:
        from zoneinfo import ZoneInfo

        return moment.astimezone(ZoneInfo("America/Los_Angeles"))
    except Exception:
        return moment.astimezone()


def format_generated_stamp(when: datetime | None = None) -> str:
    """Footer timestamp in US Pacific (profile home) with zone abbreviation."""
    local = pacific_local(when or utc_now())
    tz = local.tzname() or "local"
    return f"{local.strftime('%m/%d/%y %H:%M:%S')} {tz}"


def format_digest_stamp(run_time: datetime) -> str:
    """Digest header time in US Pacific with zone abbreviation."""
    local = pacific_local(run_time)
    tz = local.tzname() or "local"
    return f"{local.strftime('%b %d, %Y %H:%M')} {tz}"


def format_progress_status_stamp(when: datetime | None = None) -> str:
    """Wall time on the scrape progress status line (MM/DD/YYYY HH:MM:SS)."""
    dt = when or datetime.now().astimezone()
    return dt.strftime("%m/%d/%Y %H:%M:%S")


def today_iso() -> str:
    return utc_now().strftime("%Y-%m-%d")


