@dataclass
class Job:
    title: str
    company_id: str
    url: str | None = None
    skip_verify: bool = False
    force_url_verify: bool = False
    loc: str = "remote"
    match: str = "good"
    salary: str = "ok"
    salary_label: str | None = None
    loc_label: str | None = None
    work_model: str | None = None
    meta: str = ""
    why: str = ""
    posted_ts: int = 0
    job_id: str = ""
    sort_key: int = 0
    layoff_prone: bool = False
    employment: str = "full-time"
    description_text: str = ""
    applied: bool = False
    pipeline_status: str = ""
    pipeline_at: str = ""
    pipeline_applied_at: str = ""
    is_new: bool = False
    is_updated: bool = False
    loc_verify: bool = False
    cover_letter: str | None = None
    company_name: str = ""
    company_logo_url: str = ""


@dataclass
class CompanyResult:
    id: str
    name: str
    label: str
    section: str
    jobs: list[Job] = field(default_factory=list)
    browse_url: str | None = None
    hub_url: str | None = None
    hub_note: str | None = None
    footer_links: list[dict[str, str]] = field(default_factory=list)
    subsection: str | None = None
    subsection_warn: bool = False
    search_note: str = ""
    layoff_prone: bool = False
    source_group: str = "company"
    h1b_grade: str = ""
    h1b_label: str = ""


def job_to_dict(job: Job) -> dict[str, Any]:
    return {field.name: getattr(job, field.name) for field in job.__dataclass_fields__.values()}


def job_from_dict(data: dict[str, Any]) -> Job:
    fields = Job.__dataclass_fields__
    return Job(**{key: data[key] for key in fields if key in data})


def company_result_to_dict(co: CompanyResult) -> dict[str, Any]:
    return {
        "id": co.id,
        "name": co.name,
        "label": co.label,
        "section": co.section,
        "jobs": [job_to_dict(job) for job in co.jobs],
        "browse_url": co.browse_url,
        "hub_url": co.hub_url,
        "hub_note": co.hub_note,
        "footer_links": co.footer_links,
        "subsection": co.subsection,
        "subsection_warn": co.subsection_warn,
        "search_note": co.search_note,
        "layoff_prone": co.layoff_prone,
        "source_group": co.source_group,
        "h1b_grade": co.h1b_grade,
        "h1b_label": co.h1b_label,
    }


def company_result_from_dict(data: dict[str, Any]) -> CompanyResult:
    jobs = [job_from_dict(row) for row in data.get("jobs") or [] if isinstance(row, dict)]
    return CompanyResult(
        id=str(data.get("id") or ""),
        name=str(data.get("name") or ""),
        label=str(data.get("label") or ""),
        section=str(data.get("section") or "matching"),
        jobs=jobs,
        browse_url=data.get("browse_url"),
        hub_url=data.get("hub_url"),
        hub_note=data.get("hub_note"),
        footer_links=list(data.get("footer_links") or []),
        subsection=data.get("subsection"),
        subsection_warn=bool(data.get("subsection_warn")),
        search_note=str(data.get("search_note") or ""),
        layoff_prone=bool(data.get("layoff_prone")),
        source_group=str(data.get("source_group") or "company"),
        h1b_grade=str(data.get("h1b_grade") or ""),
        h1b_label=str(data.get("h1b_label") or ""),
    )


def company_result_suspicious_zero_yield(co: CompanyResult) -> bool:
    """True when a scrape likely failed but the board still had postings (do not wipe jobs)."""
    if co.jobs:
        return False
    note = (co.search_note or "").lower()
    if "greenhouse api returned http" in note or "lever api returned http" in note:
        return True
    if "stall abort" in note:
        return True
    if "abandoned mid-scrape" in note or "links but 0 details" in note:
        return True
    match = re.search(r"board scan \((\d+) total,\s*0 parsed\)", note, re.I)
    if match and int(match.group(1)) > 0:
        return True
    # Apple-style / paginated browse: pages fetched but nothing parsed (likely breakage).
    match = re.search(r"\((\d+)\s+pages?,\s*0\s+roles?,\s*0\s+parsed\)", note, re.I)
    if match and int(match.group(1)) > 0:
        return True
    # Playwright multi-query scrape that never got details (stall/cache poison pattern).
    match = re.search(
        r"playwright \S+ \((\d+) queries?,\s*(\d+) details?,\s*(\d+) parsed\)",
        note,
        re.I,
    )
    if match and int(match.group(1)) > 0 and int(match.group(2)) == 0 and int(match.group(3)) == 0:
        return True
    return False


def company_result_expected_filter_zero_yield(co: CompanyResult) -> bool:
    """True when zero jobs is title/location/JD filters working, not a scrape failure."""
    if co.jobs:
        return False
    note = str(co.search_note or "")
    if company_result_suspicious_zero_yield(co) and re.search(
        r"\(skipped:\s*\d+\s+title", note, re.I
    ):
        return True
    if re.search(r"phenom \(\d+ queries, \d+ listed, 0 parsed\)", note, re.I):
        return True
    if re.search(r"oracle hcm \(\d+ queries, \d+ found, 0 parsed\)", note, re.I):
        return True
    return False


def _job_identity_key(company_id: str, job: Job) -> str:
    if job.job_id:
        return f"{company_id}:{job.job_id}"
    if job.url:
        return normalize_job_url(job.url)
    return f"{company_id}:{job.title}"


def build_prior_jobs_index(prior: dict[str, Any] | None) -> dict[str, Job]:
    """Index prior snapshot jobs that have description_text (for list-only merge)."""
    index: dict[str, Job] = {}
    if not prior:
        return index
    for row in prior.get("companies") or []:
        if not isinstance(row, dict) or not row.get("id"):
            continue
        co = company_result_from_dict(row)
        for job in co.jobs:
            if not (job.description_text or "").strip():
                continue
            index[_job_identity_key(co.id, job)] = job
    return index


def merge_prior_job_descriptions(
    results: list[CompanyResult],
    prior: dict[str, Any] | None,
) -> int:
    """Restore description_text from a prior snapshot for jobs missing JD text."""
    index = build_prior_jobs_index(prior)
    if not index:
        return 0
    merged = 0
    for co in results:
        for job in co.jobs:
            if (job.description_text or "").strip():
                continue
            prior_job = index.get(_job_identity_key(co.id, job))
            if prior_job and (prior_job.description_text or "").strip():
                job.description_text = prior_job.description_text
                merged += 1
    return merged


def greenhouse_list_only_scrape() -> bool:
    """True when Greenhouse board list is fetched without per-job JD content."""
    return not _env_flag("QUICKJOBS_GREENHOUSE_FETCH_CONTENT") and _env_flag(
        "QUICKJOBS_GREENHOUSE_LIST_ONLY", default="0"
    )


GREENHOUSE_DETAIL_OFFSETS_UI_KEY = "greenhouse_detail_offsets"
ASHBY_DETAIL_OFFSETS_UI_KEY = "ashby_detail_offsets"
APPLE_DETAIL_OFFSETS_UI_KEY = "apple_detail_offsets"
_DETAIL_ROTATION_UI_KEYS = (
    GREENHOUSE_DETAIL_OFFSETS_UI_KEY,
    ASHBY_DETAIL_OFFSETS_UI_KEY,
    APPLE_DETAIL_OFFSETS_UI_KEY,
)
_DETAIL_ROTATION_STORES: dict[str, dict[str, int]] = {}
_DETAIL_ROTATION_STORE_LOCK = threading.Lock()
_DETAIL_ROTATION_OUT_PATH: Path | None = None


def load_detail_rotation_offsets(out_path: Path, ui_key: str) -> dict[str, int]:
    doc = load_runtime_document(out_path)
    ui = doc.get("ui") or {}
    raw = ui.get(ui_key) or {}
    if not isinstance(raw, dict):
        return {}
    out: dict[str, int] = {}
    for key, val in raw.items():
        company_id = str(key).strip()
        if not company_id:
            continue
        try:
            out[company_id] = max(0, int(val))
        except (TypeError, ValueError):
            continue
    return out


def save_detail_rotation_offsets(
    out_path: Path, ui_key: str, offsets: dict[str, int]
) -> None:
    doc = load_runtime_document(out_path)
    ui = doc.get("ui")
    if not isinstance(ui, dict):
        ui = {}
    ui[ui_key] = {
        str(k): max(0, int(v)) for k, v in sorted(offsets.items()) if str(k).strip()
    }
    doc["ui"] = ui
    save_runtime_document(out_path, doc)


def init_detail_rotation_stores(out_path: Path) -> None:
    global _DETAIL_ROTATION_OUT_PATH
    _DETAIL_ROTATION_OUT_PATH = out_path
    with _DETAIL_ROTATION_STORE_LOCK:
        _DETAIL_ROTATION_STORES.clear()
        for ui_key in _DETAIL_ROTATION_UI_KEYS:
            _DETAIL_ROTATION_STORES[ui_key] = load_detail_rotation_offsets(
                out_path, ui_key
            )


def persist_detail_rotation_stores() -> None:
    out_path = _DETAIL_ROTATION_OUT_PATH
    if out_path is None:
        return
    with _DETAIL_ROTATION_STORE_LOCK:
        for ui_key, offsets in _DETAIL_ROTATION_STORES.items():
            save_detail_rotation_offsets(out_path, ui_key, dict(offsets))


def load_greenhouse_detail_offsets(out_path: Path) -> dict[str, int]:
    return load_detail_rotation_offsets(out_path, GREENHOUSE_DETAIL_OFFSETS_UI_KEY)


def save_greenhouse_detail_offsets(out_path: Path, offsets: dict[str, int]) -> None:
    save_detail_rotation_offsets(out_path, GREENHOUSE_DETAIL_OFFSETS_UI_KEY, offsets)


def init_greenhouse_detail_offset_store(out_path: Path) -> None:
    init_detail_rotation_stores(out_path)


def persist_greenhouse_detail_offset_store() -> None:
    persist_detail_rotation_stores()


def get_detail_rotation_offset(ui_key: str, company_id: str) -> int:
    with _DETAIL_ROTATION_STORE_LOCK:
        store = _DETAIL_ROTATION_STORES.setdefault(ui_key, {})
        return int(store.get(company_id, 0))


def advance_detail_rotation_offset(
    ui_key: str, company_id: str, survivor_count: int, detail_cap: int
) -> int:
    with _DETAIL_ROTATION_STORE_LOCK:
        store = _DETAIL_ROTATION_STORES.setdefault(ui_key, {})
        offset = int(store.get(company_id, 0))
        new_offset = (offset + detail_cap) % max(survivor_count, 1)
        store[company_id] = new_offset
        return new_offset


def get_greenhouse_detail_offset(company_id: str) -> int:
    return get_detail_rotation_offset(GREENHOUSE_DETAIL_OFFSETS_UI_KEY, company_id)


def advance_greenhouse_detail_offset(
    company_id: str, survivor_count: int, detail_cap: int
) -> int:
    return advance_detail_rotation_offset(
        GREENHOUSE_DETAIL_OFFSETS_UI_KEY, company_id, survivor_count, detail_cap
    )


def get_ashby_detail_offset(company_id: str) -> int:
    return get_detail_rotation_offset(ASHBY_DETAIL_OFFSETS_UI_KEY, company_id)


def advance_ashby_detail_offset(
    company_id: str, survivor_count: int, detail_cap: int
) -> int:
    return advance_detail_rotation_offset(
        ASHBY_DETAIL_OFFSETS_UI_KEY, company_id, survivor_count, detail_cap
    )


def get_apple_detail_offset(company_id: str) -> int:
    return get_detail_rotation_offset(APPLE_DETAIL_OFFSETS_UI_KEY, company_id)


def advance_apple_detail_offset(
    company_id: str, survivor_count: int, detail_cap: int
) -> int:
    return advance_detail_rotation_offset(
        APPLE_DETAIL_OFFSETS_UI_KEY, company_id, survivor_count, detail_cap
    )


def _greenhouse_detail_window_enabled() -> bool:
    """Rotating detail window for capped full Greenhouse scrapes (not global list-only)."""
    if greenhouse_list_only_scrape():
        return False
    return _greenhouse_fetch_job_content_enabled(in_watch=False)


def _greenhouse_detail_window_job_ids(
    survivors: list[tuple[dict[str, Any], bool]],
    *,
    company_id: str,
    detail_cap: int,
) -> tuple[set[int], int, int]:
    """Return job ids that receive detail fetch, current offset, and non-watch survivor count."""
    non_watch = sorted(
        (job for job, in_watch in survivors if not in_watch),
        key=lambda row: str(row.get("id") or ""),
    )
    detail_ids: set[int] = {job["id"] for job, in_watch in survivors if in_watch}
    if not _greenhouse_detail_window_enabled():
        return detail_ids, 0, len(non_watch)
    offset = get_greenhouse_detail_offset(company_id)
    if detail_cap > 0:
        for job in non_watch[offset : offset + detail_cap]:
            detail_ids.add(job["id"])
    return detail_ids, offset, len(non_watch)


def _ashby_detail_window_enabled(*, use_board_html: bool) -> bool:
    """Rotating detail window for capped Ashby posting-page HTML fetches."""
    if _ashby_max_detail_fetches() <= 0:
        return False
    if use_board_html:
        return True
    return _ashby_posting_html_salary_enabled(in_watch=False)


def _ashby_detail_window_posting_ids(
    survivors: list[tuple[dict[str, Any], bool]],
    *,
    company_id: str,
    detail_cap: int,
    use_board_html: bool,
) -> tuple[set[str], int, int]:
    """Return posting ids that receive posting-page HTML fetch, offset, non-watch count.

    When survivors fit in the cap, every non-watch id is included (Ashby list API
    omits pay; otherwise salary badges disappear after the offset advances).
    When over cap, the window wraps so rotation still covers the full set.
    """
    non_watch = sorted(
        (posting for posting, in_watch in survivors if not in_watch),
        key=lambda row: str(row.get("id") or ""),
    )
    detail_ids: set[str] = {
        str(posting.get("id") or "")
        for posting, in_watch in survivors
        if in_watch and str(posting.get("id") or "").strip()
    }
    if not _ashby_detail_window_enabled(use_board_html=use_board_html):
        for posting in non_watch:
            pid = str(posting.get("id") or "").strip()
            if pid:
                detail_ids.add(pid)
        return detail_ids, 0, len(non_watch)
    offset = get_ashby_detail_offset(company_id)
    n = len(non_watch)
    if detail_cap > 0 and n:
        if n <= detail_cap:
            window = non_watch
        else:
            start = offset % n
            window = [non_watch[(start + i) % n] for i in range(detail_cap)]
        for posting in window:
            pid = str(posting.get("id") or "").strip()
            if pid:
                detail_ids.add(pid)
    return detail_ids, offset, n


def _apple_detail_window_enabled() -> bool:
    return _apple_max_detail_fetches() > 0


def _apple_detail_window_urls(
    survivors: list[dict[str, str]],
    *,
    company_id: str,
    detail_cap: int,
) -> tuple[set[str], int, int]:
    """Return listing URLs that receive detail fetch, current offset, survivor count."""
    ordered = sorted(survivors, key=lambda row: str(row.get("url") or ""))
    detail_urls: set[str] = set()
    if not _apple_detail_window_enabled():
        for row in ordered:
            url = str(row.get("url") or "").strip()
            if url:
                detail_urls.add(url)
        return detail_urls, 0, len(ordered)
    offset = get_apple_detail_offset(company_id)
    if detail_cap > 0:
        for row in ordered[offset : offset + detail_cap]:
            url = str(row.get("url") or "").strip()
            if url:
                detail_urls.add(url)
    return detail_urls, offset, len(ordered)


def preserve_prior_jobs_if_empty_scrape(
    fresh: CompanyResult, prior: CompanyResult | None
) -> CompanyResult:
    """Keep prior ingested jobs when a re-run returns zero but the board was non-empty."""
    if not prior or not prior.jobs or not company_result_suspicious_zero_yield(fresh):
        return fresh
    kept = CompanyResult(
        id=prior.id,
        name=prior.name,
        label=prior.label,
        section=prior.section,
        jobs=list(prior.jobs),
        browse_url=prior.browse_url or fresh.browse_url,
        hub_url=prior.hub_url,
        hub_note=prior.hub_note,
        footer_links=list(prior.footer_links or fresh.footer_links),
        subsection=prior.subsection,
        subsection_warn=prior.subsection_warn,
        search_note=(
            f"{fresh.search_note} · kept {len(prior.jobs)} prior job(s) "
            "(latest scrape returned 0; likely rate limit or verify drop)"
        ),
        layoff_prone=prior.layoff_prone,
        source_group=prior.source_group or fresh.source_group,
    )
    print(
        f"preserve_prior_jobs: {fresh.id} kept {len(prior.jobs)} prior job(s) "
        f"({fresh.search_note})",
        file=sys.stderr,
    )
    sys.stderr.flush()
    return kept


def merge_company_results(
    snapshot: dict[str, Any] | None,
    fresh: list[CompanyResult],
    company_order: list[str],
    *,
    allowed_ids: set[str] | None = None,
) -> list[CompanyResult]:
    by_id: dict[str, CompanyResult] = {}
    if snapshot:
        for row in snapshot.get("companies") or []:
            if isinstance(row, dict) and row.get("id"):
                cid = str(row["id"])
                if allowed_ids is not None and cid not in allowed_ids:
                    continue
                by_id[cid] = company_result_from_dict(row)
    for co in fresh:
        by_id[co.id] = preserve_prior_jobs_if_empty_scrape(co, by_id.get(co.id))
    ordered: list[CompanyResult] = []
    seen: set[str] = set()
    for cid in company_order:
        if cid in by_id:
            ordered.append(by_id[cid])
            seen.add(cid)
    for cid, co in by_id.items():
        if cid not in seen:
            if allowed_ids is not None and cid not in allowed_ids:
                continue
            ordered.append(co)
    return ordered


def layoff_prone_ids(cfg: dict[str, Any]) -> set[str]:
    return {str(x) for x in (cfg.get("layoff_prone_company_ids") or [])}


def is_layoff_prone_company(company: dict[str, Any], cfg: dict[str, Any]) -> bool:
    if company.get("layoff_prone") is True:
        return True
    if company.get("layoff_prone") is False:
        return False
    return company["id"] in layoff_prone_ids(cfg)


def attach_company_flags(co: CompanyResult, company: dict[str, Any], cfg: dict[str, Any]) -> CompanyResult:
    co.layoff_prone = is_layoff_prone_company(company, cfg)
    group = str(company.get("source_group") or "").strip().lower()
    if group not in {"company", "job_sites", "recruiters"}:
        group = "company"
    co.source_group = group or "company"
    return co


_SALARY_PROVENANCE_SUFFIX_RE = re.compile(
    r"\s*[·•]\s*(?:DOL\s+LCA|est\.|Levels\.fyi|Levels\s+est\.)\s*$",
    re.I,
)


def salary_label_preserve_provenance(label: str, *, title: str = "") -> str:
    """Compact dollar range but keep estimation / DOL LCA provenance for tooltips."""
    raw = str(label or "").strip()
    if not raw:
        return ""
    prov = ""
    match = _SALARY_PROVENANCE_SUFFIX_RE.search(raw)
    if match:
        tail = match.group(0)
        if re.search(r"DOL\s+LCA", tail, re.I):
            prov = " · DOL LCA"
        else:
            # Crowd / Levels.fyi company reference — mark as estimation.
            prov = " · est."
        raw = raw[: match.start()].strip()
    compact = compact_salary_badge_label(raw, title=title)
    if not compact:
        return ""
    return f"{compact}{prov}"


def company_salary_label_for_title(company: dict[str, Any], title: str) -> str:
    """Resolve Levels.fyi / reference pay label from company config (not posting text)."""
    rules = company.get("company_salary_by_title")
    if isinstance(rules, list):
        title_lower = (title or "").lower()
        fallback = ""
        for rule in rules:
            if not isinstance(rule, dict):
                continue
            label = str(rule.get("label") or "").strip()
            if not label:
                continue
            needle = str(rule.get("contains") or "").strip().lower()
            if rule.get("default") or not needle:
                fallback = label
                continue
            if needle in title_lower:
                return salary_label_preserve_provenance(label, title=title)
        if fallback:
            return salary_label_preserve_provenance(fallback, title=title)
    label = str(company.get("company_salary_label") or "").strip()
    return salary_label_preserve_provenance(label, title=title) if label else ""


def apply_company_salary_reference(
    job: Job, company: dict[str, Any], cfg: dict[str, Any]
) -> None:
    """Fill salary badge from Levels.fyi/est. or DOL LCA when JD has no pay (US-workable only)."""
    if not job_us_salary_eligible(job):
        return
    if job.salary_label or job.salary == "low":
        return
    label = company_salary_label_for_title(company, job.title)
    if label:
        job.salary_label = label
        ref = company.get("company_salary")
        if ref in ("ok", "maybe", "low") and job.salary in (None, "maybe"):
            job.salary = str(ref)
        reconcile_job_salary_status(job, cfg)
        return
    apply_lca_salary_reference(job, company, cfg)


def apply_lca_salary_reference(
    job: Job, company: dict[str, Any], cfg: dict[str, Any]
) -> None:
    """Fill salary badge from public DOL LCA wage filings when the JD omits pay."""
    if _h1b_employer is None:
        return
    if not job_us_salary_eligible(job):
        return
    if job.salary_label or job.salary == "low":
        return
    name = str(
        company.get("name") or company.get("label") or job.company_name or ""
    ).strip()
    if not name:
        return
    try:
        hit = _h1b_employer.lookup_lca_salary_range(
            name,
            job.title or "",
            cache_root=h1b_cache_root(),
        )
    except Exception:
        return
    if not hit or not hit.get("label"):
        return
    job.salary_label = str(hit["label"])
    reconcile_job_salary_status(job, cfg)


def enrich_results_company_salary(
    results: list[CompanyResult],
    company_list: list[dict[str, Any]],
    cfg: dict[str, Any],
) -> None:
    by_id = {
        str(c.get("id") or ""): c
        for c in company_list
        if isinstance(c, dict) and c.get("id")
    }
    for co in results:
        company = by_id.get(co.id)
        if not company:
            company = {
                "id": co.id,
                "name": co.name or co.label,
                "label": co.label or co.name,
            }
        for job in co.jobs:
            apply_company_salary_reference(job, company, cfg)


def reconcile_results_salary_status(
    results: list[CompanyResult], cfg: dict[str, Any]
) -> None:
    for co in results:
        for job in co.jobs:
            reconcile_job_salary_status(job, cfg)


def enrich_results_h1b(
    results: list[CompanyResult],
    company_list: list[dict[str, Any]],
    cfg: dict[str, Any],
) -> None:
    if _h1b_employer is None or not _h1b_employer.profile_wants_h1b_validation(cfg):
        return
    by_id = {
        str(c.get("id") or ""): c
        for c in company_list
        if isinstance(c, dict) and c.get("id")
    }
    cache_root = h1b_cache_root()
    for co in results:
        company = by_id.get(co.id) or {}
        name = str(company.get("name") or co.name or co.id).strip()
        meta = _h1b_employer.lookup_company_h1b_meta(co.id, name, cache_root=cache_root)
        co.h1b_grade = str(meta.get("grade") or "")
        co.h1b_label = str(meta.get("label") or "")


def company_h1b_meta_from_result(co: CompanyResult) -> dict[str, Any]:
    grade = str(co.h1b_grade or "").strip().upper()
    return {"filer": grade in ("A", "B", "C", "D"), "grade": grade}


def _board_pipeline_config(
    cfg: dict[str, Any],
    *,
    pipeline_server: bool,
    default_runtime_path: Path,
) -> dict[str, Any]:
    """Pipeline autosave config plus optional profile text-filter presets."""
    out: dict[str, Any] = {
        "autosaveServer": pipeline_server,
        "runtimeFilePickerId": f"quickjobs-{BOARD_SUFFIX}-runtime",
        "defaultRuntimePath": str(default_runtime_path),
        # IndexedDB handle keys (one per file). Chrome picker id is shared below.
        "baseConfigFilePickerId": f"quickjobs-{BOARD_SUFFIX}-base-config",
        "profileConfigFilePickerId": f"quickjobs-{BOARD_SUFFIX}-profile-config",
        # Shared Chrome id defaults to the runtime picker id in JS so the dialog
        # opens in the same remembered folder as job-board-runtime / pipeline.
        "editConfigFilePickerId": f"quickjobs-{BOARD_SUFFIX}-runtime",
        "keywordLists": board_keyword_lists(cfg),
        "editConfigRoot": str(edit_config_root_for_board()),
    }
    base_path = resolve_base_config_path_for_board()
    if base_path:
        out["baseConfigPath"] = base_path
    profile_path = resolve_profile_config_path_for_board()
    if profile_path:
        out["profileConfigPath"] = profile_path
    out["profileFields"] = board_profile_fields(cfg)
    if _h1b_employer is None:
        return out
    resident_status = _h1b_employer.profile_resident_status(cfg)
    out["residentStatus"] = resident_status
    default_filters = _h1b_employer.profile_default_text_filters(cfg)
    if default_filters:
        out["defaultTextFilters"] = default_filters
        out["defaultFilterScope"] = _h1b_employer.profile_default_filter_scope(cfg)
        out["defaultTextFilterCombine"] = "and"
    return out


def salary_floor_value(cfg: dict[str, Any]) -> int:
    profile = cfg.get("profile", {})
    raw = profile.get("salary_floor", DEFAULT_SALARY_FLOOR) if isinstance(profile, dict) else DEFAULT_SALARY_FLOOR
    try:
        value = int(raw)
    except (TypeError, ValueError):
        value = DEFAULT_SALARY_FLOOR
    return max(value, 0)


def salary_floor_label(cfg: dict[str, Any]) -> str:
    floor = salary_floor_value(cfg)
    if floor and floor % 1000 == 0:
        return f"${floor // 1000:,}K"
    return f"${floor:,.0f}"


