def portland_metro_marker_in_text(text: str) -> bool:
    """True when text names a Portland-metro city/zip (word-safe; hillsboro ≠ hillsborough)."""
    lower = str(text or "").lower()
    if not lower:
        return False
    for marker in PORTLAND_METRO_COMMUTABLE_MARKERS:
        m = str(marker or "").strip().lower()
        if not m:
            continue
        if re.search(r"[,\s]", m):
            # Multi-token markers ("example city", "vancouver, wa"): flexible separators.
            pat = re.escape(m).replace(r"\ ", r"[\s,]+")
            if re.search(pat, lower):
                return True
            continue
        # Single token: whole word so "hillsboro" does not match "Hillsborough, NH".
        if re.search(rf"\b{re.escape(m)}\b", lower):
            return True
    return False


def _single_site_within_local_radius(site: str, cfg: dict[str, Any] | None = None) -> bool:
    """True when one city/state site plausibly lies within local_radius_miles of home_zip."""
    lower = str(site or "").lower().strip()
    if not lower:
        return False
    if "vancouver" in lower and ("wa" in lower or "washington" in lower):
        return True
    if any(marker in lower for marker in NON_COMMUTABLE_FROM_HOME_ZIP_MARKERS):
        return False
    if portland_metro_marker_in_text(lower):
        return True
    return False


def location_within_local_radius(location_name: str, cfg: dict[str, Any] | None = None) -> bool:
    """True when any work site in the location string is plausibly within local_radius_miles."""
    fragments = location_site_fragments(location_name)
    if len(fragments) >= 2:
        return any(_single_site_within_local_radius(fragment, cfg) for fragment in fragments)
    if fragments:
        return _single_site_within_local_radius(fragments[0], cfg)
    return False


def profile_home_state_name(cfg: dict[str, Any] | None = None) -> str:
    """Full US state name for profile home (e.g. Oregon for 00000)."""
    code = profile_home_us_state(cfg or {})
    return US_STATE_CODE_TO_NAME.get(code, code)


def profile_context(cfg: dict[str, Any]) -> dict[str, str]:
    p = cfg.get("profile", {})
    home_zip = str(p.get("home_zip", "00000"))
    radius = int(p.get("local_radius_miles", 50))
    local_badge = f"≤{radius} mi from {home_zip}"
    home_state = profile_home_us_state(cfg)
    home_state_name = profile_home_state_name(cfg)
    remote_from_home_label = f"Remote from {home_state_name}"
    floor = salary_floor_value(cfg)
    return {
        "home_zip": home_zip,
        "home_state": home_state,
        "home_state_name": home_state_name,
        "remote_from_home_label": remote_from_home_label,
        "local_radius_miles": str(radius),
        "local_radius": str(radius),
        "local_badge": local_badge,
        "salary_floor": str(floor),
        "salary_floor_label": salary_floor_label(cfg),
    }


def format_profile_text(text: str, ctx: dict[str, str]) -> str:
    if not text:
        return text
    out = text
    for key, value in ctx.items():
        out = out.replace("{" + key + "}", value)
    return out


def expand_profile_templates(obj: Any, ctx: dict[str, str]) -> Any:
    if isinstance(obj, str):
        return format_profile_text(obj, ctx)
    if isinstance(obj, list):
        return [expand_profile_templates(item, ctx) for item in obj]
    if isinstance(obj, dict):
        return {key: expand_profile_templates(value, ctx) for key, value in obj.items()}
    return obj


def deep_merge_config(base: Any, overlay: Any) -> Any:
    if isinstance(base, dict) and isinstance(overlay, dict):
        merged = {key: value for key, value in base.items()}
        for key, value in overlay.items():
            if key in merged:
                merged[key] = deep_merge_config(merged[key], value)
            else:
                merged[key] = value
        return merged
    return overlay


def read_json_config(path: Path) -> dict[str, Any]:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as err:
        raise RuntimeError(f"Invalid JSON config: {path}") from err
    if not isinstance(data, dict):
        raise RuntimeError(f"Config root must be an object: {path}")
    return data


def resolve_config_path(path: str | Path, *, label: str) -> Path:
    resolved = Path(path).expanduser()
    if not resolved.is_absolute():
        resolved = (SCRIPT_DIR / resolved).resolve()
    if not resolved.is_file():
        raise RuntimeError(f"{label} not found: {resolved}")
    return resolved


def expected_board_config_paths() -> tuple[Path, Path]:
    """Base and profile paths implied by this script's filename."""
    return quickjobs_base_config_path(), quickjobs_profile_config_path()


def validate_static_config(
    script_dir: Path | None = None,
    *,
    check_py: bool = True,
) -> list[str]:
    """Validate the static bundle (py + JSON) before rsync to remote. Empty list = ok."""
    import py_compile

    issues: list[str] = []
    root = (script_dir or SCRIPT_DIR).resolve()
    py_path = root / f"{QUICKJOBS_STEM}.py"
    base_path = quickjobs_base_config_path(script_dir=root)
    companies_path = quickjobs_companies_config_path(script_dir=root)
    profile_path = quickjobs_profile_config_path(script_dir=root)
    config_bundle_path = root / "scripts" / "_shared" / "config_bundle.py"
    optional_json = (
        companies_path,
        quickjobs_unconvertible_careers_path(script_dir=root),
        quickjobs_manual_career_meta_path(script_dir=root),
    )

    if check_py:
        if not py_path.is_file():
            issues.append(f"missing script: {py_path}")
        else:
            try:
                py_compile.compile(str(py_path), doraise=True)
            except py_compile.PyCompileError as err:
                issues.append(f"Python compile failed: {py_path}: {err}")
    if not config_bundle_path.is_file():
        issues.append(f"missing config bundle helper: {config_bundle_path}")
    elif check_py:
        try:
            py_compile.compile(str(config_bundle_path), doraise=True)
        except py_compile.PyCompileError as err:
            issues.append(f"Python compile failed: {config_bundle_path}: {err}")

    for label, path in (("base", base_path), ("profile", profile_path)):
        if not path.is_file():
            issues.append(f"missing {label} config: {path}")
            continue
        try:
            data = read_json_config(path)
        except RuntimeError as err:
            issues.append(str(err))
            continue
        if label == "base":
            tier1 = data.get("keywords_include_tier1")
            tier2 = data.get("keywords_include_tier2")
            if not isinstance(tier1, list) or not tier1:
                issues.append(f"{path}: keywords_include_tier1 must be a non-empty list")
            if not isinstance(tier2, list) or not tier2:
                issues.append(f"{path}: keywords_include_tier2 must be a non-empty list")
            if data.get("companies") is not None:
                issues.append(
                    f"{path}: companies must live in {companies_path.name}, not inline in base.json"
                )
        elif label == "profile":
            profile = data.get("profile")
            if not isinstance(profile, dict):
                issues.append(f"{path}: profile must be an object")
            else:
                if not str(profile.get("name") or "").strip():
                    issues.append(f"{path}: profile.name is required")
                if not str(profile.get("jobs_dir") or "").strip():
                    issues.append(f"{path}: profile.jobs_dir is required")

    if not companies_path.is_file():
        issues.append(f"missing companies config: {companies_path}")
    else:
        try:
            co_data = read_json_config(companies_path)
        except RuntimeError as err:
            issues.append(str(err))
        else:
            cb = _load_config_bundle_module()
            issues.extend(
                cb.validate_companies_list(
                    co_data.get("companies"),
                    path_label=str(companies_path),
                )
            )

    for path in optional_json:
        if path == companies_path:
            continue
        if not path.is_file():
            continue
        try:
            read_json_config(path)
        except RuntimeError as err:
            issues.append(str(err))

    return issues


def cmd_validate_static_config(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description="Validate quickjobs static config before sync.")
    parser.add_argument(
        "--dir",
        type=Path,
        default=SCRIPT_DIR,
        help="Directory containing quickjobs.<name>.py and JSON configs",
    )
    parser.add_argument("--no-py-compile", action="store_true", help="Skip py_compile check")
    parser.add_argument("-q", "--quiet", action="store_true")
    args = parser.parse_args(argv)
    issues = validate_static_config(args.dir, check_py=not args.no_py_compile)
    if issues:
        print("Static config validation failed:", file=sys.stderr)
        for issue in issues:
            print(f"  - {issue}", file=sys.stderr)
        return 1
    # Mac: keep picker-dir symlinks fresh so Link config opens beside runtime.
    linked = ensure_edit_config_picker_symlinks(edit_root=Path(args.dir))
    removed = remove_stale_edit_config_picker_symlinks(edit_root=Path(args.dir))
    if not args.quiet:
        print(f"Static config OK ({args.dir})")
        if linked:
            print(
                f"Edit-config picker symlinks: {len(linked)} under "
                f"{edit_config_picker_jobs_dir(Path(args.dir))}"
            )
        if removed:
            print(f"Removed stale picker symlinks: {len(removed)} under {edit_config_picker_dir()}")
    return 0


def _load_config_bundle_module():
    shared = SCRIPT_DIR / "scripts" / "_shared"
    shared_str = str(shared)
    if shared_str not in sys.path:
        sys.path.insert(0, shared_str)
    import config_bundle

    return config_bundle


def load_config_base() -> dict[str, Any]:
    """Shared sources/keywords/sections + companies — no personal profile or overrides."""
    base_env = os.environ.get("JOB_BOARD_BASE", "").strip()
    base_path = resolve_config_path(
        base_env or quickjobs_base_config_path(),
        label="Base config",
    )
    return _load_config_bundle_module().load_base_bundle(base_path)


def companies_config_path_for_base(base_path: Path) -> Path:
    return _load_config_bundle_module().companies_path_for_base(base_path)


def load_config_raw() -> dict[str, Any]:
    """Load config: monolithic JOB_BOARD_CONFIG, or base + profile + optional overlay."""
    external_path = os.environ.get("JOB_BOARD_CONFIG", "").strip()
    if external_path:
        external = resolve_config_path(external_path, label="Config")
        data = read_json_config(external)
    else:
        data = load_config_base()
        profile_env = os.environ.get("JOB_BOARD_PROFILE", "").strip()
        if profile_env.lower() in {"none", "false", "0", "-"}:
            profile_path: Path | None = None
        elif profile_env:
            profile_path = resolve_config_path(profile_env, label="Profile config")
        else:
            profile_path = quickjobs_profile_config_path()
            if not profile_path.is_file():
                base_path, prof_path = expected_board_config_paths()
                raise RuntimeError(
                    f"Profile config not found for {QUICKJOBS_STEM}.py: {prof_path}\n"
                    f"Expected pair:\n  {base_path}\n  {prof_path}"
                )
        if profile_path is not None:
            data = deep_merge_config(data, read_json_config(profile_path))
    overlay_path = os.environ.get("JOB_BOARD_CONFIG_OVERLAY", "").strip()
    if overlay_path:
        overlay_file = resolve_config_path(overlay_path, label="Overlay config")
        overlay = read_json_config(overlay_file) or {}
        if overlay:
            data = deep_merge_config(data, overlay)
    if not data.get("companies"):
        raise RuntimeError("Config is invalid or missing companies")
    if not data.get("unconvertible_careers"):
        try:
            import hub_tools

            hub_tools.ensure_manual_careers_migrated()
            for unc_path in hub_tools.manual_careers_load_paths():
                unc = read_json_config(unc_path) or {}
                if unc.get("employers"):
                    data["unconvertible_careers"] = unc
                    break
        except ImportError:
            unc_path = quickjobs_unconvertible_careers_path(
                quickjobs_namespace(),
                script_dir=SCRIPT_DIR,
            )
            if unc_path.is_file():
                unc = read_json_config(unc_path) or {}
                if unc.get("employers"):
                    data["unconvertible_careers"] = unc
    if not data.get("manual_career_meta"):
        meta_path = quickjobs_manual_career_meta_path(
            quickjobs_namespace(),
            script_dir=SCRIPT_DIR,
        )
        if meta_path.is_file():
            meta = read_json_config(meta_path) or {}
            if meta.get("employers"):
                data["manual_career_meta"] = meta
    return data


def load_config() -> dict[str, Any]:
    data = load_config_raw()
    profile = data.setdefault("profile", {})
    if not isinstance(profile, dict):
        raise RuntimeError("profile must be a mapping")
    ctx = profile_context(data)
    return expand_profile_templates(data, ctx)


