_RESUME_CERT_LINE_RE = re.compile(
    r"(?i)\b(?:"
    r"flight instructor|certified flight instructor|cfi|cfii|"
    r"commercial pilot(?:\s*:\s*asel)?|private pilot(?:\s*:\s*asel)?|"
    r"instrument rating(?:\s*:\s*asel)?|"
    r"advanced ground instructor|agi|instrument ground instructor|igi|"
    r"high performance endorsement|first class medical"
    r")\b"
)


def extract_resume_text(resume_path: Path) -> str:
    suffix = resume_path.suffix.lower()
    if suffix in {".txt", ".md", ".rst", ".log"}:
        return resume_path.read_text(encoding="utf-8", errors="ignore")
    if suffix == ".docx":
        with zipfile.ZipFile(resume_path) as zf:
            data = zf.read("word/document.xml").decode("utf-8", "ignore")
        text = re.sub(r"<[^>]+>", " ", data)
        return html.unescape(re.sub(r"\s+", " ", text)).strip()
    raise RuntimeError(
        "Unsupported resume format. Use .txt/.md/.docx (or convert PDF to text first)."
    )


def infer_skills_from_resume(resume_text: str) -> list[str]:
    lower = resume_text.lower()
    found: list[str] = []
    for skill in RESUME_SKILL_HINTS:
        if skill in lower and skill not in found:
            found.append(skill)
    for line in resume_text.splitlines():
        for match in _RESUME_CERT_LINE_RE.finditer(line):
            phrase = re.sub(r"\s+", " ", match.group(0).strip().lower())
            phrase = phrase.replace(": asel", "").strip()
            if phrase and phrase not in found:
                found.append(phrase)
    if "cfi:" in lower or re.search(r"\bcf[ií]\b", lower):
        if "cfi" not in found:
            found.append("cfi")
    return found[:40]


