def _resume_looks_aviation(lower: str, skills: list[str]) -> bool:
    hints = (
        "cfi",
        "cfii",
        "pilot",
        "aviation",
        "flight instructor",
        "certified flight instructor",
        "asel",
        "atp",
        "pic",
        "commercial pilot",
        "first officer",
        "airline pilot",
        "airline transport",
    )
    if any(h in lower for h in hints):
        return True
    return any(any(h in skill for h in hints) for skill in skills)


def profile_aviation_search(cfg: dict[str, Any]) -> bool:
    profile = cfg.get("profile") or {}
    if profile.get("aviation_search") in (True, "true", "yes", "1", 1):
        return True
    skills = [str(s).lower() for s in (profile.get("skills") or [])]
    return _resume_looks_aviation("", skills)


def filter_companies_for_profile(
    cfg: dict[str, Any], companies: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Aviation profiles scrape only sector=aviation employers (pilot/cargo/charter)."""
    if not profile_aviation_search(cfg):
        return companies
    return [c for c in companies if str(c.get("sector") or "").lower() == "aviation"]


def _skill_in_blob(skill: str, blob: str) -> bool:
    """Avoid false positives (e.g. agi inside engineering, pic inside topic)."""
    skill = str(skill or "").strip().lower()
    if not skill:
        return False
    if " " in skill or len(skill) >= 5:
        return skill in blob
    return bool(re.search(rf"\b{re.escape(skill)}\b", blob))


def _aviation_role_in_blob(blob: str) -> bool:
    return any(term in blob for term in AVIATION_ROLE_KEYWORDS) or any(
        phrase in blob
        for phrase in (
            "flight instructor",
            "certified flight instructor",
            "commercial pilot",
            "airline pilot",
            "cargo pilot",
            "corporate pilot",
        )
    )


def infer_keywords_from_resume(resume_text: str, base_cfg: dict[str, Any] | None = None) -> list[str]:
    """Role/search keywords inferred from resume (portable setup and profile overlay)."""
    _ = base_cfg
    lower = resume_text.lower()
    skills = infer_skills_from_resume(resume_text)
    found: list[str] = []
    patterns = (
        r"\b(devops|sre|platform engineer|infrastructure engineer|site reliability engineer|"
        r"cloud engineer|kubernetes|terraform|ci/cd|observability|data platform|"
        r"release engineer|build engineer|automation engineer|software engineer)\b",
        r"\b(flight instructor|certified flight instructor|cfi|cfii|chief flight instructor|"
        r"commercial pilot|private pilot|first officer|airline pilot|flight training|"
        r"ground instructor|flight school|aviation)\b",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, lower):
            phrase = re.sub(r"\s+", " ", match.group(1).strip())
            if phrase and phrase not in found:
                found.append(phrase)
    for skill in skills:
        if skill not in found:
            found.append(skill)
    if _resume_looks_aviation(lower, skills):
        for kw in AVIATION_ROLE_KEYWORDS:
            if kw not in found:
                found.insert(0, kw)
    return found[:28]


def generate_personalized_config(
    base_cfg: dict[str, Any],
    name: str,
    home_zip: str,
    resident_status: str,
    resume_text: str,
    jobs_dir: str | None = None,
) -> dict[str, Any]:
    cfg = json.loads(json.dumps(base_cfg))
    profile = cfg.setdefault("profile", {})
    profile["name"] = name
    profile["home_zip"] = str(home_zip)
    status = resident_status.lower().strip().replace("-", "_")
    if status in ("visa", "work_visa"):
        status = "h1b"
    profile["resident_status"] = status
    if jobs_dir:
        profile["jobs_dir"] = jobs_dir
    profile["skills"] = infer_skills_from_resume(resume_text)
    extra_kw = infer_keywords_from_resume(resume_text, base_cfg)
    if extra_kw:
        tier2 = [str(x).lower() for x in (cfg.get("keywords_include_tier2") or [])]
        for kw in extra_kw:
            lower = str(kw).strip().lower()
            if lower and lower not in tier2:
                tier2.append(lower)
        cfg["keywords_include_tier2"] = tier2
    return cfg


def _normalize_keyword_list(raw: Any) -> list[str]:
    return [str(x).strip().lower() for x in (raw or []) if str(x).strip()]


def cfg_keyword_excludes(cfg: dict[str, Any]) -> list[str]:
    exclude = _normalize_keyword_list(cfg.get("keywords_exclude"))
    profile = cfg.get("profile") or {}
    resident_status = str(profile.get("resident_status") or "citizen").strip().lower()
    status_excludes: dict[str, tuple[str, ...]] = {
        # H1B path: auto-filter postings that are citizenship-only, clearance-only,
        # or explicitly no-sponsorship.
        "h1b": (
            "security clearance",
            "active clearance",
            "secret clearance",
            "top secret",
            "u.s. citizenship",
            "us citizenship",
            "requires citizenship",
            "must be a us citizen",
            "must be authorized to work in the united states without sponsorship",
            "work authorization without sponsorship",
            "without sponsorship",
            "no visa sponsorship",
            "visa sponsorship is not available",
            "sponsorship is not available",
            "not eligible for sponsorship",
            "not eligible for visa sponsorship",
            "unable to sponsor",
            "will not sponsor",
        ),
        # Green-card and citizen holders do not require visa sponsorship,
        # so no auto-added sponsorship exclusions.
        "green_card": (),
        "citizen": (),
    }
    for term in status_excludes.get(resident_status, ()):
        lower = term.lower()
        if lower not in exclude:
            exclude.append(lower)
    return exclude


def cfg_title_tiers(cfg: dict[str, Any]) -> tuple[list[str], list[str], list[str]]:
    """Tier 1 = broad scrape/query terms; tier 2 = title-family phrases; tier 3 = match level unchanged."""
    tier1 = _normalize_keyword_list(cfg.get("keywords_include_tier1"))
    tier2 = _normalize_keyword_list(cfg.get("keywords_include_tier2"))
    if not tier1 or not tier2:
        legacy = _normalize_keyword_list(cfg.get("keywords_include"))
        if not tier1:
            tier1 = list(legacy)
        if not tier2:
            tier2 = list(legacy)
    return tier1, tier2, cfg_keyword_excludes(cfg)


def cfg_keywords(cfg: dict[str, Any]) -> tuple[list[str], list[str]]:
    """Tier-1 include list and exclude list (legacy name; used for ATS query terms)."""
    tier1, _, exclude = cfg_title_tiers(cfg)
    return tier1, exclude


def _company_uses_aviation_pilot_titles(company: dict[str, Any]) -> bool:
    if str(company.get("sector") or "").lower() != "aviation":
        return False
    company_kw = [
        str(q).strip().lower() for q in (company.get("search_keywords") or []) if str(q).strip()
    ]
    if not company_kw:
        return False
    return _aviation_role_in_blob(" ".join(company_kw))


def company_title_tiers(
    company: dict[str, Any], cfg: dict[str, Any]
) -> tuple[list[str], list[str], list[str]]:
    """Global tiers merged with per-company search_keywords on tier 1 (aviation employers)."""
    tier1, tier2, exclude = cfg_title_tiers(cfg)
    if profile_aviation_search(cfg) and str(company.get("sector") or "").lower() != "aviation":
        return tier1, tier2, exclude
    company_kw = [
        str(q).strip().lower() for q in (company.get("search_keywords") or []) if str(q).strip()
    ]
    if company_kw:
        tier1 = list(dict.fromkeys([*company_kw, *tier1]))
    if _company_uses_aviation_pilot_titles(company):
        tier1 = list(
            dict.fromkeys(
                [
                    *tier1,
                    "flight instructor",
                    "flight ops",
                    "flt ops",
                    "instructor pilot",
                    "instructor",
                    "flight qualified",
                    "technical pilot",
                ]
            )
        )
        tier2 = []
    return tier1, tier2, exclude


def company_keywords(
    company: dict[str, Any], cfg: dict[str, Any]
) -> tuple[list[str], list[str]]:
    """Profile/global tier-1 merged with per-company search_keywords (aviation employers)."""
    tier1, _, exclude = company_title_tiers(company, cfg)
    return tier1, exclude


def cfg_search_keywords_extra(cfg: dict[str, Any]) -> list[str]:
    """Board-wide ATS search terms appended for Distinguished / lead IC coverage."""
    return [
        str(q).strip()
        for q in (cfg.get("search_keywords_extra") or [])
        if str(q).strip()
    ]


def company_search_queries(company: dict[str, Any], cfg: dict[str, Any]) -> list[str]:
    """Search terms sent to ATS APIs (tier 1) — aviation profiles never use IT company defaults."""
    tier1, _, _ = cfg_title_tiers(cfg)
    if profile_aviation_search(cfg):
        if str(company.get("sector") or "").lower() == "aviation":
            company_kw = [
                str(q).strip() for q in (company.get("search_keywords") or []) if str(q).strip()
            ]
            if company_kw:
                return company_kw
        return [str(q).strip() for q in tier1 if str(q).strip()]
    base = [
        str(q).strip() for q in (company.get("search_keywords") or tier1) if str(q).strip()
    ]
    if company.get("skip_search_keywords_extra"):
        return base
    extra = cfg_search_keywords_extra(cfg)
    if not extra:
        return base
    # Prefer extras first so Workday/Greenhouse detail budgets cover IC titles.
    # Job-site aggregators (LinkedIn/Dice) cap queries tightly — put core profile
    # keywords first so remote/platform searches are not starved by extras alone.
    group = str(company.get("source_group") or "").strip().lower()
    ctype = str(company.get("type") or "").strip().lower()
    if group in {"job_sites", "recruiters"} or ctype in {
        "linkedin",
        "dice_mcp",
        "qualityinfo",
    }:
        return list(dict.fromkeys([*base, *extra]))
    return list(dict.fromkeys([*extra, *base]))


def cap_company_search_queries(
    company: dict[str, Any],
    cfg: dict[str, Any],
    *,
    max_queries_key: str,
    default: int = 4,
) -> list[str]:
    """Limit keyword searches per company (talentbrew_max_queries / oracle_max_queries / …)."""
    queries = company_search_queries(company, cfg)
    if not queries:
        return queries
    max_q = int(company.get(max_queries_key) or default)
    if max_q <= 0:
        return queries
    return queries[:max_q]


INTERNSHIP_TITLE_PATTERNS = (
    re.compile(r"\bintern(ship)?\b", re.I),
    re.compile(r"\bskillbridge\b", re.I),
    re.compile(r"\bco[\s-]?op\b", re.I),
)

SALES_TITLE_PATTERNS = (
    re.compile(r"\bsales\b", re.I),
    re.compile(r"\baccount executive\b", re.I),
    re.compile(r"\baccount manager\b", re.I),
    re.compile(r"\bbusiness development\b", re.I),
)


def title_is_internship_role(title: str) -> bool:
    return any(pattern.search(title or "") for pattern in INTERNSHIP_TITLE_PATTERNS)


def title_is_sales_role(title: str) -> bool:
    return any(pattern.search(title or "") for pattern in SALES_TITLE_PATTERNS)


def title_matches_tier1(title: str, tier1: list[str], exclude: list[str]) -> bool:
    if title_is_internship_role(title):
        return False
    if title_is_sales_role(title):
        return False
    if text_has_exclude(title, exclude):
        return False
    if not tier1:
        return True
    lower = (title or "").lower()
    return any(term in lower for term in tier1)


def title_matches_tier2(title: str, tier2: list[str]) -> bool:
    if not tier2:
        return True
    lower = (title or "").lower()
    return any(term in lower for term in tier2)


def title_matches_title_filters(
    title: str,
    cfg: dict[str, Any],
    *,
    company: dict[str, Any] | None = None,
    tier1: list[str] | None = None,
    tier2: list[str] | None = None,
    exclude: list[str] | None = None,
) -> bool:
    if tier1 is None or tier2 is None or exclude is None:
        if company is not None:
            resolved_t1, resolved_t2, resolved_ex = company_title_tiers(company, cfg)
        else:
            resolved_t1, resolved_t2, resolved_ex = cfg_title_tiers(cfg)
        tier1 = resolved_t1 if tier1 is None else tier1
        tier2 = resolved_t2 if tier2 is None else tier2
        exclude = resolved_ex if exclude is None else exclude
    return title_matches_tier1(title, tier1, exclude) and title_matches_tier2(title, tier2)


def _normalize_title_for_keyword_tiers(title: str) -> str:
    """Collapse common title variants so tier-2 substring checks match."""
    normalized = title or ""
    normalized = re.sub(r"\bdev[\s/-]+ops\b", "devops", normalized, flags=re.I)
    normalized = re.sub(
        r"\bsoftware\s+development\s+engineer\b", "software engineer", normalized, flags=re.I
    )
    normalized = re.sub(
        r"\bsoftware\s+dev\s+engineer\b", "software engineer", normalized, flags=re.I
    )
    return normalized


def title_filter_fail_reason(
    title: str,
    cfg: dict[str, Any],
    *,
    company: dict[str, Any] | None = None,
    tier1: list[str] | None = None,
    tier2: list[str] | None = None,
    exclude: list[str] | None = None,
) -> str | None:
    if title_is_internship_role(title):
        return "intern"
    if title_is_sales_role(title):
        return "sales"
    if tier1 is None or tier2 is None or exclude is None:
        if company is not None:
            resolved_t1, resolved_t2, resolved_ex = company_title_tiers(company, cfg)
        else:
            resolved_t1, resolved_t2, resolved_ex = cfg_title_tiers(cfg)
        tier1 = resolved_t1 if tier1 is None else tier1
        tier2 = resolved_t2 if tier2 is None else tier2
        exclude = resolved_ex if exclude is None else exclude
    if text_has_exclude(title, exclude):
        return "title_exclude"
    lower = _normalize_title_for_keyword_tiers(title).lower()
    if tier1 and not any(term in lower for term in tier1):
        return "title_tier1"
    if tier2 and not any(term in lower for term in tier2):
        return "title_tier2"
    return None


def posting_filter_fail_reason(
    title: str,
    description_text: str,
    cfg: dict[str, Any],
    *,
    company: dict[str, Any] | None = None,
) -> str | None:
    """Title-tier / exclude failures; sales/commission JD language also drops."""
    reason = title_filter_fail_reason(title, cfg, company=company)
    if reason:
        return reason
    if sales_commission_jd_hit(description_text, title):
        return "sales"
    return None


def clear_filter_rejects() -> None:
    with _FILTER_REJECT_LOCK:
        FILTER_REJECT_COUNTS.clear()
        FILTER_REJECTS.clear()
        _FILTER_REJECT_BY_REASON.clear()
        _FILTER_REJECT_LINKEDIN_SAMPLES.clear()


def _filter_reject_entry_key(entry: dict[str, str]) -> tuple[str, str, str, str]:
    return (
        entry.get("reason") or "",
        entry.get("company") or "",
        entry.get("title") or "",
        entry.get("url") or "",
    )


def _filter_reject_log_entries() -> list[dict[str, str]]:
    """Merged per-reason samples plus reserved LinkedIn rows for the filtered log file."""
    with _FILTER_REJECT_LOCK:
        by_reason = {k: list(v) for k, v in _FILTER_REJECT_BY_REASON.items()}
        linkedin = list(_FILTER_REJECT_LINKEDIN_SAMPLES)
    entries: list[dict[str, str]] = []
    seen: set[tuple[str, str, str, str]] = set()
    for reason in sorted(by_reason):
        for entry in by_reason[reason]:
            key = _filter_reject_entry_key(entry)
            if key in seen:
                continue
            seen.add(key)
            entries.append(entry)
    for entry in linkedin:
        key = _filter_reject_entry_key(entry)
        if key in seen:
            continue
        seen.add(key)
        entries.append(entry)
    return entries


def record_filter_reject(
    company_id: str,
    title: str,
    url: str | None,
    reason: str,
    *,
    detail: str = "",
) -> None:
    entry = {
        "company": str(company_id or "").strip(),
        "title": str(title or "").strip(),
        "url": str(url or "").strip(),
        "reason": str(reason or "unknown").strip(),
        "detail": str(detail or "").strip(),
    }
    with _FILTER_REJECT_LOCK:
        FILTER_REJECT_COUNTS[entry["reason"]] = FILTER_REJECT_COUNTS.get(entry["reason"], 0) + 1
        is_linkedin = entry["company"] == "linkedin" or "linkedin.com" in entry["url"]
        if is_linkedin and len(_FILTER_REJECT_LINKEDIN_SAMPLES) < FILTER_REJECT_LINKEDIN_SAMPLE_CAP:
            _FILTER_REJECT_LINKEDIN_SAMPLES.append(dict(entry))
        bucket = _FILTER_REJECT_BY_REASON.setdefault(entry["reason"], [])
        if len(bucket) < FILTER_REJECT_SAMPLE_MAX_PER_REASON:
            bucket.append(dict(entry))
        # Summary helpers still read FILTER_REJECTS (first N per reason in encounter order).
        if len(FILTER_REJECTS) < FILTER_REJECT_SAMPLE_MAX_PER_REASON * max(len(FILTER_REASON_LABELS), 8):
            FILTER_REJECTS.append(dict(entry))


def record_jd_filter_reject(
    company_id: str,
    title: str,
    skip_detail: str,
    *,
    url: str | None = None,
) -> None:
    detail = str(skip_detail or "").strip()
    lower = detail.lower()
    if "h1b" in lower or "h-1b" in lower or "visa sponsorship" in lower:
        reason = "h1b"
    elif "sales/commission" in lower:
        reason = "sales"
    elif "india" in lower:
        reason = "location_india"
    elif "malformed" in lower and "url" in lower:
        reason = "malformed_url"
    elif "non_us" in lower or "non-us" in lower or "non us" in lower:
        reason = "location_non_us"
    else:
        reason = "jd_block"
    record_filter_reject(company_id, title, url, reason, detail=detail)
    RUN_METRICS["skipped_jd"].append(f"{title} ({skip_detail})")


def title_rejected_by_scrape_filters(
    title: str,
    cfg: dict[str, Any],
    company: dict[str, Any],
    *,
    url: str | None = None,
) -> bool:
    """Return True when the posting should be skipped (reject recorded)."""
    cid = str(company.get("id") or "")
    if not str(title or "").strip():
        return True
    reason = title_filter_fail_reason(title, cfg, company=company)
    if reason:
        record_filter_reject(cid, title, url, reason)
        return True
    return False


def filter_reject_summary_lines() -> list[str]:
    with _FILTER_REJECT_LOCK:
        counts = dict(FILTER_REJECT_COUNTS)
        samples = list(FILTER_REJECTS)
    if not counts:
        return []
    total = sum(counts.values())
    lines = [f"  Scrape filters: {total} posting(s) dropped"]
    title_total = sum(
        counts.get(k, 0) for k in ("intern", "sales", "title_exclude", "title_tier1", "title_tier2")
    )
    if title_total:
        parts = []
        for key in ("title_tier1", "title_tier2", "title_exclude", "intern", "sales"):
            n = counts.get(key, 0)
            if n:
                parts.append(f"{key}: {n}")
        lines.append(f"  Title filter: {title_total} ({', '.join(parts)})")
    for key in (
        "location",
        "location_india",
        "location_non_us",
        "description_exclude",
        "jd_block",
        "h1b",
        "malformed_url",
    ):
        n = counts.get(key, 0)
        if n:
            label = FILTER_REASON_LABELS.get(key, key)
            lines.append(f"  {label}: {n}")
    shown: dict[str, int] = {}
    sample_lines: list[str] = []
    for entry in samples:
        reason = entry["reason"]
        if shown.get(reason, 0) >= FILTER_REJECT_SAMPLE_PER_REASON:
            continue
        shown[reason] = shown.get(reason, 0) + 1
        who = entry["company"] or "?"
        log_tag = FILTER_REASON_LOG_TAGS.get(reason, reason)
        sample_lines.append(f"    [{log_tag}] {who}: {entry['title']}")
    if sample_lines:
        lines.append("  Examples:")
        lines.extend(sample_lines)
    return lines


def print_filter_reject_summary() -> None:
    lines = filter_reject_summary_lines()
    if not lines:
        return
    width = 56
    print("─" * width)
    for line in lines:
        print(line)
    print(f"  Full list: {FILTERED_LOG}")
    print("─" * width)
    sys.stdout.flush()


def _run_step(message: str, *, quiet: bool = False) -> None:
    if not quiet:
        print(message, flush=True)


def structure_validation_sample_size() -> int:
    """Max job cards to badge-check after publish; 0 = all (QUICKJOBS_VALIDATE_STRUCTURE_SAMPLE)."""
    raw = os.environ.get("QUICKJOBS_VALIDATE_STRUCTURE_SAMPLE", "").strip()
    if not raw:
        return DEFAULT_STRUCTURE_VALIDATION_SAMPLE
    try:
        return max(0, int(raw))
    except ValueError:
        return DEFAULT_STRUCTURE_VALIDATION_SAMPLE


def _sample_validation_articles(bodies: list[str], max_samples: int) -> list[str]:
    if max_samples <= 0 or len(bodies) <= max_samples:
        return bodies
    total = len(bodies)
    stride = max(1, total // max_samples)
    indices = list(range(0, total, stride))[:max_samples]
    if (total - 1) not in indices:
        indices[-1] = total - 1
    return [bodies[i] for i in sorted(set(indices))[:max_samples]]


def write_filter_reject_log(run_time: datetime, *, quiet: bool = False) -> int:
    # _filter_reject_log_entries() takes _FILTER_REJECT_LOCK; do not nest that lock here.
    entries = _filter_reject_log_entries()
    with _FILTER_REJECT_LOCK:
        counts = dict(FILTER_REJECT_COUNTS)
    if not entries and not counts:
        return 0
    FILTERED_LOG.parent.mkdir(parents=True, exist_ok=True)
    lines = [f"--- {run_time.isoformat()} ---"]
    if counts:
        count_parts = ", ".join(f"{k}={v}" for k, v in sorted(counts.items()))
        lines.append(f"# counts: {count_parts}")
    for entry in entries:
        parts = [entry["reason"], entry["company"], entry["title"]]
        if entry.get("url"):
            parts.append(entry["url"])
        if entry.get("detail"):
            parts.append(f"({entry['detail']})")
        lines.append("\t".join(parts))
    FILTERED_LOG.write_text("\n".join(lines) + "\n", encoding="utf-8")
    total_rejects = sum(counts.values())
    _run_step(
        f"Wrote filtered log ({len(entries)} samples, {total_rejects} total rejects) → {FILTERED_LOG}",
        quiet=quiet,
    )
    return len(entries)


def title_matches_keywords(title: str, include: list[str], exclude: list[str]) -> bool:
    """Deprecated single-list helper; prefer title_matches_title_filters with cfg."""
    return title_matches_tier1(title, include, exclude)


def posting_matches_title_filters(
    title: str,
    description_text: str,
    cfg: dict[str, Any],
    *,
    company: dict[str, Any] | None = None,
    tier1: list[str] | None = None,
    tier2: list[str] | None = None,
    exclude: list[str] | None = None,
) -> bool:
    """Title tiers only — keywords_exclude is not applied to JD collaborator text."""
    _ = description_text  # kept for call-site compatibility
    return title_matches_title_filters(
        title, cfg, company=company, tier1=tier1, tier2=tier2, exclude=exclude
    )


def posting_matches_keywords(title: str, description_text: str, include: list[str], exclude: list[str]) -> bool:
    """Deprecated; tier filters and keywords_exclude are title-only."""
    _ = description_text
    if title_is_internship_role(title):
        return False
    if title_is_sales_role(title):
        return False
    return title_matches_tier1(title, include, exclude)


def html_to_plain(text: str) -> str:
    if not text:
        return ""
    cleaned = html.unescape(text)
    cleaned = re.sub(r"(?is)<(script|style|noscript)[^>]*>.*?</\1>", " ", cleaned)
    cleaned = re.sub(r"(?is)<br\s*/?>", "\n", cleaned)
    cleaned = re.sub(r"(?is)</p>", "\n", cleaned)
    cleaned = re.sub(r"<[^>]+>", " ", cleaned)
    return re.sub(r"\s+", " ", cleaned).strip()


def profile_domain_years_map(cfg: dict[str, Any]) -> tuple[dict[str, float], float]:
    profile = cfg.get("profile") or {}
    default = float(profile.get("default_domain_years", 0))
    raw = profile.get("domain_years") or {}
    mapping = {str(k).lower(): float(v) for k, v in raw.items()}
    return mapping, default


def normalize_domain_phrase(phrase: str) -> str:
    cleaned = re.sub(r"\s+", " ", phrase.lower().strip(" .;,"))
    cleaned = re.sub(r"^(?:the|a|an)\s+", "", cleaned)
    return cleaned


def years_for_domain_phrase(phrase: str, domain_map: dict[str, float], default: float) -> float:
    normalized = normalize_domain_phrase(phrase)
    if normalized in domain_map:
        return domain_map[normalized]
    best_key = ""
    best_val: float | None = None
    for key, val in domain_map.items():
        if key in normalized or normalized in key:
            if len(key) > len(best_key):
                best_key = key
                best_val = val
    return best_val if best_val is not None else default


def parse_domain_year_requirements(text: str) -> list[tuple[int, str]]:
    if not text:
        return []
    seen: set[tuple[int, str]] = set()
    found: list[tuple[int, str]] = []
    for pattern in DOMAIN_YEARS_PATTERNS:
        for match in pattern.finditer(text):
            years = int(match.group(1))
            domain = normalize_domain_phrase(match.group(2))
            if not domain or years <= 0:
                continue
            key = (years, domain)
            if key in seen:
                continue
            seen.add(key)
            found.append(key)
    return found


def downgrade_match(match: str, steps: int) -> str:
    if steps <= 0:
        return match
    try:
        idx = MATCH_ORDER.index(match)
    except ValueError:
        idx = 1
    return MATCH_ORDER[min(idx + steps, len(MATCH_ORDER) - 1)]


def apply_domain_years_to_match(
    match: str, description_text: str, cfg: dict[str, Any]
) -> tuple[str, str | None]:
    """Down-rate match when the JD names N+ years in a domain you haven't logged."""
    domain_map, default = profile_domain_years_map(cfg)
    gaps: list[str] = []
    for required_years, domain_phrase in parse_domain_year_requirements(description_text):
        have = years_for_domain_phrase(domain_phrase, domain_map, default)
        if have + 1e-9 < required_years:
            have_label = str(int(have)) if float(have).is_integer() else f"{have:g}"
            gaps.append(f"needs {required_years}+ yrs in {domain_phrase} (you: {have_label})")
    if not gaps:
        return match, None
    new_match = downgrade_match(match, len(gaps))
    note = "Downrated (domain years): " + "; ".join(gaps) + "."
    return new_match, note


def _ascii_safe_url(url: str) -> str:
    """Percent-encode non-ASCII so urllib.request can open the URL (IRI paths, e.g. Café in slug)."""
    text = str(url or "").strip()
    if not text:
        return text
    try:
        text.encode("ascii")
        return text
    except UnicodeEncodeError:
        pass
    parts = urllib.parse.urlsplit(text)
    if not parts.scheme or not parts.netloc:
        return text
    path = urllib.parse.quote(parts.path, safe="/%:@&+$,;=-._~", encoding="utf-8")
    query = (
        urllib.parse.quote(parts.query, safe="/%:@&+$,;=-._~&=", encoding="utf-8")
        if parts.query
        else ""
    )
    fragment = (
        urllib.parse.quote(parts.fragment, safe="/%:@&+$,;=-._~", encoding="utf-8")
        if parts.fragment
        else ""
    )
    return urllib.parse.urlunsplit((parts.scheme, parts.netloc, path, query, fragment))


def _http_request_add_close(req: urllib.request.Request) -> None:
    if not req.has_header("Connection"):
        req.add_unredirected_header("Connection", "close")


def _http_fresh_opener(context: ssl.SSLContext | None = None) -> urllib.request.OpenerDirector:
    """Per-request opener so urllib's process-wide connection cache cannot leak CLOSE-WAIT."""
    handlers: list[urllib.request.BaseHandler] = [urllib.request.HTTPHandler()]
    if context is not None:
        handlers.insert(0, urllib.request.HTTPSHandler(context=context))
    else:
        handlers.insert(0, urllib.request.HTTPSHandler())
    return urllib.request.build_opener(*handlers)


def _http_read_body(
    raw: bytes,
    headers: Any,
    *,
    gzip_decode: bool = False,
) -> bytes:
    if gzip_decode and (headers.get("Content-Encoding") or "").lower() == "gzip" and raw:
        try:
            import gzip as gzip_mod

            return gzip_mod.decompress(raw)
        except OSError:
            pass
    return raw


def _http_fetch_should_stop() -> bool:
    """True when the active company fetch was abandoned or stall-aborted."""
    cid = _current_fetch_company_id()
    if not cid:
        return False
    if _company_fetch_abandoned(cid):
        return True
    return _company_stall_abort_requested(cid)


def _http_semaphore_acquire(*, max_wait: float) -> bool:
    """Acquire the global HTTP slot with short polls so abandon/stall can unblock waits."""
    deadline = time.monotonic() + max(0.5, max_wait)
    while time.monotonic() < deadline:
        if _http_fetch_should_stop():
            return False
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        if _HTTP_SEMAPHORE.acquire(timeout=min(0.5, max(0.05, remaining))):
            return True
    return False


def _http_urlopen_read(
    req: urllib.request.Request,
    *,
    timeout: int | None = None,
    context: ssl.SSLContext | None = None,
    max_bytes: int | None = None,
    gzip_decode: bool = False,
    fallback_url: str = "",
) -> tuple[int, str, bytes]:
    """Semaphore-guarded GET/POST: Connection close, full body read, fresh opener, socket closed."""
    read_timeout = (
        _http_read_timeout_sec()
        if timeout is None
        else _coerce_positive_int(timeout, _http_read_timeout_sec())
    )
    socket_timeout = _http_socket_timeout(read_timeout)
    connect_sec = _http_connect_timeout_sec()
    if _http_fetch_should_stop():
        return 599, fallback_url or req.get_full_url(), b""
    _http_request_add_close(req)
    sem_wait = max(5, connect_sec + read_timeout + 15)
    if not _http_semaphore_acquire(max_wait=float(sem_wait)):
        return 599, fallback_url or req.get_full_url(), b""
    try:
        if _http_fetch_should_stop():
            return 599, fallback_url or req.get_full_url(), b""
        opener = _http_fresh_opener(context)
        open_kw: dict[str, Any] = {"timeout": socket_timeout}
        try:
            with opener.open(req, **open_kw) as resp:
                read_cap = None if max_bytes is None else max_bytes + 1
                raw = resp.read(read_cap)
                if max_bytes is not None and len(raw) > max_bytes:
                    raw = raw[:max_bytes]
                raw = _http_read_body(raw, resp.headers, gzip_decode=gzip_decode)
                return resp.getcode(), resp.geturl(), raw
        except urllib.error.HTTPError as err:
            read_cap = None if max_bytes is None else max_bytes + 1
            raw = err.read(read_cap) if err.fp else b""
            if max_bytes is not None and len(raw) > max_bytes:
                raw = raw[:max_bytes]
            raw = _http_read_body(raw, err.headers, gzip_decode=gzip_decode)
            final_url = err.geturl() if hasattr(err, "geturl") else fallback_url
            return err.code, final_url or fallback_url, raw
    finally:
        _HTTP_SEMAPHORE.release()


def http_get(url: str, timeout: int | None = None) -> tuple[int, str, str]:
    url = _ascii_safe_url(url)
    ctx = ssl.create_default_context()
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": USER_AGENT,
            "Accept": "application/rss+xml, application/atom+xml, application/xml, application/json, */*",
            "Accept-Encoding": "gzip",
            **_HTTP_CLOSE_HEADERS,
        },
    )
    try:
        code, final_url, raw = _http_urlopen_read(
            req, timeout=timeout, context=ctx, gzip_decode=True, fallback_url=url
        )
        return code, final_url, raw.decode("utf-8", "replace")
    except (urllib.error.URLError, TimeoutError, OSError):
        return 599, url, ""


def http_post_json(
    url: str,
    payload: dict[str, Any],
    timeout: int | None = None,
    headers: dict[str, str] | None = None,
) -> tuple[int, str, str]:
    data = json.dumps(payload).encode("utf-8")
    req_headers = {
        "User-Agent": USER_AGENT,
        "Accept": "application/json",
        "Content-Type": "application/json",
        **_HTTP_CLOSE_HEADERS,
    }
    if headers:
        req_headers.update(headers)
    req = urllib.request.Request(
        url,
        data=data,
        method="POST",
        headers=req_headers,
    )
    try:
        code, final_url, raw = _http_urlopen_read(req, timeout=timeout, fallback_url=url)
        return code, final_url, raw.decode("utf-8", "replace")
    except urllib.error.HTTPError as err:
        body = (err.read(8000) if err.fp else b"").decode("utf-8", "replace")
        return err.code, url, body
    except (urllib.error.URLError, TimeoutError, OSError):
        return 599, url, ""


def http_post_form(
    url: str,
    fields: dict[str, str],
    timeout: int | None = None,
    headers: dict[str, str] | None = None,
) -> tuple[int, str, str]:
    """POST application/x-www-form-urlencoded (Avature SearchJobs, DuckDuckGo lite, …)."""
    data = urllib.parse.urlencode(
        {str(k): str(v) for k, v in (fields or {}).items()}
    ).encode("utf-8")
    req_headers = {
        "User-Agent": USER_AGENT,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Content-Type": "application/x-www-form-urlencoded",
        **_HTTP_CLOSE_HEADERS,
    }
    if headers:
        req_headers.update(headers)
    req = urllib.request.Request(
        url,
        data=data,
        method="POST",
        headers=req_headers,
    )
    try:
        code, final_url, raw = _http_urlopen_read(req, timeout=timeout, fallback_url=url)
        return code, final_url, raw.decode("utf-8", "replace")
    except urllib.error.HTTPError as err:
        body = (err.read(8000) if err.fp else b"").decode("utf-8", "replace")
        return err.code, url, body
    except (urllib.error.URLError, TimeoutError, OSError):
        return 599, url, ""


def http_verify_get(
    url: str,
    timeout: int | None = None,
    max_bytes: int | None = None,
) -> tuple[int, str, str]:
    """Light GET for url_is_live: shorter timeout, no gzip, cap body read for soft-404 sniffing."""
    if timeout is None:
        timeout = _verify_timeout_sec()
    if max_bytes is None:
        max_bytes = _verify_max_body_bytes()
    url = _ascii_safe_url(url)
    ctx = ssl.create_default_context()
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": USER_AGENT,
            "Accept": "text/html,application/xhtml+xml,*/*;q=0.8",
            **_HTTP_CLOSE_HEADERS,
        },
    )
    try:
        code, final_url, raw = _http_urlopen_read(
            req,
            timeout=timeout,
            context=ctx,
            max_bytes=max_bytes,
            fallback_url=url,
        )
        return code, final_url, raw.decode("utf-8", "replace")
    except (urllib.error.URLError, TimeoutError, OSError, UnicodeEncodeError):
        return 599, url, ""


def posting_url_skip_verify(url: str) -> bool:
    """ATS URLs already validated during structured fetch; skip redundant verify GETs."""
    lower = str(url or "").lower()
    # LinkedIn guest / logged-out pages often look dead (login wall, soft copy) even
    # when the posting is live — never URL-verify or denylist them.
    if "linkedin.com/jobs/" in lower:
        return True
    # Greenhouse embeds on company domains (e.g. seatgeek.com/jobs/N?gh_jid=N) block bot verify GETs.
    if re.search(r"[?&]gh_jid=\d+", lower):
        return True
    return any(
        host in lower
        for host in (
            "boards.greenhouse.io",
            "job-boards.greenhouse.io",
            "jobs.lever.co",
            "api.lever.co",
            "myworkdayjobs.com",
            "myworkdaysite.com",
            "myworkday.com",
            "phenompeople.com",
            "phenom.com",
            "oraclecloud.com",
            "smartrecruiters.com",
            "icims.com",
            "successfactors.com",
            "successfactors.eu",
            "talentbrew.com",
        )
    )


def url_is_linkedin_job_posting(url: str) -> bool:
    return "linkedin.com/jobs/" in str(url or "").lower()


_SCRAPE_LOCK_HOLDER: "GlobalScrapeLock | None" = None


def _quickjobs_reports_dir() -> Path:
    """Run logs, scrape lock, and other durable runtime reports."""
    state = os.environ.get("QUICKJOBS_STATE_DIR", "").strip()
    if state:
        return Path(state).expanduser()
    portable_root = globals().get("QUICKJOBS_ROOT")
    if portable_root is not None:
        return Path(portable_root) / "output" / "quickjobs-reports"
    return Path.home() / "ws/scriptdir/output/quickjobs-reports"


def global_scrape_lock_path() -> Path:
    return _quickjobs_reports_dir() / "quickjobs-scrape.lock"


def _process_alive(pid: int) -> bool:
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True


def _parse_lock_pid(content: str) -> int | None:
    for line in content.splitlines():
        if line.startswith("pid="):
            try:
                return int(line.split("=", 1)[1].strip())
            except ValueError:
                return None
    return None


def _lock_started_from_content(content: str) -> str:
    for line in content.splitlines():
        if line.startswith("started="):
            return line.split("=", 1)[1].strip()
    return ""


def _exit_scrape_lock_busy(path: Path, pid: int, started: str = "") -> None:
    detail = f"pid {pid}"
    if started:
        detail = f"{detail}, started {started}"
    print(
        f"quickjobs: full-board scrape already running ({detail})",
        file=sys.stderr,
    )
    print(f"  lock: {path}", file=sys.stderr)
    raise SystemExit(2)


class GlobalScrapeLock:
    """Exclusive full-board scrape lock (skipped for --only refreshes)."""

    def __init__(self) -> None:
        self._path = global_scrape_lock_path()
        self._fd: int | None = None
        self._released = False
        self._prev_sigterm: Any = signal.SIG_DFL

    def acquire(self) -> None:
        global _SCRAPE_LOCK_HOLDER
        self._path.parent.mkdir(parents=True, exist_ok=True)
        fd = self._open_and_lock()
        existing = self._read_fd(fd)
        holder = _parse_lock_pid(existing)
        if holder is not None and holder != os.getpid() and _process_alive(holder):
            self._close_fd(fd)
            _exit_scrape_lock_busy(self._path, holder, _lock_started_from_content(existing))
        self._write_lock(fd)
        self._fd = fd
        _SCRAPE_LOCK_HOLDER = self
        atexit.register(self.release)
        self._prev_sigterm = signal.signal(signal.SIGTERM, self._on_sigterm)

    def _open_and_lock(self) -> int:
        for attempt in range(2):
            fd = os.open(str(self._path), os.O_CREAT | os.O_RDWR, 0o644)
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                return fd
            except BlockingIOError:
                self._close_fd(fd)
                if attempt == 0:
                    self._exit_if_live_holder_from_file()
                    continue
                self._exit_if_live_holder_from_file()
                print(
                    "quickjobs: another full-board scrape holds the global lock "
                    f"({self._path})",
                    file=sys.stderr,
                )
                raise SystemExit(2)
        raise RuntimeError("unreachable")

    def _exit_if_live_holder_from_file(self) -> None:
        try:
            content = self._path.read_text(encoding="utf-8")
        except OSError:
            content = ""
        holder = _parse_lock_pid(content)
        if holder is not None and holder != os.getpid() and _process_alive(holder):
            _exit_scrape_lock_busy(self._path, holder, _lock_started_from_content(content))

    @staticmethod
    def _read_fd(fd: int) -> str:
        os.lseek(fd, 0, os.SEEK_SET)
        return os.read(fd, 4096).decode("utf-8", errors="replace")

    def _write_lock(self, fd: int) -> None:
        started = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        payload = f"pid={os.getpid()}\nstarted={started}\n"
        os.ftruncate(fd, 0)
        os.lseek(fd, 0, os.SEEK_SET)
        os.write(fd, payload.encode())

    def _close_fd(self, fd: int) -> None:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        except OSError:
            pass
        try:
            os.close(fd)
        except OSError:
            pass

    def _on_sigterm(self, signum: int, frame: Any) -> None:
        self.release()
        prev = self._prev_sigterm
        if prev is signal.SIG_DFL:
            signal.signal(signal.SIGTERM, signal.SIG_DFL)
            os.kill(os.getpid(), signal.SIGTERM)
            return
        if callable(prev) and prev is not signal.SIG_IGN:
            prev(signum, frame)
        raise SystemExit(128 + signum)

    def release(self) -> None:
        global _SCRAPE_LOCK_HOLDER
        if self._released:
            return
        self._released = True
        if self._fd is not None:
            self._close_fd(self._fd)
            self._fd = None
        try:
            if self._path.is_file():
                holder = _parse_lock_pid(self._path.read_text(encoding="utf-8"))
                if holder == os.getpid():
                    self._path.unlink(missing_ok=True)
        except OSError:
            pass
        if _SCRAPE_LOCK_HOLDER is self:
            _SCRAPE_LOCK_HOLDER = None


_DEAD_JOB_PAGE_PHRASES = (
    "this job is no longer available",
    "job is no longer available",
    "requisition is no longer available",
    "position is no longer available",
    "role is no longer available",
    "job posting has expired",
    "this posting has expired",
    "posting is closed",
    "this job has been closed",
    "job has been filled",
    "position has been filled",
    "no longer accepting applications",
    "requisition not found",
    "job not found",
)


def url_page_indicates_dead_job(code: int, final_url: str, body: str) -> bool:
    """Detect soft 404s (HTTP 200 but 'Page not found', Oracle /errors/404, etc.)."""
    if code < 200 or code >= 400:
        return True
    final_l = (final_url or "").lower()
    if "/errors/404" in final_l or "/error/404" in final_l:
        return True
    if "viewrequisition" in final_l and "rid=" not in final_l:
        return True
    snippet = (body or "")[:12000].lower()
    if "page not found" in snippet and (
        "return to home" in snippet
        or "no longer exists" in snippet
        or "was moved" in snippet
    ):
        return True
    # Ashby SPA returns HTTP 200 with a ~7KB shell when jobs.ashbyhq.com/{board}/{id} is dead
    # (e.g. Cursor uses cursor.com/careers/{slug}). Live boards serve full HTML (100KB+).
    if "jobs.ashbyhq.com" in final_l and len(body or "") < 12_000:
        return True
    # Talentbrew / att.jobs and similar career sites often return HTTP 200 with expiry copy.
    if any(phrase in snippet for phrase in _DEAD_JOB_PAGE_PHRASES):
        return True
    return False


def normalize_expired_job_url(url: str) -> str:
    return str(url or "").strip().rstrip("/").lower()


def expired_job_urls_path(out_path: Path | None = None) -> Path:
    if out_path is not None:
        return _sidecar_path(out_path, "expired-job-urls.json")
    root = Path(os.environ.get("JOB_SEARCH_DIR", str(DEFAULT_JOB_SEARCH_DIR))).expanduser()
    path = (root / BOARD_SUFFIX).resolve()
    path.mkdir(parents=True, exist_ok=True)
    return path / "expired-job-urls.json"


def load_expired_job_urls(out_path: Path | None = None) -> set[str]:
    path = expired_job_urls_path(out_path)
    if not path.is_file():
        return set()
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return set()
    urls = data.get("urls") if isinstance(data, dict) else data
    if not isinstance(urls, list):
        return set()
    return {normalize_expired_job_url(u) for u in urls if str(u or "").strip()}


def remember_expired_job_urls(
    urls: list[str] | set[str],
    out_path: Path | None = None,
) -> int:
    """Persist dead posting URLs so later scrapes cannot re-add them. Returns new count."""
    incoming = {
        normalize_expired_job_url(u)
        for u in urls
        if str(u or "").strip() and not url_is_linkedin_job_posting(u)
    }
    if not incoming:
        return 0
    path = expired_job_urls_path(out_path)
    existing = load_expired_job_urls(out_path)
    before = len(existing)
    existing |= incoming
    payload = {
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "urls": sorted(existing),
    }
    atomic_write_text(path, json.dumps(payload, indent=2) + "\n")
    return len(existing) - before


def purge_linkedin_expired_job_urls(out_path: Path | None = None) -> int:
    """Drop LinkedIn guest URLs from the expired denylist (unreliable verify)."""
    path = expired_job_urls_path(out_path)
    existing = load_expired_job_urls(out_path)
    if not existing:
        return 0
    kept = {u for u in existing if not url_is_linkedin_job_posting(u)}
    removed = len(existing) - len(kept)
    if removed <= 0:
        return 0
    payload = {
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "urls": sorted(kept),
    }
    atomic_write_text(path, json.dumps(payload, indent=2) + "\n")
    return removed


def url_is_live(url: str, *, force: bool = False) -> bool:
    """Return True when a posting URL looks alive.

    force=True: do not trust ATS-host skip (aggregator-copied Greenhouse/Workday
    links were never validated by a first-party board scrape).
    """
    if not force and posting_url_skip_verify(url):
        return True
    if force:
        workday = workday_aggregator_url_is_live(url)
        if workday is not None:
            return workday
    code, final_url, body = http_verify_get(url)
    if url_page_indicates_dead_job(code, final_url, body):
        return False
    return 200 <= code < 400


WORKDAY_AGGREGATOR_JOB_URL_RE = re.compile(
    r"https://([a-z0-9.-]+)\.myworkdayjobs\.com/"
    r"(?:(?:en(?:-[a-z]{2})?|[a-z]{2}-[a-z]{2})/)?"
    r"([^/]+)/job/([^/?#]+)",
    re.I,
)


def workday_aggregator_url_is_live(url: str) -> bool | None:
    """Probe Workday CXS for an aggregator-copied posting URL.

    Returns True/False when CXS answers; None when the URL is not a Workday job
    path or the probe cannot decide (keep the listing).
    """
    match = WORKDAY_AGGREGATOR_JOB_URL_RE.search(str(url or "").strip())
    if not match:
        return None
    host, site, slug = match.group(1), match.group(2), match.group(3)
    tenant = host.split(".")[0]
    if not tenant or not site or not slug:
        return None
    path = f"/job/{slug}"
    cxs = f"https://{host}.myworkdayjobs.com/wday/cxs/{tenant}/{site}{path}"
    try:
        code, _, body = http_get(cxs)
    except Exception:
        return None
    if code == 404:
        return False
    if code < 200 or code >= 400:
        return None
    try:
        data = json.loads(body or "")
    except json.JSONDecodeError:
        return None
    info = data.get("jobPostingInfo") if isinstance(data, dict) else None
    return bool(isinstance(info, dict) and (info.get("title") or info.get("externalUrl")))


def parse_iso_ts(value: str | None) -> int:
    if not value:
        return 0
    try:
        normalized = value.replace("Z", "+00:00")
        if len(normalized) >= 5 and normalized[-5] in "+-" and normalized[-3] != ":":
            normalized = normalized[:-2] + ":" + normalized[-2:]
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp())
    except ValueError:
        return 0


def format_posted(ts: int) -> str:
    if ts <= 0:
        return ""
    return datetime.fromtimestamp(ts, tz=timezone.utc).astimezone().strftime("%m/%d/%Y")


def format_pipeline_applied_date(value: str) -> str:
    """Pipeline applied_at is ISO YYYY-MM-DD; show compact MM/DD/YY in Applied section."""
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        when = datetime.strptime(text[:10], "%Y-%m-%d")
    except ValueError:
        match = re.match(r"^(\d{4})-(\d{2})-(\d{2})", text)
        if not match:
            return ""
        when = datetime(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    return when.strftime("%m/%d/%y")


def parse_human_posted(value: str | None) -> int:
    text = (value or "").strip()
    if not text:
        return 0
    lower = text.lower()
    if lower.startswith("posted "):
        lower = lower[7:].strip()
    now = datetime.now(timezone.utc)
    if lower in ("today", "just posted", "moments ago"):
        return int(now.timestamp())
    if lower == "yesterday":
        return int((now - timedelta(days=1)).timestamp())
    match = re.search(r"(\d+)\s+minute", lower)
    if match:
        return int((now - timedelta(minutes=int(match.group(1)))).timestamp())
    match = re.search(r"(\d+)\s+hour", lower)
    if match:
        return int((now - timedelta(hours=int(match.group(1)))).timestamp())
    match = re.search(r"(\d+)\s+day", lower)
    if match:
        return int((now - timedelta(days=int(match.group(1)))).timestamp())
    match = re.search(r"(\d+)\s+week", lower)
    if match:
        return int((now - timedelta(weeks=int(match.group(1)))).timestamp())
    match = re.search(r"(\d+)\s+month", lower)
    if match:
        return int((now - timedelta(days=30 * int(match.group(1)))).timestamp())
    for fmt in ("%b %d, %Y", "%B %d, %Y"):
        try:
            return int(datetime.strptime(text, fmt).replace(tzinfo=timezone.utc).timestamp())
        except ValueError:
            continue
    return 0


def extract_json_array_after_key(text: str, key: str = '"positions"') -> list[Any]:
    marker = key
    idx = text.find(marker)
    if idx < 0:
        return []
    bracket = text.find("[", idx)
    if bracket < 0:
        return []
    depth = 0
    for pos in range(bracket, min(bracket + 800_000, len(text))):
        ch = text[pos]
        if ch == "[":
            depth += 1
        elif ch == "]":
            depth -= 1
            if depth == 0:
                try:
                    return json.loads(text[bracket : pos + 1])
                except json.JSONDecodeError:
                    return []
    return []


def parse_netflix_posting_date(value: str | None) -> int:
    """Netflix apply API posting_date is MM-DD-YYYY (Job Posting Date on the careers page)."""
    text = str(value or "").strip()
    if not text:
        return 0
    for fmt in ("%m-%d-%Y", "%m/%d/%Y"):
        try:
            return int(datetime.strptime(text, fmt).replace(tzinfo=timezone.utc).timestamp())
        except ValueError:
            continue
    return 0


def netflix_posting_date_from_apply_payload(data: dict[str, Any]) -> str:
    custom = data.get("custom_JD")
    if not isinstance(custom, dict):
        return ""
    fields = custom.get("data_fields")
    if not isinstance(fields, dict):
        return ""
    raw = fields.get("posting_date")
    if isinstance(raw, list):
        for item in raw:
            text = str(item or "").strip()
            if text:
                return text
        return ""
    return str(raw or "").strip()


def netflix_fetch_apply_detail(job_id: str) -> dict[str, str]:
    """Apply API payload: job_description plus public Job Posting Date."""
    cache_key = f"netflix-apply-{job_id}"
    cached = cache_get(SCRIPT_DIR, cache_key)
    if cached is not None:
        try:
            data = json.loads(cached)
        except json.JSONDecodeError:
            data = None
        if isinstance(data, dict):
            return {
                "job_description": str(data.get("job_description") or ""),
                "posting_date": str(data.get("posting_date") or ""),
            }
    legacy_jd = cache_get(SCRIPT_DIR, f"netflix-jd-{job_id}") or ""
    code, _, body = http_get(
        f"https://explore.jobs.netflix.net/api/apply/v2/jobs/{job_id}?domain=netflix.com"
    )
    if code != 200:
        return {"job_description": legacy_jd, "posting_date": ""}
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return {"job_description": legacy_jd, "posting_date": ""}
    if not isinstance(data, dict):
        return {"job_description": legacy_jd, "posting_date": ""}
    detail = {
        "job_description": str(data.get("job_description") or legacy_jd or ""),
        "posting_date": netflix_posting_date_from_apply_payload(data),
    }
    if detail["job_description"] or detail["posting_date"]:
        cache_set(SCRIPT_DIR, cache_key, json.dumps(detail))
    return detail


def netflix_fetch_job_description(job_id: str) -> str:
    return netflix_fetch_apply_detail(job_id).get("job_description") or ""


def netflix_posting_ts(job_id: str, position: dict[str, Any]) -> int:
    """Prefer Netflix's public Job Posting Date; fall back to listing t_create/t_update."""
    posting_date = netflix_fetch_apply_detail(job_id).get("posting_date") or ""
    ts = parse_netflix_posting_date(posting_date)
    if ts:
        return ts
    return int(position.get("t_create") or position.get("t_update") or 0)


def microsoft_fetch_job(job_id: str) -> dict[str, Any] | None:
    if not job_id:
        return None
    cache_key = f"msft-job-{job_id}"
    cached = cache_get(SCRIPT_DIR, cache_key)
    if cached is not None:
        try:
            data = json.loads(cached)
        except json.JSONDecodeError:
            data = None
        if isinstance(data, dict) and data.get("name"):
            name = _normalize_whitespace(str(data.get("name") or ""))
            if name and not _microsoft_title_is_bogus(name):
                return data
    code, _, body = http_get(f"https://apply.careers.microsoft.com/api/apply/v2/jobs/{job_id}")
    if code != 200:
        return None
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return None
    if not isinstance(data, dict) or not data.get("name"):
        return None
    name = _normalize_whitespace(str(data.get("name") or ""))
    if not name or _microsoft_title_is_bogus(name):
        return None
    cache_set(SCRIPT_DIR, cache_key, json.dumps(data))
    return data


def netflix_fetch_position(job_id: str) -> dict[str, Any] | None:
    code, final_url, body = http_get(f"https://explore.jobs.netflix.net/careers/job/{job_id}")
    if code != 200:
        return None
    positions = extract_json_array_after_key(html.unescape(body))
    if not positions:
        return None
    p = positions[0]
    p["canonical_url"] = final_url.split("?")[0]
    if not p.get("job_description"):
        p["job_description"] = netflix_fetch_job_description(job_id)
    return p


def netflix_is_remote_us(p: dict[str, Any]) -> bool:
    loc = (p.get("location") or "").lower()
    locations = [x.lower() for x in (p.get("locations") or [])]
    opt = (p.get("work_location_option") or "").lower()
    return "usa - remote" in loc or any("usa - remote" in x for x in locations) or "remote" in opt


def company_employer_region(company: dict[str, Any]) -> str:
    return str(company.get("employer_region") or "us")


def location_name_is_remoteish(name: str) -> bool:
    lower = name.lower()
    return any(
        term in lower
        for term in (
            "remote",
            "anywhere",
            "home based",
            "home-based",
            "work from home",
            "distributed",
            "telecommute",
        )
    )


def remote_location_fragment(name: str) -> str:
    text = str(name or "").strip()
    if not text:
        return ""
    parts = [part.strip() for part in re.split(r"[;|]", text) if part.strip()]
    for part in parts:
        if location_name_is_remoteish(part):
            return part
    return text if location_name_is_remoteish(text) else ""


def is_region_locked_non_us(lower: str) -> bool:
    lower = " ".join(str(lower or "").replace("·", ",").split())
    # US/USA - Remote (and Remote US / United States - Remote) must not match the
    # generic "Country - Remote" rule below — Workday/Alteryx-style nationwide US.
    if remote_scope_is_broad_us(lower):
        return False
    if any(
        t in lower
        for t in (
            "worldwide",
            "global",
            "anywhere",
            "americas",
            "united states",
            "remote, us",
            "remote us",
            "us - remote",
            "usa - remote",
            "u.s. - remote",
            "u.s.a. - remote",
            "home based - americas",
        )
    ):
        return False
    emea_only = (
        "home based - emea",
        "remote, emea",
        "distributed, emea",
    )
    if lower in emea_only:
        return True
    if "home based - emea" in lower and "americas" not in lower and "worldwide" not in lower:
        return True
    if lower.startswith("office based"):
        return True
    if location_text_indicates_canada(lower):
        return True
    if "remote," in lower and " us" not in lower and "americas" not in lower and "worldwide" not in lower:
        if ";" in lower:
            return True
    non_us_remote_markers = (
        "united kingdom",
        "gbr",
        " uk",
        "emea",
        "europe",
        "apac",
        "anz",
        "canada",
        "poland",
        "netherlands",
        "romania",
        "germany",
        "france",
        "spain",
        "italy",
        "india",
        "singapore",
        "australia",
        "new zealand",
        "japan",
        "korea",
        "israel",
        "brazil",
        "mexico",
        "ireland",
        "republic of ireland",
        "sweden",
    )
    if "remote" in lower and any(marker in lower for marker in non_us_remote_markers):
        return True
    if re.match(r"^[a-z][a-z .(),/-]+ - remote\b", lower):
        return True
    return False


def remote_scope_is_broad_us(lower: str) -> bool:
    """True only when text explicitly pairs remote with US country tokens."""
    lower = " ".join(str(lower or "").replace("·", ",").split())
    patterns = (
        r"\bremote\b\s*[-,:]?\s*(?:usa|us|u\.s\.|united states)\b",
        r"\b(?:usa|us|u\.s\.|united states)\s*[-–—]\s*remote(?:\s+opportunity)?\b",
        r"\bremote\b\s*[-,:]?\s*north america\b",
        r"\bremote\b\s*[-,:]?\s*americas\b",
        r"\bhome[- ]based\b\s*-\s*americas\b",
    )
    return any(re.search(pattern, lower) for pattern in patterns)


