_STATE_REMOTE_IN_ONLY_RE = re.compile(
    r"\bremote\s+in\s+(?P<states>.+?)\s+only\b",
    re.I,
)
_STATE_REMOTE_PAREN_IN_ONLY_RE = re.compile(
    r"\(\s*remote\s+in\s+(?P<states>.+?)\s+only\s*\)",
    re.I,
)
_STATE_REMOTE_PAREN_ONLY_RE = re.compile(
    r"\bremote\s*\(\s*(?P<states>.+?)\s+only\s*\)",
    re.I,
)
_STATE_REMOTE_DASH_ABBREV_RE = re.compile(
    r"\bremote\s*[-:]\s*(?P<state>[A-Za-z]{2})\b",
    re.I,
)
_STATE_REMOTE_SUFFIX_RE = re.compile(
    r"^remote\s*[-–—:,]\s*(?P<place>.+?)\s*$",
    re.I,
)
_NATIONWIDE_US_REMOTE_COUNTRY_TOKENS = frozenset(
    {"us", "usa", "u.s.", "u.s", "united states", "united states of america"}
)


def _state_blob_is_broad_us_remote(states_blob: str) -> bool:
    lower = str(states_blob or "").strip().lower()
    if not lower:
        return False
    broad_markers = (
        "united states",
        "usa",
        "u.s.",
        "u.s.a",
        "us nationwide",
        "nationwide",
        "anywhere",
        "worldwide",
        "global",
        "north america",
        "americas",
        "all us states",
        "all u.s. states",
        "all 50 states",
        "50 states",
    )
    return any(marker in lower for marker in broad_markers)


def parse_us_state_codes_from_blob(blob: str) -> frozenset[str]:
    """Parse US state abbreviations / names from a remote-scope fragment."""
    codes: set[str] = set()
    for part in re.split(r"\s*(?:,|/|;|\band\b)\s*", str(blob or "").strip(), flags=re.I):
        token = part.strip().strip(".")
        if not token:
            continue
        upper = token.upper()
        if upper in US_STATE_CODES:
            codes.add(upper)
            continue
        mapped = US_STATE_NAME_TO_CODE.get(token.lower())
        if mapped:
            codes.add(mapped)
    return frozenset(codes)


def extract_state_limited_remote_allowed_states(*parts: str) -> frozenset[str] | None:
    """Return allowed US state codes when remote is limited to specific state(s).

    None means nationwide / multi-country US-eligible remote, or no state-only pattern.
    """
    blob = " ".join(str(part).strip() for part in parts if str(part).strip())
    if not blob:
        return None
    if location_is_multi_country_us_eligible(blob):
        return None
    if extract_linkedin_location_mode(blob) == "remote" and not re.search(
        r"\bremote\s+in\s+.+?\s+only\b", blob, re.I
    ):
        return None

    found_codes: set[str] = set()
    matched = False
    for pattern in (
        _STATE_REMOTE_IN_ONLY_RE,
        _STATE_REMOTE_PAREN_IN_ONLY_RE,
        _STATE_REMOTE_PAREN_ONLY_RE,
    ):
        for match in pattern.finditer(blob):
            states_blob = match.group("states")
            if _state_blob_is_broad_us_remote(states_blob):
                return None
            matched = True
            found_codes.update(parse_us_state_codes_from_blob(states_blob))

    for match in _STATE_REMOTE_DASH_ABBREV_RE.finditer(blob):
        state = match.group("state").upper()
        if state in US_STATE_CODES:
            matched = True
            found_codes.add(state)

    if not matched or not found_codes:
        return None
    return frozenset(found_codes)


def location_text_is_state_locked_us_remote(text: str) -> bool:
    """True for Remote - CA / Remote, Oregon (not Remote - US/USA/United States)."""
    raw = str(text or "").strip()
    if not raw:
        return False
    lower = " ".join(raw.lower().replace("·", ",").split())
    match = _STATE_REMOTE_SUFFIX_RE.match(lower)
    if match:
        place = match.group("place").strip().strip(".")
        if place in _NATIONWIDE_US_REMOTE_COUNTRY_TOKENS:
            return False
        if re.match(r"^united states(?:\s+of\s+america)?$", place):
            return False
        if _state_blob_is_broad_us_remote(place):
            return False
        if parse_us_state_codes_from_blob(place):
            return True
    allowed = extract_state_limited_remote_allowed_states(raw)
    return allowed is not None and bool(allowed)


def profile_remote_ok_states(cfg: dict[str, Any] | None) -> frozenset[str]:
    """US states where the profile user may work a state-limited remote role."""
    home = profile_home_us_state(cfg or {})
    ok = {home}
    if home == "OR":
        ok.add("WA")
    elif home == "WA":
        ok.add("OR")
    return frozenset(ok)


def location_or_title_is_state_limited_remote(
    location_name: str,
    *,
    title: str = "",
    description_text: str = "",
    cfg: dict[str, Any] | None = None,
) -> tuple[bool, str]:
    """True when remote work is limited to US state(s) that exclude the user's home area."""
    allowed = extract_state_limited_remote_allowed_states(
        location_name,
        title,
        description_text,
    )
    if allowed is None:
        return False, ""
    ok_states = profile_remote_ok_states(cfg)
    if allowed & ok_states:
        return False, ""
    readable = ", ".join(
        US_STATE_CODE_TO_NAME.get(code, code) for code in sorted(allowed)
    )
    return True, f"Remote in {readable} only"


