def wellfound_has_us_work_signal(*parts: str) -> bool:
    blob = " ".join(str(part).strip() for part in parts if str(part).strip()).lower()
    if not blob:
        return False
    return any(signal in blob for signal in US_REMOTE_WORK_SIGNALS)


def remote_country_suffix(text: str) -> str | None:
    """Return the geography suffix for locations like 'Remote Poland' or 'Remote - UK'."""
    lower = str(text or "").lower().strip()
    match = re.match(r"^remote(?:\s*[-:,]\s*|\s+)(.+)$", lower)
    if not match:
        return None
    place = match.group(1).strip()
    return place or None


def remote_location_indicates_non_us_country(text: str) -> bool:
    """True when 'Remote {place}' names a non-US geography (e.g. Remote Poland, Remote Canada)."""
    raw = str(text or "").strip()
    if re.match(
        r"^remote\s*\(\s*(?:us|usa|u\.s\.(?:\.|a\.)?|united states(?:\s+of\s+america)?)\s*\)\s*$",
        " ".join(raw.lower().split()),
    ):
        return False
    place = remote_country_suffix(text)
    if not place:
        return False
    lower = str(text or "").lower().strip()
    place_clean = place.strip().strip("()").strip()
    if country_part_is_us(place_clean) or remote_scope_is_broad_us(lower):
        return False
    if location_text_indicates_us_worksite(place):
        return False
    return True


_NON_US_COUNTRY_REMOTE_PREFIX_RE = re.compile(
    r"^(?P<country>.+?)\s*[-–—]\s*remote\s*$",
    re.I,
)


def location_text_is_non_us_country_remote(text: str) -> bool:
    """True for country-locked remote labels like 'Canada - Remote' or 'Remote - Poland'."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if re.match(
        r"^remote\s*\(\s*(?:us|usa|u\.s\.(?:\.|a\.)?|united states(?:\s+of\s+america)?)\s*\)\s*$",
        " ".join(raw.lower().split()),
    ):
        return False
    if remote_location_indicates_non_us_country(raw):
        return True
    if location_country_paren_remote_lock(raw):
        return True
    match = _NON_US_COUNTRY_REMOTE_PREFIX_RE.match(" ".join(raw.lower().split()))
    if match:
        country = match.group("country").strip()
        if country_part_is_non_us(country):
            return True
        if location_text_indicates_non_us_worksite(country) and not country_part_is_us(country):
            return True
    return False


def remote_scope_is_geo_restricted(lower: str) -> bool:
    if not lower:
        return False
    if remote_scope_is_broad_us(lower):
        return False
    if remote_location_indicates_non_us_country(lower):
        return True
    if posting_text_indicates_india_hire(lower):
        return True
    if location_text_indicates_india(lower):
        return True
    if is_region_locked_non_us(lower):
        return True
    paren = re.search(r"\bremote\s*\(([^)]+)\)", lower, re.I)
    if paren and location_text_indicates_india(paren.group(1)):
        return True
    patterns = (
        r"\bremote\b\s*[-,:]\s*[a-z]",
        r"\bhome[- ]based\b\s*-\s*[a-z]",
        r"\bdistributed\b\s*,\s*[a-z]",
    )
    return any(re.search(pattern, lower) for pattern in patterns)


def remote_location_us_workable(name: str, employer_region: str = "us") -> bool:
    """True when a remote posting plausibly allows working from the US."""
    if location_is_multi_country_us_eligible(name):
        return True
    if location_is_geo_plus_us_nationwide_remote(name):
        return True
    if location_has_us_nationwide_remote_segment(name):
        if posting_text_indicates_india_hire(name):
            return False
        if location_text_indicates_india(name):
            return False
        return True
    if workday_has_state_locked_remote_only(name):
        return False
    if location_has_site_bound_segments(name):
        return False
    if location_text_indicates_canada(name):
        return False
    if posting_text_indicates_india_hire(name):
        return False
    if location_text_indicates_india(name):
        return False
    if remote_location_indicates_non_us_country(name):
        return False
    fragment = remote_location_fragment(name)
    if not fragment:
        return False
    if remote_location_indicates_non_us_country(fragment):
        return False
    lower = fragment.lower().strip()
    if location_text_indicates_india(fragment):
        return False
    if remote_scope_is_broad_us(lower):
        return True
    if remote_scope_is_geo_restricted(lower):
        return False
    if remote_scope_is_geo_restricted(name.lower()):
        return False
    if employer_region == "international":
        return lower in ("remote", "distributed") or location_name_is_remoteish(fragment)
    return True


def location_text_indicates_us_worksite(*parts: str) -> bool:
    blob = " / ".join(str(part).strip() for part in parts if str(part).strip()).lower()
    if not blob:
        return False
    if remote_scope_is_broad_us(blob):
        return True
    if re.search(r"\b(?:usa|u\.s\.a?\.?|united states)\b", blob):
        return True
    if re.search(r",\s*(us|usa|u\.s\.a?\.?|united states)\b", blob):
        return True
    if re.search(
        r",\s*(al|ak|az|ar|ca|co|ct|de|fl|ga|hi|ia|id|il|in|ks|ky|la|ma|md|me|mi|mn|mo|"
        r"ms|mt|nc|nd|ne|nh|nj|nm|nv|ny|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|va|vt|wa|wi|wv|wy|dc)\b",
        blob,
    ):
        return True
    for state_name in US_STATE_CODE_TO_NAME.values():
        if re.search(rf"\b{re.escape(state_name.lower())}\b", blob):
            return True
    us_city_markers = (
        "new york",
        "san francisco",
        "los angeles",
        "seattle",
        "portland",
        "austin",
        "denver",
        "chicago",
        "boston",
        "atlanta",
        "bay area",
        "silicon valley",
        "washington dc",
        "remote us",
        "remote - us",
        "remote, us",
    )
    return any(marker in blob for marker in us_city_markers)


