def location_text_indicates_non_us_worksite(*parts: str) -> bool:
    for part in parts:
        if location_country_paren_remote_lock(part) or greenhouse_title_country_lock(part):
            return True
    blob = " / ".join(str(part).strip() for part in parts if str(part).strip()).lower()
    if not blob:
        return False
    if location_text_indicates_us_worksite(blob):
        return False
    if location_text_indicates_canada(blob):
        return True
    if location_text_indicates_india(blob):
        return True
    if blob.startswith("london") or blob.endswith("london") or " london" in blob:
        return True
    for country in _COUNTRY_NAME_PARTS:
        if country in _US_COUNTRY_NAMES:
            continue
        if re.search(rf"\b{re.escape(country)}\b", blob):
            return True
    return any(marker in blob for marker in NON_US_WORKSITE_MARKERS)


def lever_posting_location_label(posting: dict[str, Any]) -> str:
    categories = posting.get("categories") if isinstance(posting.get("categories"), dict) else {}
    all_locs = categories.get("allLocations")
    if isinstance(all_locs, list):
        cleaned = [str(item).strip() for item in all_locs if str(item).strip()]
        if cleaned:
            return " / ".join(cleaned)
    return str(categories.get("location") or "").strip()


def lever_posting_country(posting: dict[str, Any]) -> str:
    return str(posting.get("country") or "").strip().upper()


def lever_posting_us_workable(posting: dict[str, Any], description_text: str = "") -> bool:
    country = lever_posting_country(posting)
    if country and country not in ("US", "USA"):
        return False
    location_name = lever_posting_location_label(posting)
    if location_name and location_text_indicates_non_us_worksite(location_name):
        return False
    if description_text:
        based = re.search(
            r"(?:this role is based in|where you['’]ll be)[^\n.]{0,160}",
            description_text,
            re.I,
        )
        if based and location_text_indicates_non_us_worksite(based.group(0)):
            if not location_text_indicates_us_worksite(based.group(0)):
                return False
    return True


