_LI_ONSITE_TAG_RE = re.compile(r"#LI-Onsite\b", re.I)
_LI_HYBRID_TAG_RE = re.compile(r"#LI-Hybrid\b", re.I)
_LI_REMOTE_TAG_RE = re.compile(r"#LI-Remote\b", re.I)

_US_COUNTRY_NAMES = frozenset(
    {
        "united states",
        "united states of america",
        "usa",
        "u.s.",
        "u.s.a.",
        "us",
    }
)


def normalize_country_token(text: str) -> str:
    return " ".join(str(text or "").lower().split())


def country_part_is_us(country_part: str) -> bool:
    lower = normalize_country_token(country_part)
    if not lower:
        return False
    if lower in _US_COUNTRY_NAMES:
        return True
    return lower.startswith("united states")


def country_part_is_non_us(country_part: str) -> bool:
    lower = normalize_country_token(country_part)
    if not lower or country_part_is_us(lower):
        return False
    if _part_is_country_name(lower):
        return lower not in _US_COUNTRY_NAMES
    return lower.startswith("united ") and not lower.startswith("united states")


def greenhouse_title_country_lock(title: str) -> str | None:
    """Greenhouse titles like 'Role | Spain | Remote' lock hire to that country."""
    parts = [part.strip() for part in str(title or "").split("|") if part.strip()]
    if len(parts) >= 2 and parts[-1].lower().strip() == "remote":
        country = parts[-2].strip()
        if country_part_is_non_us(country):
            return country
    return None


def location_country_paren_remote_lock(location_name: str) -> str | None:
    """Locations like 'Spain (Remote)' or 'Republic of Ireland (Remote)'."""
    match = re.match(r"^(.+?)\s*\(\s*remote\s*\)\s*$", str(location_name or "").strip(), re.I)
    if not match:
        return None
    country = match.group(1).strip()
    if country_part_is_non_us(country):
        return country
    return None


def _part_is_country_name(part: str) -> bool:
    lower = part.lower().strip()
    if not lower:
        return False
    if lower in _COUNTRY_NAME_PARTS or lower in _US_COUNTRY_NAMES:
        return True
    # Workday often uses "United States of America" (does not end with "states").
    if lower.startswith("united states"):
        return True
    if lower.startswith("united ") and lower.endswith(("states", "kingdom")):
        return True
    return False


def _location_country_name_parts(location_name: str) -> list[str]:
    """Country-name tokens from comma/semicolon location lists (drops Remote/Hybrid)."""
    core, _ = location_strip_paren_suffix(location_name)
    text = core.strip()
    if not text:
        return []
    parts = [p.strip() for p in re.split(r"[,;]\s*", text) if p.strip()]
    countries: list[str] = []
    for part in parts:
        if _segment_is_bare_remote(part):
            continue
        lower = normalize_country_token(part)
        if lower in {"hybrid", "onsite", "on-site", "on site"}:
            continue
        if _part_is_country_name(part) or country_part_is_us(part) or country_part_is_non_us(part):
            countries.append(part)
    return countries


def location_is_country_only_multi_country(location_name: str) -> bool:
    """True when comma/semicolon-separated parts are all country names (not city/state sites)."""
    countries = _location_country_name_parts(location_name)
    if len(countries) < 2:
        return False
    core, _ = location_strip_paren_suffix(location_name)
    text = core.strip()
    if not re.search(r"[,;]", text):
        return False
    return True


def location_is_multi_country_us_eligible(location_name: str) -> bool:
    """Comma/semicolon-separated country list that includes United States (either/or hire)."""
    countries = _location_country_name_parts(location_name)
    if len(countries) < 2:
        return False
    return any(country_part_is_us(p) for p in countries)


def location_lists_us_with_other_countries(location_name: str) -> bool:
    """True when US is listed alongside at least one other country (not US-only remote)."""
    countries = _location_country_name_parts(location_name)
    if len(countries) < 2:
        return False
    has_us = any(country_part_is_us(p) for p in countries)
    has_other = any(country_part_is_non_us(p) for p in countries)
    return has_us and has_other


def location_names_city_state_site(location_name: str) -> bool:
    """True for city, ST or city, ST, country site-bound locations (not country-only lists)."""
    return any(
        segment_names_city_state_site(segment)
        for segment in location_work_segments(location_name)
    )


def classify_city_state_site(
    location_name: str, cfg: dict[str, Any] | None = None
) -> tuple[str, str] | None:
    """Return local or excluded when location names a US city/state work site."""
    if not location_names_city_state_site(location_name):
        return None
    label = str(location_name or "").strip()
    fragments: list[str] = []
    for segment in location_work_segments(location_name):
        if _segment_is_bare_remote(segment):
            continue
        frag = segment_to_city_state_fragment(segment)
        if frag and frag not in fragments:
            fragments.append(frag)
            continue
        for city, state in LOCATION_SITE_RE.findall(segment):
            city = city.strip()
            state = state.strip().upper()
            if state not in US_STATE_CODES:
                continue
            if city.upper() in US_STATE_CODES:
                continue
            if city.upper().startswith("OR "):
                city = city[3:].strip()
            normalized = f"{city}, {state}"
            if normalized not in fragments:
                fragments.append(normalized)
    if fragments:
        if any(_single_site_within_local_radius(fragment, cfg) for fragment in fragments):
            return "local", label
        return "excluded", label
    if location_within_local_radius(location_name, cfg):
        return "local", label
    return "excluded", label


def extract_linkedin_location_mode(*parts: str) -> str | None:
    """Return onsite, hybrid, or remote from LinkedIn #LI-* location tags."""
    blob = "\n".join(str(p) for p in parts if str(p).strip())
    if not blob:
        return None
    if _LI_ONSITE_TAG_RE.search(blob):
        return "onsite"
    if _LI_HYBRID_TAG_RE.search(blob):
        return "hybrid"
    if _LI_REMOTE_TAG_RE.search(blob):
        return "remote"
    return None


def classify_explicit_remote_over_site_anchor(
    location_name: str,
    employer_region: str,
    *,
    title: str = "",
    description_text: str = "",
) -> tuple[str, str] | None:
    """US-remote when title/JD say so despite a Greenhouse city/state HQ location."""
    if not location_names_city_state_site(location_name):
        return None
    li_mode = extract_linkedin_location_mode(title, location_name, description_text)
    if li_mode == "onsite":
        return None
    title_remote_us = location_text_is_remote_us_nationwide(title)
    if li_mode != "remote" and not title_remote_us:
        return None
    if li_mode == "hybrid" and not title_remote_us:
        return None

    for source in (title,):
        lock = location_country_paren_remote_lock(source) or greenhouse_title_country_lock(source)
        if lock:
            label = str(source or lock).strip() or lock
            return "excluded", excluded_location_label(label)

    if is_region_locked_non_us(str(location_name or "").lower()) or location_text_indicates_non_us_worksite(
        location_name, title
    ):
        return "excluded", excluded_location_label(location_name)

    label = "Remote US" if title_remote_us or li_mode == "remote" else (location_name or "Remote")
    job_loc = classify_remote_loc(label, employer_region)
    if job_loc:
        return job_loc, label
    if location_is_multi_country_us_eligible(location_name):
        return "remote", location_name
    if not location_text_indicates_non_us_worksite(location_name, title):
        return ("remote-intl" if employer_region == "international" else "remote"), label
    return "excluded", excluded_location_label(location_name)


def classify_remote_loc(location_name: str, employer_region: str) -> str | None:
    if not remote_location_us_workable(location_name, employer_region):
        return None
    return "remote-intl" if employer_region == "international" else "remote"


def excluded_location_label(location_name: str) -> str:
    fragment = remote_location_fragment(location_name)
    return fragment or str(location_name or "").strip()


def classify_location_with_fallback(
    location_name: str,
    employer_region: str,
    default_loc: str = "",
    cfg: dict[str, Any] | None = None,
    *,
    title: str = "",
    description_text: str = "",
) -> tuple[str | None, str | None]:
    original = str(location_name or "").strip()
    rejected_title = bool(original and location_text_looks_like_job_title(original))
    if rejected_title:
        location_name = ""
    elif original and location_text_looks_like_jd_prose(original):
        geo = extract_geographic_location_fragment(original)
        location_name = geo if geo else ""
    state_excluded, state_label = location_or_title_is_state_limited_remote(
        location_name,
        title=title,
        description_text=description_text,
        cfg=cfg,
    )
    if state_excluded:
        return "excluded", state_label

    for source in (location_name, title):
        lock = location_country_paren_remote_lock(source) or greenhouse_title_country_lock(source)
        if lock:
            label = str(source or lock).strip() or lock
            return "excluded", excluded_location_label(label)

    if workday_remote_matches_profile(location_name, cfg):
        label = str(location_name or "").strip() or "Remote"
        return (
            "remote-intl" if employer_region == "international" else "remote",
            label,
        )

    if workday_has_state_locked_remote_only(location_name):
        return "excluded", workday_state_locked_remote_exclusion_label(location_name)

    if location_is_geo_plus_us_nationwide_remote(location_name):
        label = str(location_name or "").strip() or NATIONWIDE_REMOTE_US_LABEL
        if is_region_locked_non_us(label.lower()) or location_text_indicates_non_us_worksite(
            location_name, title
        ):
            return "excluded", excluded_location_label(location_name)
        return (
            "remote-intl" if employer_region == "international" else "remote",
            label,
        )

    explicit_remote = classify_explicit_remote_over_site_anchor(
        location_name,
        employer_region,
        title=title,
        description_text=description_text,
    )
    if explicit_remote:
        return explicit_remote

    site_class = classify_city_state_site(location_name, cfg)
    if site_class:
        return site_class

    paren_mode = location_paren_mode_hint(location_name)
    if paren_mode in ("hybrid", "onsite"):
        label = str(location_name or "").strip() or (
            "Hybrid" if paren_mode == "hybrid" else "On-site"
        )
        if location_within_local_radius(location_name, cfg):
            return "local", label
        return "excluded", label

    if location_is_multi_country_us_eligible(location_name):
        return (
            "remote-intl" if employer_region == "international" else "remote",
            location_name,
        )

    li_mode = extract_linkedin_location_mode(title, location_name, description_text)

    if li_mode == "onsite":
        if location_within_local_radius(location_name, cfg):
            return "local", location_name
        return "excluded", location_name or "On-site"

    if li_mode == "hybrid":
        if location_within_local_radius(location_name, cfg):
            return "local", location_name
        return "excluded", location_name or "Hybrid"

    if li_mode == "remote":
        label = location_name or "Remote"
        if is_region_locked_non_us(label.lower()) or location_text_indicates_non_us_worksite(
            location_name, title
        ):
            return "excluded", excluded_location_label(label)
        job_loc = classify_remote_loc(label, employer_region)
        if job_loc:
            return job_loc, label
        if location_is_multi_country_us_eligible(location_name):
            return "remote", location_name
        if not location_text_indicates_non_us_worksite(location_name, title):
            return ("remote-intl" if employer_region == "international" else "remote"), label
        return "excluded", excluded_location_label(location_name)

    job_loc = classify_remote_loc(location_name, employer_region)
    if job_loc:
        return job_loc, location_name or None
    if location_name_is_remoteish(location_name):
        return "excluded", excluded_location_label(location_name)
    if location_name and location_text_indicates_non_us_worksite(location_name):
        return "excluded", location_name
    fallback = str(default_loc or "").strip()
    if fallback == "local":
        if location_within_local_radius(location_name, cfg):
            return "local", location_name or None
        if location_name:
            return "excluded", location_name
        return None, None
    if fallback in ("remote", "remote-intl") and location_name:
        if location_text_indicates_us_worksite(location_name) and not location_name_is_remoteish(
            location_name
        ):
            if location_within_local_radius(location_name, cfg):
                return "local", location_name
            return "excluded", location_name
        if not location_text_indicates_us_worksite(location_name) and not location_name_is_remoteish(
            location_name
        ):
            return "excluded", location_name
    if fallback:
        if not location_name and rejected_title:
            return "excluded", None
        label = location_name if fallback == "excluded" and location_name else None
        return fallback, label
    if location_name:
        return "excluded", location_name
    return None, None


def discovered_location_why(job_loc: str, location_name: str, employer_region: str) -> str:
    label = str(location_name or "").strip()
    if job_loc == "remote":
        return "Remote US (auto-discovered)."
    if job_loc == "remote-intl":
        return "International employer · remote from the US (auto-discovered)."
    if job_loc == "local":
        return f"Local / commutable role ({label})." if label else "Local / commutable role."
    if job_loc == "excluded":
        if label and location_name_is_remoteish(label):
            return f"Remote restricted to {excluded_location_label(label)}; not workable from the US."
        if label:
            if location_text_indicates_us_worksite(label):
                return f"On-site role ({label}); not remote."
            return f"Location-bound / hybrid too far ({label})."
        return "Location-bound / not workable from the US."
    return (
        "International employer · US/Americas/worldwide remote (auto-discovered)."
        if employer_region == "international"
        else "Remote US (auto-discovered)."
    )


def location_us_salary_eligible(
    job_loc: str | None,
    location_name: str = "",
    *,
    title: str = "",
) -> bool:
    """True when JD comp labels apply to this US profile."""
    loc = str(job_loc or "").strip().lower()
    if loc == "excluded":
        return False
    if loc in ("remote", "local", "remote-intl"):
        if loc == "remote-intl" and location_text_indicates_non_us_worksite(
            location_name, title
        ):
            return False
        return True
    if location_text_indicates_non_us_worksite(location_name, title):
        return False
    if location_text_indicates_us_worksite(location_name, title):
        return True
    if loc:
        return False
    return True


def job_us_salary_eligible(job: Job) -> bool:
    return location_us_salary_eligible(
        job.loc, job.loc_label or "", title=job.title
    )


def netflix_infer_match(name: str) -> str:
    lower = name.lower()
    if any(
        h in lower
        for h in (
            "continuous integration",
            "managed compute",
            "cloud gateway",
            "site reliability",
            "sre",
        )
    ):
        return "strong"
    if any(h in lower for h in ("distributed systems", "data platform", "automation", "infrastructure")):
        return "good"
    return "good"


def netflix_job_description_text(position: dict[str, Any], job_id: str) -> str:
    desc_html = position.get("job_description") or ""
    if not desc_html:
        desc_html = netflix_fetch_job_description(job_id)
    return html_to_plain(desc_html)


def finalize_discovered_match(
    match: str,
    why: str,
    description_text: str,
    title: str,
    cfg: dict[str, Any],
    override: dict[str, Any],
) -> tuple[str, str]:
    if override.get("skip_years_check"):
        return match, why
    if "match" not in override:
        match = infer_match_from_skills(description_text, title, cfg)
    if not description_text:
        return match, why
    adjusted, note = apply_domain_years_to_match(match, description_text, cfg)
    if not note:
        return match, why
    RUN_METRICS["downrated"].append(title)
    if why:
        return adjusted, f"{note} {why}"
    return adjusted, note


def greenhouse_api_get(url: str, timeout: int | None = None) -> tuple[int, str, str]:
    cid = _current_fetch_company_id()
    if _company_fetch_abandoned(cid):
        return 599, url, ""
    with _GREENHOUSE_API_SEMAPHORE:
        if _company_fetch_abandoned(cid):
            return 599, url, ""
        return http_get(url, timeout=timeout)


def stripe_greenhouse_supplement_detail(job_id: int, detail_text: str) -> str:
    """Stripe's Greenhouse API JD omits pay; stripe.com search?gh_jid= embeds Pay and benefits."""
    if extract_comp_range_from_text(detail_text):
        return detail_text
    url = f"https://stripe.com/jobs/search?gh_jid={job_id}"
    body = cached_html_fetch(url, f"stripe-gh-{job_id}", cache_ttl_hours=24.0)
    if not body:
        return detail_text
    pay_match = re.search(
        r"Pay and benefits[\s\S]{0,1400}?"
        r"(?:annual US base salary range for this role is|"
        r"The annual US base salary range for this role is)\s*"
        r"\$?\s*([\d,]+)\s*(?:-|–|—|to)\s*\$?\s*([\d,]+)",
        body,
        re.I,
    )
    if not pay_match:
        return detail_text
    snippet = pay_match.group(0)
    return f"{detail_text}\n{snippet}" if detail_text else snippet


def greenhouse_fetch_job_content(board: str, job_id: int, force_refresh: bool = False) -> str:
    if _company_fetch_abandoned(_current_fetch_company_id()):
        return ""
    cache_key = f"gh-{board}-{job_id}"
    if not force_refresh:
        cached = cache_get(SCRIPT_DIR, cache_key)
        if cached is not None:
            return html.unescape(cached)
    code, _, body = greenhouse_api_get(
        f"https://boards-api.greenhouse.io/v1/boards/{board}/jobs/{job_id}"
    )
    if code != 200:
        return ""
    try:
        payload = json.loads(body)
        content = str(payload.get("content") or "")
        metadata = payload.get("metadata")
        if isinstance(metadata, list):
            meta_bits: list[str] = []
            for entry in metadata:
                if not isinstance(entry, dict):
                    continue
                name = str(entry.get("name") or "").strip()
                value = str(entry.get("value") or "").strip()
                if name and value:
                    meta_bits.append(f"{name}: {value}")
            if meta_bits:
                content = f"{content}\n" + "\n".join(meta_bits)
    except json.JSONDecodeError:
        return ""
    content = html.unescape(content)
    if content:
        cache_set(SCRIPT_DIR, cache_key, content)
    return content


def greenhouse_extract_comp_range(detail_text: str) -> tuple[str, int, int] | None:
    return extract_comp_range_from_text(detail_text)


AFFIRM_HIGH_COST_STATE_MARKERS = (
    "california",
    ", ca",
    " ca ",
    "washington",
    ", wa",
    " wa ",
    "new york",
    ", ny",
    " ny ",
    "new jersey",
    ", nj",
    " nj ",
    "connecticut",
    ", ct",
    " ct ",
    "san francisco",
    "seattle",
    "nyc",
    "new york city",
)
AFFIRM_OTHER_STATE_MARKERS = (
    "oregon",
    ", or",
    " or ",
    "portland",
    "all other u.s. states",
    "all other us states",
)


def profile_home_us_state(cfg: dict[str, Any]) -> str:
    """Two-letter US state for salary geo heuristics (defaults OR for 00000)."""
    profile = cfg.get("profile") or {}
    explicit = str(profile.get("home_state") or "").strip().upper()
    if len(explicit) == 2 and explicit.isalpha():
        return explicit
    home_zip = str(profile.get("home_zip", "00000")).strip()
    if home_zip.startswith("97"):
        return "OR"
    return "OR"


def extract_usa_base_pay_geo_bands(
    detail_text: str,
) -> tuple[tuple[int, int] | None, tuple[int, int] | None, tuple[int, int] | None]:
    """Parse GH 'USA base pay range (...)' tiers (high-cost states, OR, all other US)."""
    if not detail_text:
        return None, None, None
    if not re.search(r"(?:usa\s+)?base pay range\s*\(", detail_text, re.I):
        return None, None, None
    money = _money_capture_pattern()
    dash = r"(?:-|–|—|to)"
    gap = r"[^$]{0,240}?"
    prefix = r"(?:usa\s+)?base pay range"
    high_pattern = (
        rf"{prefix}\s*\(\s*ca\s*,\s*wa\s*,\s*ny\s*,\s*nj\s*,\s*ct\s*\)"
        rf"{gap}{money}\s*{dash}\s*{money}"
    )
    oregon_pattern = (
        rf"{prefix}\s*\(\s*(?:or|oregon)\s*\)"
        rf"{gap}{money}\s*{dash}\s*{money}"
    )
    other_pattern = rf"{prefix}\s*\(\s*all other{gap}{money}\s*{dash}\s*{money}"
    high_ranges = _collect_comp_ranges_from_patterns(detail_text, (high_pattern,))
    oregon_ranges = _collect_comp_ranges_from_patterns(detail_text, (oregon_pattern,))
    other_ranges = _collect_comp_ranges_from_patterns(detail_text, (other_pattern,))
    high = high_ranges[0] if high_ranges else None
    oregon = oregon_ranges[0] if oregon_ranges else None
    other = other_ranges[0] if other_ranges else None
    return high, oregon, other


def affirm_extract_geo_bands(detail_text: str) -> tuple[tuple[int, int] | None, tuple[int, int] | None]:
    """Parse Affirm tiered US base pay (high-cost states vs all other states)."""
    high, oregon, other = extract_usa_base_pay_geo_bands(detail_text)
    if oregon:
        other = oregon
    return high, other


def pick_usa_base_pay_geo_band(
    high: tuple[int, int] | None,
    other: tuple[int, int] | None,
    *,
    oregon: tuple[int, int] | None = None,
    location_name: str = "",
    cfg: dict[str, Any] | None = None,
) -> tuple[int, int] | None:
    """Prefer OR-specific tier, else high-cost vs all-other from location/profile."""
    loc_pref = affirm_location_prefers_high_cost_band(location_name)
    if loc_pref is None and cfg is not None:
        loc_pref = profile_home_us_state(cfg) in {"CA", "WA", "NY", "NJ", "CT"}
    home = profile_home_us_state(cfg or {})
    loc = str(location_name or "").lower()
    if oregon and (home == "OR" or any(m in loc for m in AFFIRM_OTHER_STATE_MARKERS)):
        return oregon
    if loc_pref:
        return high or other
    return other or high


def affirm_location_prefers_high_cost_band(location_name: str) -> bool | None:
    """True/False when location clearly maps to a band; None defers to profile home state."""
    loc = str(location_name or "").lower()
    if not loc:
        return None
    if any(marker in loc for marker in AFFIRM_HIGH_COST_STATE_MARKERS):
        return True
    if any(marker in loc for marker in AFFIRM_OTHER_STATE_MARKERS):
        return False
    if "remote us" in loc or loc.strip() in {"remote", "united states", "us", "usa"}:
        return None
    return None


def extract_state_tier_pay_bands(detail_text: str) -> list[tuple[str, int, int]]:
    """Greenhouse pay-transparency bullets: 'Based in <states>: $low - $high.'"""
    if not detail_text:
        return []
    money = _money_capture_pattern()
    pattern = rf"Based in (?P<states>[^:]+?):\s*{money}\s*(?:-|–|—|to)\s*{money}"
    bands: list[tuple[str, int, int]] = []
    for match in re.finditer(pattern, detail_text, re.I):
        states_blob = " ".join(match.group("states").split())
        low = parse_money_amount(match.group(2))
        high = parse_money_amount(match.group(3))
        if low > 0 and high > 0 and high >= low:
            bands.append((states_blob, low, high))
    return bands


def twilio_pick_tier_band(
    bands: list[tuple[str, int, int]],
    location_name: str,
    cfg: dict[str, Any],
) -> tuple[int, int] | None:
    """Pick a Twilio tier band from location and profile home state (OR defaults to WA tier)."""
    if not bands:
        return None
    loc = str(location_name or "").lower()
    home = profile_home_us_state(cfg)

    def band_where(pred: Callable[[str], bool]) -> tuple[int, int] | None:
        for states_blob, low, high in bands:
            if pred(states_blob):
                return low, high
        return None

    if "san francisco" in loc or "bay area" in loc:
        hit = band_where(lambda b: "san francisco" in b.lower())
        if hit:
            return hit
    if "new york" in loc or "new jersey" in loc:
        hit = band_where(lambda b: "new york" in b.lower() or "new jersey" in b.lower())
        if hit:
            return hit
    if "washington" in loc and "d.c" not in loc:
        hit = band_where(lambda b: "washington state" in b.lower())
        if hit:
            return hit
    if "california" in loc or ", ca" in loc or " ca " in loc:
        hit = band_where(lambda b: "california" in b.lower())
        if hit:
            return hit

    if home == "CA":
        hit = band_where(lambda b: "san francisco" in b.lower())
        if hit:
            return hit
        hit = band_where(lambda b: "california" in b.lower())
        if hit:
            return hit
    if home == "NY":
        hit = band_where(lambda b: "new york" in b.lower())
        if hit:
            return hit
    if home == "NJ":
        hit = band_where(lambda b: "new jersey" in b.lower())
        if hit:
            return hit
    if home == "WA":
        hit = band_where(lambda b: "washington state" in b.lower())
        if hit:
            return hit
    if home in ("CO", "HI", "IL", "MD", "MA", "MN", "VT"):
        markers = {
            "CO": "colorado",
            "HI": "hawaii",
            "IL": "illinois",
            "MD": "maryland",
            "MA": "massachusetts",
            "MN": "minnesota",
            "VT": "vermont",
        }
        hit = band_where(lambda b, m=markers[home]: m in b.lower())
        if hit:
            return hit
    if home == "DC":
        hit = band_where(lambda b: "washington d.c" in b.lower() or "d.c." in b.lower())
        if hit:
            return hit

    # Remote US / Oregon / other: middle tier when present (includes Washington State).
    hit = band_where(lambda b: "washington state" in b.lower())
    if hit:
        return hit
    if len(bands) >= 2:
        return bands[1][1], bands[1][2]
    return bands[0][1], bands[0][2]


def extract_instacart_pay_bands(detail_text: str) -> list[tuple[str, int, int]]:
    """Instacart Greenhouse pay-input tiers (state list + USD range)."""
    if not detail_text:
        return []
    money = _money_capture_pattern()
    bands: list[tuple[str, int, int]] = []
    if "pay-input" in detail_text and 'class="title"' in detail_text:
        block_pat = re.compile(
            r'class="title">(?P<states>[^<]+)</div>\s*<div class="pay-range">'
            r'<span>\$?(?P<low>\d[\d,]*)</span>.*?<span>\$?(?P<high>\d[\d,]*)\s*USD?',
            re.I | re.S,
        )
        for match in block_pat.finditer(detail_text):
            states_blob = " ".join(match.group("states").split())
            low = parse_money_amount(match.group("low"))
            high = parse_money_amount(match.group("high"))
            if low > 0 and high > 0 and high >= low:
                bands.append((states_blob, low, high))
        if bands:
            return bands
    plain_pat = re.compile(
        rf"(?P<states>(?:All other states|WA|[A-Z]{{2}}(?:,\s*[A-Z]{{2}})+))\s+"
        rf"{money}\s*(?:—|-|–|to)\s*{money}\s*USD",
        re.I,
    )
    for match in plain_pat.finditer(detail_text):
        states_blob = " ".join(match.group("states").split())
        low = parse_money_amount(match.group(2))
        high = parse_money_amount(match.group(3))
        if low > 0 and high > 0 and high >= low:
            bands.append((states_blob, low, high))
    return bands


def _pay_band_includes_state(states_blob: str, state: str) -> bool:
    code = str(state or "").strip().upper()
    if not code or re.search(r"all other states", states_blob, re.I):
        return False
    codes = {m.upper() for m in re.findall(r"\b[A-Z]{2}\b", states_blob.upper())}
    return code in codes


def instacart_pick_tier_band(
    bands: list[tuple[str, int, int]],
    location_name: str,
    cfg: dict[str, Any],
) -> tuple[int, int] | None:
    """Map profile home state (or job location) to Instacart's per-state pay band."""
    if not bands:
        return None
    loc = str(location_name or "").lower()
    home = profile_home_us_state(cfg)
    state = home
    for code, markers in (
        ("CA", ("california", ", ca", " ca ")),
        ("NY", ("new york", ", ny", " ny ")),
        ("CT", ("connecticut", ", ct", " ct ")),
        ("NJ", ("new jersey", ", nj", " nj ")),
        ("WA", ("washington", ", wa", " wa ")),
        ("OR", ("oregon", ", or", " or ", "portland")),
    ):
        if any(m in loc for m in markers):
            state = code
            break

    for states_blob, low, high in bands:
        if _pay_band_includes_state(states_blob, state):
            return low, high
    for states_blob, low, high in bands:
        if re.search(r"all other states", states_blob, re.I):
            return low, high
    return None


def instacart_salary_from_detail(
    detail_text: str,
    cfg: dict[str, Any],
    *,
    location_name: str = "",
) -> tuple[str, str | None]:
    bands = extract_instacart_pay_bands(detail_text)
    if bands:
        picked = instacart_pick_tier_band(bands, location_name, cfg)
        if picked:
            low, high = picked
            return salary_range_status("base", low, high, cfg)
    comp_range = extract_comp_range_from_text(detail_text, location_name=location_name)
    if not comp_range:
        return "maybe", None
    kind, low, high = comp_range
    return salary_range_status(kind, low, high, cfg)


def extract_workday_state_pay_bands(detail_text: str) -> list[tuple[str, int, int]]:
    """Workday/Adobe: 'In California, the pay range for this position is $X - $Y'."""
    if not detail_text:
        return []
    money = _money_capture_pattern()
    sep = r"(?:-|–|—|--|to)"
    pattern = (
        rf"In\s+(?P<state>[A-Za-z][A-Za-z\s]+?),\s*"
        rf"the pay range for this position is\s*{money}\s*{sep}\s*{money}"
    )
    bands: list[tuple[str, int, int]] = []
    for match in re.finditer(pattern, detail_text, re.I):
        state = " ".join(match.group("state").split())
        low = parse_money_amount(match.group(2))
        high = parse_money_amount(match.group(3))
        if low >= 10_000 and high >= low:
            bands.append((state, low, high))
    return bands


_WORKDAY_STATE_LOCATION_MARKERS: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("california", ("california", ", ca", " ca ", "san jose", "san francisco", "los angeles", "palo alto", "santa clara", "san diego")),
    ("washington", ("washington", ", wa", " wa ", "seattle", "redmond", "bellevue")),
    ("new york", ("new york", ", ny", " ny ", "nyc", "manhattan", "brooklyn")),
    ("colorado", ("colorado", ", co", " co ", "denver", "boulder")),
    ("massachusetts", ("massachusetts", ", ma", " ma ", "boston", "cambridge")),
    ("texas", ("texas", ", tx", " tx ", "austin", "dallas", "houston")),
    ("illinois", ("illinois", ", il", " il ", "chicago")),
    ("oregon", ("oregon", ", or", " or ", "portland", "beaverton", "hillsboro")),
)


def workday_pick_state_pay_band(
    bands: list[tuple[str, int, int]],
    location_name: str,
) -> tuple[int, int] | None:
    """Pick a Workday state-specific pay band from job location text."""
    if not bands:
        return None
    loc = str(location_name or "").lower()
    for state, low, high in bands:
        if state.lower() in loc:
            return low, high
    for state_name, markers in _WORKDAY_STATE_LOCATION_MARKERS:
        if not any(marker in loc for marker in markers):
            continue
        for state, low, high in bands:
            if state.lower() == state_name or state_name in state.lower():
                return low, high
    return None


def extract_for_location_only_salary_bands(detail_text: str) -> list[tuple[str, int, int]]:
    """BlackRock/Talentbrew: 'For New York, NY Only the salary range ... is USD$X - USD$Y'."""
    if not detail_text:
        return []
    normalized = _normalize_comp_detail_text(detail_text)
    pattern = re.compile(
        r"For\s+(?P<location>[^.]+?)\s+Only\s+the\s+salary\s+range\s+for\s+this\s+position\s+is\s+"
        r"USD\$\s*([\d,]+(?:\.\d+)?)\s*(?:-|–|—|to)\s*USD\$\s*([\d,]+(?:\.\d+)?)",
        re.I,
    )
    bands: list[tuple[str, int, int]] = []
    for match in pattern.finditer(normalized):
        location = " ".join(match.group("location").split())
        low = parse_money_amount(match.group(2))
        high = parse_money_amount(match.group(3))
        if low >= 10_000 and high >= low:
            bands.append((location, low, high))
    return bands


def pick_for_location_only_salary_band(
    bands: list[tuple[str, int, int]],
    location_name: str,
    cfg: dict[str, Any] | None = None,
) -> tuple[int, int] | None:
    """Prefer OR band for OR profile/listing, else listing match, else NY, else any US band."""
    if not bands:
        return None
    loc = str(location_name or "").lower()
    home = profile_home_us_state(cfg or {})

    def band_matches_markers(band_loc: str, markers: tuple[str, ...]) -> bool:
        bl = band_loc.lower()
        return any(marker in bl for marker in markers)

    oregon_markers = ("oregon", ", or", " or ", "portland", "beaverton", "hillsboro")
    if home == "OR" or any(marker in loc for marker in oregon_markers):
        for band_loc, low, high in bands:
            if band_matches_markers(band_loc, oregon_markers):
                return low, high

    for state_name, markers in _WORKDAY_STATE_LOCATION_MARKERS:
        if not any(marker in loc for marker in markers):
            continue
        for band_loc, low, high in bands:
            bl = band_loc.lower()
            if state_name in bl or band_matches_markers(band_loc, markers):
                return low, high

    ny_markers = ("new york", ", ny", " ny ", "nyc", "manhattan", "brooklyn")
    for band_loc, low, high in bands:
        if band_matches_markers(band_loc, ny_markers):
            return low, high

    best = max(bands, key=lambda band: band[2])
    return best[1], best[2]


def _comp_range_match_plausible(match: re.Match[str], detail_text: str, low: int, high: int) -> bool:
    """Reject phone numbers and other sub-thousand false positives on generic range patterns."""
    if low >= 10_000 and high >= 10_000:
        return True
    if low >= 1_000 and high >= 1_000 and high >= low:
        return True
    start = match.start()
    prefix = detail_text[max(0, start - 20):start].lower()
    if any(token in prefix for token in ("+1", "call ", "phone", "tel:", "tel ")):
        return False
    return False


def twilio_salary_from_detail(
    detail_text: str,
    cfg: dict[str, Any],
    *,
    location_name: str = "",
) -> tuple[str, str | None]:
    bands = extract_state_tier_pay_bands(detail_text)
    if not bands:
        comp_range = extract_comp_range_from_text(detail_text, location_name=location_name)
        if not comp_range:
            return "maybe", None
        kind, low, high = comp_range
        return salary_range_status(kind, low, high, cfg)
    picked = twilio_pick_tier_band(bands, location_name, cfg)
    if not picked:
        return "maybe", None
    low, high = picked
    return salary_range_status("base", low, high, cfg)


