def location_text_looks_like_job_title(text: str) -> bool:
    """True when text is probably a job title mis-mapped as location."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if re.search(r",\s*[A-Z]{2}\b", raw):
        return False
    if re.search(r"\b(united states|usa|u\.s\.|remote|hybrid|on-site|onsite)\b", raw, re.I):
        return False
    if re.search(r"\b\d{5}\b", raw):
        return False
    lower = raw.lower()
    return any(token in lower for token in _JOB_TITLE_LOCATION_TOKENS)


