def location_text_looks_like_jd_prose(text: str) -> bool:
    """True when text is JD prose glued onto a location field."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if location_text_is_known_multi_segment_ats_location(raw):
        return False
    if len(raw) > 80:
        return True
    lower = raw.lower()
    if any(marker in lower for marker in _JD_PROSE_MARKERS):
        return True
    return location_text_looks_like_job_title(raw)

def parse_city_state_usa_segment(segment: str) -> tuple[str, str] | None:
    """Parse ``City, State, USA`` onsite segment; returns (city, state_code)."""
    core, _ = location_strip_paren_suffix(str(segment or "").strip())
    if not core or location_name_is_remoteish(core):
        return None
    parts = [p.strip() for p in re.split(r",\s*", core) if p.strip()]
    if len(parts) != 3:
        return None
    if not country_part_is_us(parts[2]):
        return None
    if _part_is_country_name(parts[0]):
        return None
    state_code = _parse_us_state_token(parts[1])
    if not state_code:
        return None
    return (parts[0], state_code)



def parse_state_usa_remote_segment(segment: str) -> str | None:
    """Return state code from ``State, USA, Remote`` segment."""
    core, _ = location_strip_paren_suffix(str(segment or "").strip())
    match = _GH_STATE_USA_REMOTE_RE.match(core) if core else None
    if not match:
        return None
    return _parse_us_state_token(match.group("state"))



def segment_is_city_state_usa_onsite(segment: str) -> bool:
    """Greenhouse/Datadog: ``New York, New York, USA`` without Remote."""
    return parse_city_state_usa_segment(segment) is not None



def segment_is_state_usa_remote(segment: str) -> bool:
    """Greenhouse/Datadog: ``California, USA, Remote`` (state-locked remote)."""
    core, _ = location_strip_paren_suffix(str(segment or "").strip())
    if not core:
        return False
    match = _GH_STATE_USA_REMOTE_RE.match(core)
    if not match:
        return False
    return bool(_parse_us_state_token(match.group("state")))



def _segment_is_recognized_ats_location(segment: str) -> bool:
    seg = str(segment or "").strip()
    if not seg:
        return False
    if (
        segment_is_state_usa_remote(seg)
        or parse_city_state_usa_segment(seg)
        or parse_us_country_state_segment(seg)
        or segment_is_us_country_remote(seg)
        or us_country_segment_to_city_state(seg)
        or extract_geo_from_geo_or_remote_segment(seg)
    ):
        return True
    if _segment_is_bare_remote(seg) and not location_text_is_remote_us_nationwide(seg):
        return True
    return segment_names_city_state_site(seg)



def location_text_is_known_multi_segment_ats_location(text: str) -> bool:
    """True for semicolon-separated ATS location lists (Datadog, multi-site GH)."""
    segments = location_work_segments(str(text or "").strip())
    if len(segments) < 2:
        return False
    recognized = sum(1 for seg in segments if _segment_is_recognized_ats_location(seg))
    return recognized >= 2 and recognized * 2 >= len(segments)



def location_has_mixed_remote_and_onsite_us(location_name: str) -> bool:
    """True when a posting lists both a US onsite/geo segment and a US-remote segment.

    Company-wide Greenhouse pattern (Pinterest and similar boards):

        San Francisco, CA, US; Remote, US

    means the role is open to people at that office and to people remote anywhere
    in the United States. Treat as US-remote workable, not onsite-only at the city.
    """
    return location_has_onsite_us_site_segments(
        location_name
    ) and location_has_remote_us_work_segments(location_name)


def location_is_geo_plus_us_nationwide_remote(location_name: str) -> bool:
    """US office/geo segment plus nationwide US remote (not state-locked remote only)."""
    return location_has_onsite_us_site_segments(
        location_name
    ) and location_has_us_nationwide_remote_segment(location_name)



def location_has_onsite_us_site_segments(location_name: str) -> bool:
    for segment in location_work_segments(location_name):
        if segment_is_city_state_usa_onsite(segment):
            return True
        if segment_names_city_state_site(segment) and not location_name_is_remoteish(segment):
            if segment_to_city_state_fragment(segment):
                return True
    return False



def location_has_remote_us_work_segments(location_name: str) -> bool:
    for segment in location_work_segments(location_name):
        if (
            segment_is_state_usa_remote(segment)
            or segment_is_us_country_state_remote(segment)
            or segment_is_us_country_remote(segment)
            or _segment_is_bare_remote(segment)
        ):
            return True
    return False



def location_text_has_explicit_remote_signal(text: str) -> bool:
    """True when text states remote/US-remote scope (not a bare country name)."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if location_name_is_remoteish(raw):
        return True
    lower = " ".join(raw.lower().replace("·", ",").split())
    if remote_scope_is_broad_us(lower):
        return True
    if re.search(r"\b(?:fully\s+)?remote\b", lower):
        return True
    if re.search(r"\b(?:work from home|work-from-home|telecommute|distributed)\b", lower):
        return True
    return False



def location_text_is_bare_us_country(text: str) -> bool:
    """True for country-only US labels without city/state or remote scope."""
    raw = str(text or "").strip()
    if not raw or location_name_is_remoteish(raw):
        return False
    if location_text_has_explicit_remote_signal(raw):
        return False
    if location_names_city_state_site(raw):
        return False
    lower = " ".join(raw.lower().replace("·", ",").split())
    return lower in {
        "united states",
        "united states of america",
        "us",
        "usa",
        "u.s.",
        "u.s.a.",
        "north america",
        "americas",
    }



def location_text_looks_like_non_geographic_label(text: str) -> bool:
    """True for company names, employment types, and other non-place loc_label noise."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if raw.upper() in {"EMEA", "APAC", "AMERICAS", "LATAM", "NA", "EU"}:
        return False
    lower = " ".join(raw.lower().split())
    if lower in _EMPLOYMENT_TYPE_LABELS:
        return True
    if location_text_looks_like_job_title(raw):
        return True
    if location_text_is_work_model_only(raw):
        return True
    if "," in raw or re.search(r"\b(?:united states|usa|remote|hybrid)\b", raw, re.I):
        return False
    if re.search(r"\s", raw):
        return False
    if len(raw) >= 4 and raw.isupper() and raw.isalpha():
        if location_text_indicates_non_us_worksite(raw):
            return False
        if raw.upper() not in US_STATE_CODES and not _abbreviate_country_token(raw, whole_segment=True):
            return True
    return False



def split_chained_city_state_locations(text: str) -> list[str]:
    """Parse ``Austin, TX, Beaverton, OR`` into separate city, ST sites."""
    parts = [p.strip() for p in str(text or "").split(",") if p.strip()]
    if len(parts) < 4 or len(parts) % 2:
        return []
    segments: list[str] = []
    for idx in range(0, len(parts), 2):
        city = parts[idx]
        state = _parse_us_state_token(parts[idx + 1])
        if not state or _part_is_country_name(city):
            return []
        city_display = city.title() if city.isupper() else city
        segments.append(f"{city_display}, {state}")
    return segments if len(segments) >= 2 else []



def split_bare_multi_city_label(text: str) -> list[str]:
    """Split comma-separated city names without states (e.g. ``AUSTIN, BEAVERTON``)."""
    raw = str(text or "").strip()
    if "," not in raw:
        return []
    parts = [p.strip() for p in raw.split(",") if p.strip()]
    if len(parts) < 2:
        return []
    if len(parts) == 2 and _second_part_is_country_code(parts[0], parts[1]):
        return []
    if len(parts) == 2 and (
        _parse_us_state_token(parts[1])
        or _abbreviate_state_token(parts[1])
        or parts[1].upper() in US_STATE_CODES
        or parts[1].upper() in {"US", "USA"}
    ):
        return []
    if any(
        " " in part
        or _parse_us_state_token(part)
        or _abbreviate_state_token(part)
        or _part_is_country_name(part)
        or _token_is_country_abbrev(part)
        or part.upper() in US_STATE_CODES
        or part.upper() in {"US", "USA"}
        or part.lower() in _BARE_REMOTE_SEGMENTS
        or location_name_is_remoteish(part)
        or not re.match(r"^[A-Za-z][A-Za-z .'-]{1,40}$", part)
        for part in parts
    ):
        return []
    return [part.title() if part.isupper() else part for part in parts]



def extract_hybrid_any_office_cities(text: str) -> list[str]:
    """Parse Greenhouse 'Hybrid- Any Office (City, ST, …)' multi-site locations."""
    raw = str(text or "").strip()
    match = _HYBRID_ANY_OFFICE_PREFIX_RE.match(raw)
    if not match:
        return []
    inner = match.group(1).strip()
    cities: list[str] = []
    for city, state in LOCATION_SITE_RE.findall(inner):
        city = city.strip()
        if city.upper().startswith("OR "):
            city = city[3:].strip()
        normalized = f"{city}, {state}"
        if normalized not in cities:
            cities.append(normalized)
    return cities



def hybrid_any_office_loc_label(text: str) -> str:
    """Greenhouse ``Hybrid- Any Office (City, ST, …)`` → stacked city, ST lines."""
    cities = extract_hybrid_any_office_cities(text)
    if not cities:
        return ""
    return "\n".join(cities)



def greenhouse_multi_segment_display_lines(text: str) -> list[str]:
    """Abbreviated lines for Greenhouse semicolon lists (Datadog State, USA, Remote)."""
    segments = location_work_segments(str(text or "").strip())
    if len(segments) < 2:
        return []
    lines: list[str] = []
    for segment in segments:
        state = parse_state_usa_remote_segment(segment)
        if state:
            lines.append(f"Remote, {state}")
            continue
        parsed = parse_us_country_state_segment(segment)
        if parsed and location_name_is_remoteish(parsed[2]):
            lines.append(f"Remote, {parsed[1]}")
            continue
        frag = segment_to_city_state_fragment(segment)
        if frag:
            lines.append(_abbreviate_location_segment(frag))
            continue
        if _segment_is_bare_remote(segment) or location_text_is_remote_us_nationwide(segment):
            continue
        abbrev = _abbreviate_location_segment(segment)
        if abbrev:
            lines.append(abbrev)
    return lines



def _polish_location_display_segment(text: str) -> str:
    """Title-case ALL CAPS US cities and abbreviate US state names for badges."""
    seg = str(text or "").strip()
    if not seg or "," not in seg:
        return seg
    parts = [p.strip() for p in seg.split(",") if p.strip()]
    if len(parts) < 2:
        return seg
    if not location_text_indicates_us_worksite(seg):
        return seg
    abbreviated = _abbreviate_location_segment(seg)
    if abbreviated == seg and not parts[0].isupper():
        return seg
    if "," not in abbreviated:
        return abbreviated
    city_out, state_out = [p.strip() for p in abbreviated.split(",", 1)]
    if parts[0].isupper() and parts[1].upper() not in {"US", "USA"}:
        city_out = parts[0].title()
    return f"{city_out}, {state_out}"



def netflix_normalize_location(location_name: str) -> str:
    """Normalize Netflix ``State - Remote,United States`` strings for classification."""
    text = str(location_name or "").strip()
    if not text:
        return text
    match = _NETFLIX_STATE_REMOTE_RE.match(text)
    if match:
        return f"{match.group('state').strip()}, USA, Remote"
    return text



def ibm_is_mega_multi_us_location(text: str) -> bool:
    raw = str(text or "").strip()
    if raw.count(",") < 6:
        return False
    return bool(_IBM_MEGA_US_LOC_RE.search(raw))



def ibm_parse_mega_multi_us_location(text: str) -> str:
    """Collapse IBM comma-separated multi-city US lists to pipe-separated cities."""
    raw = str(text or "").strip()
    if not raw:
        return ""
    tokens = [t.strip() for t in raw.split(",") if t.strip()]
    state_names = {name.lower() for name in US_STATE_NAME_TO_CODE} | {
        "united states",
        "us",
        "usa",
        "u.s.",
        "u.s.a.",
    }
    cities: list[str] = []
    for token in tokens:
        lower = " ".join(token.lower().split())
        if lower in state_names:
            continue
        if token.upper() in US_STATE_CODES:
            continue
        display = token.title() if token.isupper() else token
        if display and display not in cities:
            cities.append(display)
        if len(cities) >= 8:
            break
    if len(cities) >= 2:
        return " | ".join(cities)
    if len(cities) == 1:
        return cities[0]
    return "Multiple US locations"



def ibm_format_city_state_country(city: str, state: str, country: str) -> str:
    city_raw = str(city or "").strip()
    state_raw = str(state or "").strip()
    country_raw = str(country or "").strip()
    country_lower = " ".join(country_raw.lower().split())
    if ibm_is_mega_multi_us_location(city_raw) or (
        country_lower in {"united states", "usa", "us", "u.s.", "u.s.a."}
        and city_raw.count(",") >= 6
    ):
        return ibm_parse_mega_multi_us_location(city_raw)
    if country_lower in {"united states", "usa", "us", "u.s.", "u.s.a."}:
        state_code = _parse_us_state_token(state_raw.split(",")[0])
        if not state_code:
            state_code = US_STATE_NAME_TO_CODE.get(state_raw.lower())
        city_display = city_raw.title() if city_raw.isupper() else city_raw
        if state_code and "," not in city_raw:
            return f"{city_display}, {state_code}"
        if state_raw:
            return f"{city_display}, {state_raw}, United States"
        return f"{city_display}, United States"
    if country_lower in {"canada", "ca"}:
        prov = _abbreviate_state_token(state_raw) or state_raw
        return f"{city_raw}, {prov}, Canada"
    country_abbrev = _abbreviate_country_token(country_raw, whole_segment=True) or country_raw
    if state_raw and state_raw.lower() != country_lower:
        return f"{city_raw}, {state_raw}, {country_abbrev}"
    return f"{city_raw}, {country_abbrev}"



def ibm_normalize_card_location(card_location: str) -> str:
    raw = _normalize_whitespace(str(card_location or "").strip())
    if not raw or raw.lower() == "multiple cities":
        return raw
    match = re.match(r"^([A-Za-z][A-Za-z .'-]+),\s*([A-Z]{2,3})$", raw)
    if not match:
        return raw
    city, code = match.group(1).strip(), match.group(2).strip().upper()
    city_display = city.title() if city.isupper() else city
    if code == "US":
        return f"{city_display}, US"
    return f"{city_display}, {code}"



def ibm_work_arrangement_to_mode(work_arrangement: str) -> str | None:
    lower = " ".join(str(work_arrangement or "").strip().lower().split())
    if not lower:
        return None
    if lower == "remote":
        return "remote"
    if lower == "hybrid":
        return "hybrid"
    if lower in {"onsite", "on-site", "on site", "in person", "in-office", "in office"}:
        return "in-office"
    return None



def ibm_workplace_mode_from_text(*parts: str) -> str | None:
    for part in parts:
        fields = ibm_extract_structured_fields(str(part or ""))
        mode = ibm_work_arrangement_to_mode(fields.get("work_arrangement", ""))
        if mode:
            return mode
    for part in parts:
        for line in str(part or "").splitlines():
            candidate = " ".join(line.strip().split())
            if not candidate:
                continue
            mode = ibm_work_arrangement_to_mode(candidate)
            if mode:
                return mode
    return None



def ibm_extract_structured_fields(description_text: str) -> dict[str, str]:
    """Parse IBM detail-page City / State / Country / Work arrangement blocks."""
    lines = [line.strip() for line in str(description_text or "").splitlines() if line.strip()]
    fields: dict[str, str] = {}

    def _value_after(label_re: str) -> str:
        for index, line in enumerate(lines):
            if not re.match(label_re, line, re.I):
                continue
            if index + 1 >= len(lines):
                return ""
            nxt = lines[index + 1].strip()
            if re.match(label_re, nxt, re.I):
                return ""
            return nxt
        return ""

    city = _value_after(r"^City\s*/\s*Township\s*/\s*Village$")
    if city:
        fields["city"] = city
    state = _value_after(r"^State\s*/\s*Province$")
    if state:
        fields["state"] = state
    country = _value_after(r"^Country$")
    if country:
        fields["country"] = country
    work = _value_after(r"^Work\s+arrangement$")
    if work:
        fields["work_arrangement"] = work
    return fields



def ibm_resolve_location(
    location: str,
    description_text: str = "",
    *,
    card_location: str = "",
) -> str:
    """Prefer IBM structured City/State/Country blocks; normalize card/header hints."""
    header = _normalize_whitespace(str(location or "").strip())
    card = ibm_normalize_card_location(card_location)
    if header and (
        header.lower() in {"ibm", "professional"}
        or location_text_looks_like_jd_prose(header)
        or location_text_looks_like_job_title(header)
    ):
        header = ""
    if header and location_text_is_work_model_only(header):
        header = ""
    fields = ibm_extract_structured_fields(description_text)
    if fields.get("city") or fields.get("country"):
        built = ibm_format_city_state_country(
            fields.get("city", ""),
            fields.get("state", ""),
            fields.get("country", ""),
        )
        if built:
            return built
    for candidate in (header, card):
        if not candidate:
            continue
        if candidate.lower() == "multiple cities":
            continue
        if ibm_is_mega_multi_us_location(candidate):
            return ibm_parse_mega_multi_us_location(candidate)
        match = re.match(r"^([A-Za-z][A-Za-z .'-]+),\s*([A-Z]{2,3})$", candidate)
        if match:
            return ibm_normalize_card_location(candidate)
        parts = [p.strip() for p in candidate.split(",") if p.strip()]
        if len(parts) >= 3 and parts[-1].lower() in {"united states", "usa", "us"}:
            return ibm_format_city_state_country(parts[0], parts[1], parts[-1])
        return candidate
    if card:
        return card
    if header:
        return header
    if card_location and str(card_location).strip().lower() == "multiple cities":
        return "Multiple Cities"
    return ""

def location_text_is_work_model_only(text: str) -> bool:
    lower = " ".join(str(text or "").strip().lower().split())
    return lower in _WORK_MODEL_ONLY_LABELS


def location_text_is_scrape_note(text: str) -> bool:
    p = str(text or "").strip()
    return bool(p and _SCRAPE_NOTE_RE.match(p))


_EMPLOYMENT_TYPE_LABELS = frozenset(
    {
        "full-time",
        "full time",
        "part-time",
        "part time",
        "contract",
        "internship",
        "temporary",
        "perm",
        "n/a",
    }
)

def _truncate_at_jd_boundary(text: str) -> str:
    raw = str(text or "").strip()
    if not raw:
        return ""
    for pattern in (
        r"\s+You['']ll\b",
        r"\s+You'll\b",
        r"\s+The annual salary\b",
        r"\s+Behavioral Competencies\b",
        r"\s+Additional Locations:\b",
        r"\s+Business group:\b",
        r"\s+Proven track record\b",
        r"\s+THIS POSITION IS\b",
        r"\s+This position is\b",
        r"\s+Travel may be\b",
        r"\s+#job-location\b",
        r"\s+\{",
        r"\s+Role Summary\b",
    ):
        match = re.search(pattern, raw, re.I)
        if match:
            raw = raw[: match.start()].strip()
    return raw


def extract_geographic_location_fragment(text: str) -> str:
    """Pull city/state/country prefix from glued location+JD text."""
    raw = _truncate_at_jd_boundary(str(text or "").strip())
    if not raw:
        return ""
    match = re.match(
        r"^([A-Za-z][A-Za-z\s.'-]{1,60}?,\s*(?:[A-Z]{2,3}|[A-Za-z][A-Za-z\s.-]{2,40}))(?:\b|$)",
        raw,
    )
    if match:
        return match.group(1).strip()
    match = re.match(r"^([A-Za-z][A-Za-z\s.-]{1,50},\s*[A-Z]{2,3})\b", raw)
    if match:
        return match.group(1).strip()
    match = re.match(r"^Remote\s*,\s*[A-Z]{2}\b", raw, re.I)
    if match:
        return match.group(0).strip()
    return raw


def truncate_street_address_to_city(text: str) -> str:
    """For long street addresses, keep city/state/country tail when possible."""
    raw = str(text or "").strip()
    if not raw or len(raw) < 60:
        return raw
    match = re.search(
        r",\s*(\d{5,6}\s+[A-Za-z][A-Za-z\s-]+(?:,\s*[A-Za-z][A-Za-z\s-]+)?)\s*$",
        raw,
    )
    if match:
        return match.group(1).strip()
    match = re.search(r",\s*([A-Za-z][A-Za-z\s.]+,\s*[A-Z]{2}(?:\s+\d{5})?)\s*$", raw)
    if match:
        return match.group(1).strip()
    if len(raw) > 80:
        return raw[:77].rstrip(" ,.;") + "..."
    return raw


def _meta_part_is_location_candidate(part: str) -> bool:
    p = str(part or "").strip()
    if not p:
        return False
    if location_text_is_scrape_note(p):
        return False
    if re.match(r"^Posted\s+", p, re.I):
        return False
    if re.match(r"^JR\d+\b", p, re.I):
        return False
    if location_text_is_work_model_only(p):
        return False
    if location_text_looks_like_non_geographic_label(p):
        return False
    if location_text_looks_like_job_title(p) or location_text_looks_like_jd_prose(p):
        return False
    if location_text_is_bare_us_country(p):
        return True
    if location_text_has_geographic_place(p):
        return True
    if location_name_is_remoteish(p) and not location_text_is_remote_us_nationwide(p):
        return bool(re.search(r"[-–—|,/]", p) or re.search(r"\bremote\s*[-–—]", p, re.I))
    return False

def strip_company_prefix_from_location(location: str, company_name: str = "") -> str:
    """Drop leading employer name from geographic labels (e.g. Waymo Mountain View, CA)."""
    loc = str(location or "").strip()
    name = " ".join(str(company_name or "").strip().split())
    if not loc or not name:
        return loc
    if loc.lower() == name.lower():
        return loc

    def _remainder_looks_geographic(text: str) -> bool:
        remainder = str(text or "").strip()
        if not remainder or "," not in remainder:
            return False
        city = remainder.split(",", 1)[0].strip()
        return len(city) >= 2

    if loc.lower().startswith(name.lower() + " "):
        remainder = loc[len(name) :].strip()
        if _remainder_looks_geographic(remainder):
            return remainder
    first_token = name.split()[0]
    if first_token and len(first_token) >= 3:
        match = re.match(rf"^{re.escape(first_token)}\s+", loc, re.I)
        if match:
            remainder = loc[match.end() :].strip()
            if _remainder_looks_geographic(remainder):
                return remainder
    return loc


_DISPLAY_NAME_LOC_RE = re.compile(
    r"""['"]displayName['"]\s*:\s*['"]([^'"]+)['"]""",
    re.I,
)
_LIST_LITERAL_LOC_RE = re.compile(r"^\[['\"]([^'\"]+)['\"]\]")
_CAREER_SITE_JUNK_RE = re.compile(r"\s*Career Site Department:.*$", re.I)
_REMOTE_DASH_PREFIX_RE = re.compile(r"^remote\s*[-–—]\s*(.+)$", re.I)
_REMOTE_WRAPPED_RE = re.compile(r"^-\s*REMOTE\s*,\s*(.+?)\s*-$", re.I)
_VIRTUAL_STATE_RE = re.compile(r"^virtual\s*,\s*([A-Z]{2})\s*$", re.I)
_WORK_AT_HOME_PREFIX_RE = re.compile(r"^work at home\s*,\s*(.+)$", re.I)
_HYBRID_DASH_PREFIX_RE = re.compile(r"^hybrid\s*[-–—]\s*(.+)$", re.I)
_HYBRID_GLUE_PREFIX_RE = re.compile(r"^hybrid-\s*(.+)$", re.I)
_LEADING_POSTAL_RE = re.compile(r"^\d{5,6}\s+")
_TRAILING_POSTAL_PART_RE = re.compile(
    r"^(?:\d{5,6}(?:-\d{4})?|\d{2,3}-\d{3})$"
)
_MULTIPLE_LOCATIONS_LABEL_RE = re.compile(r"^multiple\s+locations?\s*$", re.I)
_CANADA_SELECT_LOC_RE = re.compile(
    r":\s*select\s+locations?\s*$", re.I
)
_HEADQUARTERS_PAREN_RE = re.compile(r"^Headquarters\s*\(([^)]+)\)\s*$", re.I)
_BRANCH_PREFIX_RE = re.compile(r"^Branch\s+\S{3}\s+", re.I)
_RA_REGION_PREFIX_RE = re.compile(r"^RA\s*[-–—]\s+", re.I)
_STATE_TRAILING_DIGIT_RE = re.compile(r"^([A-Z]{2})\d+$")
_STREET_ADDRESS_TAIL_RE = re.compile(
    r",\s*([A-Za-z][A-Za-z\s.'-]+?),\s*([A-Z]{2})(?:\s+\d{5}(?:-\d{4})?)?(?:,\s*(?:US|USA))?\s*$"
)

_STREET_ADDRESS_CITY_ALIASES: dict[str, str] = {
    "upper marlboro": "Marlboro",
    "north las vegas": "Las Vegas",
}

