def location_text_is_visa_or_perm_metadata(text: str) -> bool:
    """True when ATS location field holds visa/employment metadata, not geography."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if location_text_is_scrape_note(raw):
        return True
    lower = " ".join(raw.lower().split())
    if re.match(r"^(?:perm|temp|h1b|h-1b|contract|intern(?:ship)?)\b", lower):
        return True
    if re.match(r"^n\s*/\s*a$", lower):
        return True
    return False


def greenhouse_onsite_hint_from_description(description_text: str) -> str:
    """City/state from Greenhouse JD prose (e.g. Waymo 'Mountain View, CA office')."""
    text = str(description_text or "")
    if not text.strip():
        return ""
    patterns = (
        r"\b([A-Z][a-z]+(?:[\s-][A-Z][a-z]+){0,4},\s*[A-Z]{2})\s+office\b",
        r"report(?:s)? to (?:the )?(?:\w+\s+){0,4}([A-Z][a-z]+(?:[\s-][A-Z][a-z]+){0,4},\s*[A-Z]{2})\s+office\b",
    )
    candidates: list[str] = []
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            loc = re.sub(r"\s+", " ", match.group(1)).strip(" .")
            if len(loc) < 4 or location_name_is_remoteish(loc):
                continue
            if location_text_indicates_us_worksite(loc):
                candidates.append(loc)
    if not candidates:
        return ""
    def _city_words(label: str) -> int:
        return len(label.split(",", 1)[0].split())

    viable = [c for c in candidates if _city_words(c) >= 2 or len(c.split(",", 1)[0]) >= 8]
    pool = viable or candidates
    return min(pool, key=_city_words)[:160]


def greenhouse_url_slug_to_us_location(url: str) -> str:
    """Parse Waymo-style /jobs/...-mountain-view-california-united-states-UUID slugs."""
    path = urlparse(str(url or "")).path.lower()
    match = re.search(r"/jobs/([^/?#]+)", path)
    if not match:
        return ""
    slug = re.sub(
        r"-[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$",
        "",
        match.group(1),
        flags=re.I,
    )
    for state_name, _state_code in sorted(
        US_STATE_NAME_TO_CODE.items(), key=lambda item: len(item[0]), reverse=True
    ):
        state_slug = state_name.replace(" ", "-")
        marker = f"-{state_slug}-united-states"
        if not slug.endswith(marker):
            continue
        prefix = slug[: -len(marker)]
        city_tokens: list[str] = []
        for token in reversed(prefix.split("-")):
            if token in _GH_SLUG_TITLE_STOP_TOKENS:
                break
            city_tokens.insert(0, token)
            if len(city_tokens) >= 4:
                break
        if not city_tokens:
            tail = prefix.split("-")
            city_tokens = tail[-2:] if len(tail) >= 2 else tail[-1:]
        city = " ".join(city_tokens).title()
        if not city:
            return ""
        return f"{city}, {state_name.title()}"
    return ""


def greenhouse_resolve_location(
    location_name: str,
    url: str = "",
    content_html: str = "",
    company_name: str = "",
) -> str:
    """Replace visa/PERM Greenhouse placeholders with geographic location when possible."""
    loc = str(location_name or "").strip()
    needs_resolve = (
        not loc
        or location_text_is_visa_or_perm_metadata(loc)
        or location_text_is_scrape_note(loc)
        or location_text_is_work_model_only(loc)
    )
    if loc and not needs_resolve:
        return strip_company_prefix_from_location(loc, company_name)
    desc_text = html_to_plain(content_html) if content_html else ""
    for resolver in (
        lambda: greenhouse_url_slug_to_us_location(url),
        lambda: greenhouse_extract_locations_from_content(content_html),
        lambda: greenhouse_onsite_hint_from_description(desc_text),
        lambda: workday_onsite_hint_from_description(desc_text),
    ):
        resolved = str(resolver() or "").strip()
        if resolved and not location_text_is_visa_or_perm_metadata(resolved):
            return strip_company_prefix_from_location(resolved, company_name)
    return strip_company_prefix_from_location(loc, company_name)


def greenhouse_extract_locations_from_content(content: str) -> str:
    if not content:
        return ""
    text = html_to_plain(content)
    for pattern in (
        r"Available Locations?:\s*([^.\n]+?)(?:\.|\n|$)",
        r"Role Location[s]?:\s*([^.\n]+?)(?:\.|\n|$)",
        r"Office Location[s]?:\s*([^.\n]+?)(?:\.|\n|$)",
        r"Location[s]?:\s*([A-Za-z][^.\n]{3,80}?,\s*[A-Za-z][^.\n]{2,40})",
    ):
        match = re.search(pattern, text, re.I)
        if not match:
            continue
        loc = re.sub(r"\s+", " ", match.group(1)).strip(" .,&")
        if loc and not location_text_is_work_model_only(loc):
            return loc
    return ""


def geographic_loc_badge_label(job: Job) -> str:
    meta_parts = [p.strip() for p in re.split(r"\s*·\s*", job.meta or "") if p.strip()]
    label = sanitize_loc_label_for_badge(
        job.loc_label or "",
        title=job.title,
        description_text=job.description_text,
        meta_parts=meta_parts,
        company_name=getattr(job, "company_name", ""),
    )
    if label and (
        location_text_is_remote_us_nationwide(label)
        or location_text_is_scrape_note(label)
    ):
        label = ""
    if label:
        return label
    for part in meta_parts:
        if _meta_part_is_location_candidate(part):
            cleaned = sanitize_loc_label_for_badge(
                part,
                title=job.title,
                company_name=getattr(job, "company_name", ""),
            )
            if (
                cleaned
                and not location_text_is_remote_us_nationwide(cleaned)
                and location_text_has_geographic_place(cleaned)
            ):
                return cleaned
    return ""


_TALENTBREW_LISTING_NON_GEO_TOKENS = frozenset(
    {
        "flexible",
        "onsite",
        "on-site",
        "on site",
        "remote",
        "hybrid",
        "full-time",
        "full time",
        "part-time",
        "part time",
        "day",
        "night",
        "evening",
        "swing",
        "weekend",
    }
)

_DUPLICATE_CITY_LOCATION_RE = re.compile(r"^([^,]+),\s*\1\s*$", re.I)

def _normalize_primary_location_value(loc: str) -> str:
    """Parse Kaiser/Talentbrew Primary Location prose to City, ST."""
    parts = [p.strip() for p in str(loc or "").split(",") if p.strip()]
    if not parts:
        return ""
    if len(parts) >= 2 and _abbreviate_state_token(parts[0]) and not _abbreviate_state_token(
        parts[1]
    ):
        state = _abbreviate_state_token(parts[0])
        return f"{parts[1]}, {state}"
    if len(parts) >= 2:
        state = _abbreviate_state_token(parts[-1])
        if state and parts[0].lower() != parts[-1].lower():
            return f"{parts[0]}, {state}"
    return str(loc).strip()


def primary_location_from_description(description_text: str) -> str:
    """Extract Primary Location from Talentbrew/Kaiser JD plain text."""
    text = str(description_text or "")
    if not text.strip():
        return ""
    for pattern in (
        r"Primary Location\s*:?\s*([^\n]{3,120})",
        r"Primary Location\s+([A-Za-z][^\n]{3,80})",
    ):
        match = re.search(pattern, text, re.I)
        if not match:
            continue
        loc = re.sub(r"\s+", " ", match.group(1)).strip(" .,&")
        loc = re.split(
            r"\s+(?:Facility Name|Schedule|Shift|Salary|Job Number)\b",
            loc,
            maxsplit=1,
            flags=re.I,
        )[0].strip(" .,&")
        normalized = _normalize_primary_location_value(loc)
        if normalized and not location_text_looks_like_job_title(normalized):
            return normalized
    return ""


def _display_preserve_case(token: str) -> str:
    raw = str(token or "").strip()
    if not raw:
        return raw
    if raw.isupper():
        return raw
    if raw.islower():
        return raw.title()
    return raw


def _lookup_country_name_for_abbrev(abbrev: str) -> str | None:
    upper = str(abbrev or "").strip().upper()
    if not upper:
        return None
    iso2 = _COUNTRY_ALPHA3_TO_ISO2.get(upper, upper)
    for name, code in _COUNTRY_LABEL_TO_ABBREV.items():
        if code == iso2:
            return name
    return None


def _resolve_country_abbrev_token(token: str) -> str | None:
    raw = str(token or "").strip()
    if not raw:
        return None
    upper = raw.upper()
    if upper in _COUNTRY_ALPHA3_TO_ISO2:
        return _COUNTRY_ALPHA3_TO_ISO2[upper]
    abbrev = _abbreviate_country_token(raw, whole_segment=True)
    if abbrev:
        return abbrev
    if len(upper) in {2, 3} and upper in frozenset(_COUNTRY_LABEL_TO_ABBREV.values()):
        return upper
    return None


def _token_is_country_abbrev(token: str) -> bool:
    return _resolve_country_abbrev_token(token) is not None


def _second_part_is_country_code(city_part: str, tail_part: str) -> bool:
    country = _resolve_country_abbrev_token(tail_part)
    if not country:
        return False
    if len(str(tail_part or "").strip()) >= 3:
        return True
    state = _parse_us_state_token(tail_part)
    if not state:
        return True
    city_blob = str(city_part or "").strip().lower()
    if location_text_indicates_india(city_part):
        return True
    if location_text_indicates_non_us_worksite(city_part):
        return True
    if any(marker.strip() in city_blob for marker in NON_US_WORKSITE_MARKERS):
        return True
    return False


def _pick_country_name_or_abbrev(name_part: str, abbrev_part: str) -> str:
    abbrev = _resolve_country_abbrev_token(abbrev_part) or str(abbrev_part or "").strip().upper()
    display = _display_preserve_case(name_part)
    if len(display) <= _COUNTRY_NAME_SHORT_MAX:
        return display
    return abbrev


def _normalize_multiline_location_label(text: str) -> str:
    """Join stacked city + country lines (Workday Bangalore\\nInd) into one segment."""
    raw = str(text or "").strip()
    if "\n" not in raw:
        return raw
    lines = [ln.strip() for ln in raw.splitlines() if ln.strip()]
    if len(lines) == 2:
        if _resolve_country_abbrev_token(lines[1]) or _token_is_country_abbrev(lines[1]):
            return f"{lines[0]}, {lines[1]}"
    return raw


def _normalize_glued_city_country_comma(text: str) -> str:
    raw = str(text or "").strip()
    if not raw:
        return raw
    match = re.match(r"^([A-Za-z][A-Za-z .'-]+),([A-Za-z]{2,3})$", raw)
    if match:
        return f"{match.group(1)}, {match.group(2)}"
    return raw


def dedupe_country_name_and_code_in_location(text: str) -> str:
    """Collapse redundant country name + code pairs (Singapore, SG → Singapore)."""
    raw = _normalize_multiline_location_label(str(text or "").strip())
    raw = _normalize_glued_city_country_comma(raw)
    if not raw or "," not in raw:
        return raw
    parts = [p.strip() for p in re.split(r",\s*", raw) if p.strip()]
    if len(parts) < 2:
        return raw
    if len(parts) == 2:
        first, second = parts
        second_lower = " ".join(second.lower().split())
        if _part_is_country_name(second) or second_lower in _COUNTRY_NAME_PARTS:
            first_key = " ".join(first.lower().split())
            if first_key == second_lower:
                abbrev = _COUNTRY_LABEL_TO_ABBREV.get(second_lower) or _abbreviate_country_token(
                    second, whole_segment=True
                )
                if abbrev:
                    return _pick_country_name_or_abbrev(first, abbrev)
            return raw
        if second_lower in _COUNTRY_LABEL_TO_ABBREV:
            first_key = " ".join(first.lower().split())
            if first_key == second_lower:
                return _pick_country_name_or_abbrev(first, _COUNTRY_LABEL_TO_ABBREV[second_lower])
            return raw
        country_abbrev = _resolve_country_abbrev_token(second)
        if not country_abbrev:
            return raw
        country_name = _lookup_country_name_for_abbrev(second)
        first_key = " ".join(first.lower().split())
        if country_name and first_key == country_name:
            return _pick_country_name_or_abbrev(first, second)
        city_display = _display_preserve_case(first)
        if country_abbrev == "TP":
            return city_display
        return f"{city_display}, {country_abbrev}"
    last = parts[-1]
    prev = parts[-2]
    country_abbrev = _resolve_country_abbrev_token(last)
    if country_abbrev:
        prev_key = " ".join(prev.lower().split())
        expected = _COUNTRY_LABEL_TO_ABBREV.get(prev_key)
        if expected and expected == country_abbrev:
            parts = parts[:-1]
            parts[-1] = _pick_country_name_or_abbrev(prev, last)
            return ", ".join(parts)
    return ", ".join(parts)


def extract_work_model_from_location_prefix(location_name: str) -> str | None:
    raw = str(location_name or "").strip()
    if not raw:
        return None
    if location_has_remote_marker(raw):
        return "remote"
    if location_has_hybrid_marker(raw):
        return "hybrid"
    lower = " ".join(raw.lower().split())
    if lower.startswith("office based") or lower.startswith("office-based"):
        return "in-office"
    if lower.startswith("home based") or lower.startswith("home-based"):
        return "remote"
    if re.match(r"^intl(?:ernational)?[- ]remote\b", lower):
        return "remote"
    if re.match(r"^remote[- ]nationwide\b", lower):
        return "remote"
    return None


def strip_work_model_prefix_from_location(text: str) -> str:
    """Remove office/home/intl-remote/nationwide prefixes; keep geographic tail only."""
    raw = str(text or "").strip()
    if not raw:
        return raw
    lower = " ".join(raw.lower().split())
    if lower in {
        "intl remote",
        "international remote",
        "remote nationwide",
        "remote nationwide us",
        "remote nationwide, us",
        "remote, nationwide",
        "remote, nationwide us",
    }:
        return ""
    match = _WORK_MODEL_LOCATION_PREFIX_RE.match(raw)
    if match:
        geo = str(match.group("geo") or "").strip()
        return dedupe_country_name_and_code_in_location(geo) if geo else ""
    return raw


def dedupe_duplicate_city_in_location(text: str, description_text: str = "") -> str:
    """Fix City, City (county dup) and Kaiser City, County, ST listing tails."""
    raw = str(text or "").strip()
    if not raw:
        return raw
    if re.search(r"\s*(?:/|\||;)\s*", raw):
        return raw
    if _DUPLICATE_CITY_LOCATION_RE.match(raw):
        from_desc = primary_location_from_description(description_text)
        if from_desc:
            return from_desc
    parts = [p.strip() for p in raw.split(",") if p.strip()]
    while parts and parts[-1].lower().replace("-", " ") in _TALENTBREW_LISTING_NON_GEO_TOKENS:
        parts.pop()
    if len(parts) >= 3 and parts[0].lower() == parts[1].lower():
        state = _abbreviate_state_token(parts[2])
        if state:
            return f"{parts[0]}, {state}"
    if len(parts) == 2 and parts[0].lower() == parts[1].lower():
        from_desc = primary_location_from_description(description_text)
        if from_desc:
            return from_desc
    if len(parts) == 2 and re.match(r"^[^,\s]+,[^,\s]", raw):
        return raw
    return ", ".join(parts) if parts else raw


def talentbrew_normalize_listing_location(location: str, description_text: str = "") -> str:
    """Normalize Talentbrew listing labels (Kaiser city/county/schedule tails)."""
    raw = str(location or "").strip()
    if not raw:
        return raw
    return dedupe_duplicate_city_in_location(raw, description_text) or raw


def talentbrew_loc_from_path(path: str) -> str:
    """City slug from Talentbrew paths like /job/new-york/title/391/id."""
    match = re.search(r"/job/([^/]+)/", str(path or ""), re.I)
    if not match:
        return ""
    slug = match.group(1).replace("-", " ").strip()
    if not slug or slug.isdigit():
        return ""
    return slug.title()


def talentbrew_extract_location_from_detail(body: str) -> str:
    if not body:
        return ""
    plain = html_to_plain(body) if "<" in body else body
    from_primary = primary_location_from_description(plain)
    if from_primary:
        return from_primary
    for pattern in (
        r'<span class="job-location-scrape"[^>]*>([^<]+)</span>',
        r'<span class="job-location"[^>]*>([^<]+)</span>',
        r"\bLocation\b\s*\n+\s*([^\n]{3,120})",
        r"location:\s*['\"]?([^'\"\n]{3,120})",
    ):
        match = re.search(pattern, body if "<" in body else plain, re.I)
        if not match:
            continue
        location = html.unescape(re.sub(r"\s+", " ", match.group(1)).strip(" ,"))
        if location and not location_text_looks_like_job_title(location):
            return talentbrew_normalize_listing_location(location, plain)
    return ""


def talentbrew_resolve_listing_location(row: dict[str, str], detail_text: str = "") -> str:
    location = str(row.get("location") or "").strip()
    if location and not location_text_looks_like_job_title(location):
        return talentbrew_normalize_listing_location(location, detail_text)
    path_loc = talentbrew_loc_from_path(str(row.get("path") or ""))
    if path_loc:
        return path_loc
    detail_loc = talentbrew_extract_location_from_detail(detail_text)
    if detail_loc:
        return detail_loc
    return ""


def extract_level_based_comp_range(detail_text: str) -> tuple[int, int] | None:
    """Min low / max high across Level N: $X - $Y lines (Costco-, SpaceX-style)."""
    if not detail_text:
        return None
    money = _money_capture_pattern()
    dash = r"(?:-|–|—|to)"
    level_patterns = (
        rf"level\s+\d+\s*:?\s*{money}\s*{dash}\s*{money}",
        rf"level\s+[ivxlcdm]+\s*:\s*{money}\s*{dash}\s*{money}\s*(?:/|\s)per\s*/?\s*year",
        rf"pay range:\s*(?:level\s+[ivxlcdm\d]+|senior|staff|principal)\s*:?\s*{money}\s*{dash}\s*{money}\s*(?:/|\s)per\s*/?\s*year",
        rf"pay range:\s*[^:$\n]{{3,120}}:\s*{money}\s*{dash}\s*{money}\s*(?:/|\s)per\s*/?\s*year",
    )
    lows: list[int] = []
    highs: list[int] = []
    for pattern in level_patterns:
        for match in re.finditer(pattern, detail_text, re.I):
            low = parse_money_amount(match.group(1))
            high = parse_money_amount(match.group(2))
            if low > 0 and high > 0:
                if low > high:
                    low, high = high, low
                lows.append(low)
                highs.append(high)
    if not lows:
        return None
    return min(lows), max(highs)


def extract_grade_level_comp_range(detail_text: str) -> tuple[int, int] | None:
    """Ford-style salary/leadership grade lines: 'grade 5 and ranges from $X-$Y'."""
    if not detail_text:
        return None
    money = _money_capture_pattern()
    dash = r"(?:-|–|—|to)"
    pattern = rf"(?:salary grade|leadership level)\s+\d+\s+and ranges from\s*{money}\s*{dash}\s*{money}"
    lows: list[int] = []
    highs: list[int] = []
    for match in re.finditer(pattern, detail_text, re.I):
        low = parse_money_amount(match.group(1))
        high = parse_money_amount(match.group(2))
        if low > 0 and high > 0:
            if low > high:
                low, high = high, low
            lows.append(low)
            highs.append(high)
    if not lows:
        return None
    return min(lows), max(highs)


def extract_min_max_comp_range(detail_text: str) -> tuple[int, int] | None:
    """PG&E-style minimum/maximum pairs: 'minimum:$136,000 ... maximum: $232,000'."""
    if not detail_text:
        return None
    money = _money_capture_pattern()
    pattern = rf"(?:minimum|min):\s*{money}[\s\S]{{0,120}}?(?:maximum|max):\s*{money}"
    lows: list[int] = []
    highs: list[int] = []
    for match in re.finditer(pattern, detail_text, re.I):
        low = parse_money_amount(match.group(1))
        high = parse_money_amount(match.group(2))
        if low > 0 and high > 0:
            if low > high:
                low, high = high, low
            lows.append(low)
            highs.append(high)
    if not lows:
        return None
    return min(lows), max(highs)


def extract_comp_range_from_text(
    detail_text: str,
    *,
    location_name: str = "",
    cfg: dict[str, Any] | None = None,
) -> tuple[str, int, int] | None:
    if not detail_text:
        return None
    detail_text = _normalize_comp_detail_text(detail_text)
    loc_lower = str(location_name or "").lower()
    text_lower = detail_text.lower()
    if location_country_paren_remote_lock(location_name) or greenhouse_title_country_lock(location_name):
        return None
    if any(token in loc_lower for token in (", can", " canada", "ontario-can", "british columbia", " bc")):
        return None
    if re.search(r"\bfor canada based roles\b", text_lower):
        return None
    if re.search(r"\bin local currency\b", text_lower) and location_text_indicates_canada(
        location_name
    ):
        return None
    if location_name and location_text_indicates_non_us_worksite(location_name):
        return None
    money = _money_capture_pattern()
    explicit_usd_range = bool(
        re.search(
            rf"(?:salary range|pay range|base pay|base salary)[^.\n]{{0,160}}"
            rf"{money}\s*(?:-|–|—|to)\s*{money}\+?\s*usd\b",
            detail_text,
            re.I,
        )
    )
    if (
        not explicit_usd_range
        and re.search(r"\bin local currency\b", text_lower)
        and location_text_indicates_canada(detail_text)
    ):
        return None
    hiring_patterns = (
        rf"expected target hiring range(?: for [^.$]{{0,160}}?)? is\s*{money}\s*(?:-|–|—|/|to)\s*{money}",
        rf"expected hiring range(?: for [^.$]{{0,160}}?)? is\s*{money}\s*(?:-|–|—|/|to)\s*{money}",
        rf"hiring range for the [^.$]{{0,160}}? is\s*{money}\s*(?:-|–|—|/|to)\s*{money}",
        rf"(?:the\s+)?hiring range for this (?:position|role) in [^.$]{{0,220}}? is\s*{money}\s*(?:-|–|—|/|to)\s*{money}",
        rf"hiring range for the [^.$]{{0,160}}? is\s*{money}\s*(?:-|–|—|/|to)\s*{money}",
        rf"expected hiring range(?: for [^.$]{{0,120}}?)? is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"hiring range in usd from:\s*{money}\s*(?:to|-|–|—)\s*{money}\s*per\s+annum",
    )
    hiring_ranges = _collect_comp_ranges_from_patterns(detail_text, hiring_patterns)
    if hiring_ranges:
        low, high = max(hiring_ranges, key=lambda pair: pair[1])
        return "base", low, high
    location_line_ranges = _collect_comp_ranges_from_patterns(
        detail_text,
        (
            rf"(?:^|[\n\r])\s*[A-Za-z][^:\n]{{2,72}}:\s*{money}\s*(?:-|–|—)\s*{money}\s*for\b",
            rf"{money}\s*(?:-|–|—)\s*{money}\s*for\s+[^.\n]{{5,80}}(?:Engineer|Developer|Analyst|Architect|Manager|Director)\b",
        ),
    )
    if location_line_ranges:
        low, high = max(location_line_ranges, key=lambda pair: pair[1])
        return "base", low, high
    tiered = _extract_tiered_us_comp_range(
        detail_text, money, location_name=location_name
    )
    if tiered:
        low, high = tiered
        return "base", low, high
    zone_extents = extract_zone_salary_extents(detail_text)
    if zone_extents:
        low, high = zone_extents
        return "base", low, high
    level_extents = extract_level_based_comp_range(detail_text)
    if level_extents:
        low, high = level_extents
        return "base", low, high
    grade_extents = extract_grade_level_comp_range(detail_text)
    if grade_extents:
        low, high = grade_extents
        return "base", low, high
    min_max_extents = extract_min_max_comp_range(detail_text)
    if min_max_extents:
        low, high = min_max_extents
        return "base", low, high
    workday_bands = extract_workday_state_pay_bands(detail_text)
    if workday_bands:
        picked = workday_pick_state_pay_band(workday_bands, location_name)
        if picked:
            low, high = picked
            return "base", low, high
    patterns = (
        # Workday/Adobe (Phenom-hosted): U.S. wide band uses double hyphen; state lines handled above.
        rf"(?:the\s+)?u\.s\. pay range for this position\s*is\s*{money}\s*--\s*{money}\s*(?:annually\b)?",
        rf"pay range for this position\s*is\s*{money}\s*--\s*{money}\s*(?:annually\b)?",
        rf"the pay range for this position is\s*{money}\s*(?:-|–|—|--|to)\s*{money}\s*(?:annually\b)?",
        # Phenom/Humana (and similar): "Pay Range" label then disclaimer, then "$X - $Y per year".
        rf"pay range\b[\s\S]{{0,700}}?{money}\s*(?:-|–|—|to)\s*{money}\s*(?:per\s+year|/year|annually)\b",
        rf"estimated base salary range is between\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"typical starting salary range for this role is:\s*{money}\s*(?:-|–|—|to)\s*{money}\s*usd",
        rf"(?:u\.s\.|us)\s+salary range\s*{money}\s*(?:-|–|—|to)\s*{money}\s*usd",
        rf"base salary range\s*-\s*{money}\s*(?:to|-|–|—)\s*{money}",
        rf"estimated pay ranges for this role are as follows:\s*{money}\s*(?:to|-|–|—)\s*{money}",
        rf"targeted at\s*{money}\s*/?\s*yr\s*(?:to|-|–|—)\s*{money}\s*/?\s*yr",
        rf"expected hiring range(?: for [^.$]{{0,120}}?)? is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base pay range for this position is expected in the range below[\s:]*[\s\S]{{0,160}}?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"the pay range for this role is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"annual salary range for this position is[\s:]*[\s\S]{{0,80}}?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"(?:US|U\.S\.):\s*{money}\s*(?:-|–|—|to)\s*{money}\s*\(USD\)",
        rf"annual base pay scale\s*{money}\s*(?:-|–|—|to)\s*{money}",
        # AXS / Ultipro-style transparency line (must beat catch-all "4-6 years" noise).
        rf"pay\s+scale\s*:?\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"the range for this role is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base compensation range for this role is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"the pay range is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base pay for this role is between\s*{money}\s*(?:to|-|–|—)\s*{money}",
        rf"base pay range for this role is between\s*{money}\s+and\s*{money}",
        rf"base salary range\s+between\s*{money}\s*(?:to|and|-|–|—)\s*{money}",
        rf"salary range\s+between\s*{money}\s*(?:to|and|-|–|—)\s*{money}",
        rf"salary range for this role is\s*{money}\s*(?:to|-|–|—)\s*{money}",
        rf"expected base pay rates for the role will be between\s*{money}\s*(?:and|to|-|–|—)\s*{money}",
        rf"united states base range for this position is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base pay range for this role is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base pay range\s*(?:is|:)?\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"(?:pay range\s*:?\s*)+(?:pay range\s*)?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"the salary for this role will range from\s*{money}\s*(?:to|-|–|—)\s*{money}",
        rf"(?:usa,\s*)?[a-z]{{2}},\s*[^.\n]{{2,48}}-\s*{money}\s*-\s*{money}\s*usd annually",
        rf"(?:[\w\s,.]+?\s+)?base pay range for this role is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base salary range(?: listed)?(?: for this full-time position)?(?: excludes .*?)?\s*Base Pay Range\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"base salary range(?: for this position)?(?: for all u\.s\. candidates)?(?: is|:)?\s*(?:usd\s*)?{money}\s*(?:-|–|—|to)\s*(?:usd\s*)?{money}",
        # Greenhouse pay-input: title and pay-range spans split across divs (Reddit, etc.).
        rf"base salary range for this position is[\s\S]{{0,200}}?{money}[\s\S]{{0,80}}?{money}",
        rf"salary range for this position(?: \([^)]*\))?(?: for all u\.s\. candidates)?(?: is|:)?\s*(?:usd\s*)?{money}\s*(?:-|–|—|to)\s*(?:usd\s*)?{money}",
        rf"salary:\s*{money}\s*(?:-|–|—|to)\s*{money}\b",
        rf"salary\s*:?\s*{money}\s*(?:-|–|—|to)\s*{money}\s*/?\s*year",
        rf"pay range\s*:?\s*{money}\s*(?:-|–|—|to)\s*{money}\s*/?\s*year",
        rf"pay:\s*{money}\s*(?:-|–|—|to)\s*{money}\b",
        rf"{money}\s*(?:-|–|—|to)\s*{money}\s*usd\b",
        rf"{money}\s*(?:-|–|—|to)\s*{money}\s*(?:a year|per year|annually|/year|/yr)\b",
        rf"starting base salary between\s*{money}\s*(?:and|-)\s*{money}",
        rf"begin at\s*{money}\s*and up to\s*{money}",
        rf"annual salary of\s*{money}\s*(?:-|–|—|to)\s*{money}\s*usd",
        rf"(?:the\s+)?(?:u\.s\.|us)\s+base salary range for this full-time position is\s*{money}\s*(?:to|-|–|—)\s*{money}",
        rf"compensation range for this position is\s*:\s*{money}\s*(?:-|–|—)\s*{money}",
        rf"estimated annual cash salary(?: for this role)? is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"salary range\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"expected to range from\s*{money}\s*to\s*{money}",
        rf"starting salary[^.\n]{{0,120}}?\s*{money}\s*to\s*{money}",
        rf"annual\s+(?:u\.s\.|us)\s+base\s+salary\s+range\b[\s\S]{{0,240}}?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"estimated\s+pay\s+range\b[\s\S]{{0,240}}?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"(?:USD|US\$)\s*(\d[\d,]*(?:\.\d+)?(?:\s*[kKmM])?)\s*(?:-|–|—|to)\s*(?:USD|US\$)\s*(\d[\d,]*(?:\.\d+)?(?:\s*[kKmM])?)",
        rf"(?:USD|US\$)\s*{money}\s*(?:-|–|—|to)\s*(?:USD|US\$)?\s*{money}\s*/\s*year",
        rf"salary range:\s*{money}\s*(?:-|–|—|to)\s*{money}\+?\s*(?:usd\b)?",
        rf"salary range\s*:?\s*{money}\s*(?:-|–|—|to)\s*{money}\+?\s*(?:usd\b)?",
        # Prose between amounts: "between $145,000 [minimum…] to $261,500"
        rf"reasonably expected salary range is between\s*{money}[\s\S]{{0,180}}?(?:to|-|–|—)\s*{money}",
        rf"salary range is between\s*{money}[\s\S]{{0,180}}?(?:to|-|–|—)\s*{money}",
        rf"local pay range\s*{money}\s*(?:-|–|—|to)\s*{money}\s*(?:usd\b)?",
        rf"full-time salary range\s*:?\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"anticipated base salary range[^.$]{{0,160}}?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"typical pay range for this role is\s*{money}\s*(?:-|–|—|to)\s*{money}",
        rf"pay transparency[^.$]{{0,240}}?{money}\s*(?:-|–|—|to)\s*{money}",
        rf"{money}\s*usd\s*(?:-|–|—|to)\s*{money}\s*usd",
        rf"salary range\s*{money}\s*/year\s+to\s*{money}\s*/year",
        rf"salary range\s*{money}\s*(?:-|–|—|to)\s*{money}\s*(?:per year|/year|annually)",
        rf"\(\s*{money}\s*(?:-|–|—|to)\s*{money}\s*\)",
        rf"{money}\s*(?:-|–|—|to)\s*{money}\b",
    )
    for pattern in patterns:
        # Prefer finditer so an early "4-6 years" style hit does not block a later Pay Scale.
        for match in re.finditer(pattern, detail_text, re.I | re.S):
            low = parse_money_amount(match.group(1))
            high = parse_money_amount(match.group(2))
            low, high = apply_shared_k_salary_suffix(low, high, match.group(0))
            if low <= 0 or high <= 0:
                continue
            if low > high:
                low, high = high, low
            if not _comp_range_match_plausible(match, detail_text, low, high):
                continue
            return "base", low, high
    return None


def salary_from_detail_text(
    detail_text: str,
    cfg: dict[str, Any],
    *,
    location_name: str = "",
    job_loc: str | None = None,
    title: str = "",
) -> tuple[str, str | None]:
    # Posted JD pay: badge for display/filter even when loc is excluded (onsite US, etc.).
    # Levels.fyi reference fallback stays gated in apply_company_salary_reference.
    comp_range = extract_comp_range_from_text(detail_text, location_name=location_name)
    if not comp_range:
        return "maybe", None
    kind, low, high = comp_range
    return salary_range_status(kind, low, high, cfg, title=title)


def workday_extract_comp_range(detail_text: str) -> tuple[str, int, int] | None:
    return extract_comp_range_from_text(detail_text)


def workday_salary_from_detail(detail_text: str, cfg: dict[str, Any]) -> tuple[str, str | None]:
    comp_range = workday_extract_comp_range(detail_text)
    if not comp_range:
        return "maybe", None
    kind, low, high = comp_range
    return salary_range_status(kind, low, high, cfg)


def sap_successfactors_salary_guess(title: str, location_name: str, cfg: dict[str, Any]) -> tuple[str, str] | None:
    title_lower = (title or "").lower()
    loc_lower = (location_name or "").lower()
    seniorish = any(token in title_lower for token in ("architect", "manager", "lead", "principal", "director", "head", "chief"))
    clearly_non_us = not any(
        token in loc_lower
        for token in (
            ", us",
            " usa",
            " united states",
            "new york",
            "palo alto",
            "san jose",
            "newtown square",
            "herndon",
            "washington dc",
            "remote us",
            "remote - us",
            "remote - usa",
        )
    )
    if clearly_non_us and not seniorish:
        floor_label = salary_floor_label(cfg)
        return "low", f"Likely < {floor_label}"
    return None


def successfactors_salary_from_detail(
    company: dict[str, Any], title: str, location_name: str, detail_text: str, cfg: dict[str, Any]
) -> tuple[str, str | None]:
    comp_range = successfactors_extract_comp_range(
        detail_text, location_name=location_name
    )
    if comp_range:
        kind, low, high = comp_range
        return salary_range_status(kind, low, high, cfg)
    if company.get("salary_heuristic") == "sap":
        guessed = sap_successfactors_salary_guess(title, location_name, cfg)
        if guessed:
            return guessed
    return "maybe", None


def successfactors_loc_from_detail(
    company: dict[str, Any],
    location_name: str,
    work_model: str,
    cfg: dict[str, Any] | None = None,
) -> tuple[str, str | None]:
    employer_region = company_employer_region(company)
    default_loc = str(company.get("default_loc") or "local")
    remote_source = ""
    if work_model and location_name_is_remoteish(work_model):
        remote_source = work_model
    elif location_name and location_name_is_remoteish(location_name):
        remote_source = location_name
    if remote_source:
        job_loc = classify_remote_loc(remote_source, employer_region)
        if job_loc:
            return job_loc, None
    geo = sanitize_loc_label_for_badge(location_name) or str(location_name or "").strip()
    if geo:
        if default_loc == "local":
            if location_within_local_radius(geo, cfg):
                return "local", geo
            return "excluded", geo
        return "excluded", geo
    if default_loc == "local":
        return None, None
    return default_loc, None


def successfactors_fetch_search(
    search_base: str,
    query: str,
    origin: str,
    *,
    location: str = "",
) -> list[dict[str, str]]:
    loc_key = re.sub(r"[^a-z0-9]+", "-", location.lower()).strip("-")[:40] if location else "all"
    cache_key = f"sf-{origin}-{loc_key}-{query}"
    cached = cache_get(SCRIPT_DIR, cache_key)
    if cached is not None:
        try:
            return json.loads(cached)
        except json.JSONDecodeError:
            pass
    base = search_base.rstrip("/")
    if query.strip():
        url = f"{base}/?q={urllib.parse.quote(query.strip())}"
        if location.strip():
            url += f"&locationsearch={urllib.parse.quote(location.strip())}"
    elif location.strip():
        url = f"{base}/?locationsearch={urllib.parse.quote(location.strip())}"
    else:
        url = f"{base}/"
    code, _, body = http_get(url)
    if code != 200:
        return []
    jobs = successfactors_parse_search(body, origin)
    cache_set(SCRIPT_DIR, cache_key, json.dumps(jobs))
    return jobs


def search_successfactors(company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]) -> CompanyResult:
    return _search_successfactors(company, cfg, overrides)


def search_smartrecruiters(company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]) -> CompanyResult:
    return _search_smartrecruiters(company, cfg, overrides)


def rss_parse_pub_date(value: str | None) -> int:
    text = (value or "").strip()
    if not text:
        return 0
    try:
        dt = email.utils.parsedate_to_datetime(text)
    except (TypeError, ValueError, IndexError):
        return 0
    if dt is None:
        return 0
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return int(dt.timestamp())


def rss_fetch_items(company: dict[str, Any]) -> tuple[list[dict[str, str]], str | None]:
    feed_url = str(company.get("rss_url") or "").strip()
    if not feed_url:
        return [], "RSS feed missing URL"
    cache_key = f"rss-{company['id']}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=float(company.get("cache_ttl_hours", 12)))
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, list):
                for row in payload:
                    if isinstance(row, dict) and row.get("url"):
                        row["url"] = str(row["url"]).replace("http://", "https://", 1).split("?")[0]
                return payload, None
        except json.JSONDecodeError:
            pass
    code, _, body = http_get(feed_url)
    if code != 200 or not body:
        return [], f"RSS feed returned HTTP {code}"
    try:
        root = ET.fromstring(body)
    except ET.ParseError:
        return [], "RSS feed returned invalid XML"
    job_ns = "{https://recruiterbox.com/rss/job/}"
    rows: list[dict[str, str]] = []
    for item in root.findall("./channel/item"):
        title = str(item.findtext("title") or "").strip()
        link = str(item.findtext("link") or item.findtext("guid") or "").strip()
        job_id_match = re.search(r"/(?:jobs|remote-jobs)/([^/?#]+)/?", link)
        city = str(item.findtext(f"{job_ns}locationCity") or "").strip()
        state = str(item.findtext(f"{job_ns}locationState") or "").strip()
        country = str(item.findtext(f"{job_ns}locationCountry") or "").strip()
        team = str(item.findtext(f"{job_ns}team") or "").strip()
        position_type = str(item.findtext(f"{job_ns}positionType") or "").strip()
        region = str(item.findtext("region") or "").strip()
        skills = str(item.findtext("skills") or "").strip()
        category = str(item.findtext("category") or "").strip()
        expires_at = str(item.findtext("expires_at") or "").strip()
        if not position_type:
            position_type = str(item.findtext("type") or "").strip()
        salary_range = str(
            item.findtext("salary_range")
            or item.findtext(f"{job_ns}salaryRange")
            or ""
        ).strip()
        rows.append(
            {
                "title": title,
                "url": link.replace("http://", "https://", 1).split("?")[0],
                "job_id": job_id_match.group(1) if job_id_match else "",
                "description_html": str(item.findtext("description") or ""),
                "posted": str(item.findtext("pubDate") or "").strip(),
                "location": ", ".join(x for x in (city, state, country) if x and x.lower() != "none"),
                "team": team,
                "position_type": position_type,
                "region": region,
                "skills": skills,
                "category": category,
                "expires_at": expires_at,
                "salary_range": salary_range,
            }
        )
    cache_set(SCRIPT_DIR, cache_key, json.dumps(rows))
    return rows, None


def wwr_headquarters_label(description_html: str) -> str:
    text = html.unescape(description_html or "")
    match = re.search(r"Headquarters:</strong>\s*([^<\n]+)", text, re.I)
    if not match:
        return ""
    label = " ".join(match.group(1).split()).strip(" ,")
    if label.lower() in {"english version", "url:"}:
        return ""
    return label


def wwr_employer_region(hq_label: str) -> str:
    lower = (hq_label or "").lower()
    if not lower:
        return "international"
    if any(token in lower for token in ("remote - us", "united states", " usa", " us", "u.s.")):
        return "us"
    return "international"


def wwr_remote_scope(region: str, hq_label: str) -> str:
    hq = str(hq_label or "").strip()
    if hq and location_name_is_remoteish(hq):
        return hq
    lower = str(region or "").strip().lower()
    mapping = {
        "anywhere in the world": "Anywhere",
        "usa only": "Remote - US",
        "north america only": "Remote - North America",
        "americas only": "Remote - Americas",
        "latin america only": "Remote - Latin America",
        "europe only": "Remote - Europe",
        "uk only": "Remote - UK",
        "canada only": "Remote - Canada",
        "emea only": "Remote - EMEA",
        "asia only": "Remote - Asia",
        "africa only": "Remote - Africa",
        "oceania only": "Remote - Oceania",
    }
    if lower in mapping:
        return mapping[lower]
    return hq or str(region or "").strip()


def wwr_split_title(title: str) -> tuple[str, str]:
    text = str(title or "").strip()
    if ":" not in text:
        return "", text
    company_name, role_title = text.split(":", 1)
    return company_name.strip(), role_title.strip()


def wwr_salary_from_range_label(range_label: str, cfg: dict[str, Any]) -> tuple[str, str | None]:
    """Parse WWR Read API / RSS salary_range bucket labels."""
    raw = str(range_label or "").strip()
    if not raw or "prefer not to share" in raw.lower():
        return "maybe", None
    comp = extract_comp_range_from_text(raw)
    if comp:
        kind, low, high = comp
        return salary_range_status(kind, low, high, cfg)
    bucket_match = re.search(
        r"\$?\s*(\d[\d,]*(?:\.\d+)?(?:\s*[kKmM])?)\s*(?:-|–|—|to)\s*\$?\s*(\d[\d,]*(?:\.\d+)?(?:\s*[kKmM])?)\s*(?:USD|usd)?",
        raw,
    )
    if bucket_match:
        low = parse_money_amount(bucket_match.group(1))
        high = parse_money_amount(bucket_match.group(2))
        if low > 0 and high > 0:
            return salary_range_status("base", low, high, cfg)
    or_more = re.search(r"\$?\s*(\d[\d,]*)\s*or more", raw, re.I)
    if or_more:
        low = parse_money_amount(or_more.group(1))
        if low > 0:
            return salary_range_status("base", low, low, cfg)
    return "maybe", None


def wwr_extract_salary(description_text: str, cfg: dict[str, Any]) -> tuple[str, str | None]:
    if not description_text:
        return "maybe", None
    comp = extract_comp_range_from_text(description_text)
    if comp:
        kind, low, high = comp
        return salary_range_status(kind, low, high, cfg)
    for pattern in (
        r"Base Salary Range\s*\$?\s*(\d[\d,]*)\s*-\s*\$?\s*(\d[\d,]*)\s*USD",
        r"salary range\s*\$?\s*(\d[\d,]*)\s*-\s*\$?\s*(\d[\d,]*)\s*USD",
        r"pay range\s*(?:is|:)?\s*\$?\s*(\d[\d,]*)\s*(?:-|–|—|to)\s*\$?\s*(\d[\d,]*)\s*USD",
        r"compensation(?: range)?\s*(?:is|:)?\s*\$?\s*(\d[\d,]*)\s*(?:-|–|—|to)\s*\$?\s*(\d[\d,]*)\s*USD",
    ):
        match = re.search(pattern, description_text, re.I | re.S)
        if not match:
            continue
        low = parse_money_amount(match.group(1))
        high = parse_money_amount(match.group(2))
        if low > 0 and high > 0 and high >= low:
            return salary_range_status("base", low, high, cfg)
    return "maybe", None


def wwr_specific_non_us_hq(hq_label: str) -> bool:
    lower = (hq_label or "").strip().lower()
    if not lower or lower == "remote":
        return False
    if any(token in lower for token in ("united states", "remote - us", " usa", " us", "u.s.")):
        return False
    return True


def wwr_has_non_english_markers(title: str, description_text: str) -> bool:
    text = f"{title} {description_text}".lower()
    patterns = (
        r"\bpessoa\b",
        r"\bengenheir[ao]\b",
        r"\bprofissional\b",
        r"\bsobre a\b",
        r"\bbenef[ií]cios\b",
        r"\brequisitos\b",
        r"\bqualifica[cç][õo]es\b",
        r"\bconhecimento\b",
        r"\bexperi[eê]ncia\b",
        r"\bnossa\b",
        r"\bvaga\b",
        r"\bportugu[eê]s\b",
        r"\bvoc[eê]\b",
        r"\bcomo profissional\b",
    )
    return any(re.search(pattern, text) for pattern in patterns)


def wwr_has_low_signal_markers(description_text: str) -> bool:
    lower = (description_text or "").lower()
    return any(
        marker in lower
        for marker in (
            "timely updates on job openings",
            "join our community",
            "members from",
            "applications through other channels will not be reviewed",
        )
    )


def wwr_match_penalty(title: str, description_text: str, hq_label: str, region: str) -> tuple[int, str | None]:
    reasons: list[str] = []
    if wwr_specific_non_us_hq(hq_label) and str(region or "").strip().lower() == "anywhere in the world":
        reasons.append("non-US HQ with only broad global-feed scope")
    if wwr_has_non_english_markers(title, description_text):
        reasons.append("locale-specific / non-English posting")
    if wwr_has_low_signal_markers(description_text):
        reasons.append("community-style / low-signal posting")
    if not reasons:
        return 0, None
    return len(reasons), "Downrated (WWR intl fit): " + "; ".join(reasons) + "."


