def roberthalf_parse_search(html_text: str) -> list[str]:
    return extract_search_links(
        html_text,
        "https://www.roberthalf.com",
        r'href="([^"]*?/us/en/job/[^"]+)"',
    )


def roberthalf_arrangement_label(description_html: str, locality: str) -> tuple[str, str | None]:
    raw = str(description_html or "")
    arrangement = ""
    for pattern in (
        r"Work Location/Arrangement:\s*(.+?)(?:Pay:|Position Overview|Key Responsibilities|Required Qualifications)",
        r"Location:\s*(.+?)(?:Salary:|What You’ll Work On|What We're Looking For|What We’re Looking For)",
    ):
        match = re.search(pattern, raw, re.I | re.S)
        if match:
            arrangement = " ".join(match.group(1).split()).strip(" |,-")
            break
    locality = locality.strip()
    lower = arrangement.lower()
    if "remote" in lower:
        remote_scope = arrangement if any(token in lower for token in ("united states", "usa", "u.s.")) else "Remote - United States"
        return (f"{remote_scope}; {locality}" if locality and locality.lower() not in lower else remote_scope), (
            f"{locality} · remote" if locality else remote_scope
        )
    if arrangement:
        if locality and locality.lower() not in lower:
            label = f"{arrangement}; {locality}"
        else:
            label = arrangement
        return label, label.replace(";", " ·", 1)
    return locality, locality or None


def roberthalf_fetch_detail(url: str, cache_ttl_hours: float = 12.0) -> dict[str, Any] | None:
    body = cached_html_fetch(url, "roberthalf-detail", cache_ttl_hours=cache_ttl_hours)
    if not body:
        return None
    postings = extract_json_ld_jobpostings(body)
    if not postings:
        return None
    posting = postings[0]
    address = posting.get("jobLocation", {}).get("address", {}) if isinstance(posting.get("jobLocation"), dict) else {}
    locality = str(address.get("addressLocality") or "").strip() if isinstance(address, dict) else ""
    location_name, meta_location = roberthalf_arrangement_label(str(posting.get("description") or ""), locality)
    match = re.search(r"/([^/]+)$", urllib.parse.urlparse(url).path.rstrip("/"))
    return {
        "job_id": match.group(1) if match else "",
        "title": str(posting.get("title") or "").strip(),
        "description_text": html_to_plain(str(posting.get("description") or "")),
        "posted_ts": parse_iso_ts(str(posting.get("datePosted") or "")),
        "salary": posting,
        "location_name": location_name,
        "meta_location": meta_location,
        "employment": jsonld_employment_type(posting),
    }


