def wellfound_session_path(company: dict[str, Any]) -> Path:
    raw = str(company.get("session_path") or str(TMP_WELLFOUND_SESSION_PATH)).strip()
    path = Path(raw).expanduser()
    if not path.is_absolute():
        path = SCRIPT_DIR / path
    return path


def wellfound_profile_dir(company: dict[str, Any]) -> Path:
    raw = str(company.get("profile_dir") or str(TMP_WELLFOUND_PROFILE_DIR)).strip()
    path = Path(raw).expanduser()
    if not path.is_absolute():
        path = SCRIPT_DIR / path
    return path


def wellfound_detect_cdp_url(company: dict[str, Any]) -> str | None:
    explicit = str(company.get("cdp_url") or "").strip()
    if explicit:
        return explicit
    if company.get("cdp_auto") is False:
        return None
    for port in (9222,):
        probe = f"http://127.0.0.1:{port}/json/version"
        try:
            with urllib.request.urlopen(probe, timeout=1) as resp:
                if resp.status == 200:
                    return f"http://127.0.0.1:{port}"
        except (OSError, urllib.error.URLError, TimeoutError):
            continue
    return None


def wellfound_role_urls(company: dict[str, Any]) -> list[str]:
    urls = [str(url).strip() for url in (company.get("role_urls") or []) if str(url).strip()]
    if not urls:
        browse = str(company.get("browse_url") or "").strip()
        if browse:
            urls = [browse]
    seen: set[str] = set()
    deduped: list[str] = []
    for url in urls:
        if url not in seen:
            seen.add(url)
            deduped.append(url)
    return deduped


def wellfound_money(raw: str, k_suffix: str | None = None) -> int:
    text = str(raw or "").replace(",", "").strip()
    if not text:
        return 0
    if k_suffix or text.lower().endswith("k"):
        base = text[:-1] if text.lower().endswith("k") else text
        try:
            return int(float(base) * 1000)
        except ValueError:
            return 0
    value = parse_money_amount(text)
    if 0 < value < 1000:
        return value * 1000
    return value


def wellfound_extract_salary(
    compensation: str, cfg: dict[str, Any], description_text: str = ""
) -> tuple[str, str | None]:
    text = f"{compensation} {description_text}".strip()
    if wellfound_has_indian_compensation(text):
        return "maybe", None
    match = re.search(
        r"\$?\s*(\d[\d,]*(?:\.\d+)?)\s*([kK])?\s*(?:-|–|—|to)\s*\$?\s*(\d[\d,]*(?:\.\d+)?)\s*([kK])?",
        text,
    )
    if match:
        low = wellfound_money(match.group(1), match.group(2))
        high = wellfound_money(match.group(3), match.group(4))
        if low > 0 and high > 0 and high >= low:
            return salary_range_status("base", low, high, cfg)
    return wwr_extract_salary(description_text, cfg)


def wellfound_has_devanagari(text: str) -> bool:
    return bool(re.search(r"[\u0900-\u097F]", text or ""))


def wellfound_has_indian_compensation(text: str) -> bool:
    comp = str(text or "")
    if re.search(r"₹|\bINR\b|\bRs\.?\b|\blakh\b|\blakhs\b", comp, re.I):
        return True
    if re.search(r"\d+(?:\.\d+)?\s*L\s*(?:[–—\-]|to)\s*(?:₹\s*)?\d+(?:\.\d+)?\s*L\b", comp, re.I):
        return True
    return bool(re.search(r"(?:₹\s*)?\d+(?:\.\d+)?\s*L\b", comp, re.I))


def wellfound_non_us_fit_reason(
    title: str,
    description_text: str,
    compensation: str,
    location_names: list[str] | None = None,
    location_label: str = "",
    detail_text: str = "",
    remote: bool = False,
) -> str | None:
    pay_blob = f"{compensation} {description_text} {detail_text}"
    loc_blob = ", ".join([location_label, *(location_names or [])])
    full_blob = f"{title} {pay_blob} {loc_blob}"
    if wellfound_has_devanagari(full_blob):
        return "Hindi/Devanagari text in posting"
    if wellfound_has_indian_compensation(pay_blob):
        return "India-market compensation (₹ / lakh)"
    if posting_text_indicates_india_hire(full_blob):
        return "India-only remote posting"
    if remote and not wellfound_has_us_work_signal(full_blob):
        return "No US remote / USD signal"
    if wwr_has_non_english_markers(title, description_text):
        return "non-English locale in posting"
    return None


def wellfound_location_label(remote: bool, location_names: list[str]) -> str:
    cleaned = [str(name).strip() for name in location_names if str(name).strip()]
    if cleaned:
        joined = ", ".join(cleaned)
        return f"Remote ({joined})" if remote else joined
    return "Remote" if remote else ""


def run_wellfound_scraper(company: dict[str, Any], start_urls: list[str]) -> tuple[list[dict[str, Any]], str | None]:
    session_path = wellfound_session_path(company)
    profile_dir = wellfound_profile_dir(company)
    if not session_path.is_file() and not profile_dir.is_dir():
        return [], (
            "Wellfound session missing — run: "
            f"{sys.executable} {Path(__file__).resolve()} --wellfound-session-gate"
        )
    cache_ttl = float(company.get("cache_ttl_hours", 6))
    cache_key = f"wellfound-v5-{'-'.join(re.sub(r'[^a-z0-9]+', '-', url.lower()).strip('-') for url in start_urls[:3])}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, dict):
                if payload.get("error") == "challenge":
                    return [], str(payload.get("message") or "Wellfound verification required")
                results = payload.get("results") or []
                if isinstance(results, list):
                    return results, None
        except json.JSONDecodeError:
            pass

    cdp_url = wellfound_detect_cdp_url(company) or ""
    max_details = int(company.get("max_details", 50))
    task = {
        "start_urls": start_urls,
        "session_path": str(session_path),
        "profile_dir": str(profile_dir),
        "cdp_url": cdp_url,
        "max_pages": int(company.get("max_pages", 2)),
        "timeout_ms": int(company.get("playwright_timeout_ms", 90000)),
        "page_wait_ms": int(company.get("page_wait_ms", 2500)),
        "headless": bool(company.get("headless", True)),
        "fetch_details": bool(company.get("fetch_details", True)),
        "max_details": max_details,
        "detail_delay_ms": int(company.get("detail_delay_ms", 400)),
    }
    payload = wellfound_scrape_playwright(SCRIPT_DIR, task)
    if payload.get("error") == "missing_session":
        return [], str(payload.get("message") or "Wellfound session missing")
    if payload.get("error") == "challenge":
        return [], str(payload.get("message") or "Wellfound verification required")
    cache_set(SCRIPT_DIR, cache_key, json.dumps(payload))
    results = payload.get("results") or []
    if not isinstance(results, list):
        return [], "Wellfound scraper returned malformed results"
    return results, None


def search_wellfound(company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]) -> CompanyResult:
    _, _, exclude = cfg_title_tiers(cfg)
    cid = company["id"]
    label = company.get("label") or company["name"]
    employer_region = company_employer_region(company)
    result = CompanyResult(
        id=cid,
        name=company["name"],
        label=label,
        section=company["section"],
        browse_url=company.get("browse_url"),
    )
    start_urls = wellfound_role_urls(company)
    if not start_urls:
        result.search_note = "Wellfound missing role URLs"
        return result
    records, error = run_wellfound_scraper(company, start_urls)
    if error:
        result.search_note = error
        return result

    seen_urls: set[str] = set()
    for record in records:
        url = str(record.get("url") or "").split("?")[0].rstrip("/")
        title = str(record.get("title") or "").strip()
        if not url or not title or url in seen_urls:
            continue
        seen_urls.add(url)
        if title_is_internship_role(title):
            record_filter_reject(cid, title, url, "intern")
            continue
        if title_is_sales_role(title):
            record_filter_reject(cid, title, url, "sales")
            continue
        detail_text = html_to_plain(str(record.get("detail_text") or ""))
        description_text = html_to_plain(
            f"{record.get('description_text') or ''} {detail_text}".strip()
        )
        compensation = str(record.get("compensation") or "").strip()
        location_names = record.get("location_names") if isinstance(record.get("location_names"), list) else []
        is_remote = bool(record.get("remote"))
        location_name = wellfound_location_label(is_remote, [str(x) for x in location_names])
        non_us_reason = wellfound_non_us_fit_reason(
            title,
            description_text,
            compensation,
            [str(x) for x in location_names],
            location_name,
            detail_text,
            remote=is_remote,
        )
        if non_us_reason:
            record_jd_filter_reject(cid, title, non_us_reason, url=url)
            continue
        if title_rejected_by_scrape_filters(title, cfg, company, url=url):
            continue
        skip = jd_blocks_job(description_text, title, cfg, exclude, keyword_exclude_title_only=True)
        if skip:
            record_jd_filter_reject(cid, title, skip, url=url)
            continue
        job_loc, loc_label = classify_location_with_fallback(
            location_name or title, employer_region, str(company.get("default_loc") or "excluded")
        )
        if not job_loc:
            record_filter_reject(cid, title, url, "location")
            continue
        india_check = f"{title} {location_name} {loc_label or ''} {description_text}"
        if job_loc == "remote" and (
            posting_text_indicates_india_hire(india_check)
            or location_text_indicates_india(location_name, loc_label or "")
        ):
            record_jd_filter_reject(cid, title, "India remote misclassified", url=url)
            continue
        job_id = str(record.get("job_id") or "")
        override = overrides.get(job_id, {})
        default_why = discovered_location_why(job_loc, loc_label or location_name, employer_region)
        match, why = finalize_discovered_match(
            override.get("match", "good"),
            override.get("why", default_why),
            description_text,
            title,
            cfg,
            override,
        )
        salary, salary_label = wellfound_extract_salary(compensation, cfg, description_text)
        company_name = str(record.get("company") or "").strip()
        posted_ts = int(record.get("posted_ts") or 0)
        meta_parts = [company_name or None, compensation or None, location_name or None]
        if posted_ts:
            meta_parts.append(f"Posted {format_posted(posted_ts)}")
        meta_parts.append("Live posting (Wellfound)")
        result.jobs.append(
            Job(
                title=override.get("title", title),
                company_id=cid,
                url=url,
                skip_verify=bool(override.get("skip_verify", company.get("skip_verify", True))),
                loc=override.get("loc", job_loc),
                match=match,
                salary=override.get("salary", salary if salary != "maybe" or salary_label else company.get("default_salary", "maybe")),
                salary_label=override.get("salary_label", salary_label),
                loc_label=override.get("loc_label", loc_label),
                meta=" · ".join(part for part in meta_parts if part),
                why=why,
                posted_ts=posted_ts,
                job_id=job_id,
                employment=override.get("employment", "full-time"),
                description_text=description_text,
                cover_letter=override.get("cover_letter"),
            )
        )
    result.search_note = (
        f"Wellfound role search ({len(start_urls)} roles, {len(records)} postings, {len(result.jobs)} matches)"
    )
    return result


GENERIC_TITLE_CLUSTER = re.compile(r"\s/\s")

SPECIFIC_JOB_URL_PATTERNS = (
    r"/company/careers/",
    r"builtin\.com/job/",
    r"amazon\.jobs/.+/jobs/\d+",
    r"gh_jid=\d+",
    r"livehire\.com/",
    r"/job/R-\d+",
    r"myworkdayjobs\.com/.+/job/",
    r"accel\.com/companies/.+/jobs/\d+",
    r"jobs\.smartrecruiters\.com/[^/]+/\d",
    r"boards\.greenhouse\.io/",
    r"explore\.jobs\.netflix\.net/careers/job/",
    r"metacareers\.com/profile/job_details/\d+",
    r"careers\.pge\.com/.+/\d+",
    r"jobs\.sap\.com/.+/\d+",
    r"wellfound\.com/jobs/\d+",
)


def is_specific_job_url(url: str | None) -> bool:
    if not url or not url.strip():
        return False
    u = url.strip().lower()
    if any(re.search(p, u) for p in SPECIFIC_JOB_URL_PATTERNS):
        return True
    if re.search(r"/\d{5,}", u):
        return True
    if re.search(r"/jobs/\d+/?($|\?)", u):
        return True
    path = urllib.parse.urlparse(u).path.rstrip("/")
    if re.search(r"/(job|jobs)/[^/?]+/[^/?]+", path):
        return True
    search_markers = (
        "search-results",
        "search/jobs",
        "search-jobs",
        "/search?",
        "?search=",
        "query=",
        "keywords=",
        "keyword=",
        "?q=",
        "&q=",
    )
    if any(m in u for m in search_markers):
        return False
    if path.endswith("/careers") or path.endswith("/jobs") or path.endswith("/search"):
        return False
    return False


def entry_is_specific(entry: dict[str, Any]) -> bool:
    title = (entry.get("title") or "").strip()
    url = entry.get("url")
    if not title:
        return False
    if re.search(r"\b(browse|search page|roles)\b", title, re.I):
        return bool(url and is_specific_job_url(url))
    if GENERIC_TITLE_CLUSTER.search(title):
        return bool(url and is_specific_job_url(url))
    if url:
        return is_specific_job_url(url)
    return False


def entry_to_job(entry: dict[str, Any], company_id: str) -> Job:
    return Job(
        title=entry["title"],
        company_id=company_id,
        url=entry.get("url"),
        skip_verify=bool(entry.get("skip_verify")),
        loc=entry.get("loc", "remote"),
        match=entry.get("match", "good"),
        salary=entry.get("salary", "ok"),
        salary_label=entry.get("salary_label"),
        loc_label=entry.get("loc_label"),
        meta=entry.get("meta", ""),
        why=entry.get("why", ""),
        posted_ts=int(entry.get("posted_ts", 0)),
        sort_key=int(entry.get("sort_key", 0)),
        employment=entry.get("employment", "full-time"),
    )


def search_entries(company: dict[str, Any]) -> CompanyResult:
    cid = company["id"]
    jobs: list[Job] = []
    skipped = 0
    for entry in company.get("entries", []):
        if not entry_is_specific(entry):
            skipped += 1
            continue
        if title_is_internship_role(str(entry.get("title") or "")):
            skipped += 1
            continue
        jobs.append(entry_to_job(entry, cid))
    note = f"{len(jobs)} specific posting(s)"
    if skipped:
        note += f" ({skipped} generic/intern placeholder(s) dropped)"
    return CompanyResult(
        id=cid,
        name=company["name"],
        label=company.get("label") or company["name"],
        section=company["section"],
        jobs=jobs,
        footer_links=company.get("footer_links", []),
        subsection=company.get("subsection"),
        subsection_warn=bool(company.get("subsection_warn")),
        search_note=note,
    )


def search_hub(company: dict[str, Any]) -> CompanyResult:
    return CompanyResult(
        id=company["id"],
        name=company["name"],
        label=company.get("label") or company["name"],
        section=company["section"],
        hub_url=company.get("hub_url"),
        hub_note=company.get("hub_note", ""),
        search_note="Career hub link",
    )


def workday_playwright_search_url(browse_url: str, query: str) -> str:
    """Workday career sites accept keyword search via ?q= on the browse URL."""
    base = str(browse_url or "").strip()
    q = str(query or "").strip()
    if not base or not q:
        return base
    parts = urllib.parse.urlsplit(base)
    params = urllib.parse.parse_qs(parts.query, keep_blank_values=True)
    params["q"] = [q]
    return urllib.parse.urlunsplit(
        (
            parts.scheme,
            parts.netloc,
            parts.path,
            urllib.parse.urlencode(params, doseq=True),
            parts.fragment,
        )
    )


def playwright_search_urls(company: dict[str, Any], queries: list[str]) -> list[str]:
    template = str(company.get("search_url_template") or "").strip()
    urls: list[str] = []
    if template:
        for query in queries:
            q = query.strip()
            if not q:
                continue
            urls.append(template.replace("{query}", urllib.parse.quote(q)))
    base = str(company.get("browse_url") or company.get("hub_url") or company.get("search_base") or "").strip()
    if not urls and base and "myworkdayjobs.com" in base.lower():
        kind = str(company.get("playwright_kind") or "").lower()
        for query in queries:
            q = query.strip()
            if not q:
                continue
            urls.append(workday_playwright_search_url(base, q))
        if not urls and kind == "workday":
            urls.append(base)
    elif not urls and base:
        urls.append(base)
    seen: set[str] = set()
    deduped: list[str] = []
    for url in urls:
        if url and url not in seen:
            seen.add(url)
            deduped.append(url)
    return deduped


def playwright_cache_key(company: dict[str, Any], kind: str, queries: list[str]) -> str:
    cleaned = re.sub(r"[^a-z0-9]+", "-", "-".join(q.lower() for q in queries if q)).strip("-")
    suffix = cleaned[:60] if cleaned else "default"
    # Bump versions together when refusing empty poisoned caches so stale empties miss.
    version = "loc-v5" if kind == "nike" else (
        "icims-v7" if kind == "icims" else (
            "ibm-v4" if kind == "ibm" else (
                "microsoft-v3"
                if kind == "microsoft"
                else ("workday-v4" if kind == "workday" else "v2")
            )
        )
    )
    return f"pw-{company['id']}-{kind}-{version}-{suffix}"


def _playwright_cache_payload_usable(payload: dict[str, Any]) -> bool:
    """False for abandoned-style empties that found listing links but parsed no jobs."""
    results = payload.get("results")
    if not isinstance(results, list):
        return False
    if results:
        return True
    try:
        link_count = int(payload.get("link_count") or 0)
    except (TypeError, ValueError):
        link_count = 0
    # Links found but zero details usually means stall/orphan mid-scrape — do not reuse.
    return link_count <= 0


def run_playwright_scraper(
    company: dict[str, Any], kind: str, start_urls: list[str], queries: list[str]
) -> tuple[list[dict[str, Any]], str | None]:
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    cache_key = playwright_cache_key(company, kind, queries)
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, dict) and _playwright_cache_payload_usable(payload):
                results = payload.get("results") or []
                if isinstance(results, list):
                    if kind == "microsoft":
                        return _microsoft_repair_playwright_results(results), None
                    return results, None
        except json.JSONDecodeError:
            pass

    task = {
        "kind": kind,
        "start_urls": start_urls,
        "queries": queries,
        "scroll_count": int(company.get("scroll_count", 4)),
        "scroll_wait_ms": int(company.get("scroll_wait_ms", 1800)),
        "detail_wait_ms": int(company.get("detail_wait_ms", 2200)),
        "detail_delay_ms": int(company.get("detail_delay_ms", 250)),
        "max_details": int(company.get("max_details", 24)),
        "remote_card_only": bool(company.get("remote_card_only", True)),
        "timeout_ms": int(company.get("playwright_timeout_ms", 90000)),
        "headless": bool(company.get("headless", True)),
    }
    try:
        payload = company_scrape_playwright(task)
    except Exception as exc:
        return [], f"Playwright {kind} error: {exc}"
    if payload.get("error"):
        err = str(payload["error"])
        if not err.lower().startswith("playwright"):
            err = f"Playwright {kind} error: {err}"
        return [], err
    results = payload.get("results") or []
    if not isinstance(results, list):
        return [], f"Playwright {kind} returned malformed results"
    if kind == "microsoft":
        results = _microsoft_repair_playwright_results(results)
        payload = dict(payload)
        payload["results"] = results
    # Never cache abandoned or link-but-empty payloads (stall orphans poisoned majors).
    if _playwright_fetch_abandoned():
        return results, f"Playwright {kind} abandoned mid-scrape (not cached)"
    if not _playwright_cache_payload_usable(payload if isinstance(payload, dict) else {}):
        link_count = 0
        if isinstance(payload, dict):
            try:
                link_count = int(payload.get("link_count") or 0)
            except (TypeError, ValueError):
                link_count = 0
        return (
            results,
            f"Playwright {kind} found {link_count} links but 0 details (not cached)",
        )
    cache_set(SCRIPT_DIR, cache_key, json.dumps(payload))
    return results, None


def search_playwright(company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]) -> CompanyResult:
    return _search_playwright(company, cfg, overrides)


def apply_overrides(job: Job, overrides: dict[str, Any]) -> None:
    if not job.job_id or job.job_id not in overrides:
        return
    o = overrides[job.job_id]
    for attr in ("why", "match", "salary", "salary_label", "meta", "title", "loc", "loc_label", "employment", "cover_letter"):
        if attr in o and o[attr] is not None:
            setattr(job, attr, o[attr])


def _job_skip_verify(job: Job) -> bool:
    if getattr(job, "force_url_verify", False):
        return False
    if posting_url_skip_verify(job.url):
        return True
    if bool(job.skip_verify):
        return True
    return False


_LINKEDIN_EXPIRED_PURGED_PATHS: set[str] = set()


def verify_jobs(
    jobs: list[Job],
    removed: list[str],
    *,
    ignore_skip: bool = False,
    out_path: Path | None = None,
) -> list[Job]:
    """Drop dead posting URLs. Persist expired URLs so later scrapes cannot re-add them.

    ignore_skip: still skip structured ATS hosts (Greenhouse/Lever/Workday/…), but
    honor company/job skip_verify=false path — used by rebuild-snapshot --verify-urls.
    Jobs with force_url_verify (e.g. QualityInfo HWOL external links) always check,
    including ATS hosts that were never first-party scraped.
    """
    # LinkedIn guest URLs were historically false-positived into the denylist.
    denylist_key = str(expired_job_urls_path(out_path))
    if denylist_key not in _LINKEDIN_EXPIRED_PURGED_PATHS:
        purge_linkedin_expired_job_urls(out_path)
        _LINKEDIN_EXPIRED_PURGED_PATHS.add(denylist_key)
    expired = load_expired_job_urls(out_path)
    need_check: list[Job] = []
    live: list[Job] = []
    newly_expired: list[str] = []
    for job in jobs:
        if not job.url:
            live.append(job)
            continue
        norm = normalize_expired_job_url(job.url)
        if url_is_linkedin_job_posting(job.url):
            # Guest LinkedIn pages are not reliable for dead-link detection.
            live.append(job)
            continue
        if norm in expired:
            removed.append(f"{job.title} ({job.url})")
            continue
        force = bool(getattr(job, "force_url_verify", False))
        # ATS host skip always applies for first-party scrapes (structured fetch
        # already validated). Aggregator-copied ATS URLs set force_url_verify.
        if not force and posting_url_skip_verify(job.url):
            live.append(job)
            continue
        # Company/job skip_verify is ignored when QUICKJOBS_VERIFY_ALL=1 (remote cron)
        # or rebuild-snapshot --verify-urls (ignore_skip).
        if (
            not force
            and not ignore_skip
            and bool(job.skip_verify)
            and not _verify_all_enabled()
        ):
            live.append(job)
            continue
        need_check.append(job)
    if not need_check:
        return live

    verify_workers = _verify_worker_count()

    def _check(job: Job) -> tuple[Job, bool]:
        try:
            return job, url_is_live(
                job.url or "",
                force=bool(getattr(job, "force_url_verify", False)),
            )
        except Exception:
            return job, True

    checked: list[tuple[Job, bool]] = []
    if verify_workers == 1 or len(need_check) == 1:
        for job in need_check:
            try:
                ok = url_is_live(
                    job.url or "",
                    force=bool(getattr(job, "force_url_verify", False)),
                )
            except Exception:
                ok = True
            checked.append((job, ok))
    else:
        with ThreadPoolExecutor(max_workers=verify_workers) as pool:
            checked = list(pool.map(_check, need_check))

    for job, ok in checked:
        if ok:
            live.append(job)
        else:
            removed.append(f"{job.title} ({job.url})")
            if job.url:
                newly_expired.append(job.url)
    if newly_expired:
        remember_expired_job_urls(newly_expired, out_path)
    return live


def sort_jobs(jobs: list[Job]) -> list[Job]:
    return sorted(jobs, key=lambda j: (-(j.posted_ts or 0), -j.sort_key, j.title.lower()))



# ── Fetch layer (RawPosting + registry) ─────────────────────────────────

@dataclass
class RawPosting:
    title: str
    url: str
    description_text: str = ""
    location_name: str = ""
    posted_ts: int = 0
    job_id: str = ""
    employment: str = "full-time"
    company_name: str = ""
    salary: str | None = None
    salary_label: str | None = None
    salary_jsonld: Any = None
    meta_parts: list[str] = field(default_factory=list)
    loc: str | None = None
    loc_label: str | None = None
    skip_verify: bool = False
    force_url_verify: bool = False
    keyword_title_only: bool = True
    live_meta: str = ""
    wwr_penalty: tuple[int, str] | None = None
    loc_verify: bool = False
    match_hint: str | None = None
    why_hint: str | None = None
    skip_keyword_filter: bool = False
    skip_jd_blocklist: bool = False
    use_posting_keywords: bool = False
    force_loc: str | None = None
    force_loc_label: str | None = None
    company_logo_url: str = ""


def company_result_shell(company: dict[str, Any]) -> Any:
    return CompanyResult(
        id=company["id"],
        name=company["name"],
        label=company.get("label") or company["name"],
        section=company["section"],
        browse_url=company.get("browse_url"),
        hub_url=company.get("hub_url"),
        hub_note=company.get("hub_note"),
        footer_links=list(company.get("footer_links") or []),
        subsection=company.get("subsection"),
        subsection_warn=bool(company.get("subsection_warn")),
    )


def ingest_postings(
    company: dict[str, Any],
    cfg: dict[str, Any],
    overrides: dict[str, Any],
    raw_list: list[RawPosting],
    *,
    search_note: str = "",
    error_note: str | None = None,
) -> Any:
    _, _, exclude = company_title_tiers(company, cfg)
    cid = company["id"]
    employer_region = company_employer_region(company)
    default_loc = str(company.get("default_loc") or "")
    result = company_result_shell(company)
    if error_note:
        result.search_note = error_note
        return result

    company_h1b_meta: dict[str, Any] = {}
    if _h1b_employer is not None and _h1b_employer.profile_wants_h1b_validation(cfg):
        company_h1b_meta = _h1b_employer.lookup_company_h1b_meta(
            cid,
            str(company.get("name") or cid),
            cache_root=h1b_cache_root(),
        )

    expired_urls = load_expired_job_urls()
    for raw in raw_list:
        title = str(raw.title or "").strip()
        url = resolve_job_posting_url(
            str(raw.url or "").strip(),
            company,
            job_id=str(raw.job_id or ""),
            title=title,
        )
        if not title or not url or title_is_internship_role(title):
            if title and title_is_internship_role(title):
                record_filter_reject(cid, title, url, "intern")
            continue
        if expired_urls and normalize_expired_job_url(url) in expired_urls:
            if not url_is_linkedin_job_posting(url):
                continue
        if title_is_sales_role(title):
            record_filter_reject(cid, title, url, "sales")
            continue
        display_title = title
        if raw.company_name and ":" not in title:
            display_title = title
        if not raw.skip_keyword_filter:
            if raw.use_posting_keywords:
                fail_reason = posting_filter_fail_reason(
                    display_title, raw.description_text, cfg, company=company
                )
                if fail_reason:
                    record_filter_reject(cid, display_title, url, fail_reason)
                    continue
            elif title_rejected_by_scrape_filters(display_title, cfg, company, url=url):
                continue
        if not raw.skip_jd_blocklist:
            skip = jd_blocks_job(
                raw.description_text,
                display_title,
                cfg,
                exclude,
                keyword_exclude_title_only=raw.keyword_title_only,
            )
            if skip:
                record_jd_filter_reject(cid, display_title, skip, url=url)
                continue
        refined_loc, refined_label = classify_location_with_fallback(
            str(raw.location_name or "").strip(),
            employer_region,
            default_loc,
            cfg,
            title=display_title,
            description_text=raw.description_text,
        )
        if raw.force_loc is not None:
            job_loc, loc_label = raw.force_loc, raw.force_loc_label
        elif refined_loc:
            job_loc, loc_label = refined_loc, refined_label
        elif raw.loc:
            job_loc, loc_label = raw.loc, raw.loc_label
        else:
            record_filter_reject(cid, display_title, url, "location")
            continue
        meta_parts = list(raw.meta_parts)
        work_model = infer_work_model(
            str(raw.location_name or loc_label or ""),
            raw.description_text,
            display_title,
        )
        loc_label = sanitize_loc_label_for_badge(
            loc_label or raw.location_name or "",
            title=display_title,
            description_text=raw.description_text,
            meta_parts=meta_parts,
            company_name=str(company.get("name") or company.get("label") or cid),
        ) or loc_label
        if loc_label and (
            location_text_is_work_model_only(loc_label)
            or location_text_is_remote_us_nationwide(loc_label)
            or location_text_is_scrape_note(loc_label)
        ):
            loc_label = None
        if work_model and loc_label and location_text_is_work_model_only(loc_label):
            loc_label = None
        if (
            _h1b_employer is not None
            and _h1b_employer.profile_wants_h1b_validation(cfg)
            and job_loc != "excluded"
        ):
            h1b_skip = _h1b_employer.h1b_job_skip_reason(
                display_title,
                raw.description_text,
                company_h1b_meta,
            )
            if h1b_skip:
                record_jd_filter_reject(cid, display_title, h1b_skip, url=url)
                continue
        if (
            _h1b_employer is not None
            and _h1b_employer.profile_wants_green_card_validation(cfg)
            and job_loc != "excluded"
        ):
            gc_skip = _h1b_employer.green_card_job_skip_reason(
                display_title,
                raw.description_text,
            )
            if gc_skip:
                record_jd_filter_reject(cid, display_title, gc_skip, url=url)
                continue
        override = overrides.get(str(raw.job_id or ""), {})
        default_why = discovered_location_why(
            job_loc, loc_label or raw.location_name, employer_region
        )
        match, why = finalize_discovered_match(
            override.get("match", raw.match_hint or "stretch"),
            override.get("why", raw.why_hint or default_why),
            raw.description_text,
            display_title,
            cfg,
            override,
        )
        if raw.wwr_penalty and raw.wwr_penalty[1] and "match" not in override:
            steps, note = raw.wwr_penalty
            if note:
                adjusted = downgrade_match(match, steps)
                if adjusted != match:
                    RUN_METRICS["downrated"].append(display_title)
                    match = adjusted
                why = f"{note} {why}" if why else note
        salary = override.get("salary", raw.salary)
        salary_label = override.get("salary_label", raw.salary_label)
        if salary is None and raw.salary_jsonld is not None:
            salary, salary_label = jsonld_salary_status(raw.salary_jsonld, cfg)
        if salary is None:
            salary = company.get("default_salary", "maybe")
        if not salary_label and location_us_salary_eligible(
            job_loc, loc_label or raw.location_name, title=display_title
        ):
            ref_label = company_salary_label_for_title(company, display_title)
            if ref_label:
                salary_label = ref_label
                ref_salary = company.get("company_salary")
                if ref_salary in ("ok", "maybe", "low") and salary == "maybe":
                    salary = str(ref_salary)
        if raw.posted_ts:
            meta_parts.append(f"Posted {format_posted(raw.posted_ts)}")
        if raw.live_meta:
            meta_parts.append(raw.live_meta)
        normalized_url = normalize_job_url(url)
        if not job_url_shape_valid(normalized_url, company, job_id=str(raw.job_id or "")):
            record_jd_filter_reject(cid, display_title, "malformed job URL", url=url)
            continue
        result.jobs.append(
            Job(
                title=override.get("title", display_title),
                company_id=cid,
                url=normalized_url,
                skip_verify=bool(
                    override.get(
                        "skip_verify",
                        raw.skip_verify
                        or (
                            company.get("skip_verify", False)
                            and str(company.get("type") or "").lower() != "oracle_hcm"
                        ),
                    )
                ),
                force_url_verify=bool(
                    override.get("force_url_verify", raw.force_url_verify)
                ),
                loc=override.get("loc", job_loc),
                match=match,
                salary=salary,
                salary_label=salary_label,
                loc_label=override.get("loc_label", loc_label),
                work_model=override.get("work_model", work_model),
                meta=" · ".join(str(p) for p in meta_parts if p),
                why=why,
                posted_ts=raw.posted_ts,
                job_id=str(raw.job_id or ""),
                employment=override.get("employment", raw.employment),
                description_text=raw.description_text,
                company_name=str(
                    raw.company_name
                    or company.get("name")
                    or company.get("label")
                    or cid
                ),
                company_logo_url=str(raw.company_logo_url or ""),
                cover_letter=override.get("cover_letter"),
                loc_verify=bool(override.get("loc_verify", raw.loc_verify)),
            )
        )
    result.search_note = search_note or f"{len(raw_list)} raw → {len(result.jobs)} matches"
    return result


def html_jsonld_profile(company: dict[str, Any]) -> str:
    explicit = str(company.get("html_jsonld_profile") or "").strip().lower()
    if explicit:
        return explicit
    if company["id"] in {"motionrecruitment", "roberthalf"}:
        return company["id"]
    ctype = str(company.get("type") or "").lower()
    if ctype in {"motionrecruitment", "roberthalf"}:
        return ctype
    return "generic"


SIEMENS_WILSONVILLE_FEED = (
    "https://jobs.siemens.com/en_US/externaljobs/SearchJobs/Wilsonville/feed/"
)


def siemens_normalize_job_url(url: str) -> str:
    clean = str(url or "").replace("http://", "https://", 1).split("?")[0].strip()
    if not clean:
        return ""
    numeric = re.search(r"/JobDetail/(?:[^/]+/)?(\d+)\s*$", clean)
    if numeric:
        return f"https://jobs.siemens.com/en_US/externaljobs/JobDetail/{numeric.group(1)}"
    if "jobs.siemens.com/externaljobs/" in clean and "/en_US/" not in clean:
        return clean.replace(
            "jobs.siemens.com/externaljobs/",
            "jobs.siemens.com/en_US/externaljobs/",
            1,
        )
    return clean


def siemens_vague_us_location(location: str) -> bool:
    lower = str(location or "").lower().strip()
    if not lower:
        return False
    return lower in {
        "united states",
        "united states of america",
        "usa",
        "us",
    } or lower.startswith("united states of america")


def siemens_location_reject(location: str) -> bool:
    lower = str(location or "").lower()
    if not lower:
        return False
    return any(marker in lower for marker in NON_COMMUTABLE_FROM_HOME_ZIP_MARKERS)


def siemens_parse_search(html_text: str) -> list[str]:
    links = re.findall(
        r'href="(https://jobs\.siemens\.com(?:/en_US)?/externaljobs/JobDetail/[^"]+)"',
        html_text,
    )
    return list(dict.fromkeys(siemens_normalize_job_url(u) for u in links if u))


def siemens_parse_rss(body: str) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    try:
        root = ET.fromstring(body)
    except ET.ParseError:
        return rows
    for item in root.findall("./channel/item"):
        title = html.unescape(str(item.findtext("title") or "").strip())
        link = siemens_normalize_job_url(str(item.findtext("link") or item.findtext("guid") or ""))
        if not title or not link:
            continue
        rows.append(
            {
                "title": title,
                "url": link,
                "location_hint": html.unescape(str(item.findtext("description") or "").strip()),
                "posted": str(item.findtext("pubDate") or "").strip(),
            }
        )
    return rows


def siemens_fetch_detail(url: str, cache_ttl_hours: float = 24.0) -> dict[str, Any] | None:
    fetch_url = siemens_normalize_job_url(url)
    body = cached_html_fetch(fetch_url, "siemens-detail", cache_ttl_hours=cache_ttl_hours)
    if not body:
        return None
    job_id_match = re.search(r"/JobDetail/(?:[^/]+/)?(\d+)", fetch_url)
    title = ""
    location = ""
    salary_jsonld = None
    for block in re.findall(r'<script type="application/ld\+json">([\s\S]*?)</script>', body):
        try:
            posting = json.loads(block)
        except json.JSONDecodeError:
            continue
        if not isinstance(posting, dict) or posting.get("@type") != "JobPosting":
            continue
        title = str(posting.get("title") or title).strip()
        salary_jsonld = posting
        jl = posting.get("jobLocation")
        if isinstance(jl, dict):
            addr = jl.get("address")
            if isinstance(addr, dict):
                parts = [
                    str(addr.get("addressLocality") or "").strip(),
                    str(addr.get("addressRegion") or "").strip(),
                    str(addr.get("addressCountry") or "").strip(),
                ]
                location = ", ".join(p for p in parts if p)
        break
    for block in re.findall(r"list--locations[\s\S]*?</ul>", body):
        items = [x.strip() for x in re.findall(r'<li class="list__item">\s*([^<]+)', block) if x.strip()]
        if items:
            location = ", ".join(items)
            break
    if not title:
        title_match = re.search(
            r'article__header__text__title[\s\S]*?<a[^>]*>\s*([^<]+?)\s*</a>',
            body,
        )
        if not title_match:
            title_match = re.search(r"<h1[^>]*>\s*([^<]+)", body, re.I)
        if not title_match:
            title_match = re.search(r"<title>([^<|]+)", body)
        title = title_match.group(1).strip() if title_match else ""
    desc_match = re.search(
        r'class="article__content__view__field__value"\s*>\s*([\s\S]*?)\s*</div>\s*</div>\s*<div class="article__content__view__field',
        body,
    )
    description_text = html_to_plain(desc_match.group(1)) if desc_match else html_to_plain(body)
    posted_ts = 0
    if salary_jsonld:
        posted_ts = parse_iso_ts(str(salary_jsonld.get("datePosted") or ""))
    return {
        "job_id": job_id_match.group(1) if job_id_match else "",
        "title": title,
        "description_text": description_text[:50000],
        "location_name": location,
        "meta_location": location,
        "employment": "full-time",
        "posted_ts": posted_ts,
        "salary": salary_jsonld,
    }


def fetch_siemens(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    feed_url = str(company.get("siemens_feed_url") or SIEMENS_WILSONVILLE_FEED).strip()
    body = cached_html_fetch(feed_url, "siemens-wilsonville-feed", cache_ttl_hours=cache_ttl)
    if not body:
        return [], "Siemens Wilsonville feed fetch failed"
    rows = siemens_parse_rss(body)
    employer_hq = str(company.get("employer_hq") or "Wilsonville, OR")
    cid = str(company.get("id") or "")
    raw: list[RawPosting] = []
    for row in rows:
        title = str(row.get("title") or "").strip()
        url = str(row.get("url") or "").strip()
        if not title or not url:
            continue
        if title_rejected_by_scrape_filters(title, cfg, company, url=url):
            continue
        detail = siemens_fetch_detail(url, cache_ttl_hours=cache_ttl)
        if not detail:
            continue
        display_title = str(detail.get("title") or title).strip() or title
        location_name = str(detail.get("location_name") or row.get("location_hint") or "").strip()
        if siemens_location_reject(location_name):
            record_filter_reject(cid, display_title, url, "location")
            continue
        description_text = str(detail.get("description_text") or "")
        skip = jd_blocks_job(description_text, display_title, cfg, exclude, keyword_exclude_title_only=True)
        if skip:
            record_jd_filter_reject(cid, display_title, skip, url=url)
            continue
        force_loc = None
        force_loc_label = None
        if siemens_vague_us_location(location_name) or not location_name:
            force_loc = "local"
            force_loc_label = employer_hq
            location_name = employer_hq
        posted_ts = int(detail.get("posted_ts") or 0)
        if not posted_ts:
            posted_ts = parse_human_posted(str(row.get("posted") or ""))
        raw.append(
            RawPosting(
                title=display_title,
                url=url,
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(detail.get("job_id") or ""),
                employment=str(detail.get("employment") or "full-time"),
                salary_jsonld=detail.get("salary"),
                meta_parts=[location_name] if location_name else [],
                force_loc=force_loc,
                force_loc_label=force_loc_label,
                keyword_title_only=True,
                skip_keyword_filter=True,
                live_meta="Live posting (Siemens Wilsonville feed)",
            )
        )
    note = f"Siemens Wilsonville feed ({len(rows)} roles, {len(raw)} parsed)"
    return raw, note


def peopleadmin_parse_search(html_text: str, site_origin: str) -> list[str]:
    origin = site_origin.rstrip("/")
    seen: dict[str, str] = {}
    for path, title in re.findall(r'href="(/postings/\d+)"[^>]*>\s*([^<]+?)\s*</a>', html_text):
        clean_title = html.unescape(title.strip())
        if clean_title.lower() == "view details":
            continue
        pid = path.rsplit("/", 1)[-1]
        if pid not in seen or len(clean_title) > len(seen[pid]):
            seen[pid] = clean_title
    return [f"{origin}/postings/{pid}" for pid in seen]


def peopleadmin_fetch_detail(
    url: str, default_location: str, cache_ttl_hours: float = 24.0
) -> dict[str, Any] | None:
    body = cached_html_fetch(url, "peopleadmin-detail", cache_ttl_hours=cache_ttl_hours)
    if not body:
        return None
    job_id_match = re.search(r"/postings/(\d+)", url)
    title_match = re.search(r'<h[23][^>]*>\s*<a[^>]*>\s*([^<]+?)\s*</a>', body)
    if not title_match:
        title_match = re.search(r"<title>([^<|]+)", body)
    title = html.unescape(title_match.group(1).strip()) if title_match else ""
    desc_match = re.search(
        r'class="job-description"[^>]*>([\s\S]*?)</span>',
        body,
    )
    if not desc_match:
        desc_match = re.search(r'class="posting-description"[^>]*>([\s\S]*?)</div>', body)
    description_text = html_to_plain(desc_match.group(1)) if desc_match else html_to_plain(body)
    location = default_location
    loc_match = re.search(r"Location[^<]*</[^>]+>\s*<[^>]+>([^<]+)", body, re.I)
    if loc_match and loc_match.group(1).strip():
        location = html.unescape(loc_match.group(1).strip())
    return {
        "job_id": job_id_match.group(1) if job_id_match else "",
        "title": title,
        "description_text": description_text[:50000],
        "location_name": location,
        "meta_location": location,
        "employment": "full-time",
        "posted_ts": 0,
        "salary": None,
    }


def reed_parse_search(html_text: str) -> list[str]:
    seen: set[str] = set()
    ordered: list[str] = []
    for href in re.findall(r'href="(https://jobs\.reed\.edu/positions/[^"]+\.html)"', html_text):
        if href not in seen:
            seen.add(href)
            ordered.append(href)
    return ordered


def shopify_parse_search(html_text: str) -> list[str]:
    seen: set[str] = set()
    ordered: list[str] = []
    for path in re.findall(r"(/careers/[a-z0-9_-]+_[0-9a-f-]{36})", html_text, re.I):
        url = f"https://www.shopify.com{path.split('?')[0]}"
        if url not in seen:
            seen.add(url)
            ordered.append(url)
    return ordered


def shopify_slug_title(url: str) -> str:
    slug = str(url or "").rsplit("/", 1)[-1].split("_")[0]
    return slug.replace("-", " ").strip().title()


def shopify_fetch_detail(url: str, cache_ttl_hours: float = 12.0) -> dict[str, Any] | None:
    body = cached_html_fetch(url, "shopify-detail", cache_ttl_hours=cache_ttl_hours)
    if not body:
        return None
    title = ""
    title_match = re.search(r"<title>\s*([^<]+?)\s*(?:\||-|–)\s*Shopify", body, re.I)
    if not title_match:
        title_match = re.search(r"<title>\s*([^<|]+)", body)
    if title_match:
        title = html.unescape(title_match.group(1).strip())
    job_id_match = re.search(r"_([0-9a-f-]{36})", url, re.I)
    desc_match = re.search(r'<meta name="description" content="([^"]+)"', body)
    description_text = (
        html.unescape(desc_match.group(1)) if desc_match else html_to_plain(body[:30000])
    )
    return {
        "job_id": job_id_match.group(1) if job_id_match else "",
        "title": title or shopify_slug_title(url),
        "description_text": description_text[:50000],
        "location_name": "",
        "meta_location": "Canada — verify US remote",
        "employment": "full-time",
        "posted_ts": 0,
        "salary": None,
    }


def reed_fetch_detail(
    url: str, default_location: str, cache_ttl_hours: float = 24.0
) -> dict[str, Any] | None:
    body = cached_html_fetch(url, "reed-detail", cache_ttl_hours=cache_ttl_hours)
    if not body:
        return None
    title = ""
    title_match = re.search(r"<title>\s*([^<|]+)", body)
    if title_match:
        title = html.unescape(title_match.group(1).strip())
        title = re.sub(r"\s*-\s*Human Resources.*$", "", title, flags=re.I).strip()
    main_match = re.search(r"<main[^>]*>([\s\S]*?)</main>", body, re.I)
    description_text = html_to_plain(main_match.group(1)) if main_match else html_to_plain(body)
    if not title:
        lines = [line.strip() for line in description_text.split("\n") if line.strip()]
        title = lines[0] if lines else ""
    job_id_match = re.search(r"/positions/[^/]+/([^/.]+)\.html", url)
    return {
        "job_id": job_id_match.group(1) if job_id_match else "",
        "title": title,
        "description_text": description_text[:50000],
        "location_name": default_location,
        "meta_location": default_location,
        "employment": "full-time",
        "posted_ts": 0,
        "salary": None,
    }


def paylocity_parse_listing(html_text: str, listing_url: str) -> list[dict[str, str]]:
    jobs: list[dict[str, str]] = []
    seen: set[str] = set()
    for match in re.finditer(
        r'"JobId":(\d+),"JobTitle":"((?:\\.|[^"\\])*)"(?:,"LocationName":"([^"]*)")?',
        html_text,
    ):
        job_id = match.group(1)
        if job_id in seen:
            continue
        seen.add(job_id)
        try:
            title = json.loads(f'"{match.group(2)}"')
        except json.JSONDecodeError:
            title = match.group(2).replace("\\\"", '"')
        location = match.group(3) or ""
        jobs.append(
            {
                "job_id": job_id,
                "title": str(title).strip(),
                "location_name": location,
                "url": f"https://recruiting.paylocity.com/Recruiting/Jobs/Details/{job_id}",
            }
        )
    if not jobs and listing_url:
        origin = re.match(r"(https?://[^/]+)", listing_url)
        base = origin.group(1) if origin else "https://recruiting.paylocity.com"
        for job_id, title in re.findall(r'"JobId":(\d+)[^}]*?"JobTitle":"((?:\\.|[^"\\])*)"', html_text):
            if job_id in seen:
                continue
            seen.add(job_id)
            try:
                clean_title = json.loads(f'"{title}"')
            except json.JSONDecodeError:
                clean_title = title.replace("\\\"", '"')
            jobs.append(
                {
                    "job_id": job_id,
                    "title": str(clean_title).strip(),
                    "location_name": "",
                    "url": f"{base}/Recruiting/Jobs/Details/{job_id}",
                }
            )
    return jobs


def paylocity_fetch_detail_text(url: str, cache_ttl_hours: float = 24.0) -> str:
    body = cached_html_fetch(url, "paylocity-detail", cache_ttl_hours=cache_ttl_hours)
    return html_to_plain(body) if body else ""


def html_jsonld_listing_urls(company: dict[str, Any]) -> list[str]:
    urls = [str(u).strip() for u in (company.get("listing_urls") or []) if str(u).strip()]
    template = str(company.get("search_url_template") or "").strip()
    if template:
        for query in company.get("search_keywords") or []:
            q = str(query).strip()
            if q:
                urls.append(template.replace("{query}", urllib.parse.quote(q)))
    if not urls and company.get("browse_url"):
        urls.append(str(company["browse_url"]).strip())
    seen: set[str] = set()
    ordered: list[str] = []
    for url in urls:
        if url not in seen:
            seen.add(url)
            ordered.append(url)
    return ordered


def html_jsonld_parse_search(company: dict[str, Any], html_text: str) -> list[str]:
    profile = html_jsonld_profile(company)
    origin = str(company.get("site_origin") or "").strip()
    if profile == "motionrecruitment":
        return motion_parse_search(html_text)
    if profile == "roberthalf":
        return roberthalf_parse_search(html_text)
    if profile == "siemens":
        return siemens_parse_search(html_text)
    if profile == "peopleadmin":
        return peopleadmin_parse_search(html_text, origin or str(company.get("browse_url") or ""))
    if profile == "reed":
        return reed_parse_search(html_text)
    if profile == "shopify":
        return shopify_parse_search(html_text)
    pattern = str(company.get("link_pattern") or "")
    if pattern and origin:
        return extract_search_links(html_text, origin, pattern)
    return []


def html_jsonld_fetch_detail(
    company: dict[str, Any], url: str, cache_ttl_hours: float
) -> dict[str, Any] | None:
    profile = html_jsonld_profile(company)
    if profile == "motionrecruitment":
        return motion_fetch_detail(url, cache_ttl_hours=cache_ttl_hours)
    if profile == "roberthalf":
        return roberthalf_fetch_detail(url, cache_ttl_hours=cache_ttl_hours)
    if profile == "siemens":
        return siemens_fetch_detail(url, cache_ttl_hours=cache_ttl_hours)
    if profile == "peopleadmin":
        default_loc = str(company.get("employer_hq") or "Portland, OR")
        return peopleadmin_fetch_detail(url, default_loc, cache_ttl_hours=cache_ttl_hours)
    if profile == "reed":
        default_loc = str(company.get("employer_hq") or "Portland, OR")
        return reed_fetch_detail(url, default_loc, cache_ttl_hours=cache_ttl_hours)
    if profile == "shopify":
        return shopify_fetch_detail(url, cache_ttl_hours=cache_ttl_hours)
    prefix = str(company.get("detail_cache_prefix") or f"{company['id']}-detail")
    body = cached_html_fetch(url, prefix, cache_ttl_hours=cache_ttl_hours)
    if not body:
        return None
    postings = extract_json_ld_jobpostings(body)
    if not postings:
        return None
    posting = postings[0]
    address = posting.get("jobLocation", {}).get("address", {}) if isinstance(posting.get("jobLocation"), dict) else {}
    locality = str(address.get("addressLocality") or "").strip() if isinstance(address, dict) else ""
    return {
        "job_id": str(
            ((posting.get("identifier") or {}) if isinstance(posting.get("identifier"), dict) else {}).get("value")
            or ""
        ),
        "title": str(posting.get("title") or "").strip(),
        "description_text": html_to_plain(str(posting.get("description") or "")),
        "posted_ts": parse_iso_ts(str(posting.get("datePosted") or "")),
        "salary": posting,
        "location_name": locality,
        "meta_location": locality,
        "employment": jsonld_employment_type(posting),
    }


def fetch_html_jsonld(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    profile = html_jsonld_profile(company)
    if profile == "siemens":
        return fetch_siemens(company, cfg)
    cache_ttl = float(company.get("cache_ttl_hours", 8))
    search_prefix = str(company.get("search_cache_prefix") or f"{profile}-search")
    listing_urls = html_jsonld_listing_urls(company)
    detail_urls: list[str] = []
    seen_urls: set[str] = set()
    for listing_url in listing_urls:
        body = cached_html_fetch(listing_url, search_prefix, cache_ttl_hours=cache_ttl)
        if not body:
            continue
        for url in html_jsonld_parse_search(company, body):
            if url not in seen_urls:
                seen_urls.add(url)
                detail_urls.append(url)
    raw: list[RawPosting] = []
    live_label = "Motion Recruitment" if profile == "motionrecruitment" else (
        "Robert Half" if profile == "roberthalf" else (
            "Siemens" if profile == "siemens" else (
                company.get("name", "HTML") if profile in {"peopleadmin", "reed"} else company.get("name", "HTML")
            )
        )
    )
    for url in detail_urls:
        detail = html_jsonld_fetch_detail(company, url, cache_ttl)
        if not detail:
            continue
        raw.append(
            RawPosting(
                title=str(detail.get("title") or ""),
                url=url,
                description_text=str(detail.get("description_text") or ""),
                location_name=str(detail.get("location_name") or ""),
                posted_ts=int(detail.get("posted_ts") or 0),
                job_id=str(detail.get("job_id") or ""),
                employment=str(detail.get("employment") or "full-time"),
                salary_jsonld=detail.get("salary"),
                meta_parts=[str(detail.get("meta_location") or detail.get("location_name") or "") or None],
                live_meta=f"Live posting ({live_label})",
            )
        )
    note = f"{live_label} search ({len(listing_urls)} pages, {len(detail_urls)} roles, {len(raw)} parsed)"
    return raw, note


def fetch_paylocity(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    listing_url = str(
        company.get("paylocity_url") or company.get("browse_url") or company.get("hub_url") or ""
    ).strip()
    if not listing_url:
        return [], "Paylocity listing URL missing"
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    body = cached_html_fetch(listing_url, "paylocity-listing", cache_ttl_hours=cache_ttl)
    if not body:
        return [], "Paylocity listing fetch failed"
    employer_region = company_employer_region(company)
    default_loc = str(company.get("default_loc") or "local")
    rows = paylocity_parse_listing(body, listing_url)
    cid = str(company.get("id") or "")
    raw: list[RawPosting] = []
    for row in rows:
        title = str(row.get("title") or "").strip()
        detail_url = str(row.get("url") or "").strip()
        if title_rejected_by_scrape_filters(title, cfg, company, url=detail_url or None):
            continue
        location_name = str(row.get("location_name") or company.get("employer_hq") or "").strip()
        job_loc, loc_label = classify_location_with_fallback(
            location_name or title,
            employer_region,
            default_loc,
            cfg,
        )
        if not job_loc:
            record_filter_reject(cid, title, detail_url or None, "location")
            continue
        description_text = paylocity_fetch_detail_text(detail_url, cache_ttl_hours=cache_ttl)
        skip = jd_blocks_job(description_text, title, cfg, exclude, keyword_exclude_title_only=True)
        if skip:
            record_jd_filter_reject(cid, title, skip, url=detail_url or None)
            continue
        raw.append(
            RawPosting(
                title=title,
                url=detail_url,
                description_text=description_text,
                location_name=location_name,
                job_id=str(row.get("job_id") or ""),
                meta_parts=[location_name] if location_name else [],
                force_loc=job_loc,
                force_loc_label=loc_label,
                keyword_title_only=True,
                skip_keyword_filter=True,
                live_meta="Live posting (Paylocity)",
            )
        )
    note = f"Paylocity listing ({len(rows)} total, {len(raw)} parsed)"
    return raw, note


def rss_fetch_generic_items(company: dict[str, Any]) -> tuple[list[dict[str, str]], str | None]:
    feed_url = str(company.get("rss_url") or "").strip()
    if not feed_url:
        return [], "RSS feed missing URL"
    cache_key = f"rss-{company['id']}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=float(company.get("cache_ttl_hours", 12)))
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, list):
                return payload, None
        except json.JSONDecodeError:
            pass
    code, _, body = http_get(feed_url)
    if code != 200 or not body:
        return [], f"RSS feed returned HTTP {code}"
    if "<Monster>" in body and "<Errors>" in body:
        err_msg = ""
        err_match = re.search(r"<Message>([^<]+)</Message>", body)
        if err_match:
            err_msg = err_match.group(1).strip()
        code_match = re.search(r'Number="([^"]+)"', body)
        err_code = code_match.group(1) if code_match else ""
        detail = f": {err_msg}" if err_msg else ""
        code_bit = f" ({err_code})" if err_code else ""
        return [], f"Monster RSS API error{code_bit}{detail} — feed unavailable; use browse_url or drop source"
    try:
        root = ET.fromstring(body)
    except ET.ParseError:
        return [], "RSS feed returned invalid XML"
    return _parse_rss2_channel(root), None


def _parse_rss2_channel(root: ET.Element) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for item in root.findall("./channel/item"):
        title = str(item.findtext("title") or "").strip()
        link = str(item.findtext("link") or item.findtext("guid") or "").strip()
        if not title or not link:
            continue
        rows.append(
            {
                "title": title,
                "url": link.replace("http://", "https://", 1).split("?")[0],
                "job_id": "",
                "description_html": str(item.findtext("description") or ""),
                "posted": str(item.findtext("pubDate") or "").strip(),
                "location": "",
                "team": "",
                "position_type": "",
                "region": "",
                "skills": "",
                "category": "",
                "expires_at": "",
            }
        )
    return rows


def fetch_rss(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    variant = str(company.get("rss_variant") or "").strip().lower()
    feed_url = str(company.get("rss_url") or "")
    if variant == "monster" or "rss.jobsearch.monster.com" in feed_url:
        rows, error = rss_fetch_generic_items(company)
    else:
        rows, error = rss_fetch_items(company)
    if error:
        return [], error
    employer_region = company_employer_region(company)
    cid = str(company.get("id") or "")
    raw: list[RawPosting] = []
    for row in rows:
        title = row["title"]
        url = row["url"]
        position_type = str(row.get("position_type") or "").lower()
        if not title or not url:
            continue
        if position_type in ("part_time", "part-time", "parttime", "internship"):
            if title:
                record_filter_reject(cid, title, url, "intern")
            continue
        description_text = html_to_plain(html.unescape(row.get("description_html") or ""))
        display_company = ""
        display_title = title
        location_name = str(row.get("location") or "").strip()
        row_employer_region = employer_region
        salary, salary_label = rss_salary_from_heuristic(company, title, cfg)
        wwr_penalty = None
        if variant == "wwr":
            display_company, display_title = wwr_split_title(title)
            hq_label = wwr_headquarters_label(str(row.get("description_html") or ""))
            row_employer_region = wwr_employer_region(hq_label)
            location_name = wwr_remote_scope(str(row.get("region") or ""), hq_label)
            salary, salary_label = wwr_salary_from_range_label(str(row.get("salary_range") or ""), cfg)
            if salary == "maybe" and not salary_label:
                salary, salary_label = wwr_extract_salary(description_text, cfg)
            india_blob = f"{display_title} {description_text} {location_name} {hq_label}"
            if posting_text_indicates_india_hire(india_blob) or wellfound_has_indian_compensation(
                description_text
            ):
                record_jd_filter_reject(cid, display_title, "India-only / INR posting", url=url)
                continue
            wwr_penalty = wwr_match_penalty(
                display_title, description_text, hq_label, str(row.get("region") or "")
            )
        meta_parts: list[str] = []
        if variant == "wwr":
            meta_parts.extend(
                [
                    display_company or None,
                    str(row.get("category") or "").strip() or None,
                    location_name or None,
                ]
            )
        else:
            meta_parts.extend([row.get("team") or None, location_name or None])
        employment = "full-time" if position_type in ("full_time", "full-time", "fulltime") else "contract"
        posted_ts = rss_parse_pub_date(row.get("posted")) or parse_iso_ts(row.get("posted"))
        if title_rejected_by_scrape_filters(display_title, cfg, company, url=url):
            continue
        raw.append(
            RawPosting(
                title=display_title,
                url=url,
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(row.get("job_id") or ""),
                employment=employment,
                company_name=display_company,
                salary=salary,
                salary_label=salary_label,
                meta_parts=[str(p) for p in meta_parts if p],
                skip_verify=bool(company.get("skip_verify", False)),
                live_meta="Live posting (RSS feed)",
                wwr_penalty=wwr_penalty,
            )
        )
    note = f"RSS feed ({len(rows)} postings, {len(raw)} parsed)"
    return raw, note


def _parse_remoteok_api(body: str, cfg: dict[str, Any]) -> list[RawPosting]:
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return []
    if not isinstance(data, list):
        return []
    raw: list[RawPosting] = []
    for row in data:
        if not isinstance(row, dict) or row.get("epoch") == "notice":
            continue
        title = str(row.get("position") or row.get("title") or "").strip()
        url = str(row.get("url") or row.get("apply_url") or "").strip()
        if not title or not url:
            continue
        if not url.startswith("http"):
            url = f"https://remoteok.com{url}"
        desc = str(row.get("description") or "")
        company_name = str(row.get("company") or "").strip()
        location_name = str(row.get("location") or "Remote") or "Remote"
        posted_raw = row.get("date") or row.get("epoch") or ""
        posted_ts = parse_iso_ts(str(posted_raw)) if posted_raw else 0
        if not posted_ts and str(posted_raw).isdigit():
            posted_ts = int(posted_raw)
        salary_label = None
        salary = "maybe"
        if row.get("salary_min") or row.get("salary_max"):
            lo = int(row.get("salary_min") or 0)
            hi = int(row.get("salary_max") or 0)
            if hi:
                salary, salary_label = salary_range_status("base", lo, hi, cfg)
        raw.append(
            RawPosting(
                title=title,
                url=url,
                description_text=html_to_plain(desc),
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(row.get("id") or ""),
                company_name=company_name,
                salary=salary,
                salary_label=salary_label,
                meta_parts=[company_name, location_name],
                live_meta="Live posting (RemoteOK API)",
                skip_verify=True,
            )
        )
    return raw


def _parse_remotive_api(body: str, cfg: dict[str, Any]) -> list[RawPosting]:
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return []
    jobs = data.get("jobs") if isinstance(data, dict) else data
    if not isinstance(jobs, list):
        return []
    raw: list[RawPosting] = []
    for row in jobs:
        if not isinstance(row, dict):
            continue
        title = str(row.get("title") or "").strip()
        url = str(row.get("url") or "").strip()
        if not title or not url:
            continue
        desc = str(row.get("description") or "")
        company_name = str(row.get("company_name") or "").strip()
        location_name = str(row.get("candidate_required_location") or row.get("job_type") or "Remote")
        posted_ts = parse_iso_ts(str(row.get("publication_date") or ""))
        salary_label = str(row.get("salary") or "").strip() or None
        salary = "maybe"
        if salary_label and re.search(r"\$\s*\d", salary_label):
            nums = [int(x.replace(",", "")) for x in re.findall(r"\d[\d,]*", salary_label)]
            if len(nums) >= 2:
                salary, salary_label = salary_range_status("base", nums[0], nums[1], cfg)
        raw.append(
            RawPosting(
                title=title,
                url=url,
                description_text=html_to_plain(desc),
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(row.get("id") or ""),
                company_name=company_name,
                salary=salary,
                salary_label=salary_label,
                meta_parts=[company_name, location_name],
                live_meta="Live posting (Remotive API)",
                skip_verify=True,
            )
        )
    return raw


def qualityinfo_normalize_location(location_name: str) -> str:
    """QualityInfo city labels omit state; bare Oregon cities need ', OR' for local radius."""
    text = str(location_name or "").strip()
    if not text:
        return "Oregon"
    if re.search(r"\b(remote|hybrid|anywhere|united states|usa)\b", text, re.I):
        return text
    if re.search(r",\s*(OR|Oregon)\b", text, re.I):
        return text
    if re.search(r",\s*[A-Z]{2}\b", text):
        return text
    # City-only labels from Job Finder are Oregon worksites.
    return f"{text}, OR"


# Job Finder search is occupation-fuzzy (returns hardware/thermal noise). Keep only
# titles that look like DevOps / SRE / cloud platform work.
QUALITYINFO_TITLE_INCLUDE_RE = re.compile(
    r"\b("
    r"devops|dev[\s-]?ops|devsecops|"
    r"site\s*reliability|\bsre\b|"
    r"platform\s+(software\s+)?engineers?|"
    r"data\s+platform\s+engineers?|"
    r"directors?\s+of\s+platform\s+engineering|"
    r"cloud\s+(engineers?|architects?|solutions?\s+architects?)|"
    r"proserve\s+cloud\s+architect|"
    r"infrastructure\s+(engineers?|architects?)|"
    r"compute\s+infrastructure|"
    r"kubernetes|\bk8s\b|"
    r"linux\s+(engineers?|administrators?|sysadmins?)|"
    r"systems?\s+administrators?|sysadmins?"
    r")\b",
    re.I,
)
QUALITYINFO_TITLE_EXCLUDE_RE = re.compile(
    r"\b("
    r"thermal|mechanical|electrical|fpga|asic|silicon|photonics|foundry|"
    r"pre-silicon|hardware|aircraft|apparel|ux\s+designer|industrial\s+engineer|"
    r"npi\s+engineer|memory\s+chip|cpu\s+performance|green\s+infrastructure|"
    r"critical\s+infrastructure\s+(mechanical|electrical)|"
    r"product\s+safety|regenerative\s+agriculture"
    r")\b",
    re.I,
)


def qualityinfo_title_acceptable(title: str) -> bool:
    text = html.unescape(str(title or "")).strip()
    if not text or not QUALITYINFO_TITLE_INCLUDE_RE.search(text):
        return False
    if QUALITYINFO_TITLE_EXCLUDE_RE.search(text):
        # Allow if the include hit is a strong DevOps/SRE/cloud phrase.
        if not re.search(
            r"\b(devops|devsecops|site\s*reliability|\bsre\b|cloud\s+"
            r"(engineer|architect|solutions?\s+architect)|kubernetes)\b",
            text,
            re.I,
        ):
            return False
    return True


def qualityinfo_oed_job_url(ord_id: str) -> str:
    """Oregon Employment Department job display URL used by QualityInfo Job Finder."""
    oid = str(ord_id or "").strip()
    if not oid:
        return ""
    query = urllib.parse.urlencode(
        {
            "location_content": "jobdisplay.cfm",
            "agency_menu": "N",
            "ord": oid,
            "system": "WIOE",
            "type": "N",
            "lang": "E",
        }
    )
    return f"https://secure.emp.state.or.us/jobs/index.cfm?{query}"


def qualityinfo_parse_wage(wage_text: str, cfg: dict[str, Any]) -> tuple[str, str | None]:
    """Parse QualityInfo wageText into salary status + label."""
    label = str(wage_text or "").strip() or None
    salary = "maybe"
    if not label or not re.search(r"\$\s*\d", label):
        return salary, label
    nums = [int(x.replace(",", "")) for x in re.findall(r"\d[\d,]*", label)]
    if len(nums) >= 2:
        return salary_range_status("base", nums[0], nums[1], cfg)
    if len(nums) == 1:
        return salary_range_status("base", nums[0], nums[0], cfg)
    return salary, label


def qualityinfo_opening_to_raw(
    row: dict[str, Any], cfg: dict[str, Any]
) -> RawPosting | None:
    title = html.unescape(str(row.get("jobTitle") or "").strip())
    if not title or not qualityinfo_title_acceptable(title):
        return None
    ord_id = str(row.get("ordID") or "").strip()
    url = str(row.get("url") or "").strip()
    source = str(row.get("source") or "").strip().upper()
    if not url and source == "OED" and ord_id:
        url = qualityinfo_oed_job_url(ord_id)
    if not url:
        return None
    location_name = qualityinfo_normalize_location(
        str(row.get("locationText") or "").strip()
    )
    summary = str(row.get("summary") or "")
    occ_title = html.unescape(str(row.get("occTitle") or "").strip())
    wage_text = str(row.get("wageText") or "").strip()
    salary, salary_label = qualityinfo_parse_wage(wage_text, cfg)
    posted_ts = parse_iso_ts(str(row.get("date") or ""))
    # HWOL summaries often lead with employer on its own line.
    company_name = ""
    if source == "HWOL":
        first_line = next(
            (ln.strip() for ln in summary.replace("\r\n", "\n").split("\n") if ln.strip()),
            "",
        )
        first_line = html.unescape(html_to_plain(first_line)).strip()
        if (
            first_line
            and len(first_line) < 60
            and " " in first_line
            and not first_line.lower().startswith(title.lower()[:12])
        ):
            company_name = first_line
    meta_parts = [p for p in (company_name, location_name, source, occ_title) if p]
    # HWOL employer apply URLs are often stale (aggregator copy). Force verify even
    # when the URL is an ATS host we normally skip (Workday/Greenhouse/…).
    hwol_external = source == "HWOL" and bool(url)
    return RawPosting(
        title=title,
        url=url,
        description_text=html_to_plain(summary),
        location_name=location_name,
        posted_ts=posted_ts,
        job_id=ord_id or url,
        company_name=company_name,
        salary=salary,
        salary_label=salary_label,
        meta_parts=meta_parts,
        live_meta=f"Live posting (QualityInfo {source or 'API'})",
        skip_verify=not hwol_external,
        force_url_verify=hwol_external,
        # Title already passed qualityinfo_title_acceptable; keep near-fit
        # Cloud Solution Architects variants that miss global keyword lists.
        skip_keyword_filter=True,
    )


def qualityinfo_fetch_page(
    *,
    base_url: str,
    search: str,
    source: str,
    days: str,
    distance: int,
    page: int,
    maxrows: int,
    stfips: str,
    employer: str = "",
) -> tuple[int, list[dict[str, Any]], str | None]:
    """Return (openingCount, JobOpening rows, error note)."""
    params = {
        "searchString": search,
        "employerName": employer,
        "stfips": stfips,
        "source": source,
        "days": days,
        "distance": str(distance),
        "maxrows": str(maxrows),
        "page": str(page),
        "sidx": "date",
        "datefilter": "all",
    }
    url = f"{base_url.rstrip('/')}/jobs/getOpenings?{urllib.parse.urlencode(params)}"
    code, _, body = http_get(url)
    if code != 200 or not body:
        return 0, [], f"HTTP {code}"
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return 0, [], "invalid JSON"
    if not isinstance(data, dict):
        return 0, [], "unexpected JSON shape"
    try:
        opening_count = int(str(data.get("openingCount") or 0))
    except ValueError:
        opening_count = 0
    rows = data.get("JobOpening") or []
    if not isinstance(rows, list):
        return opening_count, [], "JobOpening not a list"
    return opening_count, [r for r in rows if isinstance(r, dict)], None


def fetch_qualityinfo(
    company: dict[str, Any], cfg: dict[str, Any]
) -> tuple[list[RawPosting], str | None]:
    """Oregon QualityInfo Job Finder via LMI /jobs/getOpenings JSON API."""
    base = str(
        company.get("qualityinfo_base")
        or "https://www.qualityinfo.org/lmiservice/service"
    ).strip()
    searches = [
        str(s).strip()
        for s in (company.get("qualityinfo_searches") or company.get("search_keywords") or [])
        if str(s).strip()
    ]
    if not searches:
        searches = [
            "devops",
            "site reliability",
            "platform engineer",
            "cloud architect",
            "cloud engineer",
        ]
    employers = [
        str(s).strip()
        for s in (company.get("qualityinfo_employers") or [])
        if str(s).strip()
    ]
    sources_raw = company.get("qualityinfo_sources") or ["all"]
    if isinstance(sources_raw, str):
        sources = [sources_raw.strip().lower()] if sources_raw.strip() else ["all"]
    else:
        sources = [str(s).strip().lower() for s in sources_raw if str(s).strip()]
    if not sources:
        sources = ["all"]
    days = str(company.get("qualityinfo_days") or "90").strip() or "90"
    distance = int(company.get("qualityinfo_distance") or 100)
    max_pages = max(1, int(company.get("qualityinfo_max_pages") or 6))
    maxrows = max(1, min(100, int(company.get("qualityinfo_maxrows") or 50)))
    stfips = str(company.get("qualityinfo_stfips") or "41").strip() or "41"

    query_pairs: list[tuple[str, str]] = [(s, "") for s in searches]
    query_pairs.extend(("", emp) for emp in employers)

    by_id: dict[str, RawPosting] = {}
    errors: list[str] = []
    pages_ok = 0
    scanned = 0
    for search, employer in query_pairs:
        for source in sources:
            for page in range(1, max_pages + 1):
                opening_count, rows, err = qualityinfo_fetch_page(
                    base_url=base,
                    search=search,
                    employer=employer,
                    source=source,
                    days=days,
                    distance=distance,
                    page=page,
                    maxrows=maxrows,
                    stfips=stfips,
                )
                if err:
                    label = search or f"employer:{employer}"
                    errors.append(f"{label}/{source}/p{page}: {err}")
                    break
                pages_ok += 1
                if not rows:
                    break
                scanned += len(rows)
                for row in rows:
                    posting = qualityinfo_opening_to_raw(row, cfg)
                    if not posting:
                        continue
                    key = posting.job_id or posting.url
                    by_id.setdefault(key, posting)
                if page * maxrows >= opening_count:
                    break

    raw = list(by_id.values())
    note = (
        f"QualityInfo ({len(query_pairs)} queries, {pages_ok} pages, "
        f"{scanned} scanned, {len(raw)} title-matched)"
    )
    if errors and not raw:
        note = f"{note}; errors: {'; '.join(errors[:3])}"
    elif errors:
        note = f"{note}; {len(errors)} page error(s)"
    return raw, note


# ── LinkedIn guest Jobs (personal / best-effort; rate-limited, not official) ──

LINKEDIN_TPR_CHOICES = {
    "day": "r86400",
    "week": "r604800",
    "month": "r2592000",
}
LINKEDIN_WT_CHOICES = {
    "onsite": "1",
    "remote": "2",
    "hybrid": "3",
}
# LinkedIn f_SB2 annual USD floors ("X+" buckets).
LINKEDIN_SB2_FLOORS: tuple[tuple[int, str], ...] = (
    (40_000, "1"),
    (60_000, "2"),
    (80_000, "3"),
    (100_000, "4"),
    (120_000, "5"),
    (140_000, "6"),
    (160_000, "7"),
    (180_000, "8"),
    (200_000, "9"),
)
LINKEDIN_GUEST_SEARCH = (
    "https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search"
)
LINKEDIN_GUEST_JOB_POSTING = (
    "https://www.linkedin.com/jobs-guest/jobs/api/jobPosting/{job_id}"
)
LINKEDIN_US_GEO_ID = "103644278"
_LINKEDIN_MONEY_RE = re.compile(
    r"\$\s*([\d]{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:\s*([kK]))?"
)
_LINKEDIN_RANGE_RE = re.compile(
    r"\$\s*([\d]{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:\s*([kK]))?"
    r"\s*(?:[-–—]|to|and)\s*"
    r"\$?\s*([\d]{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:\s*([kK]))?",
    re.I,
)
_LINKEDIN_HOURLY_HINT_RE = re.compile(r"(?:/|\bper\s+)?(?:hr|hour)\b", re.I)
_LINKEDIN_SALARY_CONTEXT_RE = re.compile(
    r"(?:salary|pay\s*range|compensation|base\s*pay|base\s*salary|"
    r"annual(?:ly)?|yearly|per\s*year|/yr|/year)",
    re.I,
)


def linkedin_min_salary_to_sb2(min_salary: int) -> tuple[str | None, int | None]:
    """Map annual USD floor to LinkedIn f_SB2 code and that bucket's floor."""
    if min_salary <= 0:
        return None, None
    chosen: tuple[str | None, int | None] = (None, None)
    for floor, code in LINKEDIN_SB2_FLOORS:
        if floor <= min_salary:
            chosen = (code, floor)
        else:
            break
    return chosen


def _linkedin_parse_money_token(num: str, k_suffix: str | None) -> int | None:
    try:
        value = float(num.replace(",", ""))
    except ValueError:
        return None
    if k_suffix:
        value *= 1000.0
    return int(round(value))


def linkedin_parse_salary_from_text(
    text: str,
    *,
    location_name: str = "",
) -> dict[str, int | str | None] | None:
    """Best-effort annual USD range from LinkedIn guest card/detail HTML."""
    if not text:
        return None
    blob = html_to_plain(text)
    loc_hint = str(location_name or "").strip()
    if not loc_hint:
        for m in re.finditer(
            r"(?:Portland|Hillsboro|Beaverton|Oregon|San Francisco|New York|"
            r"United States|Remote)[^\n,]{0,40}",
            blob,
            re.I,
        ):
            loc_hint = m.group(0)
            break
    extracted = extract_comp_range_from_text(blob, location_name=loc_hint)
    if extracted:
        _kind, low_a, high_a = extracted
        return {
            "annual_min": low_a,
            "annual_max": high_a,
            "raw": f"${low_a:,}-${high_a:,}",
            "unit": "annual",
        }

    candidates: list[str] = []
    for chunk in re.split(r"[\n\r]+|(?<=[.!?])\s+", blob):
        chunk = chunk.strip()
        if chunk and _LINKEDIN_SALARY_CONTEXT_RE.search(chunk) and "$" in chunk:
            candidates.append(chunk)
    if not candidates:
        candidates = [blob]

    best: dict[str, int | str | None] | None = None
    for chunk in candidates:
        for match in _LINKEDIN_RANGE_RE.finditer(chunk):
            low = _linkedin_parse_money_token(match.group(1), match.group(2))
            high = _linkedin_parse_money_token(match.group(3), match.group(4))
            if low is None or high is None:
                continue
            low, high = apply_shared_k_salary_suffix(low, high, match.group(0))
            if high < low:
                low, high = high, low
            window = chunk[max(0, match.start() - 24) : match.end() + 24]
            hourly = bool(_LINKEDIN_HOURLY_HINT_RE.search(window))
            if hourly or (high <= 500 and not match.group(2) and not match.group(4)):
                low_a, high_a = int(low * 2080), int(high * 2080)
                unit = "hourly"
            else:
                if high < 1000 and not (match.group(2) or match.group(4)):
                    continue
                low_a, high_a = low, high
                unit = "annual"
            if not _comp_range_pair_plausible(int(low_a), int(high_a)):
                continue
            cand = {
                "annual_min": low_a,
                "annual_max": high_a,
                "raw": match.group(0),
                "unit": unit,
            }
            if best is None or int(cand["annual_max"] or 0) > int(best["annual_max"] or 0):
                best = cand
        if best:
            return best
        for match in _LINKEDIN_MONEY_RE.finditer(chunk):
            val = _linkedin_parse_money_token(match.group(1), match.group(2))
            if val is None:
                continue
            window = chunk[max(0, match.start() - 24) : match.end() + 40]
            if not _LINKEDIN_SALARY_CONTEXT_RE.search(window) and chunk is blob:
                continue
            hourly = bool(_LINKEDIN_HOURLY_HINT_RE.search(window))
            if hourly or (val <= 500 and not match.group(2)):
                annual = int(val * 2080)
                unit = "hourly"
            else:
                if val < 1000 and not match.group(2):
                    continue
                annual = val
                unit = "annual"
            return {
                "annual_min": annual,
                "annual_max": annual,
                "raw": match.group(0),
                "unit": unit,
            }
    return best


def linkedin_build_guest_url(
    keywords: str,
    location: str,
    *,
    tpr: str,
    workplace: list[str],
    start: int,
    geo_id: str | None = None,
    salary_sb2: str | None = None,
) -> str:
    params: dict[str, str] = {
        "keywords": keywords,
        "location": location,
        "f_TPR": LINKEDIN_TPR_CHOICES.get(tpr, LINKEDIN_TPR_CHOICES["week"]),
        "start": str(max(0, start)),
    }
    if workplace:
        params["f_WT"] = ",".join(
            LINKEDIN_WT_CHOICES[w] for w in workplace if w in LINKEDIN_WT_CHOICES
        )
    if geo_id:
        params["geoId"] = geo_id
    if salary_sb2:
        params["f_SB2"] = salary_sb2
    return LINKEDIN_GUEST_SEARCH + "?" + urllib.parse.urlencode(params)


@dataclass
class LinkedInFetchState:
    """Per-scrape counters / abort flag for LinkedIn guest pacing."""

    rate_limited: bool = False
    live_gets: int = 0
    cache_hits: int = 0
    retries_429: int = 0


def linkedin_html_cache_key(url: str) -> str:
    slug = re.sub(r"[^a-zA-Z0-9]+", "-", str(url or "")).strip("-")[:140]
    return f"linkedin-html-{slug}"[:180]


def linkedin_bundle_cache_key(company_id: str) -> str:
    cid = re.sub(r"[^a-zA-Z0-9._-]+", "_", str(company_id or "linkedin"))[:80]
    return f"linkedin-bundle-{cid}"[:180]


def linkedin_scrape_fingerprint(company: dict[str, Any], cfg: dict[str, Any]) -> str:
    """Invalidate cooldown when LinkedIn search budget / keyword order changes."""
    queries = cap_company_search_queries(
        company, cfg, max_queries_key="linkedin_max_queries", default=4
    )
    payload = {
        "queries": queries,
        "pages": int(company.get("linkedin_pages_per_query") or 1),
        "details": int(company.get("linkedin_max_details") or 40),
        "tpr": str(company.get("linkedin_tpr") or "week"),
        "onsite_metro": bool(company.get("linkedin_include_onsite_metro")),
        # v3: guest f_WT is ignored by LinkedIn; remote pass requires explicit remote text.
        "v": 3,
        "strict_remote": True,
    }
    return json.dumps(payload, sort_keys=True, separators=(",", ":"))


def linkedin_cache_file_age_hours(cache_key: str) -> float | None:
    path = cache_dir(SCRIPT_DIR) / f"{cache_key}.txt"
    try:
        if not path.is_file():
            return None
        return (utc_now().timestamp() - path.stat().st_mtime) / 3600.0
    except OSError:
        return None


def linkedin_save_bundle(
    company_id: str,
    postings: list[dict[str, Any]],
    *,
    fingerprint: str = "",
) -> None:
    payload = {
        "saved_at": utc_now().isoformat(),
        "fingerprint": str(fingerprint or ""),
        "postings": postings,
    }
    cache_set(SCRIPT_DIR, linkedin_bundle_cache_key(company_id), json.dumps(payload))


def linkedin_load_bundle(
    company_id: str,
    *,
    ttl_hours: float,
    fingerprint: str | None = None,
) -> list[dict[str, Any]] | None:
    raw = cache_get(
        SCRIPT_DIR, linkedin_bundle_cache_key(company_id), ttl_hours=ttl_hours
    )
    if not raw:
        return None
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return None
    if not isinstance(data, dict):
        return None
    if fingerprint is not None and str(data.get("fingerprint") or "") != str(fingerprint):
        return None
    rows = data.get("postings")
    if not isinstance(rows, list):
        return None
    return [r for r in rows if isinstance(r, dict)]


def linkedin_fetch_html(
    url: str,
    *,
    cache_ttl_hours: float = 6.0,
    state: LinkedInFetchState | None = None,
    pace_sleep: float = 0.0,
    retries_429: int = 2,
    backoff_429_sec: float = 5.0,
    timeout: float = 30.0,
) -> tuple[int, str]:
    """GET LinkedIn guest HTML with optional disk cache and 429 backoff.

    On repeated 429s, marks state.rate_limited so the rest of the scrape stops
    making live requests.
    """
    cache_key = linkedin_html_cache_key(url)
    if cache_ttl_hours > 0:
        cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
        if cached is not None:
            if state is not None:
                state.cache_hits += 1
            return 200, cached
    if state is not None and state.rate_limited:
        return 429, ""
    if pace_sleep > 0:
        time.sleep(pace_sleep)
    attempt = 0
    while True:
        code, _, body = http_get(url, timeout=int(timeout))
        if state is not None:
            state.live_gets += 1
        if code == 429:
            if state is not None:
                state.retries_429 += 1
            if attempt >= max(0, retries_429):
                if state is not None:
                    state.rate_limited = True
                return 429, ""
            time.sleep(max(0.5, float(backoff_429_sec)) * (2**attempt))
            attempt += 1
            continue
        text = body or ""
        if code == 200 and text and cache_ttl_hours > 0:
            cache_set(SCRIPT_DIR, cache_key, text)
        return code, text


def linkedin_parse_listings(html: str) -> list[dict[str, str]]:
    """Parse LinkedIn guest search card HTML into listing dicts."""
    cards = re.findall(
        r'<li>\s*<div[^>]*class="[^"]*base-search-card[^"]*"[^>]*>.*?</li>',
        html,
        flags=re.S | re.I,
    )
    if not cards:
        cards = re.split(r'(?=<div[^>]*data-entity-urn="urn:li:jobPosting:)', html)
        cards = [c for c in cards if "urn:li:jobPosting:" in c]

    listings: list[dict[str, str]] = []
    seen: set[str] = set()
    for card in cards:
        urn_m = re.search(r'data-entity-urn="urn:li:jobPosting:(\d+)"', card)
        job_id = urn_m.group(1) if urn_m else ""
        href_m = re.search(
            r'href="(https://(?:www\.)?linkedin\.com/jobs/view/[^"?]+)',
            card,
        )
        url = href_m.group(1) if href_m else ""
        if job_id and not url:
            url = f"https://www.linkedin.com/jobs/view/{job_id}/"
        title_m = re.search(
            r'class="[^"]*base-search-card__title[^"]*"[^>]*>(.*?)</',
            card,
            flags=re.S | re.I,
        )
        company_m = re.search(
            r'class="[^"]*base-search-card__subtitle[^"]*"[^>]*>(.*?)</',
            card,
            flags=re.S | re.I,
        )
        loc_m = re.search(
            r'class="[^"]*job-search-card__location[^"]*"[^>]*>(.*?)</',
            card,
            flags=re.S | re.I,
        )
        posted_m = re.search(r'datetime="([^"]+)"', card)
        title = html_to_plain(title_m.group(1)) if title_m else ""
        company_name = html_to_plain(company_m.group(1)) if company_m else ""
        location = html_to_plain(loc_m.group(1)) if loc_m else ""
        posted = posted_m.group(1) if posted_m else ""
        if not title and not job_id:
            continue
        key = job_id or url or f"{title}|{company_name}"
        if key in seen:
            continue
        seen.add(key)
        listings.append(
            {
                "job_id": job_id,
                "title": title,
                "company": company_name,
                "location": location,
                "posted": posted,
                "url": url,
            }
        )
    return listings


def linkedin_title_dedupe_key(title: str) -> str:
    """Normalize LinkedIn card titles for within-source duplicate detection."""
    cleaned = str(title or "")
    cleaned = unicodedata.normalize("NFKD", cleaned)
    cleaned = "".join(ch for ch in cleaned if not unicodedata.combining(ch))
    cleaned = re.sub(r"[^\w\s/&+-]+", " ", cleaned, flags=re.UNICODE)
    cleaned = re.sub(r"\s+", " ", cleaned).strip().lower()
    return cleaned


def linkedin_employer_dedupe_key(employer_name: str) -> str:
    key = _employer_favicon_lookup_key(employer_name)
    return key or re.sub(r"[^a-z0-9]+", " ", str(employer_name or "").lower()).strip()


def linkedin_job_id_rank(job_id: str) -> int:
    digits = re.sub(r"\D+", "", str(job_id or ""))
    if not digits:
        return 0
    try:
        return int(digits)
    except ValueError:
        return 0


def _linkedin_merge_listing_rows(
    keep: dict[str, Any], drop: dict[str, Any]
) -> dict[str, Any]:
    merged = dict(keep)
    if str(drop.get("linkedin_remote_us") or "") == "1":
        merged["linkedin_remote_us"] = "1"
    if not str(merged.get("posted") or "").strip() and str(drop.get("posted") or "").strip():
        merged["posted"] = drop.get("posted")
    return merged


def linkedin_dedupe_listings_by_employer_title(
    listings: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], int]:
    """Collapse LinkedIn duplicate cards (same employer + title); keep newer job_id."""
    winners: dict[tuple[str, str], dict[str, Any]] = {}
    order: list[tuple[str, str]] = []
    removed = 0
    for listing in listings:
        employer = linkedin_employer_dedupe_key(str(listing.get("company") or ""))
        title = linkedin_title_dedupe_key(str(listing.get("title") or ""))
        if not employer or not title:
            key = ("", str(listing.get("job_id") or listing.get("url") or id(listing)))
            if key not in winners:
                order.append(key)
                winners[key] = dict(listing)
            continue
        key = (employer, title)
        existing = winners.get(key)
        if existing is None:
            order.append(key)
            winners[key] = dict(listing)
            continue
        removed += 1
        if linkedin_job_id_rank(str(listing.get("job_id") or "")) >= linkedin_job_id_rank(
            str(existing.get("job_id") or "")
        ):
            winners[key] = _linkedin_merge_listing_rows(listing, existing)
        else:
            winners[key] = _linkedin_merge_listing_rows(existing, listing)
    return [winners[key] for key in order], removed


def linkedin_listing_asserts_us_remote(
    location_name: str,
    *,
    title: str = "",
    description_text: str = "",
) -> bool:
    """True only when the posting itself claims remote (not hybrid/onsite).

    LinkedIn guest search ignores f_WT, so the remote-US pass must not trust the
    filter flag. Require an explicit remote cue in location, title, LI tag, or JD.
    """
    loc = str(location_name or "").strip()
    title_s = str(title or "").strip()
    plain = html_to_plain(description_text) if description_text else ""
    blob = f"{title_s}\n{loc}\n{plain}"
    li_mode = extract_linkedin_location_mode(title_s, loc, plain)
    if li_mode in {"hybrid", "onsite"}:
        return False
    if re.search(
        r"(?:workplace\s*type|work\s*arrangement)\s*[:\-]\s*"
        r"(?:hybrid|on[\s-]?site|in[\s-]?office)\b",
        blob,
        re.I,
    ):
        return False
    if re.search(
        r"\((?:onsite|on[\s-]?site|hybrid|in[\s-]?office)\)",
        title_s,
        re.I,
    ):
        return False
    if li_mode == "remote":
        return True
    if re.search(r"\bremote\b", loc, re.I):
        return True
    if location_text_is_remote_us_nationwide(loc) or location_text_is_remote_us_nationwide(
        title_s
    ):
        return True
    if re.search(
        r"\b(fully remote|remote[- ]only|work from home|wfh|"
        r"remote\s*[-–—]\s*(?:united states|usa|u\.s\.|us)\b|"
        r"united states\s*[-–—]\s*remote|"
        r"remote\s+(?:in\s+)?(?:the\s+)?(?:united states|usa|u\.s\.|us)\b)\b",
        blob,
        re.I,
    ):
        return True
    # Title like "DevOps Engineer - Remote - USA"
    if re.search(r"\bremote\b", title_s, re.I):
        return True
    return False


def linkedin_remote_us_should_force_remote(
    location_name: str,
    *,
    title: str = "",
    description_text: str = "",
) -> bool:
    """Whether a LinkedIn remote-US search hit should be forced to board loc=remote."""
    return linkedin_listing_asserts_us_remote(
        location_name,
        title=title,
        description_text=description_text,
    )


def linkedin_listing_to_raw(
    listing: dict[str, str],
    cfg: dict[str, Any],
    *,
    description_text: str = "",
    salary_parsed: dict[str, int | str | None] | None = None,
) -> RawPosting | None:
    title = str(listing.get("title") or "").strip()
    url = str(listing.get("url") or "").strip()
    job_id = str(listing.get("job_id") or "").strip()
    if not title:
        return None
    if not url and job_id:
        url = f"https://www.linkedin.com/jobs/view/{job_id}/"
    if not url:
        return None
    location_name = str(listing.get("location") or "").strip() or "Remote"
    company_name = str(listing.get("company") or "").strip()
    posted_ts = parse_iso_ts(str(listing.get("posted") or ""))
    salary = "maybe"
    salary_label: str | None = None
    if salary_parsed and salary_parsed.get("annual_min") is not None:
        low = int(salary_parsed.get("annual_min") or 0)
        high = int(salary_parsed.get("annual_max") or low)
        salary, salary_label = salary_range_status(
            "base", low, high, cfg, title=title
        )
        if not salary_label and salary_parsed.get("raw"):
            salary_label = str(salary_parsed.get("raw"))
    # Guest f_WT=remote is ignored by LinkedIn. Only keep remote-pass cards that
    # actually say remote; drop city/hybrid/onsite noise. Portland metro pass is
    # unmarked (linkedin_remote_us=0) and kept for local classification.
    remote_us = str(listing.get("linkedin_remote_us") or "").strip() in {
        "1",
        "true",
        "yes",
    }
    force_loc: str | None = None
    force_loc_label: str | None = None
    if remote_us:
        lower_loc = location_name.lower()
        localish = location_within_local_radius(
            location_name, cfg
        ) or portland_metro_marker_in_text(location_name)
        asserts_remote = linkedin_listing_asserts_us_remote(
            location_name,
            title=title,
            description_text=description_text,
        )
        if not localish and not asserts_remote:
            return None
        if not localish and asserts_remote:
            force_loc = "remote"
            if re.search(r"\bremote\b", location_name, re.I):
                force_loc_label = location_name
            elif location_name and lower_loc not in {
                "united states",
                "usa",
                "us",
                "remote",
            }:
                force_loc_label = f"Remote US · {location_name}"
            else:
                force_loc_label = "Remote US"
            location_name = force_loc_label
    meta_parts = [p for p in (company_name, location_name) if p]
    return RawPosting(
        title=title,
        url=url,
        description_text=html_to_plain(description_text),
        location_name=location_name,
        posted_ts=posted_ts,
        job_id=job_id or url,
        company_name=company_name,
        salary=salary,
        salary_label=salary_label,
        meta_parts=meta_parts,
        live_meta="Live posting (LinkedIn guest)",
        skip_verify=True,
        force_loc=force_loc,
        force_loc_label=force_loc_label,
    )


def linkedin_detail_priority(listing: dict[str, Any]) -> tuple[int, int, str]:
    """Sort key for guest detail fetches — higher priority first (negate for ascending sort)."""
    title = str(listing.get("title") or "")
    remote = 1 if str(listing.get("linkedin_remote_us") or "").strip() in {
        "1",
        "true",
        "yes",
    } else 0
    boost = 1 if re.search(
        r"\b(principal|distinguished|staff|fellow|devops|sre|"
        r"site reliability|platform|infrastructure|cloud|reliability)\b",
        title,
        re.I,
    ) else 0
    return (-remote, -boost, title.lower())


def linkedin_fetch_listing_detail(
    listing: dict[str, Any],
    *,
    cache_ttl_hours: float,
    state: LinkedInFetchState,
    detail_sleep: float,
    retries_429: int,
    backoff_429_sec: float,
    details_fetched: int,
) -> tuple[str, dict[str, int | str | None] | None, int | None]:
    """Fetch guest job detail HTML. Returns (description_html, salary_parsed, http_code)."""
    job_id = str(listing.get("job_id") or "").strip()
    if not job_id:
        return "", None, None
    detail_url = LINKEDIN_GUEST_JOB_POSTING.format(job_id=job_id)
    pace = detail_sleep if details_fetched else 0.0
    dcode, dbody = linkedin_fetch_html(
        detail_url,
        cache_ttl_hours=cache_ttl_hours,
        state=state,
        pace_sleep=pace,
        retries_429=retries_429,
        backoff_429_sec=backoff_429_sec,
    )
    if dcode == 200 and dbody:
        return (
            dbody,
            linkedin_parse_salary_from_text(
                dbody, location_name=str(listing.get("location") or "")
            ),
            dcode,
        )
    return "", None, dcode


def linkedin_backfill_bundle_details(
    rows: list[dict[str, Any]],
    company: dict[str, Any],
    *,
    max_details: int,
) -> tuple[list[dict[str, Any]], int, list[str]]:
    """Fill missing description_text on cached bundle rows (priority order)."""
    if max_details <= 0:
        return rows, 0, []
    cache_ttl = float(company.get("cache_ttl_hours") or 6)
    detail_sleep = float(company.get("linkedin_detail_sleep") or 0.75)
    retries_429 = max(0, int(company.get("linkedin_429_retries") or 2))
    backoff_429 = float(company.get("linkedin_429_backoff_sec") or 5.0)
    state = LinkedInFetchState()
    errors: list[str] = []
    # Work on copies; prioritize remote + principal/staff titles missing JD text.
    indexed = list(enumerate(rows))
    indexed.sort(key=lambda pair: linkedin_detail_priority(pair[1]))
    fetched = 0
    out = [dict(r) for r in rows]
    for idx, row in indexed:
        if fetched >= max_details or state.rate_limited:
            break
        if str(row.get("description_text") or "").strip():
            continue
        if not str(row.get("job_id") or "").strip():
            continue
        description_text, salary_parsed, dcode = linkedin_fetch_listing_detail(
            row,
            cache_ttl_hours=cache_ttl,
            state=state,
            detail_sleep=detail_sleep,
            retries_429=retries_429,
            backoff_429_sec=backoff_429,
            details_fetched=fetched,
        )
        fetched += 1
        if dcode == 429:
            errors.append(f"backfill/{row.get('job_id')}: HTTP 429")
            break
        if not description_text:
            continue
        updated = dict(out[idx])
        updated["description_text"] = description_text
        if salary_parsed:
            updated["salary_annual_min"] = salary_parsed.get("annual_min")
            updated["salary_annual_max"] = salary_parsed.get("annual_max")
            updated["salary_raw"] = salary_parsed.get("raw")
        out[idx] = updated
    return out, fetched, errors


def linkedin_raw_from_bundle_row(
    row: dict[str, Any], cfg: dict[str, Any]
) -> RawPosting | None:
    listing = {
        "job_id": str(row.get("job_id") or ""),
        "title": str(row.get("title") or ""),
        "company": str(row.get("company") or ""),
        "location": str(row.get("location") or ""),
        "posted": str(row.get("posted") or ""),
        "url": str(row.get("url") or ""),
        "linkedin_remote_us": str(row.get("linkedin_remote_us") or ""),
    }
    salary_parsed = None
    if row.get("salary_annual_min") is not None:
        salary_parsed = {
            "annual_min": row.get("salary_annual_min"),
            "annual_max": row.get("salary_annual_max"),
            "raw": row.get("salary_raw"),
        }
    return linkedin_listing_to_raw(
        listing,
        cfg,
        description_text=str(row.get("description_text") or ""),
        salary_parsed=salary_parsed,
    )


def fetch_linkedin(
    company: dict[str, Any], cfg: dict[str, Any]
) -> tuple[list[RawPosting], str | None]:
    """LinkedIn guest job search using profile salary floor + global search keywords.

    Two search passes (Portland metro + United States remote), LinkedIn f_SB2 from
    profile salary_floor, then RawPostings go through normal ingest title/location/
    salary filters. Personal / best-effort only: rate-limited and brittle.

    Safety: per-URL HTML cache (cache_ttl_hours), 429 backoff + abort, and a
    company scrape cooldown (linkedin_min_interval_hours) that replays the last
    good bundle instead of hitting LinkedIn again.
    """
    # PUBLIC_BUILD_STUB — no LinkedIn network calls in the public repo
    print("LinkedIn scrape disabled in public build", flush=True)
    return [], "disabled in public build"
    company_id = str(company.get("id") or "linkedin").strip() or "linkedin"
    cache_ttl = float(company.get("cache_ttl_hours") or 6)
    if company.get("linkedin_min_interval_hours") is not None:
        try:
            min_interval = float(company.get("linkedin_min_interval_hours"))
        except (TypeError, ValueError):
            min_interval = cache_ttl
    else:
        min_interval = cache_ttl
    scrape_fp = linkedin_scrape_fingerprint(company, cfg)

    if min_interval > 0:
        age_h = linkedin_cache_file_age_hours(linkedin_bundle_cache_key(company_id))
        if age_h is not None and age_h < min_interval:
            bundled = linkedin_load_bundle(
                company_id,
                ttl_hours=max(min_interval, cache_ttl, 0.01),
                fingerprint=scrape_fp,
            )
            if bundled is not None:
                # Older bundles predate remote-US tagging; force a live refresh once.
                if bundled and not any(
                    "linkedin_remote_us" in row for row in bundled
                ):
                    bundled = None
            if bundled is not None:
                bundled, li_deduped = linkedin_dedupe_listings_by_employer_title(bundled)
                backfill_n = max(0, int(company.get("linkedin_max_details") or 40))
                if bool(company.get("linkedin_fetch_details", True)) and backfill_n:
                    bundled, filled, bf_errors = linkedin_backfill_bundle_details(
                        bundled, company, max_details=backfill_n
                    )
                    if filled:
                        linkedin_save_bundle(
                            company_id, bundled, fingerprint=scrape_fp
                        )
                else:
                    filled = 0
                    bf_errors = []
                raw_cached: list[RawPosting] = []
                for row in bundled:
                    posting = linkedin_raw_from_bundle_row(row, cfg)
                    if posting:
                        raw_cached.append(posting)
                note = (
                    f"LinkedIn guest skipped (cooldown {age_h:.1f}h < "
                    f"{min_interval:g}h); served {len(raw_cached)} cached"
                )
                if li_deduped:
                    note += f"; deduped {li_deduped} duplicate card(s)"
                if filled:
                    note += f"; backfilled {filled} missing JD(s)"
                if bf_errors:
                    note += f"; {len(bf_errors)} backfill error(s)"
                return raw_cached, note

    queries = cap_company_search_queries(
        company, cfg, max_queries_key="linkedin_max_queries", default=4
    )
    if not queries:
        queries = ["devops", "platform engineer", "site reliability"]

    tpr = str(company.get("linkedin_tpr") or "week").strip().lower()
    if tpr not in LINKEDIN_TPR_CHOICES:
        tpr = "week"
    pages_per_query = max(1, int(company.get("linkedin_pages_per_query") or 1))
    page_size = 25
    fetch_details = bool(company.get("linkedin_fetch_details", True))
    max_details = max(0, int(company.get("linkedin_max_details") or 40))
    detail_sleep = float(company.get("linkedin_detail_sleep") or 0.75)
    search_sleep = float(company.get("linkedin_search_sleep") or 1.5)
    retries_429 = max(0, int(company.get("linkedin_429_retries") or 2))
    backoff_429 = float(company.get("linkedin_429_backoff_sec") or 5.0)

    min_salary = salary_floor_value(cfg)
    if company.get("linkedin_min_salary") is not None:
        try:
            min_salary = max(0, int(company.get("linkedin_min_salary")))
        except (TypeError, ValueError):
            pass
    salary_sb2, _sb2_floor = linkedin_min_salary_to_sb2(min_salary)

    metro_workplace = (
        ["remote", "hybrid", "onsite"]
        if company.get("linkedin_include_onsite_metro")
        else ["remote", "hybrid"]
    )
    search_specs: list[dict[str, Any]] = [
        {
            "name": "portland_metro",
            "location": str(
                company.get("linkedin_metro_location") or "Portland, Oregon"
            ).strip()
            or "Portland, Oregon",
            "workplace": metro_workplace,
            "geo_id": company.get("linkedin_metro_geo_id"),
        },
        {
            "name": "remote_us",
            "location": "United States",
            "workplace": ["remote"],
            "geo_id": str(
                company.get("linkedin_us_geo_id") or LINKEDIN_US_GEO_ID
            ).strip()
            or LINKEDIN_US_GEO_ID,
        },
    ]

    state = LinkedInFetchState()
    by_id: dict[str, dict[str, str]] = {}
    errors: list[str] = []
    pages_ok = 0
    first_request = True
    for query in queries:
        if state.rate_limited:
            break
        for spec in search_specs:
            if state.rate_limited:
                break
            for page_i in range(pages_per_query):
                if state.rate_limited:
                    break
                pace = 0.0 if first_request else search_sleep
                first_request = False
                start = page_i * page_size
                # Guest API ignores f_WT; append "remote" on the US pass so results
                # are more likely to be actual remote postings (still filtered below).
                search_keywords = str(query)
                if str(spec["name"]) == "remote_us" and not re.search(
                    r"\bremote\b", search_keywords, re.I
                ):
                    search_keywords = f"{search_keywords} remote"
                url = linkedin_build_guest_url(
                    search_keywords,
                    str(spec["location"]),
                    tpr=tpr,
                    workplace=list(spec["workplace"]),
                    start=start,
                    geo_id=str(spec["geo_id"]) if spec.get("geo_id") else None,
                    salary_sb2=salary_sb2,
                )
                code, body = linkedin_fetch_html(
                    url,
                    cache_ttl_hours=cache_ttl,
                    state=state,
                    pace_sleep=pace,
                    retries_429=retries_429,
                    backoff_429_sec=backoff_429,
                )
                if code == 429:
                    errors.append(
                        f"{query}/{spec['name']}/p{page_i}: HTTP 429 (rate limited)"
                    )
                    break
                if code != 200 or not body:
                    errors.append(
                        f"{query}/{spec['name']}/p{page_i}: HTTP {code}"
                    )
                    break
                pages_ok += 1
                batch = linkedin_parse_listings(body)
                if not batch:
                    break
                for listing in batch:
                    listing = dict(listing)
                    listing["search_pass"] = str(spec["name"])
                    listing["search_query"] = query
                    is_remote_pass = str(spec["name"]) == "remote_us"
                    if is_remote_pass:
                        listing["linkedin_remote_us"] = "1"
                    key = (
                        listing.get("job_id")
                        or listing.get("url")
                        or f"{listing.get('title')}|{listing.get('company')}"
                    )
                    existing = by_id.get(str(key))
                    if existing is not None:
                        # Metro pass often wins first; keep remote-US scope if seen later.
                        if is_remote_pass:
                            existing["linkedin_remote_us"] = "1"
                        continue
                    listing.setdefault("linkedin_remote_us", "0")
                    by_id[str(key)] = listing

    listings = list(by_id.values())
    listings, li_deduped = linkedin_dedupe_listings_by_employer_title(listings)
    listings.sort(key=linkedin_detail_priority)
    details_fetched = 0
    raw: list[RawPosting] = []
    bundle_rows: list[dict[str, Any]] = []
    for listing in listings:
        description_text = ""
        salary_parsed: dict[str, int | str | None] | None = None
        job_id = str(listing.get("job_id") or "").strip()
        if (
            fetch_details
            and job_id
            and details_fetched < max_details
            and not state.rate_limited
        ):
            description_text, salary_parsed, dcode = linkedin_fetch_listing_detail(
                listing,
                cache_ttl_hours=cache_ttl,
                state=state,
                detail_sleep=detail_sleep,
                retries_429=retries_429,
                backoff_429_sec=backoff_429,
                details_fetched=details_fetched,
            )
            details_fetched += 1
            if dcode == 429:
                errors.append(f"detail/{job_id}: HTTP 429 (rate limited)")
        posting = linkedin_listing_to_raw(
            listing,
            cfg,
            description_text=description_text,
            salary_parsed=salary_parsed,
        )
        if posting:
            raw.append(posting)
            bundle_rows.append(
                {
                    "job_id": listing.get("job_id") or "",
                    "title": listing.get("title") or "",
                    "company": listing.get("company") or "",
                    "location": listing.get("location") or "",
                    "posted": listing.get("posted") or "",
                    "url": listing.get("url") or posting.url,
                    "linkedin_remote_us": listing.get("linkedin_remote_us") or "0",
                    "description_text": posting.description_text,
                    "salary_annual_min": (
                        salary_parsed.get("annual_min") if salary_parsed else None
                    ),
                    "salary_annual_max": (
                        salary_parsed.get("annual_max") if salary_parsed else None
                    ),
                    "salary_raw": (
                        salary_parsed.get("raw") if salary_parsed else None
                    ),
                }
            )

    if raw:
        linkedin_save_bundle(company_id, bundle_rows, fingerprint=scrape_fp)

    note = (
        f"LinkedIn guest ({len(queries)} queries × {len(search_specs)} passes, "
        f"{pages_ok} pages, {len(listings)} cards, {details_fetched} details, "
        f"{len(raw)} raw; salary_floor={min_salary} f_SB2={salary_sb2}; "
        f"live={state.live_gets} cache_hits={state.cache_hits}"
    )
    if li_deduped:
        note += f"; deduped {li_deduped} duplicate card(s)"
    if state.rate_limited:
        note += "; stopped after HTTP 429"
    if errors and not raw:
        note = f"{note}; errors: {'; '.join(errors[:3])}"
    elif errors:
        note = f"{note}; {len(errors)} page error(s)"
    return raw, note


def jibe_api_url(company: dict[str, Any]) -> str:
    explicit = str(company.get("jibe_api_url") or "").strip()
    if explicit:
        return explicit.rstrip("/")
    browse = str(company.get("browse_url") or "").strip()
    if not browse:
        return ""
    parts = urllib.parse.urlsplit(browse)
    if not parts.scheme or not parts.netloc:
        return ""
    return f"{parts.scheme}://{parts.netloc}/api/jobs"


def jibe_job_url(company: dict[str, Any], slug: str) -> str:
    slug = str(slug or "").strip().strip("/")
    if not slug:
        return ""
    template = str(company.get("jibe_job_path") or "/careers-home/jobs/{slug}").strip()
    path = template.replace("{slug}", urllib.parse.quote(slug, safe=""))
    if path.startswith("http"):
        return path
    browse = str(company.get("browse_url") or "").strip()
    parts = urllib.parse.urlsplit(browse)
    if not parts.scheme or not parts.netloc:
        return ""
    if not path.startswith("/"):
        path = "/" + path
    return f"{parts.scheme}://{parts.netloc}{path}"


def fetch_jibe(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    """Jibe CMS careers boards (e.g. careers.amd.com/api/jobs)."""
    api = jibe_api_url(company)
    if not api:
        return [], "Jibe api URL missing (set jibe_api_url or browse_url)"
    queries = cap_company_search_queries(company, cfg, max_queries_key="jibe_max_queries")
    if not queries:
        queries = ["devops"]
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    max_details = int(company.get("max_details", 24))
    page_size = max(1, int(company.get("jibe_page_size") or 50))
    employer_region = company_employer_region(company)
    cid = str(company.get("id") or "")
    seen: set[str] = set()
    records: list[RawPosting] = []
    listed = 0
    for query in queries:
        if _company_fetch_abandoned(cid) or len(records) >= max_details:
            break
        page = 1
        while len(records) >= 0:
            if _company_fetch_abandoned(cid) or len(records) >= max_details:
                break
            params = urllib.parse.urlencode(
                {
                    "keywords": query,
                    "limit": page_size,
                    "page": page,
                    "sortBy": "relevance",
                    "descending": "false",
                    "internal": "false",
                }
            )
            url = f"{api}?{params}"
            cache_key = f"jibe-{cid}-{query.replace(' ', '_')}-p{page}"
            cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
            if cached is not None:
                body = cached
                code = 200
            else:
                code, _, body = http_get(url)
                if code == 200 and body:
                    cache_set(SCRIPT_DIR, cache_key, body)
            if code != 200 or not body:
                break
            try:
                payload = json.loads(body)
            except json.JSONDecodeError:
                break
            jobs = payload.get("jobs") if isinstance(payload, dict) else None
            if not isinstance(jobs, list) or not jobs:
                break
            listed += len(jobs)
            for row in jobs:
                if len(records) >= max_details:
                    break
                data = row.get("data") if isinstance(row, dict) else None
                if not isinstance(data, dict):
                    continue
                slug = str(data.get("slug") or data.get("req_id") or "").strip()
                title = str(data.get("title") or "").strip()
                if not slug or not title:
                    continue
                if slug in seen:
                    continue
                if title_rejected_by_scrape_filters(title, cfg, company):
                    continue
                seen.add(slug)
                location_name = str(
                    data.get("full_location")
                    or data.get("location_name")
                    or data.get("city")
                    or ""
                ).strip()
                job_loc, loc_label = classify_location_with_fallback(
                    location_name, employer_region
                )
                if not job_loc:
                    record_filter_reject(
                        cid, title, jibe_job_url(company, slug), "location"
                    )
                    continue
                desc = html_to_plain(str(data.get("description") or ""))
                if desc and jd_blocks_job(
                    desc, title, cfg, cfg_title_tiers(cfg)[2], keyword_exclude_title_only=True
                ):
                    record_jd_filter_reject(
                        cid, title, "jd blocklist", url=jibe_job_url(company, slug)
                    )
                    continue
                posted_ts = parse_iso_ts(str(data.get("posted_date") or ""))
                sal_min = data.get("salary_min_value")
                sal_max = data.get("salary_max_value")
                salary = str(company.get("default_salary") or "maybe")
                salary_label = None
                try:
                    lo = float(sal_min) if sal_min not in (None, "", 0, "0") else None
                    hi = float(sal_max) if sal_max not in (None, "", 0, "0") else None
                except (TypeError, ValueError):
                    lo = hi = None
                if lo or hi:
                    def _k(v: float) -> str:
                        if v >= 1000:
                            return f"${v / 1000:.1f}".rstrip("0").rstrip(".") + "K"
                        return f"${v:.0f}"

                    if lo and hi and hi != lo:
                        range_label = f"{_k(lo)}-{_k(hi)}"
                    else:
                        range_label = _k(lo or hi or 0)
                    salary, salary_label = wwr_salary_from_range_label(range_label, cfg)
                    if not salary_label:
                        salary_label = f"Base {range_label}"
                        salary = str(company.get("default_salary") or "maybe")
                job_url = jibe_job_url(company, slug)
                records.append(
                    RawPosting(
                        title=title,
                        url=job_url,
                        description_text=desc,
                        location_name=location_name,
                        posted_ts=posted_ts,
                        job_id=slug,
                        salary=str(salary or company.get("default_salary") or "maybe"),
                        salary_label=salary_label,
                        meta_parts=[p for p in (location_name, "Live posting (jibe)") if p],
                        force_loc=job_loc,
                        force_loc_label=loc_label or location_name,
                        skip_verify=bool(company.get("skip_verify")),
                        skip_keyword_filter=True,
                        skip_jd_blocklist=True,
                    )
                )
            total = int(payload.get("totalCount") or 0) if isinstance(payload, dict) else 0
            if page * page_size >= total or len(jobs) < page_size:
                break
            page += 1
            if page > 20:
                break
    note = f"Jibe ({len(queries)} queries, {listed} listed, {len(records)} parsed)"
    if not records:
        return [], note if listed else "Jibe returned no postings"
    return records, note


_AVATURE_ARTICLE_RE = re.compile(
    r'<article class="article article--result"[\s\S]*?</article>', re.I
)
_AVATURE_TITLE_LINK_RE = re.compile(
    r'href="([^"]*JobDetail[^"]+)"[^>]*>\s*([^<]+?)\s*</a>', re.I
)
_AVATURE_JOB_ID_RE = re.compile(r"(?:jobId=|/JobDetail/[^/]+/|/JobDetail/)(\d+)", re.I)


def avature_search_url(company: dict[str, Any]) -> str:
    base = str(
        company.get("avature_search_url")
        or company.get("browse_url")
        or company.get("hub_url")
        or ""
    ).strip()
    if not base:
        return ""
    if "SearchJobs" in base:
        return base.split("?")[0].rstrip("/")
    return urllib.parse.urljoin(base.rstrip("/") + "/", "SearchJobs")


def avature_parse_search_articles(html_text: str) -> list[dict[str, str]]:
    """Parse Avature SearchJobs result articles into title/url/job_id rows."""
    rows: list[dict[str, str]] = []
    seen: set[str] = set()
    for art in _AVATURE_ARTICLE_RE.findall(html_text or ""):
        match = _AVATURE_TITLE_LINK_RE.search(art)
        if not match:
            continue
        href = html.unescape(match.group(1).strip())
        title = html.unescape(re.sub(r"\s+", " ", match.group(2))).strip()
        if not href or not title:
            continue
        job_id = ""
        id_match = _AVATURE_JOB_ID_RE.search(href)
        if id_match:
            job_id = id_match.group(1)
        key = job_id or href
        if key in seen:
            continue
        seen.add(key)
        loc = ""
        for loc_match in re.finditer(
            r'class="[^"]*(?:location|subtitle|pin)[^"]*"[^>]*>\s*([^<]+)', art, re.I
        ):
            cand = html.unescape(re.sub(r"\s+", " ", loc_match.group(1))).strip()
            if cand and cand.lower() not in {"apply", "share", "save"}:
                loc = cand
                break
        rows.append({"title": title, "url": href, "job_id": job_id, "location_name": loc})
    return rows


def avature_parse_rss_items(feed_text: str) -> list[dict[str, str]]:
    items: list[dict[str, str]] = []
    seen: set[str] = set()
    for block in re.findall(r"<item>([\s\S]*?)</item>", feed_text or "", re.I):
        title_m = re.search(r"<title><!\[CDATA\[(.*?)\]\]></title>", block, re.I)
        if not title_m:
            title_m = re.search(r"<title>(.*?)</title>", block, re.I)
        link_m = re.search(r"<link>(.*?)</link>", block, re.I)
        title = html.unescape((title_m.group(1) if title_m else "").strip())
        link = html.unescape((link_m.group(1) if link_m else "").strip())
        if not title or not link:
            continue
        job_id = ""
        id_match = _AVATURE_JOB_ID_RE.search(link)
        if id_match:
            job_id = id_match.group(1)
        key = job_id or link
        if key in seen:
            continue
        seen.add(key)
        items.append({"title": title, "url": link, "job_id": job_id, "location_name": ""})
    return items


def avature_normalize_detail_url(url: str, search_url: str = "") -> str:
    text = str(url or "").strip()
    if not text:
        return ""
    if text.startswith("/"):
        origin = ""
        if search_url:
            parsed = urllib.parse.urlsplit(search_url)
            origin = f"{parsed.scheme}://{parsed.netloc}"
        text = urllib.parse.urljoin(origin + "/", text.lstrip("/"))
    # Prefer locale path used by TSMC careers portal.
    text = text.replace("://careers.tsmc.com/careers/", "://careers.tsmc.com/en_US/careers/")
    id_match = _AVATURE_JOB_ID_RE.search(text)
    if id_match and "jobId=" not in text:
        parsed = urllib.parse.urlsplit(text)
        origin = f"{parsed.scheme}://{parsed.netloc}"
        return (
            f"{origin}/en_US/careers/JobDetail?jobId={id_match.group(1)}"
            f"&source=External+Career+Site"
        )
    return text


def avature_parse_job_detail(html_text: str) -> dict[str, Any]:
    """Extract JobPosting JSON-LD (+ plain description) from an Avature JobDetail page."""
    out: dict[str, Any] = {}
    for block in re.findall(
        r'<script[^>]*type=["\']application/ld\+json["\'][^>]*>([\s\S]*?)</script>',
        html_text or "",
        re.I,
    ):
        try:
            data = json.loads(block)
        except json.JSONDecodeError:
            continue
        nodes = data if isinstance(data, list) else [data]
        for node in nodes:
            if not isinstance(node, dict):
                continue
            if str(node.get("@type") or "").lower() != "jobposting":
                continue
            out["title"] = str(node.get("title") or "").strip()
            out["description_text"] = html_to_plain(str(node.get("description") or ""))
            out["posted_ts"] = parse_iso_ts(str(node.get("datePosted") or ""))
            loc = node.get("jobLocation")
            location_name = ""
            if isinstance(loc, dict):
                addr = loc.get("address")
                if isinstance(addr, dict):
                    location_name = str(
                        addr.get("addressLocality")
                        or addr.get("streetAddress")
                        or addr.get("addressRegion")
                        or addr.get("addressCountry")
                        or ""
                    ).strip()
                elif isinstance(addr, str):
                    location_name = addr.strip()
                if not location_name:
                    location_name = str(loc.get("name") or "").strip()
            elif isinstance(loc, list) and loc:
                first = loc[0]
                if isinstance(first, dict):
                    addr = first.get("address")
                    if isinstance(addr, dict):
                        location_name = str(
                            addr.get("addressLocality")
                            or addr.get("streetAddress")
                            or addr.get("addressCountry")
                            or ""
                        ).strip()
            out["location_name"] = location_name
            return out
    return out


def fetch_avature(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    """Avature portal SearchJobs (POST) + JobDetail JSON-LD (e.g. TSMC)."""
    search_url = avature_search_url(company)
    if not search_url:
        return [], "Avature search URL missing (set avature_search_url or browse_url)"
    queries = cap_company_search_queries(
        company, cfg, max_queries_key="avature_max_queries", default=6
    )
    if not queries:
        queries = ["devops"]
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    max_details = int(company.get("max_details", 24))
    page_size = max(10, int(company.get("avature_page_size") or 50))
    employer_region = company_employer_region(company)
    default_loc = str(company.get("default_loc") or "remote")
    cid = str(company.get("id") or "")
    origin = f"{urllib.parse.urlsplit(search_url).scheme}://{urllib.parse.urlsplit(search_url).netloc}"

    # Warm session cookie (Avature often 403s cold POSTs).
    http_get(search_url)

    listed_rows: list[dict[str, str]] = []
    seen_keys: set[str] = set()

    def _add_rows(rows: list[dict[str, str]]) -> None:
        for row in rows:
            key = str(row.get("job_id") or row.get("url") or "").strip()
            if not key or key in seen_keys:
                continue
            seen_keys.add(key)
            listed_rows.append(row)

    for query in queries:
        if _company_fetch_abandoned(cid) or len(listed_rows) >= max_details * 3:
            break
        offset = 0
        for _ in range(8):
            if _company_fetch_abandoned(cid):
                break
            cache_key = (
                f"avature-search-{cid}-{query.replace(' ', '_')}-o{offset}-n{page_size}"
            )
            cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
            if cached is not None:
                body = cached
                code = 200
            else:
                code, _, body = http_post_form(
                    search_url,
                    {
                        "search": query,
                        "jobRecordsPerPage": str(page_size),
                        "jobOffset": str(offset),
                        "listFilterMode": "1",
                    },
                    headers={"Referer": search_url, "Origin": origin},
                )
                if code == 200 and body:
                    cache_set(SCRIPT_DIR, cache_key, body)
            if code != 200 or not body:
                break
            page_rows = avature_parse_search_articles(body)
            if not page_rows:
                break
            before = len(listed_rows)
            _add_rows(page_rows)
            if len(listed_rows) == before or len(page_rows) < page_size:
                break
            offset += page_size

    # RSS seed fills gaps when SearchJobs POST is blocked (featured list only).
    feed_url = str(company.get("avature_feed_url") or "").strip()
    if not feed_url:
        feed_url = search_url.rstrip("/") + "/feed/?jobRecordsPerPage=200"
    feed_cache = f"avature-feed-{cid}"
    feed_body = cache_get(SCRIPT_DIR, feed_cache, ttl_hours=cache_ttl)
    if feed_body is None:
        code, _, feed_body = http_get(feed_url)
        if code == 200 and feed_body:
            cache_set(SCRIPT_DIR, feed_cache, feed_body)
        else:
            feed_body = ""
    if feed_body:
        _add_rows(avature_parse_rss_items(feed_body))

    records: list[RawPosting] = []
    for row in listed_rows:
        if len(records) >= max_details or _company_fetch_abandoned(cid):
            break
        title = str(row.get("title") or "").strip()
        detail_url = avature_normalize_detail_url(str(row.get("url") or ""), search_url)
        if not title or not detail_url:
            continue
        if title_rejected_by_scrape_filters(title, cfg, company, url=detail_url):
            continue
        detail_cache = f"avature-detail-{cid}-{row.get('job_id') or re.sub(r'[^a-zA-Z0-9]+', '_', detail_url)[-48:]}"
        detail_html = cache_get(SCRIPT_DIR, detail_cache, ttl_hours=cache_ttl)
        if detail_html is None:
            code, _, detail_html = http_get(detail_url)
            if code == 200 and detail_html:
                cache_set(SCRIPT_DIR, detail_cache, detail_html)
            else:
                detail_html = ""
        parsed = avature_parse_job_detail(detail_html) if detail_html else {}
        if parsed.get("title"):
            title = str(parsed["title"])
        location_name = str(
            parsed.get("location_name") or row.get("location_name") or ""
        ).strip()
        description_text = str(parsed.get("description_text") or "")
        posted_ts = int(parsed.get("posted_ts") or 0)
        job_loc, loc_label = classify_location_with_fallback(
            location_name, employer_region, default_loc, cfg
        )
        if not job_loc:
            record_filter_reject(cid, title, detail_url, "location")
            continue
        if description_text and jd_blocks_job(
            description_text, title, cfg, cfg_title_tiers(cfg)[2], keyword_exclude_title_only=True
        ):
            record_jd_filter_reject(cid, title, "jd blocklist", url=detail_url)
            continue
        records.append(
            RawPosting(
                title=title,
                url=detail_url,
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(row.get("job_id") or ""),
                salary=str(company.get("default_salary") or "maybe"),
                meta_parts=[p for p in (location_name, "Live posting (avature)") if p],
                force_loc=job_loc,
                force_loc_label=loc_label or location_name,
                skip_verify=bool(company.get("skip_verify")),
                skip_keyword_filter=True,
                skip_jd_blocklist=True,
            )
        )

    note = (
        f"Avature ({len(queries)} queries, {len(listed_rows)} listed, {len(records)} parsed)"
    )
    if not records:
        return [], note if listed_rows else "Avature returned no postings"
    return records, note


def fetch_json_feed(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    variant = str(company.get("json_variant") or company["id"]).strip().lower()
    if variant in {"amazon_jobs", "amazon-jobs"}:
        return fetch_amazon_jobs(company, cfg)
    url = str(company.get("json_url") or "").strip()
    if not url:
        return [], "json_url missing"
    cache_key = f"json-{company['id']}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=float(company.get("cache_ttl_hours", 6)))
    if cached is not None:
        body = cached
    else:
        code, _, body = http_get(url)
        if code != 200 or not body:
            return [], f"JSON feed HTTP {code}"
        cache_set(SCRIPT_DIR, cache_key, body)
    if variant in {"remoteok", "remote-ok"}:
        raw = _parse_remoteok_api(body, cfg)
    elif variant in {"remotive"}:
        raw = _parse_remotive_api(body, cfg)
    else:
        return [], f"Unknown json_variant: {variant}"
    note = f"JSON feed {variant} ({len(raw)} parsed)"
    return raw, note


def amazon_jobs_search_urls(company: dict[str, Any], cfg: dict[str, Any]) -> list[str]:
    """Build amazon.jobs search.json URLs from keywords × location queries × pages."""
    queries = cap_company_search_queries(
        company, cfg, max_queries_key="amazon_max_queries", default=10
    )
    if not queries:
        queries = ["devops"]
    loc_raw = company.get("amazon_loc_queries")
    if loc_raw is None:
        loc_queries = ["Remote"]
    else:
        loc_queries = [str(x).strip() for x in (loc_raw or [])]
        if not loc_queries:
            loc_queries = [""]
    result_limit = max(10, int(company.get("amazon_result_limit") or 100))
    max_pages = max(1, int(company.get("amazon_max_pages_per_query") or 1))
    urls: list[str] = []
    seen: set[str] = set()
    for query in queries:
        for loc in loc_queries:
            for page in range(max_pages):
                params = {
                    "base_query": query,
                    "offset": page * result_limit,
                    "result_limit": result_limit,
                }
                if loc:
                    params["loc_query"] = loc
                url = (
                    "https://www.amazon.jobs/en/search.json?"
                    + urllib.parse.urlencode(params)
                )
                if url not in seen:
                    seen.add(url)
                    urls.append(url)
    # Fallback to legacy single json_url when present and no keyword URLs built.
    legacy = str(company.get("json_url") or "").strip()
    if legacy and legacy not in seen:
        urls.append(legacy)
    return urls


def fetch_amazon_jobs(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    """Multi-query amazon.jobs JSON search (keywords × locations), deduped by job_path."""
    urls = amazon_jobs_search_urls(company, cfg)
    if not urls:
        return [], "Amazon jobs search URL missing"
    cache_ttl = float(company.get("cache_ttl_hours", 8))
    cid = str(company.get("id") or "")
    merged_jobs: list[dict[str, Any]] = []
    seen_paths: set[str] = set()
    pages_ok = 0
    for idx, url in enumerate(urls):
        if _company_fetch_abandoned(cid):
            break
        cache_key = f"amazon-jobs-{cid}-p{idx}-{re.sub(r'[^a-zA-Z0-9]+', '_', url)[-100:]}"
        cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
        if cached is not None:
            body = cached
            code = 200
        else:
            code, _, body = http_get(url)
            if code == 200 and body:
                cache_set(SCRIPT_DIR, cache_key, body)
        if code != 200 or not body:
            continue
        try:
            payload = json.loads(body)
        except json.JSONDecodeError:
            continue
        pages_ok += 1
        for job in payload.get("jobs") or []:
            if not isinstance(job, dict):
                continue
            path = str(job.get("job_path") or "").strip()
            if not path or path in seen_paths:
                continue
            seen_paths.add(path)
            merged_jobs.append(job)
    raw = _parse_amazon_jobs_api(
        json.dumps({"jobs": merged_jobs}), cfg, company
    )
    max_salary_pages = int(company.get("max_details") or 12)
    filled = 0
    for posting in raw:
        if posting.salary_label or filled >= max_salary_pages:
            continue
        page_salary, page_label = amazon_jobs_fetch_page_salary(
            posting.url, cfg, cache_ttl_hours=cache_ttl
        )
        if page_label:
            posting.salary = page_salary
            posting.salary_label = page_label
            filled += 1
    note = (
        f"Amazon jobs ({len(urls)} searches, {pages_ok} ok, "
        f"{len(merged_jobs)} listed, {len(raw)} parsed)"
    )
    if not raw:
        return [], note if pages_ok else "Amazon jobs returned no postings"
    return raw, note


def taleo_cws_canonical_url(host: str, org: str, cws: str, rid: str) -> str:
    """Canonical Taleo CWS posting URL (query params required for a specific requisition)."""
    base = str(host or "").strip().rstrip("/")
    if not base.startswith(("http://", "https://")):
        base = f"https://{base.lstrip('/')}"
    query = urllib.parse.urlencode({"org": str(org).strip(), "cws": str(cws).strip(), "rid": str(rid).strip()})
    return f"{base}/viewRequisition?{query}"


def job_url_shape_valid(url: str, company: dict[str, Any], *, job_id: str = "") -> bool:
    """Reject malformed posting URLs before they reach the board (HTTP 200 is not enough)."""
    text = str(url or "").strip()
    if not text.startswith("http"):
        return False
    lower = text.lower()
    ctype = str(company.get("type") or "").lower()
    kind = str(company.get("playwright_kind") or "").lower()
    jid = str(job_id or "").strip()

    if ctype == "taleo_cws":
        return bool(re.search(r"viewRequisition.*[?&]rid=\d+", text, re.I))

    if ctype == "phenom":
        if "myworkdayjobs.com" in lower:
            return bool(re.search(r"/job/[^/?#]+", text, re.I)) and not lower.rstrip("/").endswith(
                "/apply"
            )
        # Bare /job/{id} returns HTTP 200 but redirects to the careers home page.
        path_match = re.search(r"/job/([^/?#]+)(?:/([^/?#]+))?", text, re.I)
        if not path_match:
            return False
        req_id = path_match.group(1).strip()
        title_slug = (path_match.group(2) or "").strip()
        if not title_slug:
            return False
        if jid and req_id.upper() != jid.upper():
            return False
        return bool(req_id and title_slug)

    if ctype in ("greenhouse",) or "greenhouse" in lower:
        return "/jobs/" in lower or bool(re.search(r"[?&]gh_jid=", text, re.I))

    if ctype == "lever" or "jobs.lever.co" in lower:
        return "jobs.lever.co" in lower and len(urllib.parse.urlsplit(text).path.strip("/").split("/")) >= 2

    if ctype == "ashby" or "jobs.ashbyhq.com" in lower:
        parts = urllib.parse.urlsplit(text).path.strip("/").split("/")
        return len(parts) >= 2 and bool(parts[0]) and bool(parts[1])

    if kind == "workday" or "myworkdayjobs.com" in lower:
        return bool(re.search(r"/job/[^/?#]+", text, re.I))

    if kind == "eightfold" or re.search(r"[?&]pid=\d+", text, re.I):
        parsed = urllib.parse.urlsplit(text)
        if not parsed.path.rstrip("/").endswith("/careers"):
            return False
        return bool(re.search(r"[?&]pid=\d+", text, re.I))

    if ctype == "oracle_hcm":
        return bool(re.search(r"/job/[^/?#]+", text, re.I)) or bool(jid)

    if ctype == "icims" or "icims.com" in lower:
        return bool(re.search(r"/jobs/\d+/", text, re.I))

    if ctype == "jibe" or "/careers-home/jobs/" in lower:
        return bool(re.search(r"/careers-home/jobs/[^/?#]+", text, re.I))

    return True


NIKE_COMPANY_IDS = frozenset({"nike", "nike-it"})
CISCO_COMPANY_IDS = frozenset({"cisco", "cisco-wd"})
_NIKE_REQUISITION_FROM_URL = re.compile(
    r"(?:"
    r"careers\.nike\.com/(?:[^/?#]+/)*job/(R-\d+)\b"
    r"|"
    r"myworkdayjobs\.com/(?:[^/]+/)*nke/job/[^?#]*_(R-\d+)\b"
    r")",
    re.I,
)


def nike_requisition_from_url(url: str) -> str | None:
    """Workday and careers.nike.com posting URLs share R-##### requisition ids."""
    match = _NIKE_REQUISITION_FROM_URL.search(str(url or ""))
    if not match:
        return None
    return (match.group(1) or match.group(2) or "").upper()


def nike_canonical_apply_url(requisition: str) -> str:
    rid = str(requisition or "").strip().upper()
    return f"https://careers.nike.com/job/{rid}"


def nike_canonical_apply_key(url: str) -> str | None:
    rid = nike_requisition_from_url(url)
    if not rid:
        return None
    return nike_canonical_apply_url(rid)


def migrate_nike_pipeline_keys(store: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    """Merge pipeline rows keyed by Workday vs careers.nike.com URL variants."""
    if not store:
        return store
    out = dict(store)
    for key in list(store.keys()):
        canon = nike_canonical_apply_key(key)
        if not canon or canon == key:
            continue
        merged = prefer_pipeline_entry(out.get(canon), out[key])
        if merged:
            out[canon] = merged
        out.pop(key, None)
    return out


def _nike_family_dedupe_winner(existing_id: str, challenger_id: str) -> str | None:
    if existing_id not in NIKE_COMPANY_IDS or challenger_id not in NIKE_COMPANY_IDS:
        return None
    if existing_id == "nike":
        return existing_id
    if challenger_id == "nike":
        return challenger_id
    return None


def _cisco_family_dedupe_winner(existing_id: str, challenger_id: str) -> str | None:
    if existing_id not in CISCO_COMPANY_IDS or challenger_id not in CISCO_COMPANY_IDS:
        return None
    if existing_id == "cisco":
        return existing_id
    if challenger_id == "cisco":
        return challenger_id
    return None


def consolidate_nike_family_jobs(
    results: list[CompanyResult],
    company_list: list[dict[str, Any]],
) -> int:
    """Move nike-it listings with Nike requisition ids under the primary nike company."""
    cfg_by_id = {
        str(company.get("id") or ""): company
        for company in company_list
        if isinstance(company, dict) and company.get("id")
    }
    if "nike" not in cfg_by_id:
        return 0
    nike_co = next((co for co in results if co.id == "nike"), None)
    if nike_co is None:
        nike_meta = cfg_by_id["nike"]
        nike_co = CompanyResult(
            id="nike",
            name=str(nike_meta.get("name") or "Nike"),
            label=str(nike_meta.get("label") or nike_meta.get("name") or "Nike"),
            section=str(nike_meta.get("section") or "local"),
            jobs=[],
            layoff_prone=bool(nike_meta.get("layoff_prone")),
        )
        results.append(nike_co)
    moved = 0
    for co in results:
        if co.id != "nike-it":
            continue
        keep: list[Job] = []
        for job in co.jobs:
            if not nike_requisition_from_url(job.url or ""):
                keep.append(job)
                continue
            apply_company_result_job_fields(nike_co, job)
            job.company_id = "nike"
            nike_co.jobs.append(job)
            moved += 1
        co.jobs = keep
    if moved:
        nike_co.jobs = sort_jobs(nike_co.jobs)
    return moved


_CISCO_REQUISITION_FROM_URL = re.compile(
    r"(?:"
    r"careers\.cisco\.com/(?:[^?#]*/)?job/(\d{6,})\b"
    r"|"
    r"cisco\.wd\d+\.myworkdayjobs\.com/[^?#]*_(\d{6,})(?:-\d+)?\b"
    r"|"
    r"CISCISGLOBAL(\d{6,})EXTERNAL"
    r")",
    re.I,
)


def cisco_requisition_from_url(url: str) -> str | None:
    """Phenom careers.cisco.com and Workday Cisco_Careers share numeric req ids."""
    match = _CISCO_REQUISITION_FROM_URL.search(str(url or ""))
    if not match:
        return None
    return match.group(1) or match.group(2) or match.group(3)


def cisco_canonical_apply_url(requisition: str) -> str:
    rid = str(requisition or "").strip()
    return f"https://careers.cisco.com/global/en/job/{rid}"


def cisco_canonical_apply_key(url: str) -> str | None:
    rid = cisco_requisition_from_url(url)
    if not rid:
        return None
    return cisco_canonical_apply_url(rid)


def migrate_cisco_pipeline_keys(store: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    """Merge pipeline rows keyed by Workday vs careers.cisco.com URL variants."""
    if not store:
        return store
    out = dict(store)
    for key in list(store.keys()):
        canon = cisco_canonical_apply_key(key)
        if not canon or canon == key:
            continue
        merged = prefer_pipeline_entry(out.get(canon), out[key])
        if merged:
            out[canon] = merged
        out.pop(key, None)
    return out


def consolidate_cisco_family_jobs(
    results: list[CompanyResult],
    company_list: list[dict[str, Any]],
) -> int:
    """Move cisco-wd listings with Cisco requisition ids under the primary cisco company."""
    cfg_by_id = {
        str(company.get("id") or ""): company
        for company in company_list
        if isinstance(company, dict) and company.get("id")
    }
    if "cisco" not in cfg_by_id:
        return 0
    cisco_co = next((co for co in results if co.id == "cisco"), None)
    if cisco_co is None:
        cisco_meta = cfg_by_id["cisco"]
        cisco_co = CompanyResult(
            id="cisco",
            name=str(cisco_meta.get("name") or "Cisco"),
            label=str(cisco_meta.get("label") or cisco_meta.get("name") or "Cisco"),
            section=str(cisco_meta.get("section") or "matching"),
            jobs=[],
            layoff_prone=bool(cisco_meta.get("layoff_prone")),
        )
        results.append(cisco_co)
    moved = 0
    for co in results:
        if co.id != "cisco-wd":
            continue
        keep: list[Job] = []
        for job in co.jobs:
            if not cisco_requisition_from_url(job.url or "") and not (
                str(job.job_id or "").strip().isdigit()
                and len(str(job.job_id).strip()) >= 6
            ):
                keep.append(job)
                continue
            apply_company_result_job_fields(cisco_co, job)
            job.company_id = "cisco"
            cisco_co.jobs.append(job)
            moved += 1
        co.jobs = keep
    if moved:
        cisco_co.jobs = sort_jobs(cisco_co.jobs)
    return moved


def _job_url_keep_query_string(url: str) -> bool:
    """ATS postings identified by query string must not be stripped in normalize_job_url."""
    text = str(url or "").strip()
    if not text or "?" not in text:
        return False
    if re.search(r"[?&](gh_jid|pid)=", text, re.I):
        return True
    if re.search(r"[?&]jobId=\d+", text, re.I) and "careers.ibm.com" in text.lower():
        return True
    if re.search(r"viewRequisition", text, re.I) and re.search(r"[?&]rid=\d+", text, re.I):
        return True
    if "taleo.net" in text.lower():
        return True
    if "icims.com" in text.lower() and re.search(r"[?&](?:job?id|jobs?Id|iCIMS_JID)=\w+", text, re.I):
        return True
    # Avature JobDetail identity is often ?jobId=<id>.
    if re.search(r"[?&]jobId=\d+", text, re.I) and (
        "avature.net" in text.lower() or "/careers/JobDetail" in text
    ):
        return True
    # Oregon Employment Department (QualityInfo OED): identity is ?ord=<id>.
    if "emp.state.or.us" in text.lower() and re.search(r"[?&]ord=\w+", text, re.I):
        return True
    return False


def parse_taleo_cws_search(
    html_text: str,
    *,
    host: str = "",
    org: str = "",
    cws: str = "",
) -> list[dict[str, str]]:
    """Parse Oracle Taleo CWS v2 searchResults HTML (e.g. Costco)."""
    found: list[dict[str, str]] = []
    seen: set[str] = set()
    link_pat = re.compile(
        r'<a href="((?:https://phf\.tbe\.taleo\.net|/phf\d+/ats/careers/v\d+)[^"]*viewRequisition[^"]*)" '
        r'class="viewJobLink">([^<]+)</a>',
        re.I,
    )
    meta_pat = re.compile(r'<div[^>]*tabindex="0"[^>]*>\s*([^<]+?)\s*</div>', re.I)
    host_base = str(host or "https://phf.tbe.taleo.net/phf02/ats/careers/v2").rstrip("/")
    for match in link_pat.finditer(html_text):
        href = html.unescape(match.group(1).strip())
        if href.startswith("/"):
            parsed_host = urllib.parse.urlsplit(host_base)
            href = f"{parsed_host.scheme}://{parsed_host.netloc}{href}"
        rid_match = re.search(r"[?&]rid=(\d+)", href, re.I)
        rid = rid_match.group(1) if rid_match else ""
        dedupe_key = rid or href
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        title = html.unescape(match.group(2).strip())
        tail = html_text[match.end() : match.end() + 600]
        meta = [html.unescape(re.sub(r"\s+", " ", m.strip())) for m in meta_pat.findall(tail)]
        dept = meta[0] if meta else ""
        location = meta[1] if len(meta) > 1 else ""
        if rid and org and cws:
            url = taleo_cws_canonical_url(host_base, org, cws, rid)
        else:
            url = href
        found.append(
            {
                "title": title,
                "url": url,
                "job_id": rid,
                "department": dept,
                "location": location,
            }
        )
    return found


def fetch_taleo_cws(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    org = str(company.get("taleo_org") or "").strip()
    cws = str(company.get("taleo_cws") or "").strip()
    host = str(company.get("taleo_host") or "https://phf.tbe.taleo.net/phf02/ats/careers/v2").rstrip("/")
    if not org or not cws:
        return [], "taleo_org/taleo_cws missing"
    queries = company_search_queries(company, cfg)
    if not queries:
        queries = ["devops"]
    rows_by_url: dict[str, dict[str, str]] = {}
    query_count = 0
    for kw in queries:
        query_count += 1
        url = f"{host}/searchResults?org={urllib.parse.quote(org)}&cws={urllib.parse.quote(cws)}&keyword={urllib.parse.quote(kw)}"
        cache_key = f"taleo-cws-{company['id']}-{kw}"
        cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=float(company.get("cache_ttl_hours", 8)))
        if cached is not None:
            body = cached
        else:
            code, _, body = http_get(url)
            if code != 200 or not body:
                continue
            cache_set(SCRIPT_DIR, cache_key, body)
        for row in parse_taleo_cws_search(body, host=host, org=org, cws=cws):
            key = row.get("job_id") or row["url"]
            if row.get("job_id") and org and cws:
                row["url"] = taleo_cws_canonical_url(host, org, cws, row["job_id"])
            rows_by_url[key] = row
    max_details = int(company.get("max_details") or 0)
    cache_ttl = float(company.get("cache_ttl_hours", 8))
    detail_urls: set[str] = set()
    if max_details > 0:
        ranked = sorted(rows_by_url.values(), key=lambda row: str(row.get("title") or ""))
        for row in ranked[:max_details]:
            detail_urls.add(str(row["url"]))
    raw: list[RawPosting] = []
    cid = str(company.get("id") or "")
    for row in rows_by_url.values():
        title = row["title"]
        location = row.get("location") or ""
        job_url = str(row["url"])
        if title_rejected_by_scrape_filters(title, cfg, company, url=job_url):
            continue
        meta_parts = [x for x in (row.get("department"), location, "Live posting (Taleo CWS)") if x]
        classify_loc = location
        if not classify_loc or location_text_looks_like_job_title(classify_loc):
            classify_loc = ""
        job_loc, loc_label = classify_location_with_fallback(
            classify_loc,
            company_employer_region(company),
            str(company.get("default_loc") or ""),
            cfg,
        )
        if not job_loc:
            record_filter_reject(cid, title, job_url, "location")
            continue
        description_text = ""
        salary = None
        salary_label = None
        job_url = str(row["url"])
        if job_url in detail_urls:
            description_text = taleo_fetch_detail_text(job_url, cache_ttl_hours=cache_ttl)
            if description_text:
                salary, salary_label = salary_from_detail_text(
                    description_text, cfg, location_name=location
                )
        raw.append(
            RawPosting(
                title=title,
                url=job_url,
                description_text=description_text,
                job_id=row.get("job_id") or "",
                location_name=location,
                salary=salary,
                salary_label=salary_label,
                meta_parts=meta_parts,
                force_loc=job_loc,
                force_loc_label=loc_label,
                skip_keyword_filter=True,
            )
        )
    note = f"Taleo CWS ({query_count} queries, {len(rows_by_url)} listed, {len(raw)} parsed)"
    return raw, note


def taleo_fetch_detail_text(url: str, cache_ttl_hours: float = 12.0) -> str:
    cache_key = f"taleo-detail-{re.sub(r'[^a-zA-Z0-9]+', '-', url).strip('-')[:120]}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
    if cached is not None:
        return cached
    code, _, body = http_get(url)
    if code != 200 or not body:
        return ""
    text = html_to_plain(body)
    cache_set(SCRIPT_DIR, cache_key, text)
    return text


def talentbrew_fetch_detail_text(url: str, cache_ttl_hours: float = 12.0) -> str:
    cache_key = f"talentbrew-detail-{re.sub(r'[^a-zA-Z0-9]+', '-', url).strip('-')[:120]}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
    if cached is not None:
        return cached
    code, _, body = http_get(url)
    if code != 200 or not body:
        return ""
    text = html_to_plain(body)
    cache_set(SCRIPT_DIR, cache_key, text)
    return text


def amazon_jobs_fetch_page_salary(
    job_url: str, cfg: dict[str, Any], *, cache_ttl_hours: float = 12.0
) -> tuple[str, str | None]:
    cache_key = f"amazon-job-page-{re.sub(r'[^a-zA-Z0-9]+', '-', job_url).strip('-')[:100]}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
    if cached is not None:
        return salary_from_detail_text(cached, cfg)
    code, _, body = http_get(job_url)
    if code != 200 or not body:
        return "maybe", None
    text = html_to_plain(body)
    cache_set(SCRIPT_DIR, cache_key, text)
    return salary_from_detail_text(text, cfg)


def talentbrew_total_pages(html_text: str) -> int:
    """Read total page count from Talentbrew search-results markup."""
    for pattern in (
        r'data-total-pages="(\d+)"',
        r'pagination-total-pages[^>]*>\s*/\s*(\d+)',
        r'on page \d+\s*/\s*(\d+)',
    ):
        match = re.search(pattern, html_text, re.I)
        if not match:
            continue
        try:
            return max(1, int(match.group(1)))
        except ValueError:
            continue
    return 1


def talentbrew_search_page_url(host: str, keyword: str, page: int) -> str:
    kw = urllib.parse.quote(keyword)
    base = host.rstrip("/")
    if page <= 1:
        return f"{base}/search-jobs/{kw}"
    return f"{base}/search-jobs/{kw}?page={page}"


def parse_talentbrew_search(html_text: str) -> list[dict[str, str]]:
    """Parse Radancy Talentbrew /search-jobs HTML (UHG, Kaiser, Disney, etc.)."""
    found: list[dict[str, str]] = []
    seen: set[str] = set()

    def _clean_title(raw: str) -> str:
        title_raw = re.sub(r"<[^>]+>", " ", raw)
        return html.unescape(re.sub(r"\s+", " ", title_raw).strip())

    def _clean_loc(raw: str) -> str:
        return html.unescape(re.sub(r"\s+", " ", raw).strip())

    def _append(path: str, job_id: str, title: str, location: str) -> None:
        if job_id in seen:
            return
        seen.add(job_id)
        found.append(
            {
                "title": title,
                "path": path,
                "job_id": job_id,
                "location": location,
            }
        )

    # Anchor-first with a bounded window avoids catastrophic DOTALL backtracking on large pages.
    anchor_pat = re.compile(
        r'<a[^>]+href="([^"]+)"[^>]*data-job-id="(\d+)"[^>]*>',
        re.I,
    )
    chunk_limit = 6000
    for match in anchor_pat.finditer(html_text):
        path, job_id = match.groups()
        if job_id in seen:
            continue
        chunk = html_text[match.start() : min(len(html_text), match.end() + chunk_limit)]
        title_m = re.search(r"<h2[^>]*>(.*?)</h2>", chunk, re.I | re.DOTALL)
        if not title_m:
            continue
        title = _clean_title(title_m.group(1))
        loc_m = re.search(r'<span class="job-location"[^>]*>([^<]+)</span>', chunk, re.I)
        location = _clean_loc(loc_m.group(1)) if loc_m else ""
        if not location:
            location = talentbrew_loc_from_path(path)
        remote_m = re.search(
            r'<span class="job-info job-worksetting"[^>]*>([^<]+)</span>',
            chunk,
            re.I,
        )
        if remote_m:
            remote_txt = html.unescape(remote_m.group(1).strip())
            if remote_txt and remote_txt.lower() not in location.lower():
                location = f"{location} · {remote_txt}" if location else remote_txt
        _append(path, job_id, title, location)
    return found


def talentbrew_detail_priority(title: str) -> tuple[int, str]:
    """Lower sort key = fetch salary detail earlier (director/staff before generic engineer)."""
    title_lower = (title or "").lower()
    for idx, token in enumerate(("director", "principal", "staff", "senior", "lead")):
        if token in title_lower:
            return idx, title_lower
    return 50, title_lower


def fetch_talentbrew_search(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    host = str(company.get("talentbrew_host") or company.get("site_origin") or "").strip().rstrip("/")
    if not host:
        return [], "talentbrew_host missing"
    queries = cap_company_search_queries(company, cfg, max_queries_key="talentbrew_max_queries")
    if not queries:
        queries = ["devops"]
    rows_by_id: dict[str, dict[str, str]] = {}
    query_count = 0
    cid = str(company.get("id") or "")
    for kw in queries:
        if _company_fetch_abandoned(cid):
            break
        query_count += 1
        cache_ttl = float(company.get("cache_ttl_hours", 8))
        max_pages = int(company.get("talentbrew_max_pages") or 20)
        first_body = ""
        for page in range(1, max(1, max_pages) + 1):
            if _company_fetch_abandoned(cid):
                break
            url = talentbrew_search_page_url(host, kw, page)
            cache_key = f"talentbrew-{company['id']}-{kw.replace(' ', '_')}-p{page}"
            cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
            if cached is not None:
                body = cached
            else:
                code, _, body = http_get(url)
                if code != 200 or not body:
                    break
                cache_set(SCRIPT_DIR, cache_key, body)
            if page == 1:
                first_body = body
            page_rows = parse_talentbrew_search(body)
            if not page_rows:
                break
            for row in page_rows:
                rows_by_id[row["job_id"]] = row
            total_pages = talentbrew_total_pages(first_body) if first_body else 1
            if page >= total_pages:
                break
    max_details = int(company.get("max_details") or 0)
    cache_ttl = float(company.get("cache_ttl_hours", 8))
    candidates: list[dict[str, Any]] = []
    for row in rows_by_id.values():
        if _company_fetch_abandoned(cid):
            break
        title = row["title"]
        location = talentbrew_resolve_listing_location(row)
        job_url = urllib.parse.urljoin(host + "/", row["path"].lstrip("/"))
        if title_rejected_by_scrape_filters(title, cfg, company, url=job_url):
            continue
        job_loc, loc_label = classify_location_with_fallback(
            location,
            company_employer_region(company),
            str(company.get("default_loc") or ""),
            cfg,
        )
        if not job_loc:
            record_filter_reject(cid, title, job_url, "location")
            continue
        candidates.append(
            {
                "row": row,
                "title": title,
                "location": location,
                "job_url": job_url,
                "job_loc": job_loc,
                "loc_label": loc_label,
            }
        )
    detail_urls: set[str] = set()
    if max_details > 0 and candidates:
        ranked = sorted(candidates, key=lambda item: talentbrew_detail_priority(str(item["title"])))
        for item in ranked[:max_details]:
            detail_urls.add(str(item["job_url"]))
    detail_fetched = len(detail_urls)
    detail_text_by_url: dict[str, str] = {}
    if detail_urls:
        fetched = _parallel_fetch_ats_details(
            sorted(detail_urls),
            lambda url: talentbrew_fetch_detail_text(url, cache_ttl_hours=cache_ttl),
            company_id=cid,
        )
        detail_text_by_url = {url: str(text or "") for url, text in fetched.items()}
    raw: list[RawPosting] = []
    for item in candidates:
        if _company_fetch_abandoned(cid):
            break
        row = item["row"]
        title = str(item["title"])
        location = str(item["location"])
        job_url = str(item["job_url"])
        description_text = ""
        salary = None
        salary_label = None
        if job_url in detail_urls:
            description_text = detail_text_by_url.get(job_url, "")
            if description_text:
                detail_loc = talentbrew_extract_location_from_detail(description_text)
                if detail_loc and (
                    not location
                    or location_text_looks_like_job_title(location)
                ):
                    location = detail_loc
                location = talentbrew_normalize_listing_location(location, description_text)
                salary, salary_label = salary_from_detail_text(
                    description_text,
                    cfg,
                    location_name=location,
                    job_loc=item["job_loc"],
                )
        meta_parts = [x for x in (location, "Live posting (Talentbrew)") if x]
        raw.append(
            RawPosting(
                title=title,
                url=job_url,
                description_text=description_text,
                job_id=row.get("job_id") or "",
                location_name=location,
                salary=salary,
                salary_label=salary_label,
                meta_parts=meta_parts,
                force_loc=item["job_loc"],
                force_loc_label=item["loc_label"],
                skip_keyword_filter=True,
            )
        )
    note = (
        f"Talentbrew ({query_count} queries, {len(rows_by_id)} listed, "
        f"{detail_fetched} details, {len(raw)} parsed)"
    )
    return raw, note


def dice_mcp_parse_jobs(data: Any) -> list[dict[str, Any]]:
    """Extract job dicts from Dice MCP JSON-RPC or streamable-HTTP payloads."""
    jobs: list[dict[str, Any]] = []

    def absorb(obj: Any) -> None:
        if isinstance(obj, list):
            for item in obj:
                absorb(item)
            return
        if not isinstance(obj, dict):
            return
        if obj.get("detailsPageUrl") or obj.get("title") or obj.get("jobTitle"):
            jobs.append(obj)
            return
        nested = obj.get("data")
        if isinstance(nested, list):
            for item in nested:
                if isinstance(item, dict):
                    jobs.append(item)
        content = obj.get("content")
        if isinstance(content, list):
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    try:
                        absorb(json.loads(str(block.get("text") or "")))
                    except json.JSONDecodeError:
                        pass
        result = obj.get("result")
        if isinstance(result, dict):
            absorb(result)
        elif isinstance(result, list):
            absorb(result)

    absorb(data)
    return jobs


def dice_mcp_request(endpoint: str, payload: dict[str, Any], timeout: int) -> tuple[int, str]:
    req = urllib.request.Request(
        endpoint,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": USER_AGENT,
        },
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.getcode(), resp.read().decode("utf-8", "replace")


def fetch_dice_mcp(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    include, _ = cfg_keywords(cfg)
    queries = company_search_queries(company, cfg)
    if not queries:
        queries = ["devops"]
    endpoint = str(company.get("mcp_url") or "https://mcp.dice.com/mcp").strip()
    mcp_filters = company.get("mcp_filters") or {"workplace_types": ["Remote"]}
    raw: list[RawPosting] = []
    seen: set[str] = set()
    timeout = int(company.get("mcp_timeout", 30))
    for query in queries[: int(company.get("mcp_max_queries", 5))]:
        arguments: dict[str, Any] = {"keyword": query, **mcp_filters}
        payload = {
            "jsonrpc": "2.0",
            "id": 1,
            "method": "tools/call",
            "params": {"name": "search_jobs", "arguments": arguments},
        }
        try:
            _, body = dice_mcp_request(endpoint, payload, timeout)
        except (urllib.error.URLError, TimeoutError, OSError, urllib.error.HTTPError) as err:
            return [], f"Dice MCP error for {query!r}: {err}"
        data: Any = None
        for line in body.splitlines():
            line = line.strip()
            if not line or line.startswith(":"):
                continue
            if line.startswith("data:"):
                line = line[5:].strip()
            try:
                data = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(data, dict):
                break
        if data is None:
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                return [], "Dice MCP returned invalid JSON"
        if isinstance(data, dict) and data.get("error"):
            return [], f"Dice MCP error: {data['error']}"
        jobs = dice_mcp_parse_jobs(data)
        for row in jobs:
            if not isinstance(row, dict):
                continue
            url = str(row.get("detailsPageUrl") or row.get("url") or "").strip()
            title = str(row.get("title") or row.get("jobTitle") or "").strip()
            if not url or not title or url in seen:
                continue
            seen.add(url)
            desc = str(row.get("summary") or row.get("description") or "")
            loc = str(row.get("jobLocation") or row.get("location") or "")
            posted_ts = parse_iso_ts(str(row.get("postedDate") or ""))
            salary_label = str(row.get("salary") or "").strip() or None
            salary = "maybe"
            employer = str(row.get("companyName") or "").strip()
            logo_url = str(
                row.get("companyLogoUrlOptimized") or row.get("companyLogoUrl") or ""
            ).strip()
            meta_parts = [part for part in (employer, loc) if part]
            raw.append(
                RawPosting(
                    title=title,
                    url=url,
                    description_text=html_to_plain(desc),
                    location_name=loc,
                    posted_ts=posted_ts,
                    job_id=str(row.get("id") or ""),
                    salary=salary,
                    salary_label=salary_label,
                    company_name=employer,
                    company_logo_url=logo_url,
                    meta_parts=meta_parts,
                    live_meta="Live posting (Dice MCP)",
                )
            )
    note = f"Dice MCP ({len(queries)} queries, {len(raw)} roles)"
    return raw, note


def fetch_greenhouse(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    if company.get("scrape_disabled"):
        return [], "Greenhouse scrape disabled (scrape_disabled)"
    tier1, tier2, exclude = company_title_tiers(company, cfg)
    board = company.get("board", "gitlab")
    watch = set(company.get("watch_ids", []))
    discover = company.get("discover", True)
    default_loc = str(company.get("default_loc") or "")
    employer_region = company_employer_region(company)
    api = f"https://boards-api.greenhouse.io/v1/boards/{board}/jobs"
    code, _, body = greenhouse_api_get(api)
    if code != 200:
        return [], f"Greenhouse API returned HTTP {code}"
    try:
        board_jobs = json.loads(body).get("jobs", [])
    except json.JSONDecodeError:
        return [], "Greenhouse API returned invalid JSON"
    raw: list[RawPosting] = []
    seen: set[int] = set()
    cid = str(company.get("id") or "")
    skipped_title = skipped_location = skipped_jd = 0
    detail_fetches = 0
    detail_cap = _greenhouse_max_detail_fetches()
    survivors: list[tuple[dict[str, Any], bool]] = []
    for j in board_jobs:
        if _company_fetch_abandoned(cid):
            break
        jid = j["id"]
        title = j["title"]
        job_url = str(j.get("absolute_url") or "")
        in_watch = jid in watch
        if not in_watch:
            if not discover:
                continue
            loc_name = (j.get("location") or {}).get("name", "Remote")
            if not location_text_is_visa_or_perm_metadata(loc_name):
                job_loc, _ = classify_location_with_fallback(
                    loc_name, employer_region, default_loc, cfg, title=title
                )
                if not job_loc:
                    record_filter_reject(cid, title, job_url, "location")
                    skipped_location += 1
                    continue
            if not title_matches_tier1(title, tier1, exclude):
                record_filter_reject(cid, title, job_url, "title_tier1")
                skipped_title += 1
                continue
            if not title_matches_tier2(title, tier2):
                record_filter_reject(cid, title, job_url, "title_tier2")
                skipped_title += 1
                continue
        if jid in seen:
            continue
        seen.add(jid)
        survivors.append((j, in_watch))
    detail_ids, window_offset, non_watch_count = _greenhouse_detail_window_job_ids(
        survivors,
        company_id=cid,
        detail_cap=detail_cap,
    )
    window_enabled = _greenhouse_detail_window_enabled()
    list_only_outside_window = 0
    for j, in_watch in survivors:
        if _company_fetch_abandoned(cid):
            break
        jid = j["id"]
        title = j["title"]
        job_url = str(j.get("absolute_url") or "")
        in_detail_window = jid in detail_ids
        need_content = in_detail_window and _greenhouse_fetch_job_content_enabled(
            in_watch=in_watch
        )
        if need_content:
            if not in_watch:
                detail_fetches += 1
            desc_html = greenhouse_fetch_job_content(board, int(jid), force_refresh=in_watch)
            if str(board or "").strip().lower() == "stripe":
                desc_html = stripe_greenhouse_supplement_detail(int(jid), desc_html)
        else:
            desc_html = ""
            if window_enabled and not in_watch:
                list_only_outside_window += 1
        desc_text = html_to_plain(desc_html)
        loc_name = (j.get("location") or {}).get("name", "Remote")
        ts = parse_iso_ts(j.get("updated_at")) or parse_iso_ts(j.get("first_published"))
        loc_name = greenhouse_resolve_location(
            loc_name,
            str(j.get("absolute_url") or ""),
            desc_html,
            company_name=str(company.get("name") or company.get("label") or company.get("id") or ""),
        )
        loc_name = normalize_board_location_name(loc_name)
        job_loc, loc_label = classify_location_with_fallback(
            loc_name,
            employer_region,
            default_loc,
            cfg,
            title=title,
            description_text=desc_text,
        )
        if not job_loc and not in_watch:
            record_filter_reject(cid, title, job_url, "location")
            skipped_location += 1
            continue
        if in_watch and not job_loc:
            job_loc = "excluded" if loc_name else (
                "remote-intl" if employer_region == "international" else "remote"
            )
            if job_loc == "excluded":
                loc_label = loc_name
        skip = jd_blocks_job(
            desc_text, title, cfg, exclude, keyword_exclude_title_only=not in_watch
        )
        if skip and need_content:
            record_jd_filter_reject(cid, title, skip, url=job_url)
            skipped_jd += 1
            continue
        salary, salary_label = (
            greenhouse_salary_from_detail(
                company, title, desc_text, cfg, location_name=loc_name
            )
            if need_content
            else ("maybe", None)
        )
        raw.append(
            RawPosting(
                title=title,
                url=j["absolute_url"],
                description_text=desc_text,
                location_name=loc_name,
                posted_ts=ts,
                job_id=str(jid),
                salary=salary,
                salary_label=salary_label,
                meta_parts=[loc_name] if loc_name else [],
                force_loc=job_loc or "remote",
                force_loc_label=loc_label,
                keyword_title_only=not in_watch,
                skip_keyword_filter=True,
                skip_verify=True,
            )
        )
    if window_enabled:
        advance_greenhouse_detail_offset(cid, non_watch_count, detail_cap)
    parsed = len(raw)
    note = f"Board scan ({len(board_jobs)} total, {parsed} parsed) + {len(watch)} watch IDs"
    if not _env_flag("QUICKJOBS_GREENHOUSE_FETCH_CONTENT") and _env_flag(
        "QUICKJOBS_GREENHOUSE_LIST_ONLY", default="0"
    ):
        note += " (list-only)"
    if window_enabled and non_watch_count > detail_cap:
        note += (
            f" (detail window {window_offset}:{window_offset + detail_cap}"
            f" of {non_watch_count}, {list_only_outside_window} list-only)"
        )
    elif window_enabled and detail_cap and detail_fetches >= detail_cap:
        note += f" (detail cap {detail_cap})"
    if parsed == 0 and board_jobs and discover:
        note += f" (skipped: {skipped_title} title, {skipped_location} location, {skipped_jd} JD)"
    return raw, note


def lever_salary_from_posting(
    posting: dict[str, Any],
    description_text: str,
    cfg: dict[str, Any],
    *,
    location_name: str = "",
) -> tuple[str, str | None]:
    """Lever API exposes salaryRange; amounts are often absent from descriptionPlain."""
    salary_range = posting.get("salaryRange")
    if isinstance(salary_range, dict):
        low = int(salary_range.get("min") or 0)
        high = int(salary_range.get("max") or 0)
        if low > 0 and high > 0 and high >= low:
            return salary_range_status("base", low, high, cfg)
    blob = description_text
    extra = str(posting.get("salaryDescriptionPlain") or "").strip()
    if extra and extra not in blob:
        blob = f"{blob}\n\n{extra}" if blob else extra
    return salary_from_detail_text(blob, cfg, location_name=location_name)


def lever_fetch_posting_text(posting_url: str, cache_ttl_hours: float = 24.0) -> str:
    body = cached_html_fetch(posting_url, "lever-detail", cache_ttl_hours=cache_ttl_hours)
    return html_to_plain(body) if body else ""


def fetch_lever(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = company_title_tiers(company, cfg)
    site = str(company.get("lever_site") or company["id"]).strip()
    employer_region = company_employer_region(company)
    api = f"https://api.lever.co/v0/postings/{site}?mode=json"
    code, _, body = http_get(api)
    if code != 200:
        return [], f"Lever API returned HTTP {code}"
    try:
        postings = json.loads(body)
    except json.JSONDecodeError:
        return [], "Lever API returned invalid JSON"
    if not isinstance(postings, list):
        return [], "Lever API returned unexpected payload"
    cid = str(company.get("id") or "")
    raw: list[RawPosting] = []
    for posting in postings:
        title = str(posting.get("text") or "").strip()
        posting_url = str(posting.get("hostedUrl") or posting.get("applyUrl") or "").strip()
        if title_rejected_by_scrape_filters(title, cfg, company, url=posting_url or None):
            continue
        categories = posting.get("categories") if isinstance(posting.get("categories"), dict) else {}
        location_name = lever_posting_location_label(posting)
        if not posting_url:
            continue
        description_text = str(posting.get("descriptionPlain") or "").strip()
        if not description_text:
            description_text = lever_fetch_posting_text(posting_url)
        if not lever_posting_us_workable(posting, description_text):
            record_filter_reject(cid, title, posting_url, "location_non_us")
            continue
        job_loc, loc_label = classify_location_with_fallback(
            location_name or title,
            employer_region,
            str(company.get("default_loc") or ""),
            cfg,
        )
        if not job_loc:
            record_filter_reject(cid, title, posting_url, "location")
            continue
        skip = jd_blocks_job(description_text, title, cfg, exclude, keyword_exclude_title_only=True)
        if skip:
            record_jd_filter_reject(cid, title, skip, url=posting_url)
            continue
        posted_ts = int((posting.get("createdAt") or 0) // 1000)
        salary, salary_label = lever_salary_from_posting(
            posting, description_text, cfg, location_name=location_name
        )
        if salary == "maybe" and not salary_label and posting_url:
            page_text = lever_fetch_posting_text(posting_url)
            if page_text:
                salary, salary_label = salary_from_detail_text(
                    page_text, cfg, location_name=location_name
                )
        raw.append(
            RawPosting(
                title=title,
                url=posting_url.split("?")[0],
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(posting.get("id") or ""),
                salary=salary,
                salary_label=salary_label,
                meta_parts=[location_name] if location_name else [],
                force_loc=job_loc,
                force_loc_label=loc_label,
                keyword_title_only=True,
                skip_keyword_filter=True,
            )
        )
    note = f"Lever board {site} ({len(postings)} total, {len(raw)} parsed)"
    return raw, note


def ashby_title_slug(title: str) -> str:
    """Slug for custom Ashby careers pages (e.g. cursor.com/careers/<slug>)."""
    text = str(title or "").strip().lower()
    text = re.sub(r"[^a-z0-9]+", "-", text)
    return text.strip("-")


def ashby_page_is_live(url: str, title: str = "") -> bool:
    """True when an Ashby posting URL returns HTML that looks like a real job page."""
    if not url:
        return False
    code, final_url, body = http_verify_get(url, max_bytes=65536)
    if url_page_indicates_dead_job(code, final_url, body):
        return False
    if code < 200 or code >= 400:
        return False
    title_norm = re.sub(r"\s+", " ", str(title or "").strip().lower())
    body_lower = (body or "").lower()
    if title_norm and title_norm in body_lower:
        return True
    if "page not found" in body_lower:
        return False
    return len(body or "") >= 12_000


def ashby_posting_url_candidates(company: dict[str, Any], posting: dict[str, Any]) -> list[str]:
    """Ordered Ashby posting URL candidates: API jobUrl, board/id fallback, optional custom careers slug."""
    seen: set[str] = set()
    candidates: list[str] = []

    def _add(url: str) -> None:
        clean = str(url or "").strip().split("?")[0].rstrip("/")
        if clean and clean not in seen:
            seen.add(clean)
            candidates.append(clean)

    posting_url = str(posting.get("jobUrl") or posting.get("applyUrl") or "").strip()
    if posting_url.endswith("/application"):
        posting_url = posting_url[: -len("/application")]
    _add(posting_url)
    board = str(company.get("ashby_board") or company.get("id") or "").strip()
    job_id = str(posting.get("id") or "").strip()
    if board and job_id:
        _add(f"https://jobs.ashbyhq.com/{board}/{job_id}")
    custom_base = str(company.get("ashby_custom_jobs_base") or "").strip().rstrip("/")
    title = str(posting.get("title") or "").strip()
    if custom_base and title:
        slug = ashby_title_slug(title)
        if slug:
            _add(f"{custom_base}/{slug}")
    return candidates


def _ashby_skip_url_verify() -> bool:
    """Trust standard jobs.ashbyhq.com/{board}/{id} URLs without a live GET."""
    return _env_flag("QUICKJOBS_ASHBY_SKIP_URL_VERIFY", default="1")


def _ashby_is_standard_board_url(url: str, board: str) -> bool:
    clean = str(url or "").strip().split("?")[0].rstrip("/")
    board_slug = str(board or "").strip()
    if not clean or not board_slug:
        return False
    prefix = f"https://jobs.ashbyhq.com/{board_slug}/"
    if not clean.lower().startswith(prefix.lower()):
        return False
    suffix = clean[len(prefix) :]
    return bool(
        re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
            suffix,
            re.I,
        )
    )


def ashby_pick_posting_url(company: dict[str, Any], posting: dict[str, Any]) -> str:
    """Return the first candidate URL that looks like a live posting page."""
    title = str(posting.get("title") or "").strip()
    board = str(company.get("ashby_board") or company.get("id") or "").strip()
    skip_verify = _ashby_skip_url_verify()
    for url in ashby_posting_url_candidates(company, posting):
        if skip_verify and board and _ashby_is_standard_board_url(url, board):
            return url
        if ashby_page_is_live(url, title):
            return url
    return ""


def ashby_posting_url(company: dict[str, Any], posting: dict[str, Any]) -> str:
    """Resolve a live Ashby posting URL (API jobUrl when it works; custom careers slug when not)."""
    return ashby_pick_posting_url(company, posting)


def ashby_posting_location_label(posting: dict[str, Any]) -> str:
    parts: list[str] = []
    loc = str(posting.get("location") or "").strip()
    if loc:
        parts.append(loc)
    for sec in posting.get("secondaryLocations") or []:
        if isinstance(sec, dict):
            sloc = str(sec.get("location") or "").strip()
            if sloc and sloc not in parts:
                parts.append(sloc)
    wtype = str(posting.get("workplaceType") or "").strip()
    if posting.get("isRemote") or wtype.lower() == "remote":
        if not any("remote" in p.lower() for p in parts):
            parts.append(wtype or "Remote")
    return ", ".join(parts)


def ashby_posting_us_workable(posting: dict[str, Any], description_text: str = "") -> bool:
    location_name = ashby_posting_location_label(posting)
    if location_name and location_text_indicates_us_worksite(location_name):
        return True
    for sec in posting.get("secondaryLocations") or []:
        if not isinstance(sec, dict):
            continue
        sloc = str(sec.get("location") or "").strip()
        if sloc and location_text_indicates_us_worksite(sloc):
            return True
        addr = sec.get("address") or {}
        if isinstance(addr, dict):
            postal = addr.get("postalAddress") or {}
            if isinstance(postal, dict):
                country = str(postal.get("addressCountry") or "").strip()
                if country_part_is_us(country):
                    return True
    primary = str(posting.get("location") or "").strip()
    if primary and location_text_indicates_non_us_worksite(primary):
        if not posting.get("isRemote"):
            return False
    if description_text:
        based = re.search(
            r"(?:this role is based in|where you['’]ll be)[^\n.]{0,160}",
            description_text,
            re.I,
        )
        if based and location_text_indicates_non_us_worksite(based.group(0)):
            if not location_text_indicates_us_worksite(based.group(0)):
                return False
    return bool(posting.get("isRemote") or location_name)


ASHBY_APP_DATA_RE = re.compile(
    r"window\.__appData\s*=\s*(\{.*?\})\s*;\s*\n",
    re.DOTALL,
)


def _ashby_use_board_html() -> bool:
    """List Ashby jobs from board SSR HTML instead of the posting-api JSON."""
    return _env_flag("QUICKJOBS_ASHBY_USE_BOARD_HTML", default="1")


def ashby_parse_board_job_postings(body: str) -> list[dict[str, Any]]:
    """Extract jobPostings from jobs.ashbyhq.com/{board} SSR window.__appData."""
    match = ASHBY_APP_DATA_RE.search(body or "")
    if not match:
        return []
    try:
        payload = json.loads(match.group(1))
    except json.JSONDecodeError:
        return []
    job_board = payload.get("jobBoard")
    if not isinstance(job_board, dict):
        return []
    postings = job_board.get("jobPostings") or []
    if not isinstance(postings, list):
        return []
    return [p for p in postings if isinstance(p, dict)]


def ashby_board_posting_to_listing(posting: dict[str, Any], board: str) -> dict[str, Any]:
    """Normalize board SSR jobPostings row to posting-api-like dict (no descriptions)."""
    posting_id = str(posting.get("id") or "").strip()
    workplace_type = str(posting.get("workplaceType") or "").strip()
    is_remote = bool(posting.get("isRemote")) or workplace_type.lower() == "remote"
    location = str(
        posting.get("locationName") or posting.get("locationExternalName") or ""
    ).strip()
    secondary_locations: list[dict[str, Any]] = []
    for sec in posting.get("secondaryLocations") or []:
        if not isinstance(sec, dict):
            continue
        sloc = str(sec.get("locationName") or sec.get("location") or "").strip()
        entry = dict(sec)
        if sloc:
            entry["location"] = sloc
        secondary_locations.append(entry)
    published = ashby_published_at_from_posting(posting)
    job_url = f"https://jobs.ashbyhq.com/{board}/{posting_id}" if board and posting_id else ""
    return {
        "id": posting_id,
        "title": posting.get("title"),
        "location": location,
        "employmentType": posting.get("employmentType"),
        "isListed": posting.get("isListed"),
        "isRemote": is_remote,
        "workplaceType": workplace_type,
        "publishedAt": published,
        "secondaryLocations": secondary_locations,
        "jobUrl": job_url,
        "applyUrl": job_url,
    }


def ashby_published_at_from_posting(posting: dict[str, Any] | None) -> str:
    """Published timestamp from an Ashby list or posting-api row."""
    if not isinstance(posting, dict):
        return ""
    for key in ("publishedAt", "publishedDate", "updatedAt"):
        val = str(posting.get(key) or "").strip()
        if val:
            return val
    return ""


def ashby_published_at_from_html(body: str) -> str:
    """Posted date from a posting page (__appData or JobPosting JSON-LD)."""
    text = str(body or "")
    if not text:
        return ""
    page = ashby_posting_page_posting(text)
    found = ashby_published_at_from_posting(page)
    if found:
        return found
    for match in re.finditer(
        r'<script[^>]*type=["\']application/ld\+json["\'][^>]*>(.*?)</script>',
        text,
        re.I | re.S,
    ):
        try:
            data = json.loads(match.group(1))
        except json.JSONDecodeError:
            continue
        nodes = data if isinstance(data, list) else [data]
        for node in nodes:
            if not isinstance(node, dict):
                continue
            val = str(node.get("datePosted") or "").strip()
            if val:
                return val
    return ""


def ashby_fetch_posting_api_jobs(
    board: str, cache_ttl_hours: float
) -> tuple[list[dict[str, Any]], str | None]:
    """Cached posting-api JSON jobs list (includes publishedAt)."""
    api = f"https://api.ashbyhq.com/posting-api/job-board/{board}"
    cache_key = f"ashby-list-{board}"
    body = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
    if body is not None:
        code = 200
    else:
        code, _, body = http_get(api, timeout=_ashby_read_timeout_sec())
        if code == 200 and body:
            cache_set(SCRIPT_DIR, cache_key, body)
    if code != 200:
        return [], f"Ashby API returned HTTP {code}"
    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return [], "Ashby API returned invalid JSON"
    postings = payload.get("jobs") or []
    if not isinstance(postings, list):
        return [], "Ashby API returned unexpected payload"
    return postings, None


def ashby_fetch_published_at_map(
    company: dict[str, Any], cache_ttl_hours: float
) -> dict[str, str]:
    """Map posting id -> publishedAt from the posting-api JSON board."""
    board = str(company.get("ashby_board") or company.get("id") or "").strip()
    if not board:
        return {}
    jobs, err = ashby_fetch_posting_api_jobs(board, cache_ttl_hours)
    if err:
        return {}
    out: dict[str, str] = {}
    for job in jobs:
        if not isinstance(job, dict):
            continue
        jid = str(job.get("id") or "").strip()
        published = ashby_published_at_from_posting(job)
        if jid and published:
            out[jid] = published
    return out


def ashby_overlay_published_at(
    postings: list[dict[str, Any]],
    company: dict[str, Any],
    cache_ttl_hours: float,
) -> None:
    """Fill missing publishedAt on board-HTML rows from posting-api dates."""
    missing = [
        row
        for row in postings
        if isinstance(row, dict)
        and str(row.get("id") or "").strip()
        and not ashby_published_at_from_posting(row)
    ]
    if not missing:
        return
    date_map = ashby_fetch_published_at_map(company, cache_ttl_hours)
    if not date_map:
        return
    for row in missing:
        published = date_map.get(str(row.get("id") or "").strip())
        if published:
            row["publishedAt"] = published


def ashby_posting_description_text(posting: dict[str, Any]) -> str:
    description_text = str(posting.get("descriptionPlain") or "").strip()
    if description_text:
        return description_text
    return html_to_plain(str(posting.get("descriptionHtml") or ""))


def ashby_description_from_posting_html(body: str) -> str:
    """Plain-text JD from a single Ashby posting page (__appData.posting)."""
    posting = ashby_posting_page_posting(body)
    if not posting:
        return ""
    plain = str(
        posting.get("descriptionPlainText") or posting.get("descriptionPlain") or ""
    ).strip()
    if plain:
        return plain
    return html_to_plain(str(posting.get("descriptionHtml") or ""))


def ashby_posting_page_posting(body: str) -> dict[str, Any] | None:
    match = ASHBY_APP_DATA_RE.search(body or "")
    if not match:
        return None
    try:
        payload = json.loads(match.group(1))
    except json.JSONDecodeError:
        return None
    posting = payload.get("posting")
    return posting if isinstance(posting, dict) else None


def ashby_merge_posting_page_fields(posting: dict[str, Any], body: str) -> str:
    """Merge isRemote (and related fields) from posting HTML; return description text."""
    page_posting = ashby_posting_page_posting(body)
    if not page_posting:
        return ""
    if page_posting.get("isRemote") is True:
        posting["isRemote"] = True
    page_location = str(
        page_posting.get("locationName") or page_posting.get("locationExternalName") or ""
    ).strip()
    if page_location and not str(posting.get("location") or "").strip():
        posting["location"] = page_location
    return ashby_description_from_posting_html(body)


def ashby_posting_obviously_non_us(posting: dict[str, Any]) -> bool:
    """Fast reject for clearly non-US onsite roles using board list metadata only."""
    primary = str(posting.get("location") or "").strip()
    if not primary or not location_text_indicates_non_us_worksite(primary):
        return False
    workplace_type = str(posting.get("workplaceType") or "").lower()
    if posting.get("isRemote") or workplace_type in ("remote", "hybrid"):
        return False
    return True


def ashby_lazy_fetch_description(posting_url: str, cache_ttl_hours: float = 24.0) -> str:
    body = ashby_fetch_posting_html(posting_url, cache_ttl_hours=cache_ttl_hours)
    if not body:
        return ""
    return ashby_description_from_posting_html(body)


def ashby_fetch_list_postings(
    company: dict[str, Any], cache_ttl_hours: float
) -> tuple[list[dict[str, Any]], str, str | None]:
    """Fetch Ashby board listings; returns (postings, source, error)."""
    board = str(company.get("ashby_board") or company["id"]).strip()
    read_timeout = _ashby_read_timeout_sec()
    if _ashby_use_board_html():
        board_url = f"https://jobs.ashbyhq.com/{board}"
        cache_key = f"ashby-board-html-{board}"
        body = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
        if body is not None:
            code = 200
        else:
            code, _, body = http_get(board_url, timeout=read_timeout)
            if code == 200 and body:
                cache_set(SCRIPT_DIR, cache_key, body)
        if code == 200 and body:
            raw_postings = ashby_parse_board_job_postings(body)
            if raw_postings:
                listings = [
                    ashby_board_posting_to_listing(p, board) for p in raw_postings
                ]
                return listings, "board-html", None
    postings, api_err = ashby_fetch_posting_api_jobs(board, cache_ttl_hours)
    if api_err:
        return [], "posting-api", api_err
    return postings, "posting-api", None


def ashby_fetch_posting_html(posting_url: str, cache_ttl_hours: float = 24.0) -> str:
    if _company_fetch_abandoned(_current_fetch_company_id()):
        return ""
    return cached_html_fetch(posting_url, "ashby-detail", cache_ttl_hours=cache_ttl_hours)


def ashby_comp_range_from_app_data(body: str) -> tuple[str, int, int] | None:
    """Ashby SPA embeds compensation in window.__appData.posting (not the listing API)."""
    match = ASHBY_APP_DATA_RE.search(body or "")
    if not match:
        return None
    try:
        payload = json.loads(match.group(1))
    except json.JSONDecodeError:
        return None
    posting = payload.get("posting")
    if not isinstance(posting, dict):
        return None
    lows: list[int] = []
    highs: list[int] = []
    for comp in posting.get("summaryComponents") or []:
        if not isinstance(comp, dict):
            continue
        if str(comp.get("compensationType") or "").strip().lower() != "salary":
            continue
        low = parse_money_amount(comp.get("minValue"))
        high = parse_money_amount(comp.get("maxValue"))
        if low > 0 and high > 0:
            lows.append(low)
            highs.append(high)
    for tier in posting.get("compensationTiers") or []:
        if not isinstance(tier, dict):
            continue
        for comp in tier.get("components") or []:
            if not isinstance(comp, dict):
                continue
            if str(comp.get("compensationType") or "").strip().lower() != "salary":
                continue
            low = parse_money_amount(comp.get("minValue"))
            high = parse_money_amount(comp.get("maxValue"))
            if low > 0 and high > 0:
                lows.append(low)
                highs.append(high)
    if lows and highs:
        return "base", min(lows), max(highs)
    for key in ("scrapeableCompensationSalarySummary", "compensationTierSummary"):
        summary = str(posting.get(key) or "").strip()
        if summary:
            comp = extract_comp_range_from_text(summary)
            if comp:
                return comp
    return None


def ashby_salary_from_posting_html(
    body: str, cfg: dict[str, Any], *, title: str = ""
) -> tuple[str, str | None]:
    for posting in extract_json_ld_jobpostings(body):
        salary, label = jsonld_salary_status(posting, cfg)
        if salary != "maybe" or label:
            return salary, label
    comp = ashby_comp_range_from_app_data(body)
    if comp:
        kind, low, high = comp
        return salary_range_status(kind, low, high, cfg, title=title)
    return "maybe", None


def ashby_salary_from_posting(
    posting: dict[str, Any],
    description_text: str,
    cfg: dict[str, Any],
    *,
    location_name: str = "",
    posting_url: str = "",
    title: str = "",
    allow_posting_html_fetch: bool = True,
) -> tuple[str, str | None]:
    """Ashby listing API omits pay; job pages expose JSON-LD baseSalary and __appData."""
    salary, salary_label = salary_from_detail_text(
        description_text, cfg, location_name=location_name, title=title
    )
    if salary != "maybe" or salary_label or not posting_url or not allow_posting_html_fetch:
        return salary, salary_label
    body = ashby_fetch_posting_html(posting_url)
    if not body:
        return salary, salary_label
    return ashby_salary_from_posting_html(body, cfg, title=title)


def _ashby_read_timeout_sec() -> int:
    """Ashby list API read timeout (QUICKJOBS_ASHBY_READ_TIMEOUT_SEC, default 180s)."""
    return _env_worker_count("QUICKJOBS_ASHBY_READ_TIMEOUT_SEC", 180, cap=600)


def _ashby_list_cache_ttl_hours() -> float:
    """Ashby list JSON cache TTL (QUICKJOBS_ASHBY_LIST_CACHE_TTL_HOURS, default 12h)."""
    raw = os.environ.get("QUICKJOBS_ASHBY_LIST_CACHE_TTL_HOURS", "12").strip()
    try:
        return max(1.0, min(168.0, float(raw)))
    except ValueError:
        return 12.0


def fetch_ashby(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = company_title_tiers(company, cfg)
    board = str(company.get("ashby_board") or company["id"]).strip()
    employer_region = company_employer_region(company)
    cache_ttl_hours = float(company.get("cache_ttl_hours") or _ashby_list_cache_ttl_hours())
    postings, list_source, list_err = ashby_fetch_list_postings(company, cache_ttl_hours)
    if list_err:
        return [], list_err
    if list_source == "board-html":
        ashby_overlay_published_at(postings, company, cache_ttl_hours)
    cid = str(company.get("id") or "")
    watch = {str(x) for x in company.get("watch_ids", [])}
    use_board_html = list_source == "board-html"
    detail_cap = _ashby_max_detail_fetches()
    survivors: list[tuple[dict[str, Any], str, bool, str, str, str, str | None]] = []
    for posting in postings:
        if _company_fetch_abandoned(cid):
            break
        if not isinstance(posting, dict):
            continue
        if posting.get("isListed") is False:
            continue
        title = str(posting.get("title") or "").strip()
        posting_url = ashby_posting_url(company, posting)
        if title_rejected_by_scrape_filters(title, cfg, company, url=posting_url or None):
            continue
        if not posting_url:
            continue
        list_description = (
            "" if use_board_html else ashby_posting_description_text(posting)
        )
        if use_board_html and ashby_posting_obviously_non_us(posting):
            record_filter_reject(cid, title, posting_url, "location_non_us")
            continue
        if not use_board_html and not ashby_posting_us_workable(posting, list_description):
            record_filter_reject(cid, title, posting_url, "location_non_us")
            continue
        location_name = ashby_posting_location_label(posting)
        job_loc, loc_label = classify_location_with_fallback(
            location_name or title,
            employer_region,
            str(company.get("default_loc") or ""),
            cfg,
            title=title,
            description_text=list_description,
        )
        if not job_loc:
            record_filter_reject(cid, title, posting_url, "location")
            continue
        posting_id = str(posting.get("id") or "")
        in_watch = posting_id in watch
        survivors.append(
            (
                posting,
                posting_url,
                in_watch,
                list_description,
                location_name,
                job_loc,
                loc_label,
            )
        )
    detail_ids, window_offset, non_watch_count = _ashby_detail_window_posting_ids(
        [(posting, in_watch) for posting, _url, in_watch, *_rest in survivors],
        company_id=cid,
        detail_cap=detail_cap,
        use_board_html=use_board_html,
    )
    window_enabled = _ashby_detail_window_enabled(use_board_html=use_board_html)
    urls_to_fetch: list[str] = []
    seen_fetch_urls: set[str] = set()
    for posting, posting_url, in_watch, list_description, *_rest in survivors:
        posting_id = str(posting.get("id") or "")
        in_detail_window = posting_id in detail_ids
        need_jd_html = use_board_html and in_detail_window and not list_description
        need_salary_html = (
            _ashby_posting_html_salary_enabled(in_watch=in_watch)
            and in_detail_window
            and not need_jd_html
            and bool(posting_url)
        )
        if (need_jd_html or need_salary_html) and posting_url not in seen_fetch_urls:
            seen_fetch_urls.add(posting_url)
            urls_to_fetch.append(posting_url)
    detail_html_by_url = _parallel_fetch_ats_details(
        urls_to_fetch,
        lambda url: ashby_fetch_posting_html(url, cache_ttl_hours=cache_ttl_hours),
        company_id=cid,
    )
    raw: list[RawPosting] = []
    detail_fetches = 0
    list_only_outside_window = 0
    for (
        posting,
        posting_url,
        in_watch,
        list_description,
        location_name,
        job_loc,
        loc_label,
    ) in survivors:
        if _company_fetch_abandoned(cid):
            break
        title = str(posting.get("title") or "").strip()
        posting_id = str(posting.get("id") or "")
        in_detail_window = posting_id in detail_ids
        description_text = list_description
        posting_html_body = ""
        fetched_html = False
        if use_board_html and in_detail_window and not description_text:
            posting_html_body = detail_html_by_url.get(posting_url) or ""
            if posting_html_body:
                fetched_html = True
                description_text = ashby_merge_posting_page_fields(
                    posting, posting_html_body
                )
            if not in_watch and fetched_html:
                detail_fetches += 1
        elif window_enabled and use_board_html and not in_detail_window and not in_watch:
            list_only_outside_window += 1
        if use_board_html and description_text and not ashby_posting_us_workable(
            posting, description_text
        ):
            record_filter_reject(cid, title, posting_url, "location_non_us")
            continue
        if not description_text:
            if window_enabled and not in_detail_window and not in_watch:
                pass
            else:
                record_filter_reject(cid, title, posting_url, "description")
                continue
        skip = jd_blocks_job(
            description_text, title, cfg, exclude, keyword_exclude_title_only=True
        )
        if skip and description_text:
            record_jd_filter_reject(cid, title, skip, url=posting_url)
            continue
        allow_salary_fetch = _ashby_posting_html_salary_enabled(in_watch=in_watch)
        if (
            allow_salary_fetch
            and in_detail_window
            and posting_url
            and not posting_html_body
        ):
            posting_html_body = detail_html_by_url.get(posting_url) or ""
            if posting_html_body and not fetched_html and not in_watch:
                detail_fetches += 1
        # Prefer pay from posting HTML whenever we already fetched it (board-html
        # JD window) — Ashby list payloads omit Cash Compensation.
        if posting_html_body:
            salary, salary_label = ashby_salary_from_posting_html(
                posting_html_body, cfg, title=title
            )
        else:
            salary, salary_label = ashby_salary_from_posting(
                posting,
                description_text,
                cfg,
                location_name=location_name,
                posting_url=posting_url,
                title=title,
                allow_posting_html_fetch=False,
            )
        posted_raw = ashby_published_at_from_posting(posting)
        if not posted_raw and posting_html_body:
            posted_raw = ashby_published_at_from_html(posting_html_body)
        posted_ts = parse_iso_ts(posted_raw)
        meta_parts = [
            p for p in (location_name, str(posting.get("employmentType") or "").strip()) if p
        ]
        raw.append(
            RawPosting(
                title=title,
                url=posting_url.split("?")[0],
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=posting_id,
                salary=salary,
                salary_label=salary_label,
                meta_parts=meta_parts,
                force_loc=job_loc,
                force_loc_label=loc_label,
                keyword_title_only=True,
                skip_keyword_filter=True,
            )
        )
    if window_enabled:
        advance_ashby_detail_offset(cid, non_watch_count, detail_cap)
    note = f"Ashby board {board} ({len(postings)} total, {len(raw)} parsed, {list_source})"
    if not _ashby_posting_html_salary_enabled(in_watch=False):
        note += " (salary HTML list-only)"
    if window_enabled and non_watch_count > detail_cap:
        note += (
            f" (detail window {window_offset}:{window_offset + detail_cap}"
            f" of {non_watch_count}, {list_only_outside_window} list-only)"
        )
    elif detail_cap and detail_fetches >= detail_cap:
        note += f" (posting-page cap {detail_cap})"
    return raw, note


def amazon_job_location_context(
    job: dict[str, Any], cfg: dict[str, Any] | None = None
) -> tuple[str, str, set[str]]:
    """Location label, search blob, and country tokens from an Amazon jobs API row."""
    raw_location = str(job.get("location") or "").strip()
    normalized = str(job.get("normalized_location") or "").strip()
    country_codes: set[str] = set()
    local_candidate = ""
    site_labels: list[str] = []
    for loc_blob in job.get("locations") or []:
        try:
            loc_obj = json.loads(loc_blob) if isinstance(loc_blob, str) else loc_blob
        except json.JSONDecodeError:
            continue
        if not isinstance(loc_obj, dict):
            continue
        for key in ("normalizedCountryCode", "countryIso2a", "countryIso3a"):
            val = str(loc_obj.get(key) or "").strip().upper()
            if val:
                country_codes.add(val)
        country_name = str(loc_obj.get("normalizedCountryName") or "").strip()
        if country_name:
            country_codes.add(country_name.upper())
        candidate = str(loc_obj.get("normalizedLocation") or loc_obj.get("location") or "").strip()
        if candidate and candidate not in site_labels:
            site_labels.append(candidate)
        if candidate and (
            "portland" in candidate.lower()
            or "oregon" in candidate.lower()
            or (cfg and location_within_local_radius(candidate, cfg))
        ):
            local_candidate = candidate
    location_name = local_candidate or normalized or raw_location
    blob_parts = [p for p in (raw_location, normalized, location_name, *site_labels) if p]
    search_blob = " | ".join(dict.fromkeys(blob_parts))
    return location_name, search_blob, country_codes


def amazon_job_non_us_country_codes(country_codes: set[str]) -> bool:
    if not country_codes:
        return False
    usish = {"US", "USA", "UNITED STATES", "U.S.", "U.S.A."}
    return bool(country_codes - usish)


def amazon_job_description_text(job: dict[str, Any]) -> str:
    """Join Amazon search-API description with basic/preferred qualifications for match scoring."""
    parts: list[str] = []
    for key in ("description", "basic_qualifications", "preferred_qualifications"):
        raw = str(job.get(key) or "").strip()
        if not raw:
            continue
        plain = html_to_plain(raw).strip()
        if plain:
            parts.append(plain)
    return "\n\n".join(parts)


def amazon_job_scrape_reject_reason(
    location_name: str,
    search_blob: str,
    country_codes: set[str],
    job_loc: str | None,
    loc_label: str | None,
) -> str | None:
    """Return scrape filter reason when an Amazon posting is non-US or location-bound."""
    blob = " ".join(x for x in (location_name, search_blob, loc_label or "") if x)
    india_codes = {"IND", "IN", "INDIA"}
    if amazon_job_non_us_country_codes(country_codes):
        if country_codes & india_codes or location_text_indicates_india(blob):
            return "location_india"
        return "location_non_us"
    if location_text_indicates_india(blob):
        return "location_india"
    if not job_loc or job_loc == "excluded":
        if location_text_indicates_non_us_worksite(location_name, loc_label or "", search_blob):
            return "location_non_us"
        return "location"
    return None


def _parse_amazon_jobs_api(
    body: str, cfg: dict[str, Any], company: dict[str, Any]
) -> list[RawPosting]:
    _, _, exclude = cfg_title_tiers(cfg)
    employer_region = company_employer_region(company)
    default_loc = str(company.get("default_loc") or "")
    company_filter = str(company.get("amazon_company_name") or "").strip().lower()
    discover_all = bool(company.get("amazon_discover_all"))
    cid = str(company.get("id") or "")
    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return []
    raw: list[RawPosting] = []
    for job in payload.get("jobs") or []:
        if company_filter:
            employer = str(job.get("company_name") or "").strip().lower()
            if employer and company_filter not in employer:
                continue
        title = str(job.get("title") or job.get("title_normalized") or "").strip()
        job_path = str(job.get("job_path") or "").strip()
        if not job_path:
            continue
        url = f"https://www.amazon.jobs{job_path}" if job_path.startswith("/") else job_path
        if not discover_all and title_rejected_by_scrape_filters(title, cfg, company, url=url):
            continue
        location_name, location_search_blob, country_codes = amazon_job_location_context(job, cfg)
        description_text = amazon_job_description_text(job)
        # Title-only keyword excludes: JDs often mention collaborating with "data scientists"
        # etc. without the role itself being that track.
        skip = jd_blocks_job(description_text, title, cfg, exclude, keyword_exclude_title_only=True)
        if skip:
            record_jd_filter_reject(cid, title, skip, url=url)
            continue
        job_loc, loc_label = classify_location_with_fallback(
            location_name or title,
            employer_region,
            default_loc,
            cfg,
            description_text=description_text,
        )
        reject_reason = amazon_job_scrape_reject_reason(
            location_name,
            location_search_blob,
            country_codes,
            job_loc,
            loc_label,
        )
        if reject_reason:
            record_filter_reject(cid, title, url, reject_reason)
            continue
        salary = None
        salary_label = None
        if description_text:
            salary, salary_label = salary_from_detail_text(
                description_text, cfg, location_name=location_name
            )
        raw.append(
            RawPosting(
                title=title,
                url=url,
                description_text=description_text,
                location_name=location_name,
                job_id=str(job.get("id_icims") or job.get("id") or ""),
                employment="full-time",
                salary=salary,
                salary_label=salary_label,
                meta_parts=[location_name] if location_name else [],
                force_loc=job_loc,
                force_loc_label=loc_label,
                skip_keyword_filter=True,
                skip_jd_blocklist=True,
            )
        )
    return raw


def fetch_netflix(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    tier1, _, exclude = cfg_title_tiers(cfg)
    by_id: dict[str, dict[str, Any]] = {}
    for kw in tier1:
        q = urllib.parse.quote(kw)
        url = f"https://explore.jobs.netflix.net/careers?location=Remote&query={q}"
        for p in extract_json_array_after_key(html.unescape(http_get(url)[2])):
            jid = str(p.get("id", ""))
            if jid:
                by_id[jid] = p
    for jid in company.get("watch_ids", []):
        detail = netflix_fetch_position(str(jid))
        if detail:
            by_id[str(jid)] = detail
    raw: list[RawPosting] = []
    cid = str(company.get("id") or "")
    for jid, p in by_id.items():
        name = p.get("name") or p.get("posting_name") or "Netflix role"
        job_url = p.get("canonical_url") or f"https://explore.jobs.netflix.net/careers/job/{jid}"
        remote_ok, remote_warn = netflix_remote_quality(p)
        if not remote_ok and not netflix_is_remote_us(p):
            record_filter_reject(cid, str(name), str(job_url), "location")
            continue
        desc_text = netflix_job_description_text(p, jid)
        fail_reason = posting_filter_fail_reason(str(name), desc_text, cfg, company=company)
        if fail_reason:
            record_filter_reject(cid, str(name), str(job_url), fail_reason)
            continue
        skip = jd_blocks_job(
            desc_text, name, cfg, exclude, keyword_exclude_title_only=True
        )
        if skip:
            record_jd_filter_reject(cid, str(name), skip, url=str(job_url))
            continue
        ts = netflix_posting_ts(jid, p)
        meta_parts = [
            str(p.get("display_job_id") or p.get("ats_job_id") or ""),
            str(p.get("location") or ""),
            remote_warn or "",
        ]
        location_name = str(p.get("location") or "")
        salary, salary_label = salary_from_detail_text(
            desc_text, cfg, location_name=location_name
        )
        raw.append(
            RawPosting(
                title=name,
                url=p.get("canonical_url") or f"https://explore.jobs.netflix.net/careers/job/{jid}",
                description_text=desc_text,
                posted_ts=ts,
                job_id=jid,
                salary=salary,
                salary_label=salary_label,
                force_loc="remote",
                loc_verify=bool(remote_warn),
                skip_keyword_filter=True,
                match_hint=netflix_infer_match(name),
                why_hint="USA Remote · platform/infra role (auto-discovered).",
                meta_parts=[x for x in meta_parts if x],
            )
        )
    note = f"Searched {len(tier1)} keywords + {len(company.get('watch_ids', []))} watch IDs"
    return raw, note


def fetch_successfactors(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = company_title_tiers(company, cfg)
    search_base = company.get("search_base") or company.get("browse_url") or ""
    origin = company.get("site_origin") or successfactors_origin(search_base)
    queries = company_search_queries(company, cfg)
    inspect_detail = bool(company.get("detail_salary"))
    fetch_detail_keywords = bool(company.get("fetch_detail_keywords"))
    search_location = str(company.get("search_location") or "")
    browse_location = str(company.get("search_browse_location") or "")
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    raw: list[RawPosting] = []
    rows_by_url: dict[str, dict[str, str]] = {}
    query_count = 0
    source = "search"
    if not company.get("successfactors_disable_sitemal"):
        sitemal_rows = successfactors_fetch_sitemal(origin, cache_ttl_hours=cache_ttl)
        if sitemal_rows is not None:
            source = "sitemal"
            query_count = 1
            for row in sitemal_rows:
                url = str(row.get("url") or "").strip()
                if url:
                    rows_by_url[url] = row
    if not rows_by_url:
        for kw in queries:
            if not str(kw).strip():
                continue
            query_count += 1
            for row in successfactors_fetch_search(
                search_base,
                kw,
                origin,
                location=search_location,
            ):
                rows_by_url[row["url"]] = row
        if browse_location:
            query_count += 1
            for row in successfactors_fetch_search(
                search_base,
                "",
                origin,
                location=browse_location,
            ):
                rows_by_url[row["url"]] = row
    scanned = len(rows_by_url)
    for row in rows_by_url.values():
        url = row["url"]
        title = row["title"]
        jid = row.get("job_id") or ""
        loc_hint = row.get("loc_hint") or ""
        need_detail = inspect_detail or fetch_detail_keywords
        detail_text = str(row.get("description_text") or "").strip()
        if need_detail and not detail_text:
            detail_text = successfactors_fetch_detail_text(url)
        if not posting_matches_title_filters(
            title,
            detail_text if fetch_detail_keywords else "",
            cfg,
            company=company,
        ):
            continue
        detail_loc = successfactors_extract_location(detail_text)
        work_model = successfactors_extract_work_model(detail_text)
        location_name = sanitize_loc_label_for_badge(
            detail_loc or loc_hint,
            title=title,
            description_text=detail_text,
        ) or (detail_loc or loc_hint or "")
        meta_loc = location_name or detail_loc or loc_hint
        job_loc, loc_label = successfactors_loc_from_detail(
            company, location_name or detail_loc or loc_hint, work_model, cfg
        )
        if not job_loc:
            continue
        salary, salary_label = successfactors_salary_from_detail(
            company, title, detail_loc or loc_hint, detail_text, cfg
        )
        meta_label = "Live posting (SuccessFactors sitemal)" if source == "sitemal" else "Live posting (SuccessFactors search)"
        meta_parts = [x for x in (meta_loc, work_model, meta_label) if x]
        raw.append(
            RawPosting(
                title=title,
                url=url,
                description_text=detail_text,
                location_name=location_name,
                job_id=jid,
                salary=salary,
                salary_label=salary_label,
                meta_parts=meta_parts,
                force_loc=job_loc,
                force_loc_label=loc_label,
                skip_keyword_filter=True,
            )
        )
    if source == "sitemal":
        note = f"SuccessFactors sitemal (1 feed, {scanned} rows scanned, {len(raw)} parsed)"
    else:
        note = f"SuccessFactors search ({query_count} queries, {scanned} rows scanned, {len(raw)} parsed)"
    return raw, note


def _smartrecruiters_loc_name(loc_obj: dict[str, Any]) -> str:
    loc_parts = [loc_obj.get("city"), loc_obj.get("region"), loc_obj.get("country")]
    loc_name = ", ".join(str(x) for x in loc_parts if x)
    if loc_obj.get("remote"):
        if not loc_name:
            return "Remote"
        if "remote" not in loc_name.lower():
            return f"{loc_name} (Remote)"
    return loc_name or "Remote"


def _smartrecruiters_append_posting(
    posting: dict[str, Any],
    *,
    sr_id: str,
    cid: str,
    employer_region: str,
    cfg: dict[str, Any],
    company: dict[str, Any],
    seen: set[str],
    raw: list[RawPosting],
) -> None:
    pid = str(posting.get("id") or "")
    if not pid or pid in seen:
        return
    title = posting.get("name") or ""
    loc_obj = posting.get("location") or {}
    if not isinstance(loc_obj, dict):
        loc_obj = {}
    loc_name = _smartrecruiters_loc_name(loc_obj)
    # List API `ref` is often an API detail URL, not a candidate apply link.
    job_url = str(posting.get("postingUrl") or "").strip()
    if not job_url or "api.smartrecruiters.com" in job_url.lower():
        job_url = f"https://jobs.smartrecruiters.com/{sr_id}/{pid}"
    job_loc, loc_label = classify_location_with_fallback(loc_name, employer_region)
    if not job_loc:
        record_filter_reject(cid, str(title), str(job_url), "location")
        return
    if title_rejected_by_scrape_filters(str(title), cfg, company, url=str(job_url)):
        return
    seen.add(pid)
    ts = parse_iso_ts(posting.get("releasedDate"))
    raw.append(
        RawPosting(
            title=str(title),
            url=str(job_url),
            location_name=loc_name,
            posted_ts=ts,
            job_id=pid,
            meta_parts=[loc_name] if loc_name else [],
            force_loc=job_loc,
            force_loc_label=loc_label,
            skip_keyword_filter=True,
        )
    )


def fetch_smartrecruiters(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    sr_id = company.get("smartrecruiters_id") or company.get("board") or company["id"]
    employer_region = company_employer_region(company)
    seen: set[str] = set()
    cid = str(company.get("id") or "")
    raw: list[RawPosting] = []
    total_found = 0
    use_keyword_query = bool(company.get("smartrecruiters_keyword_query"))
    query_terms: list[str] = [""]
    if use_keyword_query:
        query_terms = cap_company_search_queries(
            company, cfg, max_queries_key="smartrecruiters_max_queries", default=10
        )
        if not query_terms:
            query_terms = [""]

    for term in query_terms:
        offset = 0
        term_total = 0
        while offset < 500:
            params = f"limit=100&offset={offset}"
            if term:
                params += f"&q={urllib.parse.quote(term)}"
            api = (
                f"https://api.smartrecruiters.com/v1/companies/{urllib.parse.quote(str(sr_id))}"
                f"/postings?{params}"
            )
            code, _, body = http_get(api)
            if code != 200:
                if raw:
                    break
                return raw, f"SmartRecruiters API HTTP {code}"
            try:
                payload = json.loads(body)
            except json.JSONDecodeError:
                if raw:
                    break
                return raw, "SmartRecruiters API returned invalid JSON"
            content = payload.get("content") or []
            if offset == 0:
                term_total = int(payload.get("totalFound") or len(content))
                total_found += term_total
            if not content:
                break
            for posting in content:
                if isinstance(posting, dict):
                    _smartrecruiters_append_posting(
                        posting,
                        sr_id=str(sr_id),
                        cid=cid,
                        employer_region=employer_region,
                        cfg=cfg,
                        company=company,
                        seen=seen,
                        raw=raw,
                    )
            offset += len(content)
            if offset >= term_total:
                break
        if not use_keyword_query:
            break

    if use_keyword_query:
        note = (
            f"SmartRecruiters keyword scan ({len(query_terms)} queries, "
            f"{total_found} hits, {len(raw)} parsed)"
        )
    else:
        note = f"SmartRecruiters scan ({total_found} postings, {len(raw)} parsed)"
    return raw, note


def bullhorn_public_job_url(portal_base: str, job_id: str | int) -> str:
    """Bullhorn career-portal SPA deep link (#/jobs/{id})."""
    base = str(portal_base or "").strip().rstrip("/")
    if not base:
        return ""
    return f"{base}/#/jobs/{job_id}"


def fetch_bullhorn_public(
    company: dict[str, Any], cfg: dict[str, Any]
) -> tuple[list[RawPosting], str | None]:
    """Bullhorn Public Jobs API (career-portal corp token + swimlane)."""
    swimlane = str(company.get("bullhorn_swimlane") or "").strip()
    token = str(company.get("bullhorn_corp_token") or "").strip()
    portal = str(
        company.get("bullhorn_career_portal")
        or company.get("browse_url")
        or ""
    ).strip().rstrip("/")
    if portal.endswith("/#") or portal.endswith("#"):
        portal = portal.rstrip("#").rstrip("/")
    if not swimlane or not token:
        return [], "Bullhorn Public API missing bullhorn_swimlane/corp_token"
    employer_region = company_employer_region(company)
    cid = str(company.get("id") or "")
    fields = (
        "id,title,publishedCategory(id,name),address(city,state,zip),employmentType,"
        "dateLastPublished,publicDescription,isOpen,isPublic,isDeleted,salary,salaryUnit"
    )
    query = str(company.get("bullhorn_query") or "(isOpen:1 AND isDeleted:0)").strip()
    page_size = max(1, min(500, int(company.get("bullhorn_page_size") or 100)))
    max_start = max(page_size, int(company.get("bullhorn_max_start") or 500))
    raw: list[RawPosting] = []
    seen: set[str] = set()
    total = 0
    start = 0
    while start <= max_start:
        api = (
            f"https://public-rest{urllib.parse.quote(swimlane)}.bullhornstaffing.com"
            f"/rest-services/{urllib.parse.quote(token)}/search/JobOrder"
            f"?query={urllib.parse.quote(query)}"
            f"&fields={urllib.parse.quote(fields)}"
            f"&count={page_size}&start={start}&sort=-dateLastPublished"
        )
        code, _, body = http_get(api)
        if code != 200:
            if raw:
                break
            return raw, f"Bullhorn Public API HTTP {code}"
        try:
            payload = json.loads(body)
        except json.JSONDecodeError:
            if raw:
                break
            return raw, "Bullhorn Public API returned invalid JSON"
        if start == 0:
            total = int(payload.get("total") or 0)
        rows = payload.get("data") or []
        if not isinstance(rows, list) or not rows:
            break
        for row in rows:
            if not isinstance(row, dict):
                continue
            jid = str(row.get("id") or "").strip()
            title = str(row.get("title") or "").strip()
            if not jid or not title or jid in seen:
                continue
            addr = row.get("address") or {}
            if not isinstance(addr, dict):
                addr = {}
            loc_parts = [addr.get("city"), addr.get("state")]
            loc_name = ", ".join(str(x) for x in loc_parts if x) or "Remote"
            job_url = bullhorn_public_job_url(portal, jid)
            if not job_url:
                continue
            job_loc, loc_label = classify_location_with_fallback(
                loc_name,
                employer_region,
                description_text=str(row.get("publicDescription") or ""),
            )
            if not job_loc:
                record_filter_reject(cid, title, job_url, "location")
                continue
            if title_rejected_by_scrape_filters(title, cfg, company, url=job_url):
                continue
            seen.add(jid)
            posted_raw = row.get("dateLastPublished") or 0
            try:
                posted_ms = int(posted_raw)
            except (TypeError, ValueError):
                posted_ms = 0
            posted_ts = posted_ms // 1000 if posted_ms > 10_000_000_000 else posted_ms
            salary = row.get("salary")
            salary_unit = str(row.get("salaryUnit") or "").strip()
            salary_label = None
            if salary not in (None, "", 0, "0"):
                salary_label = f"{salary} {salary_unit}".strip()
            desc = html_to_plain(str(row.get("publicDescription") or ""))
            emp = str(row.get("employmentType") or "").strip() or "full-time"
            raw.append(
                RawPosting(
                    title=title,
                    url=job_url,
                    description_text=desc,
                    location_name=loc_name,
                    posted_ts=posted_ts,
                    job_id=jid,
                    employment=emp,
                    salary_label=salary_label,
                    meta_parts=[x for x in (loc_name, emp, salary_label) if x],
                    force_loc=job_loc,
                    force_loc_label=loc_label,
                    skip_keyword_filter=True,
                    skip_verify=True,
                )
            )
        start += len(rows)
        if start >= total:
            break
    note = f"Bullhorn Public API ({total} open, {len(raw)} parsed)"
    return raw, note


def jeffersonfrank_job_slug(title: str) -> str:
    text = html.unescape(str(title or "")).strip().lower()
    text = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return text or "job"


def jeffersonfrank_job_url(reference: str, title: str, *, site: str = "") -> str:
    base = (site or "https://www.jeffersonfrank.com").strip().rstrip("/")
    ref = str(reference or "").strip()
    if not ref:
        return ""
    slug = jeffersonfrank_job_slug(title)
    return f"{base}/job/{urllib.parse.quote(ref, safe='._-')}/{slug}"


def _jeffersonfrank_graphql(
    endpoint: str,
    api_key: str,
    query: str,
    variables: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    payload: dict[str, Any] = {"query": query}
    if variables is not None:
        payload["variables"] = variables
    code, _, body = http_post_json(
        endpoint,
        payload,
        headers={"x-api-key": api_key},
    )
    if code != 200:
        return None, f"Jefferson Frank GraphQL HTTP {code}"
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return None, "Jefferson Frank GraphQL returned invalid JSON"
    if not isinstance(data, dict):
        return None, "Jefferson Frank GraphQL returned invalid JSON"
    if data.get("errors") and not data.get("data"):
        msg = data["errors"][0].get("message") if isinstance(data["errors"], list) else "error"
        return None, f"Jefferson Frank GraphQL error: {msg}"
    return data, None


def fetch_jeffersonfrank(
    company: dict[str, Any], cfg: dict[str, Any]
) -> tuple[list[RawPosting], str | None]:
    """Jefferson Frank AppSync GraphQL job search (public site API key)."""
    endpoint = str(
        company.get("jeffersonfrank_graphql_url")
        or "https://kxcoh5wflzfgfj7zrvnhz46kuq.appsync-api.eu-west-2.amazonaws.com/graphql"
    ).strip()
    api_key = str(
        company.get("jeffersonfrank_api_key") or "da2-epuh3sf3zvfvfd3orekvfv7vvy"
    ).strip()
    site = str(company.get("jeffersonfrank_site") or "https://www.jeffersonfrank.com").strip()
    if not endpoint or not api_key:
        return [], "Jefferson Frank GraphQL missing endpoint/api key"
    employer_region = company_employer_region(company)
    cid = str(company.get("id") or "")
    queries = cap_company_search_queries(
        company, cfg, max_queries_key="jeffersonfrank_max_queries", default=8
    )
    if not queries:
        queries = ["devops", "platform engineer", "site reliability"]
    max_pages = max(1, int(company.get("jeffersonfrank_max_pages") or 5))
    gql = """
    query SearchJobs($keyword: String, $page: Int) {
      searchJobs(keyword: $keyword, page: $page) {
        pagination { value relation }
        items {
          reference
          title
          remote
          type
          role
          seniority
          description
          location { description country region }
          salary { from to currency description }
        }
      }
    }
    """
    raw: list[RawPosting] = []
    seen: set[str] = set()
    scanned = 0
    for term in queries:
        for page in range(1, max_pages + 1):
            data, err = _jeffersonfrank_graphql(
                endpoint,
                api_key,
                gql,
                {"keyword": term, "page": page},
            )
            if err:
                if raw:
                    break
                return raw, err
            block = ((data or {}).get("data") or {}).get("searchJobs") or {}
            items = block.get("items") or []
            if not isinstance(items, list) or not items:
                break
            scanned += len(items)
            for item in items:
                if not isinstance(item, dict):
                    continue
                ref = str(item.get("reference") or "").strip()
                title = html.unescape(str(item.get("title") or "")).strip()
                if not ref or not title or ref in seen:
                    continue
                loc_obj = item.get("location") or {}
                if not isinstance(loc_obj, dict):
                    loc_obj = {}
                loc_name = str(
                    loc_obj.get("description")
                    or ", ".join(
                        str(x)
                        for x in (loc_obj.get("region"), loc_obj.get("country"))
                        if x
                    )
                    or ""
                ).strip()
                if item.get("remote"):
                    if not loc_name:
                        loc_name = "Remote"
                    elif "remote" not in loc_name.lower():
                        loc_name = f"{loc_name} (Remote)"
                job_url = jeffersonfrank_job_url(ref, title, site=site)
                if not job_url:
                    continue
                desc = html_to_plain(str(item.get("description") or ""))
                job_loc, loc_label = classify_location_with_fallback(
                    loc_name,
                    employer_region,
                    description_text=desc,
                )
                if not job_loc:
                    record_filter_reject(cid, title, job_url, "location")
                    continue
                if title_rejected_by_scrape_filters(title, cfg, company, url=job_url):
                    continue
                seen.add(ref)
                sal = item.get("salary") or {}
                salary_label = None
                if isinstance(sal, dict):
                    lo, hi = sal.get("from"), sal.get("to")
                    cur = str(sal.get("currency") or "").strip()
                    if lo not in (None, "") or hi not in (None, ""):
                        salary_label = f"{lo or '?'}-{hi or '?'} {cur}".strip()
                    elif sal.get("description"):
                        salary_label = str(sal.get("description"))
                emp = str(item.get("type") or "").strip() or "full-time"
                meta = [x for x in (loc_name, emp, item.get("seniority"), salary_label) if x]
                raw.append(
                    RawPosting(
                        title=title,
                        url=job_url,
                        description_text=desc,
                        location_name=loc_name or "Remote",
                        job_id=ref,
                        employment=emp,
                        salary_label=salary_label,
                        meta_parts=[str(x) for x in meta],
                        force_loc=job_loc,
                        force_loc_label=loc_label,
                        skip_keyword_filter=True,
                        skip_verify=True,
                    )
                )
            pagination = block.get("pagination") or {}
            total = 0
            try:
                total = int(pagination.get("value") or 0)
            except (TypeError, ValueError):
                total = 0
            if page * 10 >= total:
                break
    note = (
        f"Jefferson Frank GraphQL ({len(queries)} queries, {scanned} scanned, "
        f"{len(raw)} parsed)"
    )
    return raw, note


def oracle_hcm_ce_base(company: dict[str, Any]) -> str:
    """Candidate Experience site base (per-tenant), not the generic careers.oracle.com host."""
    ce_base = str(company.get("oracle_ce_base") or "").strip().rstrip("/")
    if ce_base:
        return ce_base
    browse = str(company.get("browse_url") or "").strip()
    if browse and "/hcmUI/CandidateExperience/" in browse:
        match = re.search(
            r"(https?://[^/]+/hcmUI/CandidateExperience/en/sites/[^/]+)",
            browse,
            re.I,
        )
        if match:
            return match.group(1).rstrip("/")
    if browse:
        vanity = re.search(r"(https?://[^/]+/en/sites/[^/?#]+)", browse, re.I)
        if vanity:
            return vanity.group(1).rstrip("/")
    api_base = str(company.get("oracle_api_base") or "").strip().rstrip("/")
    if api_base and "/hcmRestApi/" in api_base:
        host = api_base.split("/hcmRestApi/", 1)[0].rstrip("/")
        site = str(company.get("oracle_site_number") or "CX_1").strip() or "CX_1"
        return f"{host}/hcmUI/CandidateExperience/en/sites/{site}"
    site_path = str(company.get("oracle_site_path") or "jobsearch").strip("/") or "jobsearch"
    return f"https://careers.oracle.com/en/sites/{site_path}"


def oracle_hcm_job_url(company: dict[str, Any], req_id: str) -> str:
    return f"{oracle_hcm_ce_base(company)}/job/{urllib.parse.quote(str(req_id).strip())}"


def oracle_hcm_search(
    company: dict[str, Any], keyword: str, *, limit: int = 25, offset: int = 0
) -> tuple[list[dict[str, Any]], int]:
    api_base = str(
        company.get("oracle_api_base")
        or "https://eeho.fa.us2.oraclecloud.com/hcmRestApi/resources/latest"
    ).rstrip("/")
    site_number = str(company.get("oracle_site_number") or "CX_1001")
    facets = (
        "LOCATIONS%3BWORK_LOCATIONS%3BWORKPLACE_TYPES%3BTITLES%3BCATEGORIES%3B"
        "ORGANIZATIONS%3BPOSTING_DATES%3BFLEX_FIELDS"
    )
    finder = (
        f"findReqs;siteNumber={site_number},facetsList={facets},limit={limit},"
        f"offset={max(0, offset)},keyword={urllib.parse.quote(keyword)}"
    )
    location_id = str(company.get("oracle_location_id") or "").strip()
    if location_id:
        finder += f",locationId={location_id}"
    url = f"{api_base}/recruitingCEJobRequisitions?onlyData=true&expand=all&finder={finder}"
    code, _, body = http_get(url)
    if code != 200 or not body:
        return [], 0
    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return [], 0
    items = payload.get("items") or []
    if not items or not isinstance(items[0], dict):
        return [], 0
    search_row = items[0]
    total = int(search_row.get("TotalJobsCount") or 0)
    reqs = search_row.get("requisitionList") or []
    return [row for row in reqs if isinstance(row, dict)], total


def oracle_hcm_fetch_detail(company: dict[str, Any], req_id: str) -> dict[str, Any] | None:
    api_base = str(
        company.get("oracle_api_base")
        or "https://eeho.fa.us2.oraclecloud.com/hcmRestApi/resources/latest"
    ).rstrip("/")
    site_number = str(company.get("oracle_site_number") or "CX_1001")
    url = (
        f"{api_base}/recruitingCEJobRequisitionDetails?onlyData=true&expand=all"
        f"&finder=ById;Id={urllib.parse.quote(str(req_id))},siteNumber={site_number}"
    )
    code, _, body = http_get(url)
    if code != 200 or not body:
        return None
    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return None
    items = payload.get("items") or []
    if not items or not isinstance(items[0], dict):
        return None
    return items[0]


def _ats_detail_parallel_workers() -> int:
    return _env_worker_count("QUICKJOBS_ATS_DETAIL_WORKERS", 4, cap=8)


def _parallel_fetch_ats_details(
    item_ids: list[str],
    fetch_one: Callable[[str], Any],
    *,
    company_id: str,
) -> dict[str, Any]:
    """Parallel detail fetches for oracle_hcm / phenom (Tier 1 slow ATS optimization)."""
    ids = [str(i).strip() for i in item_ids if str(i).strip()]
    if not ids:
        return {}
    workers = min(_ats_detail_parallel_workers(), len(ids))
    if workers <= 1:
        return {item_id: fetch_one(item_id) for item_id in ids}
    out: dict[str, Any] = {}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = {pool.submit(fetch_one, item_id): item_id for item_id in ids}
        for fut in as_completed(futures):
            if _company_fetch_abandoned(company_id):
                for pending in futures:
                    pending.cancel()
                break
            item_id = futures[fut]
            try:
                out[item_id] = fut.result()
            except Exception:
                out[item_id] = None
    return out


def parse_oracle_posted(value: str | None) -> int:
    text = str(value or "").strip()
    if not text:
        return 0
    for fmt in ("%Y-%m-%dT%H:%M:%S.%f%z", "%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%d"):
        try:
            dt = datetime.strptime(text.replace("Z", "+0000"), fmt)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return int(dt.timestamp())
        except ValueError:
            continue
    return parse_human_posted(text)


def fetch_oracle_hcm(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    queries = cap_company_search_queries(company, cfg, max_queries_key="oracle_max_queries")
    if not queries:
        queries = ["devops"]
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    cache_key = f"oracle-hcm-ce-v2-{company['id']}-{'-'.join(queries[:3])[:80]}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, list):
                raw = [
                    RawPosting(**row)
                    for row in payload
                    if isinstance(row, dict) and row.get("title")
                ]
                note = f"Oracle HCM ({len(queries)} queries, {len(payload)} details, {len(raw)} parsed)"
                return raw, note
        except (json.JSONDecodeError, TypeError):
            pass

    employer_region = company_employer_region(company)
    max_details = int(company.get("max_details", 24))
    seen_ids: set[str] = set()
    records: list[dict[str, Any]] = []
    total_seen = 0
    cid = str(company.get("id") or "")
    pending: list[tuple[dict[str, Any], str, str]] = []
    page_size = max(10, min(25, max_details))
    for query in queries:
        if _company_fetch_abandoned(cid):
            break
        offset = 0
        while not _company_fetch_abandoned(cid):
            try:
                reqs, total = oracle_hcm_search(
                    company, query, limit=page_size, offset=offset
                )
            except Exception:
                break
            total_seen = max(total_seen, total)
            if not reqs:
                break
            for req in reqs:
                if _company_fetch_abandoned(cid) or len(pending) >= max_details:
                    break
                req_id = str(req.get("Id") or "").strip()
                if not req_id or req_id in seen_ids:
                    continue
                title = str(req.get("Title") or "").strip()
                job_url = oracle_hcm_job_url(company, req_id)
                if title_rejected_by_scrape_filters(title, cfg, company, url=job_url):
                    continue
                seen_ids.add(req_id)
                pending.append((req, req_id, title))
            if len(pending) >= max_details:
                break
            if len(reqs) < page_size or offset + len(reqs) >= total:
                break
            offset += len(reqs)
            if offset >= 500:
                break
        if len(pending) >= max_details:
            break

    detail_by_id = _parallel_fetch_ats_details(
        [req_id for _, req_id, _ in pending],
        lambda rid: oracle_hcm_fetch_detail(company, rid),
        company_id=cid,
    )
    for req, req_id, title in pending:
        if _company_fetch_abandoned(cid):
            break
        job_url = oracle_hcm_job_url(company, req_id)
        detail = detail_by_id.get(req_id)
        description_parts = []
        if detail:
            for key in (
                "ExternalDescriptionStr",
                "ExternalQualificationsStr",
                "ExternalResponsibilitiesStr",
                "ShortDescriptionStr",
            ):
                chunk = str(detail.get(key) or "").strip()
                if chunk:
                    description_parts.append(html_to_plain(chunk))
        if not description_parts:
            for key in ("ShortDescriptionStr", "ExternalQualificationsStr"):
                chunk = str(req.get(key) or "").strip()
                if chunk:
                    description_parts.append(html_to_plain(chunk))
        description_text = "\n\n".join(description_parts)
        location_name = str(
            (detail or req).get("PrimaryLocation")
            or (detail or req).get("PrimaryLocationCountry")
            or req.get("WorkplaceType")
            or ""
        ).strip()
        workplace = str((detail or req).get("WorkplaceType") or req.get("WorkplaceType") or "").strip()
        if workplace and workplace.lower() not in location_name.lower():
            location_name = ", ".join(x for x in (location_name, workplace) if x)
        job_loc, loc_label = classify_location_with_fallback(location_name, employer_region)
        if not job_loc:
            record_filter_reject(cid, title, job_url, "location")
            continue
        if description_text and jd_blocks_job(
            description_text, title, cfg, exclude, keyword_exclude_title_only=True
        ):
            record_jd_filter_reject(cid, title, "jd blocklist", url=job_url)
            continue
        posted_raw = str(
            (detail or {}).get("ExternalPostedStartDate")
            or req.get("PostedDate")
            or ""
        ).strip()
        records.append(
            {
                "title": title,
                "url": job_url,
                "description_text": description_text,
                "location_name": location_name,
                "posted_ts": parse_oracle_posted(posted_raw),
                "job_id": req_id,
                "employment": str(req.get("JobSchedule") or req.get("WorkerType") or "").strip(),
                "meta_parts": [p for p in (location_name, workplace) if p],
                "force_loc": job_loc,
                "force_loc_label": loc_label,
                "skip_keyword_filter": True,
            }
        )

    if not records:
        listed = max(total_seen, len(seen_ids))
        if listed > 0:
            note = f"Oracle HCM ({len(queries)} queries, {listed} found, 0 parsed)"
            return [], note
        return [], "Oracle HCM API returned no matching postings"
    cache_set(SCRIPT_DIR, cache_key, json.dumps(records))
    raw = [RawPosting(**row) for row in records]
    note = f"Oracle HCM ({len(queries)} queries, {total_seen} found, {len(raw)} parsed)"
    return raw, note


def phenom_widgets_url(company: dict[str, Any]) -> str:
    explicit = str(company.get("phenom_widgets_url") or "").strip()
    if explicit:
        return explicit
    base = str(company.get("phenom_base") or company.get("browse_url") or "").strip()
    if not base:
        return ""
    parsed = urllib.parse.urlsplit(base)
    if not parsed.netloc:
        return ""
    return f"{parsed.scheme}://{parsed.netloc}/widgets"


def phenom_title_slug(title: str) -> str:
    text = str(title or "").strip()
    text = text.replace("–", "-").replace("—", "-")
    text = re.sub(r"[^\w\s-]", "", text)
    text = re.sub(r"[-\s]+", "-", text).strip("-")
    return text


def workday_posting_url_from_apply(apply_url: str) -> str:
    """Phenom listings often expose Workday apply URLs; strip /apply for the posting page."""
    url = str(apply_url or "").strip()
    if "myworkdayjobs.com" not in url.lower():
        return ""
    clean = url.split("?")[0].rstrip("/")
    if clean.lower().endswith("/apply"):
        return clean[: -len("/apply")]
    if "/job/" in clean.lower():
        return clean
    return ""


_CAREERS_LANDING_SUFFIXES = (
    "/en",
    "/us/en",
    "/global/en",
    "/en-us",
    "/en/global",
    "/careers",
    "/search-results",
)

_JOB_PATH_LOCALE_SEGMENTS = frozenset(
    {
        "en",
        "us",
        "uk",
        "eu",
        "global",
        "worldwide",
        "international",
        "en-us",
        "en-gb",
        "en-in",
        "en-ca",
        "en-au",
        "us-en",
    }
)


def _eightfold_posting_url(url: str) -> bool:
    text = str(url or "").strip()
    if not text:
        return False
    lower = text.lower()
    if not re.search(r"[?&]pid=\d+", lower, re.I):
        return False
    parsed = urllib.parse.urlsplit(text)
    host = (parsed.hostname or "").lower()
    path = parsed.path.rstrip("/").lower()
    if "eightfold.ai" in host:
        return True
    return path.endswith("/careers")


def _is_phenom_style_job_id_only_landing(path: str) -> bool:
    """True for Phenom-style /{locale}/job/{id} stubs that redirect to the careers home page."""
    clean = str(path or "").rstrip("/")
    match = re.search(r"/job/([^/?#]+)$", clean, re.I)
    if not match:
        return False
    if re.search(r"/careers/job/[^/?#]+$", clean, re.I):
        return False
    prefix = clean[: match.start()].rstrip("/")
    if not prefix:
        return True
    segments = [segment for segment in prefix.split("/") if segment]
    if not segments:
        return True
    return all(segment.lower() in _JOB_PATH_LOCALE_SEGMENTS for segment in segments)


def _oracle_hcm_posting_path(path: str) -> bool:
    """Oracle CE postings use /sites/{site}/job/{id} without a title slug."""
    return bool(
        re.search(
            r"(?:/hcmUI/CandidateExperience)?/en/sites/[^/]+/job/[^/]+/?$",
            str(path or "").rstrip("/"),
            re.I,
        )
    )


def is_careers_landing_url(url: str, company: dict[str, Any] | None = None) -> bool:
    """True when URL is a careers home/search page, not a specific job posting."""
    text = str(url or "").strip()
    if not text.startswith("http"):
        return True
    lower = text.lower()
    if _eightfold_posting_url(text):
        return False
    if "myworkdayjobs.com" in lower:
        if "/job/" not in lower:
            return True
        return lower.rstrip("/").endswith("/apply")
    if "/job/" in lower or "/jobs/" in lower:
        path = urllib.parse.urlsplit(text).path.rstrip("/")
        if _oracle_hcm_posting_path(path):
            return False
        if (
            company
            and str(company.get("type") or "").lower() == "oracle_hcm"
            and re.search(r"/job/[^/]+/?$", path, re.I)
        ):
            return False
        if re.search(r"/careers/job/[^/]+/?$", path, re.I):
            return False
        if _is_phenom_style_job_id_only_landing(path):
            return True
        return False
    path = urllib.parse.urlsplit(text).path.rstrip("/").lower()
    if any(path.endswith(suffix) for suffix in _CAREERS_LANDING_SUFFIXES):
        return True
    if company:
        for key in ("browse_url", "hub_url", "phenom_base"):
            base = str(company.get(key) or "").strip().rstrip("/").lower()
            if base and text.rstrip("/").lower() == base:
                return True
    return False


def resolve_job_posting_url(
    url: str,
    company: dict[str, Any],
    *,
    job_id: str = "",
    title: str = "",
    apply_url: str = "",
) -> str:
    """Prefer per-posting URLs; rebuild Phenom/Workday links when input is a careers landing page."""
    wd = workday_posting_url_from_apply(apply_url)
    if wd:
        return normalize_job_url(wd)
    text = str(url or "").strip()
    if _eightfold_posting_url(text):
        return normalize_job_url(text)
    if text and not is_careers_landing_url(text, company):
        return normalize_job_url(text)
    ctype = str(company.get("type") or "").lower()
    jid = str(job_id or "").strip()
    if ctype == "phenom" and jid:
        built = phenom_job_url(
            company,
            {"jobId": jid, "title": title, "applyUrl": apply_url},
        )
        if built and not is_careers_landing_url(built, company):
            return normalize_job_url(built)
    if text and "myworkdayjobs.com" in text.lower() and "/job/" in text.lower():
        return normalize_job_url(text)
    return normalize_job_url(text) if text and not is_careers_landing_url(text, company) else ""


def phenom_job_url(company: dict[str, Any], job: dict[str, Any]) -> str:
    apply_url = str(job.get("applyUrl") or "").strip()
    wd_url = workday_posting_url_from_apply(apply_url)
    if wd_url:
        return wd_url
    job_url = str(job.get("jobUrl") or "").strip()
    if job_url.startswith("http") and not is_careers_landing_url(job_url, company):
        return job_url.split("?")[0]
    if company.get("phenom_prefer_apply_url") and apply_url.startswith("http"):
        if "myworkdayjobs.com" in apply_url.lower():
            wd = workday_posting_url_from_apply(apply_url)
            if wd:
                return wd
        if not is_careers_landing_url(apply_url, company):
            return apply_url.split("?")[0]
    job_id = str(job.get("jobId") or job.get("reqId") or "").strip()
    base = str(company.get("phenom_base") or company.get("browse_url") or "").strip().rstrip("/")
    if not base or not job_id:
        return base
    path_prefix = str(company.get("phenom_job_path") or "/global/en/job").strip()
    if not path_prefix.startswith("/"):
        path_prefix = "/" + path_prefix
    slug = phenom_title_slug(str(job.get("title") or ""))
    path = f"{path_prefix}/{urllib.parse.quote(job_id, safe='')}"
    if slug:
        path = f"{path}/{slug}"
    return f"{base}{path}"


def phenom_fetch_job_detail(
    company: dict[str, Any],
    job_id: str,
    *,
    cache_ttl_hours: float = 24.0,
) -> dict[str, str]:
    """Full posting body from Phenom jobDetail widgets API (not search teaser)."""
    job_id = str(job_id or "").strip()
    if not job_id:
        return {}
    cache_key = f"phenom-detail-{company.get('id')}-{job_id}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl_hours)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, dict):
                return {str(k): str(v) for k, v in payload.items() if v}
        except json.JSONDecodeError:
            pass
    widgets = phenom_widgets_url(company)
    refnum = str(company.get("phenom_refnum") or "").strip() or phenom_discover_refnum(
        str(company.get("browse_url") or company.get("phenom_base") or "")
    )
    if not widgets or not refnum:
        return {}
    payload = {
        "lang": str(company.get("phenom_lang") or "en_global"),
        "deviceType": "desktop",
        "country": str(company.get("phenom_country") or "global"),
        "pageName": "job-details",
        "ddoKey": "jobDetail",
        "jobId": job_id,
        "refNum": refnum,
        "siteType": str(company.get("phenom_site_type") or "external"),
    }
    code, _, body = http_post_json(widgets, payload)
    if code != 200 or not body:
        return {}
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return {}
    block = data.get("jobDetail") if isinstance(data, dict) else None
    job = ((block or {}).get("data") or {}).get("job") if isinstance(block, dict) else None
    if not isinstance(job, dict):
        return {}
    description_html = str(job.get("description") or "").strip()
    if not description_html:
        return {}
    out = {
        "description_html": description_html,
        "description_text": html_to_plain(description_html),
        "title": str(job.get("title") or "").strip(),
    }
    for src, dst in (
        ("salaryMin", "salary_min"),
        ("salaryMax", "salary_max"),
        ("payRange", "pay_range"),
    ):
        val = str(job.get(src) or "").strip()
        if val:
            out[dst] = val
    detail_url = str(job.get("jobUrl") or "").strip()
    apply_url = str(job.get("applyUrl") or "").strip()
    wd_url = workday_posting_url_from_apply(apply_url)
    if wd_url:
        out["url"] = wd_url
    elif detail_url.startswith("http") and not is_careers_landing_url(detail_url, company):
        out["url"] = detail_url.split("?")[0]
    cache_set(SCRIPT_DIR, cache_key, json.dumps(out))
    return out


def phenom_salary_from_detail(
    detail: dict[str, str],
    description_text: str,
    cfg: dict[str, Any],
    *,
    location_name: str = "",
    title: str = "",
) -> tuple[str, str | None]:
    """Use Phenom jobDetail salaryMin/Max when present; else shared JD prose parser."""
    salary_min = str(
        detail.get("salary_min") or detail.get("salaryMin") or ""
    ).strip()
    salary_max = str(
        detail.get("salary_max") or detail.get("salaryMax") or ""
    ).strip()
    if salary_min and salary_max:
        low = parse_money_amount(salary_min)
        high = parse_money_amount(salary_max)
        if low > 0 and high > 0:
            if low > high:
                low, high = high, low
            status = salary_range_status("base", low, high, cfg, title=title)
            if status[1]:
                return status
    return salary_from_detail_text(
        description_text, cfg, location_name=location_name, title=title
    )


def phenom_discover_refnum(browse_url: str) -> str | None:
    url = str(browse_url or "").strip()
    if not url:
        return None
    parsed = urllib.parse.urlsplit(url)
    if not parsed.netloc:
        return None
    search_url = url
    if "search-results" not in parsed.path:
        search_url = f"{parsed.scheme}://{parsed.netloc}/global/en/search-results"
    code, _, body = http_get(search_url)
    if code != 200 or not body:
        return None
    match = re.search(r'"refNum"\s*:\s*"([^"]+)"', body)
    return match.group(1) if match else None


def phenom_refine_search(
    company: dict[str, Any],
    keyword: str,
    *,
    limit: int = 20,
    offset: int = 0,
) -> tuple[list[dict[str, Any]], int]:
    widgets = phenom_widgets_url(company)
    refnum = str(company.get("phenom_refnum") or "").strip() or phenom_discover_refnum(
        str(company.get("browse_url") or company.get("phenom_base") or "")
    )
    if not widgets or not refnum:
        return [], 0
    payload = {
        "lang": str(company.get("phenom_lang") or "en_global"),
        "deviceType": "desktop",
        "country": str(company.get("phenom_country") or "global"),
        "pageName": "search-results",
        "size": max(1, min(limit, 50)),
        "from": max(0, offset),
        "jobs": True,
        "counts": True,
        "keywords": keyword,
        "refNum": refnum,
        "ddoKey": "refineSearch",
        "siteType": str(company.get("phenom_site_type") or "external"),
        "global": bool(company.get("phenom_global", True)),
    }
    code, _, body = http_post_json(widgets, payload)
    if code != 200 or not body:
        return [], 0
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return [], 0
    block = data.get("refineSearch") if isinstance(data, dict) else None
    if not isinstance(block, dict):
        return [], 0
    total = int(block.get("totalHits") or 0)
    jobs = ((block.get("data") or {}).get("jobs") or []) if isinstance(block.get("data"), dict) else []
    return [row for row in jobs if isinstance(row, dict)], total


def fetch_phenom(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    queries = cap_company_search_queries(company, cfg, max_queries_key="phenom_max_queries")
    if not queries:
        queries = ["devops"]
    if not phenom_widgets_url(company):
        return [], "Phenom widgets URL missing (set phenom_base or phenom_widgets_url)"
    refnum = str(company.get("phenom_refnum") or "").strip()
    if not refnum:
        refnum = phenom_discover_refnum(str(company.get("browse_url") or "")) or ""
    if not refnum:
        return [], "Phenom refNum missing (set phenom_refnum or browse_url for discovery)"

    cache_ttl = float(company.get("cache_ttl_hours", 12))
    cache_key = f"phenom-{company['id']}-{'-'.join(queries[:3])[:80]}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, list):
                raw: list[RawPosting] = []
                for row in payload:
                    if not isinstance(row, dict) or not row.get("title"):
                        continue
                    if not row.get("salary_label") and row.get("description_text"):
                        sal, lab = phenom_salary_from_detail(
                            {},
                            str(row.get("description_text") or ""),
                            cfg,
                            location_name=str(row.get("location_name") or ""),
                            title=str(row.get("title") or ""),
                        )
                        row = {
                            **row,
                            "salary": sal or company.get("default_salary", "maybe"),
                            "salary_label": lab,
                        }
                    raw.append(RawPosting(**row))
                note = f"Phenom ({len(queries)} queries, {len(payload)} listed, {len(raw)} parsed)"
                return raw, note
        except (json.JSONDecodeError, TypeError):
            pass

    employer_region = company_employer_region(company)
    aviation_pilot_mode = _company_uses_aviation_pilot_titles(company)
    max_details = int(company.get("max_details", 24))
    seen_ids: set[str] = set()
    records: list[dict[str, Any]] = []
    total_seen = 0
    page_size = int(company.get("phenom_page_size") or 20)
    cid = str(company.get("id") or "")
    for query in queries:
        if _company_fetch_abandoned(cid):
            break
        offset = 0
        while len(records) < max_details:
            if _company_fetch_abandoned(cid):
                break
            jobs, total = phenom_refine_search(
                company, query, limit=page_size, offset=offset
            )
            total_seen = max(total_seen, total)
            if not jobs:
                break
            page_jobs: list[tuple[dict[str, Any], str, str, str, str, str]] = []
            for job in jobs:
                if _company_fetch_abandoned(cid):
                    break
                job_id = str(job.get("jobId") or job.get("reqId") or "").strip()
                if not job_id or job_id in seen_ids:
                    continue
                title = str(job.get("title") or "").strip()
                if title_rejected_by_scrape_filters(title, cfg, company):
                    continue
                seen_ids.add(job_id)
                location_name = str(
                    job.get("location")
                    or job.get("cityState")
                    or ", ".join(
                        x
                        for x in (
                            str(job.get("city") or ""),
                            str(job.get("state") or ""),
                            str(job.get("country") or ""),
                        )
                        if x
                    )
                    or ""
                ).strip()
                job_loc, loc_label = classify_location_with_fallback(location_name, employer_region)
                if aviation_pilot_mode and job_loc == "excluded" and (
                    location_text_indicates_us_worksite(location_name)
                    or "remote" in location_name.lower()
                ):
                    job_loc = str(company.get("default_loc") or "remote")
                if not job_loc:
                    record_filter_reject(cid, title, phenom_job_url(company, job), "location")
                    continue
                page_jobs.append((job, job_id, title, location_name, job_loc, loc_label))
            teaser_survivors: list[
                tuple[dict[str, Any], str, str, str, str, str, str]
            ] = []
            for job, job_id, title, location_name, job_loc, loc_label in page_jobs:
                if len(records) + len(teaser_survivors) >= max_details:
                    break
                teaser = str(job.get("descriptionTeaser") or "").strip()
                if (
                    teaser
                    and not aviation_pilot_mode
                    and jd_blocks_job(
                        teaser, title, cfg, exclude, keyword_exclude_title_only=True
                    )
                ):
                    record_jd_filter_reject(
                        cid,
                        title,
                        "jd blocklist (teaser)",
                        url=phenom_job_url(company, {**job, "title": title}),
                    )
                    continue
                teaser_survivors.append(
                    (job, job_id, title, location_name, job_loc, loc_label, teaser)
                )
            remaining = max(0, max_details - len(records))
            to_fetch = teaser_survivors[:remaining]
            detail_by_id = _parallel_fetch_ats_details(
                [job_id for _, job_id, _, _, _, _, _ in to_fetch],
                lambda jid: phenom_fetch_job_detail(company, jid, cache_ttl_hours=cache_ttl),
                company_id=cid,
            )
            for job, job_id, title, location_name, job_loc, loc_label, teaser in to_fetch:
                if _company_fetch_abandoned(cid) or len(records) >= max_details:
                    break
                detail = detail_by_id.get(job_id) or {}
                description_text = str(detail.get("description_text") or "").strip()
                if detail.get("title"):
                    title = str(detail["title"]).strip() or title
                if not description_text:
                    description_text = teaser
                if (
                    description_text
                    and description_text != teaser
                    and not aviation_pilot_mode
                    and jd_blocks_job(
                        description_text, title, cfg, exclude, keyword_exclude_title_only=True
                    )
                ):
                    record_jd_filter_reject(
                        cid,
                        title,
                        "jd blocklist",
                        url=phenom_job_url(company, {**job, "title": title}),
                    )
                    continue
                salary, salary_label = phenom_salary_from_detail(
                    detail,
                    description_text,
                    cfg,
                    location_name=location_name,
                    title=title,
                )
                apply_url = str(
                    job.get("applyUrl") or detail.get("applyUrl") or ""
                ).strip()
                job_url = resolve_job_posting_url(
                    str(detail.get("url") or "").strip()
                    or phenom_job_url(company, {**job, "title": title}),
                    company,
                    job_id=job_id,
                    title=title,
                    apply_url=apply_url,
                )
                posted_raw = str(job.get("postedDate") or "").strip()
                records.append(
                    {
                        "title": title,
                        "url": job_url,
                        "description_text": description_text,
                        "location_name": location_name,
                        "posted_ts": parse_iso_ts(posted_raw) or parse_human_posted(posted_raw),
                        "job_id": job_id,
                        "employment": str(job.get("type") or "").strip(),
                        "salary": salary or company.get("default_salary", "maybe"),
                        "salary_label": salary_label,
                        "meta_parts": [
                            p
                            for p in (
                                location_name,
                                str(job.get("category") or "").strip() or None,
                            )
                            if p
                        ],
                        "force_loc": job_loc,
                        "force_loc_label": loc_label,
                        "skip_keyword_filter": True,
                    }
                )
            if len(records) >= max_details:
                break
            offset += page_size
            if offset >= total or offset >= 200:
                break
        if len(records) >= max_details:
            break

    if not records:
        listed = max(total_seen, len(seen_ids))
        if listed > 0:
            note = f"Phenom ({len(queries)} queries, {listed} listed, 0 parsed)"
            return [], note
        return [], "Phenom API returned no matching postings"
    cache_set(SCRIPT_DIR, cache_key, json.dumps(records))
    raw = [RawPosting(**row) for row in records]
    note = f"Phenom ({len(queries)} queries, {total_seen} listed, {len(raw)} parsed)"
    return raw, note


def fetch_apple(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    _, _, exclude = cfg_title_tiers(cfg)
    queries = company_search_queries(company, cfg)
    search_urls = apple_search_urls(company, queries)
    seen_urls: set[str] = set()
    rows: list[dict[str, str]] = []
    for url in search_urls:
        code, _, body = http_get(url)
        if code != 200 or not body:
            continue
        for row in apple_parse_search(body):
            if row["url"] in seen_urls:
                continue
            seen_urls.add(row["url"])
            rows.append(row)
    cid = str(company.get("id") or "")
    survivors: list[dict[str, str]] = []
    title_skipped = 0
    for row in rows:
        title = row["title"]
        row_url = str(row["url"])
        if title_rejected_by_scrape_filters(title, cfg, company, url=row_url):
            title_skipped += 1
            continue
        survivors.append(row)
    detail_cap = _apple_max_detail_fetches()
    detail_urls, window_offset, survivor_count = _apple_detail_window_urls(
        survivors,
        company_id=cid,
        detail_cap=detail_cap,
    )
    window_enabled = _apple_detail_window_enabled()
    detail_by_url = _parallel_fetch_ats_details(
        sorted(detail_urls),
        apple_fetch_detail,
        company_id=cid,
    )
    raw: list[RawPosting] = []
    detail_fetches = 0
    list_only_outside_window = 0
    for row in survivors:
        if _company_fetch_abandoned(cid):
            break
        title = row["title"]
        row_url = str(row["url"])
        in_detail_window = row_url in detail_urls
        detail = detail_by_url.get(row_url) if in_detail_window else None
        if in_detail_window:
            if not detail:
                continue
            detail_fetches += 1
            description_text = html_to_plain(apple_detail_description(detail))
            skip = jd_blocks_job(description_text, title, cfg, exclude, keyword_exclude_title_only=True)
            if skip:
                record_jd_filter_reject(cid, title, skip, url=row_url)
                continue
            job_id = str(detail.get("job_id") or "")
            locations = [x for x in detail.get("locations") or [] if x]
            location_name = ", ".join(locations) or row.get("location") or ""
            home_office = str(detail.get("home_office") or "").lower() == "true"
            posted_ts = parse_iso_ts(str(detail.get("posted") or "")) or parse_human_posted(
                row.get("posted")
            )
            meta_parts = [detail.get("team") or row.get("team") or None, location_name or None]
            out_title = detail.get("title") or title
        else:
            if window_enabled:
                list_only_outside_window += 1
            description_text = ""
            job_id = ""
            location_name = row.get("location") or ""
            home_office = location_name_is_remoteish(location_name)
            posted_ts = parse_human_posted(row.get("posted"))
            meta_parts = [row.get("team") or None, location_name or None]
            out_title = title
        if home_office:
            job_loc, loc_label = "remote", None
        else:
            job_loc = str(company.get("default_loc") or "excluded")
            loc_label = location_name or None
        salary, salary_label = (
            salary_from_detail_text(description_text, cfg, location_name=location_name)
            if description_text
            else (None, None)
        )
        raw.append(
            RawPosting(
                title=out_title,
                url=row_url.split("?")[0],
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=job_id,
                salary=salary or company.get("default_salary", "maybe"),
                salary_label=salary_label,
                meta_parts=[str(p) for p in meta_parts if p],
                force_loc=job_loc,
                force_loc_label=loc_label,
                skip_keyword_filter=True,
            )
        )
    if survivor_count and detail_cap > 0 and window_enabled:
        advance_apple_detail_offset(cid, survivor_count, detail_cap)
    note = f"Apple search ({len(search_urls)} pages, {len(rows)} roles, {len(raw)} parsed"
    if title_skipped:
        note = f"{note}, {title_skipped} title-filtered pre-detail"
    if detail_fetches:
        note = f"{note}, {detail_fetches} details"
    if list_only_outside_window:
        note = (
            f"{note} (detail window {window_offset}:{window_offset + detail_cap}"
            f", {list_only_outside_window} list-only)"
        )
    note = f"{note})"
    return raw, note


_EIGHTFOLD_PCSX_PASSTHROUGH = frozenset(
    {
        "location",
        "filter_distance",
        "filter_include_remote",
        "sort_by",
    }
)


def parse_eightfold_pcsx_target(
    browse_url: str,
    company: dict[str, Any] | None = None,
) -> tuple[str, str, dict[str, str]] | None:
    text = str(browse_url or "").strip()
    if not text:
        return None
    parsed = urllib.parse.urlsplit(text)
    host = parsed.netloc
    if not host:
        return None
    params = urllib.parse.parse_qs(parsed.query, keep_blank_values=False)
    domain = (params.get("domain") or [None])[0]
    if not domain:
        if host.startswith("careers.") and host.count(".") >= 2:
            domain = host[len("careers.") :]
        elif host.endswith(".eightfold.ai"):
            slug = host.split(".")[0]
            domain = f"{slug}.com"
    if not domain:
        return None
    extra: dict[str, str] = {}
    for key in _EIGHTFOLD_PCSX_PASSTHROUGH:
        if key in params and params[key]:
            extra[key] = params[key][0]
    if company is not None:
        explicit_loc = str(company.get("eightfold_location") or "").strip()
        if explicit_loc and "location" not in extra:
            extra["location"] = explicit_loc
    return host, str(domain), extra


def eightfold_pcsx_location_filters_from_company(
    company: dict[str, Any],
    browse_url: str,
) -> list[str]:
    explicit = company.get("eightfold_pcsx_location_filters")
    if explicit:
        return [str(item).strip() for item in explicit if str(item).strip()]
    parsed = urllib.parse.urlsplit(browse_url)
    params = urllib.parse.parse_qs(parsed.query, keep_blank_values=False)
    raw = (params.get("filter_rmk_location") or [""])[0]
    if not raw:
        return []
    if "," in raw:
        return [part.strip() for part in raw.split(",") if part.strip()]
    return [raw.strip()]


def eightfold_pcsx_collect_by_location_filters(
    host: str,
    domain: str,
    location_filters: list[str],
    *,
    sort_by: str = "timestamp",
) -> list[dict[str, Any]]:
    """Bulk PCSX fetch: one paginated search per filter_rmk_location value, merged by id."""
    by_id: dict[Any, dict[str, Any]] = {}
    for loc_filter in location_filters:
        extra = {"filter_rmk_location": loc_filter, "sort_by": sort_by}
        try:
            batch = eightfold_pcsx_search_all(host, domain, extra)
        except Exception:
            continue
        for position in batch:
            pid = position.get("id")
            if pid is not None and pid not in by_id:
                by_id[pid] = position
    return list(by_id.values())


def eightfold_pcsx_search_page(
    host: str,
    domain: str,
    extra: dict[str, str],
    *,
    start: int = 0,
    num: int = 10,
) -> list[dict[str, Any]]:
    query = {"domain": domain, "start": str(start), "num": str(num)}
    query.update(extra)
    url = f"https://{host}/api/pcsx/search?{urllib.parse.urlencode(query)}"
    req = urllib.request.Request(
        url,
        headers={"User-Agent": DEFAULT_USER_AGENT, "Accept": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    block = data.get("data") if isinstance(data, dict) else None
    if not isinstance(block, dict):
        return []
    batch = block.get("positions") or []
    return [item for item in batch if isinstance(item, dict)] if isinstance(batch, list) else []


def eightfold_pcsx_search_all(
    host: str,
    domain: str,
    extra: dict[str, str],
) -> list[dict[str, Any]]:
    positions: list[dict[str, Any]] = []
    start = 0
    page_size = 10
    total: int | None = None
    while True:
        query = {"domain": domain, "start": str(start), "num": str(page_size)}
        query.update(extra)
        url = f"https://{host}/api/pcsx/search?{urllib.parse.urlencode(query)}"
        req = urllib.request.Request(
            url,
            headers={"User-Agent": DEFAULT_USER_AGENT, "Accept": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        block = data.get("data") if isinstance(data, dict) else None
        if not isinstance(block, dict):
            break
        batch = block.get("positions") or []
        if not isinstance(batch, list):
            break
        if total is None:
            total = int(block.get("count") or 0)
        positions.extend(item for item in batch if isinstance(item, dict))
        if not batch or (total is not None and len(positions) >= total):
            break
        start += page_size
    return positions


def _eightfold_pcsx_position_location(position: dict[str, Any]) -> str:
    locations = position.get("locations") or []
    if isinstance(locations, list) and locations:
        return ", ".join(str(item) for item in locations if item)
    return str(position.get("location") or "")


def _eightfold_pcsx_is_local_location(loc_text: str) -> bool:
    text = str(loc_text or "")
    return bool(
        re.search(r"\bOR\b", text)
        or "OR-" in text
        or any(city in text for city in ("Tualatin", "Hillsboro", "Beaverton", "Portland"))
    )


def _eightfold_pcsx_title_matches(title: str, queries: list[str]) -> bool:
    if not queries:
        return True
    lower = title.lower()
    return any(query.lower() in lower for query in queries)


def eightfold_careers_base_url(browse_url: str, *, host: str = "") -> str:
    """Eightfold posting links must use the /careers path or the host drops pid on redirect."""
    raw = str(browse_url or "").strip()
    if not raw and host:
        raw = f"https://{host}/careers"
    parsed = urllib.parse.urlsplit(raw.split("?")[0].rstrip("/"))
    scheme = parsed.scheme or "https"
    netloc = parsed.netloc or host
    if not netloc:
        return ""
    path = parsed.path or ""
    base_path = path if path.endswith("/careers") else "/careers"
    return urllib.parse.urlunsplit((scheme, netloc, base_path, "", ""))


def eightfold_posting_url(browse_url: str, pid: str | int, *, host: str = "") -> str:
    base = eightfold_careers_base_url(browse_url, host=host)
    return f"{base}?pid={pid}&sort_by=timestamp"


def eightfold_pcsx_fetch_detail(
    host: str,
    domain: str,
    position_id: str | int,
    browse_url: str,
) -> dict[str, Any] | None:
    pid = str(position_id or "").strip()
    if not pid:
        return None
    detail_url = (
        f"https://{host}/api/pcsx/position_details?"
        f"{urllib.parse.urlencode({'position_id': pid, 'domain': domain})}"
    )
    req = urllib.request.Request(
        detail_url,
        headers={"User-Agent": DEFAULT_USER_AGENT, "Accept": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    detail = data.get("data") if isinstance(data, dict) else None
    if not isinstance(detail, dict):
        return None
    title = str(detail.get("name") or "").strip()
    if not title:
        return None
    location = _eightfold_pcsx_position_location(detail)
    location = eightfold_location_label(location) or location
    job_url = eightfold_posting_url(browse_url, pid, host=host)
    posted_ts_raw = detail.get("postedTs")
    posted = ""
    posted_ts = 0
    if posted_ts_raw:
        try:
            posted_ts = int(posted_ts_raw)
            posted = datetime.fromtimestamp(posted_ts, tz=timezone.utc).strftime("%b %d, %Y")
        except (TypeError, ValueError, OSError):
            posted_ts = 0
            posted = ""
    description_html = str(detail.get("jobDescription") or "")
    employment = str(detail.get("workLocationOption") or "full-time").lower()
    return {
        "url": job_url,
        "job_id": str(detail.get("displayJobId") or detail.get("atsJobId") or pid),
        "title": title,
        "location": location,
        "posted": posted,
        "posted_ts": posted_ts,
        "employment": employment,
        "description_text": html_to_plain(description_html),
    }


def eightfold_pcsx_collect_positions(
    host: str,
    domain: str,
    extra: dict[str, str],
    queries: list[str],
    *,
    query_search: bool,
    query_page_size: int = 10,
) -> list[dict[str, Any]]:
    """Collect PCSX postings; per-query search mirrors Playwright keyword searches."""
    by_id: dict[Any, dict[str, Any]] = {}
    if query_search and queries:
        for query in queries:
            qextra = dict(extra)
            qextra["query"] = query
            try:
                batch = eightfold_pcsx_search_page(
                    host, domain, qextra, start=0, num=query_page_size
                )
            except Exception:
                continue
            for position in batch:
                pid = position.get("id")
                if pid is not None and pid not in by_id:
                    by_id[pid] = position
        return list(by_id.values())
    return eightfold_pcsx_search_all(host, domain, extra)


def fetch_eightfold_pcsx(
    company: dict[str, Any],
    cfg: dict[str, Any],
) -> tuple[list[RawPosting], str | None]:
    browse_url = str(company.get("browse_url") or company.get("hub_url") or "").strip()
    target = parse_eightfold_pcsx_target(browse_url, company)
    if not target:
        return [], "Eightfold PCSX browse_url missing or invalid"
    host, domain, extra = target
    include, _ = company_keywords(company, cfg)
    queries = company_search_queries(company, cfg)
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    location_filters = eightfold_pcsx_location_filters_from_company(company, browse_url)
    location_bulk = bool(location_filters)
    cache_key = (
        f"eightfold-pcsx-{company['id']}-v3-loc-{'-'.join(location_filters[:4])[:40]}"
        if location_bulk
        else f"eightfold-pcsx-{company['id']}-v3-careers-url"
    )
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, list):
                raw = playwright_records_to_raw(
                    payload,
                    company,
                    cfg,
                    kind="eightfold",
                    live_label="Live posting (eightfold via PCSX)",
                )
                note = f"Eightfold PCSX ({len(payload)} details, {len(raw)} parsed)"
                return raw, note
        except json.JSONDecodeError:
            pass

    try:
        if location_bulk:
            all_positions = eightfold_pcsx_collect_by_location_filters(
                host,
                domain,
                location_filters,
            )
            mode = f"location {','.join(location_filters)}"
        else:
            query_search = bool(company.get("eightfold_pcsx_query_search", True))
            search_extra = dict(extra)
            if query_search and queries and "location" not in urllib.parse.urlsplit(browse_url).query:
                search_extra.pop("location", None)
            all_positions = eightfold_pcsx_collect_positions(
                host,
                domain,
                search_extra,
                queries,
                query_search=query_search,
                query_page_size=int(company.get("eightfold_pcsx_query_page_size") or 10),
            )
            mode = f"{len(queries)} queries" if query_search and queries else "bulk"
    except Exception as exc:
        return [], f"Eightfold PCSX search error: {exc}"

    if _output_verbose():
        print(
            f"  {company['id']}: PCSX listed {len(all_positions)} posting(s) ({mode})",
            flush=True,
        )

    if location_bulk:
        ordered = list(all_positions)
        detail_cap = int(
            company.get("eightfold_pcsx_max_details")
            or company.get("max_details")
            or len(all_positions)
        )
        detail_cap = min(detail_cap, len(all_positions))
    else:
        if queries:
            matched = [
                position
                for position in all_positions
                if _eightfold_pcsx_title_matches(str(position.get("name") or ""), queries)
                and title_matches_title_filters(str(position.get("name") or ""), cfg, company=company)
            ]
        else:
            matched = list(all_positions)
        local = [
            position
            for position in matched
            if _eightfold_pcsx_is_local_location(_eightfold_pcsx_position_location(position))
        ]
        other = [position for position in matched if position not in local]
        ordered = local + other
        detail_cap = int(company.get("max_details", 24))

    records: list[dict[str, Any]] = []
    for position in ordered:
        if len(records) >= detail_cap:
            break
        try:
            detail = eightfold_pcsx_fetch_detail(
                host,
                domain,
                position.get("id"),
                browse_url,
            )
        except Exception as exc:
            RUN_METRICS.setdefault("scrape_errors", []).append(
                f"{position.get('name')}: {exc}"
            )
            continue
        if detail:
            records.append(detail)

    if not records:
        return [], "Eightfold PCSX returned no postings"

    cache_set(SCRIPT_DIR, cache_key, json.dumps(records))
    raw = playwright_records_to_raw(
        records,
        company,
        cfg,
        kind="eightfold",
        live_label="Live posting (eightfold via PCSX)",
    )
    note = (
        f"Eightfold PCSX ({mode}, {len(all_positions)} listed, "
        f"{len(records)} details, {len(raw)} parsed)"
    )
    return raw, note


WORKDAY_MAINTENANCE_MARKERS = (
    "workday is currently unavailable",
    "community.workday.com",
    "maintenance-page",
)
WORKDAY_SKIP_PROBE_CACHE_HOURS = 6.0


def workday_html_looks_like_maintenance(html: str, final_url: str = "") -> bool:
    blob = f"{html}\n{final_url}".lower()
    return any(marker in blob for marker in WORKDAY_MAINTENANCE_MARKERS)


def workday_site_skip_reason_cached(company_id: str) -> str | None:
    raw = cache_get(
        SCRIPT_DIR,
        f"workday-skip-{company_id}",
        ttl_hours=WORKDAY_SKIP_PROBE_CACHE_HOURS,
    )
    if raw is None or raw == "ok":
        return None
    return raw


def workday_site_skip_reason_cache_set(company_id: str, reason: str | None) -> None:
    cache_set(SCRIPT_DIR, f"workday-skip-{company_id}", reason if reason else "ok")


def probe_workday_site_skip(
    company: dict[str, Any],
    *,
    ignore_cached_skip: bool = False,
) -> str | None:
    """HTTP probe for Workday maintenance before launching Playwright.

    Workday listing pages are SPAs: a small HTML shell is normal, so we only skip on
    explicit maintenance markers (not on body length).
    """
    company_id = str(company.get("id") or "").strip()
    if not company_id:
        return None
    if ignore_cached_skip:
        workday_site_skip_reason_cache_set(company_id, None)
    else:
        cached = workday_site_skip_reason_cached(company_id)
        if cached and "empty listing" in cached.lower():
            workday_site_skip_reason_cache_set(company_id, None)
            cached = None
        if cached:
            return cached
    browse_url = str(company.get("browse_url") or "").strip()
    if not browse_url or "myworkdayjobs.com" not in browse_url.lower():
        return None
    status, final_url, body = http_get(browse_url, timeout=12)
    if workday_html_looks_like_maintenance(body, final_url):
        reason = "Workday unavailable (maintenance; skipped Playwright)"
        workday_site_skip_reason_cache_set(company_id, reason)
        return reason
    if status not in {200, 403, 406}:
        return None
    workday_site_skip_reason_cache_set(company_id, None)
    return None


def workday_cxs_should_playwright_fallback(note: str | None) -> bool:
    """True when CXS is blocked (HTTP 410/422) and browser scrape may still work."""
    if not note:
        return False
    blob = note.lower()
    return "422" in blob or "410" in blob


def workday_cxs_unavailable_reason(host: str, tenant: str, site: str) -> str | None:
    """One-shot CXS probe; cached when tenant returns HTTP 410 or 422."""
    cache_key = f"workday-cxs-422-{tenant}-{site}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=WORKDAY_SKIP_PROBE_CACHE_HOURS)
    if cached in ("410", "422"):
        return f"Workday CXS unavailable (HTTP {cached})"
    url = f"https://{host}.myworkdayjobs.com/wday/cxs/{tenant}/{site}/jobs"
    payload = json.dumps(
        {"appliedFacets": {}, "limit": 1, "offset": 0, "searchText": ""}
    ).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=payload,
        method="POST",
        headers={
            "User-Agent": DEFAULT_USER_AGENT,
            "Accept": "application/json",
            "Content-Type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            json.loads(resp.read().decode("utf-8"))
        return None
    except urllib.error.HTTPError as exc:
        if exc.code in (410, 422):
            cache_set(SCRIPT_DIR, cache_key, str(exc.code))
            return f"Workday CXS unavailable (HTTP {exc.code})"
        return f"Workday CXS error (HTTP {exc.code})"
    except (urllib.error.URLError, TimeoutError, OSError, json.JSONDecodeError):
        return None


def parse_workday_cxs_target(browse_url: str) -> tuple[str, str, str] | None:
    match = re.search(r"https://([^/]+)\.myworkdayjobs\.com/(?:[^/]+/)?([^/?#]+)", str(browse_url or "").strip())
    if not match:
        return None
    host = match.group(1)
    site = match.group(2)
    tenant = host.split(".")[0]
    if not tenant or not site:
        return None
    return host, tenant, site


def workday_cxs_search(
    host: str,
    tenant: str,
    site: str,
    query: str,
    *,
    limit: int = 20,
    offset: int = 0,
) -> list[dict[str, Any]]:
    url = f"https://{host}.myworkdayjobs.com/wday/cxs/{tenant}/{site}/jobs"
    payload = json.dumps(
        {
            "appliedFacets": {},
            "limit": limit,
            "offset": max(0, offset),
            "searchText": query,
        }
    ).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=payload,
        method="POST",
        headers={
            "User-Agent": DEFAULT_USER_AGENT,
            "Accept": "application/json",
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    postings = data.get("jobPostings") or []
    return postings if isinstance(postings, list) else []


def workday_cxs_fetch_detail(
    host: str,
    tenant: str,
    site: str,
    external_path: str,
) -> dict[str, Any] | None:
    path = str(external_path or "").strip()
    if not path.startswith("/"):
        path = f"/{path}"
    url = f"https://{host}.myworkdayjobs.com/wday/cxs/{tenant}/{site}{path}"
    req = urllib.request.Request(
        url,
        headers={"User-Agent": DEFAULT_USER_AGENT, "Accept": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    info = data.get("jobPostingInfo") if isinstance(data, dict) else None
    if not isinstance(info, dict):
        return None
    description_html = str(info.get("jobDescription") or "")
    bullet = info.get("bulletFields") or []
    job_id = ""
    if isinstance(bullet, list) and bullet:
        job_id = str(bullet[0] or "").strip()
    location = workday_merge_locations(
        str(info.get("location") or info.get("locationsText") or "").strip(),
        info.get("additionalLocations"),
    )
    posted = str(info.get("postedOn") or "").strip()
    employment = str(info.get("timeType") or info.get("workerSubType") or "").strip()
    title = str(info.get("title") or "").strip()
    external_url = str(info.get("externalUrl") or "").strip()
    if not external_url:
        external_url = f"https://{host}.myworkdayjobs.com/en-US/{site}{path}"
    return {
        "title": title,
        "url": normalize_job_url(external_url),
        "location": location,
        "posted": posted,
        "employment": employment,
        "job_id": job_id,
        "description_text": html_to_plain(description_html),
    }


def playwright_records_to_raw(
    records: list[dict[str, Any]],
    company: dict[str, Any],
    cfg: dict[str, Any],
    *,
    kind: str,
    live_label: str | None = None,
) -> list[RawPosting]:
    _, _, exclude = cfg_title_tiers(cfg)
    employer_region = company_employer_region(company)
    cid = str(company.get("id") or "")
    raw: list[RawPosting] = []
    seen_urls: set[str] = set()
    for record in records:
        url = normalize_job_url(str(record.get("url") or ""))
        title = str(record.get("title") or "").strip()
        if not url or not title or url in seen_urls:
            continue
        seen_urls.add(url)
        if title_rejected_by_scrape_filters(title, cfg, company, url=url):
            continue
        description_text = html_to_plain(str(record.get("description_text") or ""))
        if not company.get("skip_profile_jd_blocklist"):
            skip = jd_blocks_job(
                description_text, title, cfg, exclude, keyword_exclude_title_only=True
            )
            if skip:
                record_jd_filter_reject(cid, title, skip, url=url)
                continue
        location_name = str(record.get("location") or "").strip()
        if kind == "nike":
            if nike_title_is_international(title):
                continue
            employer_hq = str(company.get("employer_hq") or "").strip()
            if employer_hq and location_name.lower() == employer_hq.lower():
                location_name = ""
            location_name = nike_resolve_location(location_name, description_text)
            if not location_name:
                continue
            if nike_location_is_non_us(location_name):
                continue
        if kind == "eightfold" and location_name:
            location_name = eightfold_location_label(location_name) or location_name
        if kind == "icims":
            loc_text = str(location_name or "").strip()
            loc_match = re.match(r"^US-([A-Z]{2})-(.+)$", loc_text)
            if loc_match:
                city = loc_match.group(2).replace("-", " ")
                location_name = f"{city}, {loc_match.group(1)}"
            elif not loc_text:
                location_name = str(company.get("employer_hq") or "")
        if kind == "workday":
            location_name = enrich_workday_location(location_name, url, description_text)
        record_company = str(record.get("company_name") or "").strip()
        if kind == "pilotsglobal" and record_company:
            location_name = location_name or record_company
        meta_location = str(record.get("meta_location") or location_name).strip()
        classify_location = location_name if kind == "nike" else location_name
        job_loc, loc_label = classify_location_with_fallback(
            classify_location,
            employer_region,
            str(company.get("default_loc") or ""),
            cfg,
            title=title,
            description_text=description_text,
        )
        if not job_loc:
            continue
        posted_text = str(record.get("posted") or "").strip()
        posted_ts = parse_human_posted(posted_text)
        employment_raw = str(record.get("employment") or "").lower()
        employment = "contract" if "contract" in employment_raw else "full-time"
        salary = None
        salary_label = None
        if kind in {"workday", "eightfold", "google", "ibm", "icims"}:
            salary, salary_label = salary_from_detail_text(
                description_text, cfg, location_name=location_name, job_loc=job_loc
            )
        meta_parts = [record_company or None, meta_location or None] if kind == "pilotsglobal" else [meta_location or None]
        if posted_text and not posted_ts:
            meta_parts.append(posted_text)
        label = live_label or f"Live posting ({kind})"
        meta_parts.append(label)
        raw.append(
            RawPosting(
                title=title,
                url=url,
                description_text=description_text,
                location_name=location_name,
                posted_ts=posted_ts,
                job_id=str(record.get("job_id") or ""),
                employment=employment,
                salary=salary,
                salary_label=salary_label,
                company_name=record_company,
                meta_parts=[str(p) for p in meta_parts if p],
                force_loc=job_loc,
                force_loc_label=loc_label,
                skip_keyword_filter=kind != "pilotsglobal",
                skip_jd_blocklist=True,
                use_posting_keywords=kind == "pilotsglobal",
                skip_verify=kind == "pilotsglobal",
            )
        )
    return raw


def fetch_workday_cxs(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    target = parse_workday_cxs_target(str(company.get("browse_url") or ""))
    if not target:
        return [], "Workday CXS browse_url missing or invalid"
    host, tenant, site = target
    cxs_skip = workday_cxs_unavailable_reason(host, tenant, site)
    if cxs_skip:
        return [], cxs_skip
    include, _ = cfg_keywords(cfg)
    queries = company_search_queries(company, cfg)
    if not queries:
        queries = [""]
    cache_ttl = float(company.get("cache_ttl_hours", 12))
    cache_key = f"workday-cxs-{company['id']}-{'-'.join(queries[:3])[:80]}"
    cached = cache_get(SCRIPT_DIR, cache_key, ttl_hours=cache_ttl)
    if cached is not None:
        try:
            payload = json.loads(cached)
            if isinstance(payload, list):
                raw = playwright_records_to_raw(payload, company, cfg, kind="workday")
                note = f"Workday CXS ({len(queries)} queries, {len(payload)} details, {len(raw)} parsed)"
                return raw, note
        except json.JSONDecodeError:
            pass

    seen_paths: set[str] = set()
    records: list[dict[str, Any]] = []
    max_details = int(company.get("max_details", 24))
    per_query_cap = int(company.get("workday_cxs_max_details_per_query") or 0)
    if per_query_cap <= 0 and len(queries) > 1:
        # Spread the detail budget so later search_keywords still get pulls.
        per_query_cap = max(5, max_details // max(len(queries), 1))
    page_size = 20
    cid = str(company.get("id") or "")
    for query in queries:
        offset = 0
        query_details = 0
        while not _company_fetch_abandoned(cid):
            try:
                postings = workday_cxs_search(
                    host, tenant, site, query, limit=page_size, offset=offset
                )
            except urllib.error.HTTPError as exc:
                if exc.code in (410, 422):
                    cache_set(SCRIPT_DIR, f"workday-cxs-422-{tenant}-{site}", str(exc.code))
                    return [], f"Workday CXS unavailable (HTTP {exc.code})"
                break
            except Exception:
                break
            if not postings:
                break
            for posting in postings:
                if not isinstance(posting, dict):
                    continue
                external_path = str(posting.get("externalPath") or "").strip()
                if not external_path or external_path in seen_paths:
                    continue
                # Skip detail fetch when the listing title already fails filters
                # (Workday search ranking is fuzzy; this preserves the detail budget).
                list_title = str(posting.get("title") or "").strip()
                if list_title and not title_matches_title_filters(
                    list_title, cfg, company=company
                ):
                    seen_paths.add(external_path)
                    continue
                seen_paths.add(external_path)
                try:
                    detail = workday_cxs_fetch_detail(host, tenant, site, external_path)
                except Exception:
                    continue
                if not detail or not detail.get("title"):
                    continue
                if not detail.get("location"):
                    detail["location"] = str(posting.get("locationsText") or "").strip()
                records.append(detail)
                query_details += 1
                if len(records) >= max_details:
                    break
                if per_query_cap and query_details >= per_query_cap:
                    break
            if len(records) >= max_details:
                break
            if per_query_cap and query_details >= per_query_cap:
                break
            if len(postings) < page_size:
                break
            offset += page_size
            if offset >= 500:
                break

    if not records:
        return [], "Workday CXS returned no postings"
    cache_set(SCRIPT_DIR, cache_key, json.dumps(records))
    raw = playwright_records_to_raw(records, company, cfg, kind="workday")
    note = f"Workday CXS ({len(queries)} queries, {len(records)} details, {len(raw)} parsed)"
    return raw, note


def fetch_workday_playwright(
    company: dict[str, Any], cfg: dict[str, Any], *, cxs_note: str | None = None
) -> tuple[list[RawPosting], str | None]:
    """Browser scrape for Workday (listing scroll + job detail pages)."""
    force_pw = workday_cxs_should_playwright_fallback(cxs_note)
    site_skip = probe_workday_site_skip(company, ignore_cached_skip=force_pw)
    if site_skip:
        return [], site_skip
    include, _ = cfg_keywords(cfg)
    queries = company_search_queries(company, cfg)
    max_queries = int(company.get("workday_playwright_max_queries") or 0)
    if max_queries > 0:
        queries = queries[:max_queries]
    start_urls = playwright_search_urls(company, queries)
    if not start_urls:
        return [], "Playwright workday missing search URL"
    records, error = run_playwright_scraper(company, "workday", start_urls, queries)
    if error:
        if cxs_note:
            return [], f"{cxs_note}; fallback {error}"
        return [], error
    raw = playwright_records_to_raw(
        records,
        company,
        cfg,
        kind="workday",
        live_label="Live posting (workday via Playwright)",
    )
    query_count = len(start_urls)
    pw_note = f"Playwright workday ({query_count} queries, {len(records)} details, {len(raw)} parsed)"
    if cxs_note:
        pw_note = f"{pw_note}; {cxs_note}"
    return raw, pw_note


def fetch_playwright(company: dict[str, Any], cfg: dict[str, Any]) -> tuple[list[RawPosting], str | None]:
    kind = str(company.get("playwright_kind") or company["id"])
    if kind == "workday" and str(company.get("workday_fetch") or "cxs").lower() != "playwright":
        raw, cxs_note = fetch_workday_cxs(company, cfg)
        if raw or not workday_cxs_should_playwright_fallback(cxs_note):
            return raw, cxs_note
        skip_pw = company.get("workday_skip_playwright_on_422", True)
        if skip_pw is not False:
            return [], "Workday currently unavailable (CXS API blocked; Playwright skipped)"
        return fetch_workday_playwright(company, cfg, cxs_note=cxs_note)
    if kind == "workday":
        return fetch_workday_playwright(company, cfg)
    if kind == "eightfold" and str(company.get("eightfold_fetch") or "pcsx").lower() != "playwright":
        raw, note = fetch_eightfold_pcsx(company, cfg)
        return raw, note
    include, _ = cfg_keywords(cfg)
    queries = company_search_queries(company, cfg)
    if kind == "pilotsglobal":
        start_urls = [
            str(url).strip()
            for url in (company.get("listing_urls") or [company.get("browse_url") or ""])
            if str(url).strip()
        ]
        queries = []
    else:
        start_urls = playwright_search_urls(company, queries)
    if not start_urls:
        return [], f"Playwright {kind} missing search URL"
    records, error = run_playwright_scraper(company, kind, start_urls, queries)
    if error:
        return [], error
    raw = playwright_records_to_raw(
        records,
        company,
        cfg,
        kind=kind,
        live_label=f"Live posting ({kind} via Playwright)",
    )
    query_count = len(queries) if kind in {"nike", "eightfold"} else len(start_urls)
    note = f"Playwright {kind} ({query_count} queries, {len(records)} details, {len(raw)} parsed)"
    return raw, note



def _wrap_fetch_ingest(
    fetch_fn: Callable[[dict[str, Any], dict[str, Any]], tuple[list[RawPosting], str | None]],
    company: dict[str, Any],
    cfg: dict[str, Any],
    overrides: dict[str, Any],
) -> Any:
    raw, note = fetch_fn(company, cfg)
    note_lower = (note or "").lower()
    playwright_error = note_lower.startswith("playwright ") and (
        "missing" in note_lower
        or "unsupported" in note_lower
        or "malformed" in note_lower
        or " error:" in note_lower
        or "navigation failed" in note_lower
    )
    if note and not _oracle_no_matching_postings_note(note) and (
        note.startswith(
            (
                "RSS feed missing",
                "JSON feed HTTP",
                "Dice MCP error",
                "Monster RSS API error",
                "RSS feed returned",
                "json_url",
                "Unknown json_variant",
                "Greenhouse API",
                "Lever API",
                "SmartRecruiters API",
                "Bullhorn Public API HTTP",
                "Bullhorn Public API missing",
                "Bullhorn Public API returned",
                "Jefferson Frank GraphQL HTTP",
                "Jefferson Frank GraphQL missing",
                "Jefferson Frank GraphQL returned",
                "Jefferson Frank GraphQL error",
                "Oracle HCM API",
                "Phenom API",
                "Phenom widgets URL missing",
                "Phenom refNum missing",
            )
        )
        or playwright_error
        or ("HTTP " in note and "returned" in note)
    ):
        return ingest_postings(company, cfg, overrides, [], error_note=note)
    return ingest_postings(company, cfg, overrides, raw, search_note=note or "")


def _legacy_search(name: str, company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]) -> Any:
    return globals()[f"search_{name}"](company, cfg, overrides)


def dispatch_company_search(
    company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]
) -> Any:
    ctype = str(company.get("type", "entries")).strip().lower()
    handler = SEARCH_HANDLERS.get(ctype)
    if handler is None:
        return _legacy_search("entries", company, cfg, overrides)
    return handler(company, cfg, overrides)


