def company_is_hub_link(company: dict[str, Any]) -> bool:
    return str(company.get("type") or "").lower() == "hub"


def reconcile_cfg_hub_results(
    results: list[CompanyResult], company_list: list[dict[str, Any]]
) -> list[CompanyResult]:
    hub_by_id = {
        str(c["id"]): c for c in company_list if c.get("id") and company_is_hub_link(c)
    }
    if not hub_by_id:
        return results
    out: list[CompanyResult] = []
    for co in results:
        company = hub_by_id.get(co.id)
        out.append(search_hub(company) if company else co)
    return out


def reconcile_cfg_company_display(
    results: list[CompanyResult], company_list: list[dict[str, Any]]
) -> list[CompanyResult]:
    """Refresh name/label from static config (snapshot rows may be stale)."""
    cfg_by_id = {
        str(c.get("id") or "").strip(): c
        for c in company_list
        if isinstance(c, dict) and str(c.get("id") or "").strip()
    }
    if not cfg_by_id:
        return results
    out: list[CompanyResult] = []
    for co in results:
        company = cfg_by_id.get(co.id)
        if not company:
            out.append(co)
            continue
        name = str(company.get("name") or co.name or "")
        label = str(company.get("label") or co.label or "")
        if name == co.name and label == co.label:
            out.append(co)
            continue
        out.append(
            CompanyResult(
                id=co.id,
                name=name,
                label=label,
                section=co.section,
                jobs=co.jobs,
                browse_url=co.browse_url,
                hub_url=co.hub_url,
                hub_note=co.hub_note,
                footer_links=list(co.footer_links),
                subsection=co.subsection,
                subsection_warn=co.subsection_warn,
                search_note=co.search_note,
                layoff_prone=co.layoff_prone,
                source_group=co.source_group,
                h1b_grade=co.h1b_grade,
                h1b_label=co.h1b_label,
            )
        )
    return out


def company_result_is_hub_link(co: CompanyResult) -> bool:
    return co.search_note == "Career hub link" and bool(co.hub_url)


def board_layout_section(
    co: CompanyResult,
    company_cfg: dict[str, Any] | None = None,
) -> str:
    """Section id used when placing job cards on the HTML board.

    Index employers converted from hub→scrape keep section=\"hubs\" in JSON; they must
    render under matching (not the hub-link table) or sidebar counts lie.
    """
    if co.section != "hubs":
        return co.section
    if company_cfg is not None and not company_is_hub_link(company_cfg):
        return "matching"
    if not company_result_is_hub_link(co):
        return "matching"
    return "hubs"


MANUAL_CAREER_INDEX_LABEL_RE = re.compile(
    r"\s*\((?:S&amp;P\s*500|Nasdaq|NASDAQ|S&P\s*500)[^)]*\)\s*",
    re.IGNORECASE,
)

COMPANY_HEADER_LABEL_SUFFIX_RE = re.compile(r"\s*\([^)]*\)\s*$")


def _strip_trailing_parentheticals(text: str) -> str:
    """Remove trailing '(…)' suffixes from board company headers."""
    cleaned = str(text or "").strip()
    while cleaned:
        nxt = COMPANY_HEADER_LABEL_SUFFIX_RE.sub("", cleaned).strip()
        if nxt == cleaned:
            return cleaned
        cleaned = nxt
    return cleaned


def company_result_preserves_posting_employer(co: CompanyResult) -> bool:
    """Aggregators/recruiters keep per-posting employer names on job cards."""
    return str(getattr(co, "source_group", "") or "").strip().lower() in {
        "job_sites",
        "recruiters",
    }


def apply_company_result_job_fields(co: CompanyResult, job: Job) -> None:
    """Copy company-level flags onto a job without clobbering aggregator employers."""
    job.layoff_prone = co.layoff_prone
    if company_result_preserves_posting_employer(co) and str(job.company_name or "").strip():
        return
    job.company_name = co.name


def company_header_display_name(co: CompanyResult) -> str:
    """Company name shown on the board (no trailing location/hub suffixes in parens)."""
    raw = str(co.label or co.name or "").strip()
    cleaned = _strip_trailing_parentheticals(raw)
    return cleaned or raw


