def favicon_domains_path(namespace: str | None = None) -> Path:
    stem = quickjobs_config_stem(namespace if namespace is not None else quickjobs_namespace())
    return (SCRIPT_DIR / f"{stem}.favicon-domains.json")


def company_favicon_domains_cache_path(namespace: str | None = None) -> Path:
    stem = quickjobs_config_stem(namespace if namespace is not None else quickjobs_namespace())
    return (SCRIPT_DIR / f"{stem}.company_favicon_domains.json")


def load_favicon_domain_overrides() -> dict[str, dict[str, str]]:
    global _FAVICON_DOMAIN_OVERRIDES_MEMO
    if _FAVICON_DOMAIN_OVERRIDES_MEMO is not None:
        return _FAVICON_DOMAIN_OVERRIDES_MEMO
    path = favicon_domains_path()
    if path.is_file():
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            raw = {}
    else:
        raw = {}
    overrides = {
        "by_company_id": dict(raw.get("by_company_id") or {}),
        "by_greenhouse_board": dict(raw.get("by_greenhouse_board") or {}),
        "by_ashby_board": dict(raw.get("by_ashby_board") or {}),
        "by_lever_site": dict(raw.get("by_lever_site") or {}),
        "by_workday_site": dict(raw.get("by_workday_site") or {}),
        "by_smartrecruiters_company": dict(raw.get("by_smartrecruiters_company") or {}),
    }
    legacy_path = company_favicon_domains_cache_path()
    legacy_changed = False
    if legacy_path.is_file():
        try:
            legacy_raw = json.loads(legacy_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            legacy_raw = {}
        legacy_by_id = legacy_raw.get("by_company_id") or {}
        if legacy_by_id:
            merged_by_id = dict(overrides["by_company_id"])
            for key, value in legacy_by_id.items():
                k = str(key).strip()
                v = str(value).strip()
                if not k or not v or k in merged_by_id:
                    continue
                merged_by_id[k] = v
                legacy_changed = True
            if legacy_changed:
                overrides["by_company_id"] = merged_by_id
        try:
            legacy_path.unlink()
        except OSError:
            pass
    if legacy_changed:
        persist_favicon_domain_overrides(overrides)
        return _FAVICON_DOMAIN_OVERRIDES_MEMO
    _FAVICON_DOMAIN_OVERRIDES_MEMO = overrides
    return _FAVICON_DOMAIN_OVERRIDES_MEMO


def persist_favicon_domain_overrides(
    overrides: dict[str, dict[str, str]],
    *,
    namespace: str | None = None,
) -> Path:
    global _FAVICON_DOMAIN_OVERRIDES_MEMO, _COMPANY_FAVICON_CACHE_MEMO
    path = favicon_domains_path(namespace)
    payload = {
        "by_company_id": dict(sorted((overrides.get("by_company_id") or {}).items())),
        "by_greenhouse_board": dict(
            sorted((overrides.get("by_greenhouse_board") or {}).items())
        ),
        "by_ashby_board": dict(sorted((overrides.get("by_ashby_board") or {}).items())),
        "by_lever_site": dict(sorted((overrides.get("by_lever_site") or {}).items())),
        "by_workday_site": dict(sorted((overrides.get("by_workday_site") or {}).items())),
        "by_smartrecruiters_company": dict(
            sorted((overrides.get("by_smartrecruiters_company") or {}).items())
        ),
    }
    atomic_write_text(path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    _FAVICON_DOMAIN_OVERRIDES_MEMO = payload
    _COMPANY_FAVICON_CACHE_MEMO = dict(payload["by_company_id"])
    return path


def load_company_favicon_domains_cache() -> dict[str, str]:
    global _COMPANY_FAVICON_CACHE_MEMO
    if _COMPANY_FAVICON_CACHE_MEMO is not None:
        return _COMPANY_FAVICON_CACHE_MEMO
    _COMPANY_FAVICON_CACHE_MEMO = dict(load_favicon_domain_overrides().get("by_company_id") or {})
    return _COMPANY_FAVICON_CACHE_MEMO


def persist_company_favicon_domains_cache(
    by_company_id: dict[str, str],
    *,
    namespace: str | None = None,
) -> Path:
    overrides = {
        key: dict(value)
        for key, value in load_favicon_domain_overrides().items()
    }
    overrides["by_company_id"] = dict(sorted(by_company_id.items()))
    return persist_favicon_domain_overrides(overrides, namespace=namespace)


def _is_ats_favicon_host(host: str) -> bool:
    h = str(host or "").strip().lower().removeprefix("www.")
    if not h:
        return True
    if h in _ATS_FAVICON_HOSTS:
        return True
    return any(h == suffix or h.endswith(f".{suffix}") for suffix in _ATS_FAVICON_HOST_SUFFIXES)


def _is_ats_browse_url(url: str) -> bool:
    lower = str(url or "").strip().lower()
    return any(token in lower for token in _ATS_BROWSE_URL_TOKENS)


def _company_skips_favicon_domain_audit(company_cfg: dict[str, Any] | None) -> bool:
    """Job aggregators / recruiters have per-posting employers, not one corporate domain."""
    if not isinstance(company_cfg, dict):
        return False
    group = str(company_cfg.get("source_group") or "").strip().lower()
    if group in {"job_sites", "recruiters"}:
        return True
    return str(company_cfg.get("type") or "").strip().lower() in _AGGREGATOR_FAVICON_TYPES


def _employer_favicon_lookup_key(employer_name: str) -> str:
    """Normalize employer display names for favicon alias lookup."""
    cleaned = str(employer_name or "")
    cleaned = unicodedata.normalize("NFKD", cleaned)
    cleaned = "".join(ch for ch in cleaned if not unicodedata.combining(ch))
    cleaned = re.sub(r"\([^)]*\)", " ", cleaned)
    cleaned = cleaned.replace("&", " and ")
    # Possessives with ASCII or curly apostrophes ("Orange County's" / "County’s").
    cleaned = re.sub(r"[''']s\b", " ", cleaned, flags=re.I)
    cleaned = re.sub(r"[''']", "", cleaned)
    cleaned = re.sub(
        r"\b(inc|llc|ltd|corp|corporation|co|company|group|holdings|"
        r"technologies|technolog|joint venture|jv|and services|services|"
        r"medtech|mexican grill)\b\.?",
        " ",
        cleaned,
        flags=re.I,
    )
    return re.sub(r"[^a-z0-9]+", " ", cleaned.lower()).strip()


