def search_company(company: dict[str, Any], cfg: dict[str, Any], overrides: dict[str, Any]) -> CompanyResult:
    co = dispatch_company_search(company, cfg, overrides)
    return attach_company_flags(co, company, cfg)


def esc(text: str) -> str:
    return html.escape(str(text), quote=True)


def _favicon_png_path(filename: str) -> Path | None:
    for base in (SCRIPT_DIR, SCRIPT_DIR / "portable"):
        path = base / filename
        if path.is_file():
            return path
    bundled = Path(__file__).resolve().parent / "portable" / filename
    if bundled.is_file():
        return bundled
    return None


def _png_data_uri(path: Path) -> str:
    encoded = base64.standard_b64encode(path.read_bytes()).decode("ascii")
    return f"data:image/png;base64,{encoded}"


def favicon_head_tags() -> str:
    """Favicon embedded in HTML (no separate PNG fetch; confirmed via headless network trace)."""
    fav = _favicon_png_path("quickjobs-favicon.png")
    if not fav:
        return ""
    lines = [
        f'  <link rel="icon" href="{_png_data_uri(fav)}" type="image/png" sizes="32x32">',
    ]
    apple = _favicon_png_path("quickjobs-apple-touch-icon.png")
    if apple:
        lines.append(
            f'  <link rel="apple-touch-icon" href="{_png_data_uri(apple)}" sizes="180x180">',
        )
    return "\n".join(lines) + "\n"


def badge_match(match: str) -> str:
    return f'<span class="badge badge-match-{match}">{esc(MATCH_LABELS.get(match, match))}</span>'


def loc_badge_communicates_remote_us(job: Job) -> bool:
    """True when the displayed loc badge still shows US-wide remote text."""
    if job.loc in {"excluded", "remote-intl"} or job.loc_verify:
        return False
    if location_is_geo_or_remote_us_hybrid(str(job.loc_label or "")):
        return False
    geo = geographic_loc_badge_label(job)
    return bool(geo and location_text_is_remote_us_nationwide(geo))


