def location_text_is_unqualified_bare_remote(text: str) -> bool:
    """True for bare Remote / WFH labels with no US or country scope."""
    lower = " ".join(str(text or "").strip().lower().split())
    return lower in _UNQUALIFIED_BARE_REMOTE_SEGMENTS


def job_employer_region_for_job(job: Job, cfg: dict[str, Any] | None = None) -> str:
    company_id = str(getattr(job, "company_id", None) or "")
    if cfg and company_id:
        for company in cfg.get("companies", []):
            if str(company.get("id") or "") == company_id:
                return company_employer_region(company)
    return "us"


def _job_meta_location_parts(job: Job) -> list[str]:
    parts: list[str] = []
    for part in re.split(r"\s*·\s*", job.meta or ""):
        piece = part.strip()
        if not piece:
            continue
        if _meta_part_is_scrape_note(piece) or re.match(
            r"^(?:Posted|Relisted)\s+", piece, re.I
        ):
            continue
        if re.match(r"^JR\d+\b", piece, re.I):
            continue
        parts.append(piece)
    return parts


def _label_is_us_plus_allied_country_remote_eligible(label: str, job_loc: str) -> bool:
    """Deprecated: US + allied-country lists are not nationwide US-only remote."""
    return False


def _job_jd_nationwide_remote_blocked(job: Job) -> bool:
    """Block title/JD from promoting geo-anchored or country-locked roles to nationwide remote."""
    label = str(job.loc_label or "").strip()
    if label and location_text_is_state_locked_us_remote(label):
        return True
    if label and location_text_is_non_us_country_remote(label):
        return True
    if label and location_is_geo_or_remote_us_hybrid(label):
        return True
    if label and location_text_has_geographic_place(label) and not location_text_is_remote_us_nationwide(label):
        return True
    if str(job.loc or "").strip() == "excluded" and label:
        if location_text_indicates_us_worksite(label) and not location_name_is_remoteish(label):
            return True
    if extract_linkedin_location_mode(job.title, label, job.description_text) == "onsite":
        return True
    return False


def job_is_nationwide_us_remote_unrestricted(
    job: Job,
    cfg: dict[str, Any] | None = None,
    *,
    employer_region: str | None = None,
) -> bool:
    """True when any US resident could work remotely (no state or site lock)."""
    if job.loc_verify:
        return False
    if _job_location_text_is_remote_nationwide(job):
        return True
    # Workday remote-eligible roles often list HQ cities plus additionalLocations
    # "US Remote". Badge sanitization may strip "US Remote" from loc_label; still
    # honor an explicit nationwide remote segment from label/meta.
    for part in (
        str(job.loc_label or "").strip(),
        str(job.meta or "").strip(),
        *_job_meta_location_parts(job),
    ):
        if not part:
            continue
        if location_has_us_nationwide_remote_segment(part):
            return True
    if job.loc not in {"remote", "excluded"}:
        return False
    if location_is_geo_or_remote_us_hybrid(str(job.loc_label or "")):
        return False
    region = employer_region if employer_region is not None else job_employer_region_for_job(job, cfg)
    us_employer = region != "international"
    label = str(job.loc_label or "").strip()
    jd_blocked = _job_jd_nationwide_remote_blocked(job)
    if label:
        if location_text_is_bare_us_country(label):
            return False
        if location_text_is_non_us_country_remote(label):
            return False
        if location_text_is_remote_us_nationwide(label):
            return True
        if _label_is_us_plus_allied_country_remote_eligible(label, job.loc):
            return True
        if location_text_has_geographic_place(label) and not location_text_is_remote_us_nationwide(label):
            return False
        if location_text_is_state_locked_us_remote(label):
            return False
    if jd_blocked:
        return False
    explicit_remote = False
    for part in _job_meta_location_parts(job):
        if location_text_is_bare_us_country(part):
            continue
        if location_text_is_non_us_country_remote(part):
            continue
        if location_text_is_remote_us_nationwide(part):
            return True
        if location_text_has_explicit_remote_signal(part):
            explicit_remote = True
    if explicit_remote and not label and us_employer:
        return True
    return False


def job_is_nationwide_us_remote(job: Job, cfg: dict[str, Any] | None = None) -> bool:
    """True when job is US-wide remote with no city/state anchor in loc_label/meta."""
    if job_is_onsite_work_model(job):
        return False
    return job_is_nationwide_us_remote_unrestricted(job, cfg)


def location_text_is_remote_us_nationwide(text: str) -> bool:
    raw = str(text or "").strip()
    if not raw:
        return False
    if location_lists_us_with_other_countries(raw):
        return False
    if location_text_is_non_us_country_remote(raw):
        return False
    if location_is_geo_or_remote_us_hybrid(raw):
        return False
    if location_has_onsite_us_site_segments(raw):
        return False
    if location_has_mixed_remote_and_onsite_us(raw):
        return False
    if segment_is_state_usa_remote(raw):
        return False
    segments = location_work_segments(raw)
    if len(segments) >= 2 and all(
        segment_is_state_usa_remote(seg) or segment_is_us_country_state_remote(seg)
        for seg in segments
    ):
        return False
    lower = " ".join(raw.lower().replace("·", ",").split())
    if location_text_is_state_locked_us_remote(raw):
        return False
    state_remote = re.match(r"^remote\s*[-–—:,]\s*(?P<place>[a-z][a-z .'-]{0,40})\s*$", lower)
    if state_remote:
        place = state_remote.group("place").strip()
        if not _state_blob_is_broad_us_remote(place):
            state = _parse_us_state_token(place.split()[0])
            if state:
                return False
    if lower in {
        "remote us",
        "remote usa",
        "remote - us",
        "remote, us",
        "remote (us)",
        "remote (u.s.)",
        "remote (u.s)",
        "remote, usa",
        "remote, united states",
        "remote - united states",
        "remote united states",
        "remote nationwide",
        "remote nationwide us",
        "remote nationwide, us",
        "remote, nationwide",
        "remote, nationwide us",
        "united states - remote",
        "united states - remote opportunity",
        "united states (remote)",
        "united states, remote",
        "remote - usa",
        "us remote",
        "us - remote",
        "usa - remote",
        "u.s. - remote",
        "u.s.a. - remote",
        "u.s. (remote)",
        "us (remote)",
        "usa, remote",
        "us, remote",
    }:
        return True
    if re.match(
        r"^remote\s*[-–—:,]\s*(?:us|usa|u\.s\.|united states)"
        r"(?:\s*:\s*all\s+locations(?:\s*\([^)]*\))?)?\s*$",
        lower,
    ):
        return True
    if re.match(
        r"^[-–—\s]*remote\s*,?\s*(?:usa|us|u\.s\.|united states)\s*[-–—\s]*$",
        lower,
    ):
        return True
    if re.match(
        r"^remote\s*,?\s*nationwide(?:\s*[-–—:,]\s*(?:us|usa|u\.s\.|united states))?\s*$",
        lower,
    ):
        return True
    if location_text_is_bare_us_country(raw):
        return False
    if re.match(r"^remote\s*\(\s*(?:u\.s\.|us|usa|united states)\s*\)\s*$", lower):
        return True
    if re.match(r"^united states\s*[-–—]\s*remote(?:\s+opportunity)?\s*$", lower):
        return True
    if re.match(r"^united states\s*\(\s*remote\s*\)\s*$", lower):
        return True
    if re.match(r"^(?:us|usa|u\.s\.|united states)\s*[-–—]\s*remote(?:\s+opportunity)?\s*$", lower):
        return True
    if re.match(r"^(?:us|usa|u\.s\.|united states)\s*\(\s*remote\s*\)\s*$", lower):
        return True
    if _segment_is_bare_remote(raw) and not location_text_is_unqualified_bare_remote(raw):
        return True
    if segment_is_us_country_remote(raw) or location_has_us_nationwide_remote_segment(raw):
        return True
    if remote_scope_is_broad_us(lower):
        return True
    if re.search(r"\bremote\s+(?:us|usa|u\.s\.|united states)\b", lower):
        return True
    if re.search(r"\b(?:us|usa|u\.s\.|united states)\s*,?\s*remote\b", lower):
        return True
    compact = re.sub(r"\s*·\s*", ", ", lower)
    if re.match(r"^remote\s*,?\s*(?:us|usa|u\.s\.|united states)\.?$", compact):
        return True
    return False


def _remote_label_workable_from_home_states(
    *parts: str,
    cfg: dict[str, Any] | None = None,
) -> bool:
    """True when location/title/JD text signals US-wide or profile-home-state remote."""
    blob = "\n".join(str(p or "") for p in parts if str(p or "").strip())
    if not blob:
        return False
    if location_text_is_remote_us_nationwide(blob):
        return True
    if workday_remote_matches_profile(blob, cfg):
        return True
    allowed = extract_state_limited_remote_allowed_states(blob)
    if allowed is not None:
        return bool(allowed & profile_remote_ok_states(cfg))
    ok_states = profile_remote_ok_states(cfg)
    for segment in location_work_segments(blob):
        lower = segment.lower()
        state_remote = re.match(r"^remote\s*,\s*(?P<place>.+)$", lower)
        if state_remote:
            state = _parse_us_state_token(state_remote.group("place").split(",")[0].strip())
            if state in ok_states:
                return True
        if segment_is_state_usa_remote(segment):
            match = _GH_STATE_USA_REMOTE_RE.match(
                location_strip_paren_suffix(segment)[0]
            )
            if match:
                state = _parse_us_state_token(match.group("state"))
                if state in ok_states:
                    return True
    lower = blob.lower()
    for code in ok_states:
        name = US_STATE_CODE_TO_NAME.get(code, "").lower()
        if name and re.search(rf"\b{re.escape(name)}\b", lower):
            if location_name_is_remoteish(blob) or "remote" in lower:
                return True
        if re.search(rf"remote\s*,\s*{code.lower()}\b", lower):
            return True
    return False


def job_is_remote_workable_from_home(job: Job, cfg: dict[str, Any] | None = None) -> bool:
    """True for nationwide US remote or remote workable from the profile home state."""
    loc = str(job.loc or "").strip()
    if job_is_onsite_work_model(job):
        return False
    if loc == "local":
        return False
    # Nationwide US remote is always workable from the profile home state (OR).
    if job_is_nationwide_us_remote_unrestricted(job, cfg):
        return True
    loc_label = str(job.loc_label or "")
    title = str(job.title or "")
    desc = str(job.description_text or "")[:2500]

    def us_remote_eligible() -> bool:
        if job_is_nationwide_us_remote(job):
            return True
        if location_is_multi_country_us_eligible(loc_label):
            return True
        return _remote_label_workable_from_home_states(
            loc_label,
            title,
            desc,
            cfg=cfg,
        )

    if loc == "remote-intl":
        return us_remote_eligible()

    if loc == "excluded":
        allowed = extract_state_limited_remote_allowed_states(loc_label, title, desc)
        if allowed is not None:
            return bool(allowed & profile_remote_ok_states(cfg))
        return workday_remote_matches_profile(loc_label, cfg)

    if loc != "remote":
        return False

    allowed = extract_state_limited_remote_allowed_states(loc_label, title, desc)
    if allowed is not None:
        return bool(allowed & profile_remote_ok_states(cfg))
    return us_remote_eligible()


def _job_location_text_is_remote_nationwide(job: Job) -> bool:
    """True when raw loc_label/meta names Remote Nationwide (not generic Remote US)."""
    for part in (
        str(job.loc_label or "").strip(),
        *[p.strip() for p in re.split(r"\s*·\s*", job.meta or "") if p.strip()],
    ):
        if not part:
            continue
        lower = " ".join(part.lower().split())
        if lower in {"remote nationwide", "remote nationwide us", "remote nationwide, us", "remote, nationwide", "remote, nationwide us"}:
            return True
        if re.match(
            r"^remote\s*,?\s*nationwide(?:\s*[-–—:,]\s*(?:us|usa|u\.s\.|united states))?\s*$",
            lower,
        ):
            return True
    return False


def loc_badge_tooltip_label(job: Job, display: str) -> str:
    """Full location for title/aria on loc badges (prefer raw loc_label)."""
    full = str(job.loc_label or "").strip()
    return full or str(display or "").strip()


