_US_COUNTRY_DISPLAY_PREFIX_RE = re.compile(
    r"^\s*(?:USA|US|United States)\s*[-–—]\s*",
    re.I,
)

_INTL_COUNTRY_DISPLAY_PREFIX_RE = re.compile(
    r"^\s*(?:GBR|UK|United Kingdom|CAN|Canada|DE|Germany|FR|France)\s*[-–—]\s*",
    re.I,
)

_WASHINGTON_DC_SEGMENT_RE = re.compile(
    r"^Washington\s*,?\s*(?:DC|D\.?\s*C\.?|District\s+of\s+Columbia)\.?$",
    re.I,
)


def _strip_redundant_us_country_prefix(text: str) -> str:
    """Drop leading 'USA - ' / 'United States - ' before city, state display."""
    return _US_COUNTRY_DISPLAY_PREFIX_RE.sub("", str(text or "").strip(), count=1).strip()


def _strip_redundant_country_prefix(text: str) -> str:
    """Drop leading country code labels (USA -, GBR -, …) before city display."""
    seg = _strip_redundant_us_country_prefix(text)
    return _INTL_COUNTRY_DISPLAY_PREFIX_RE.sub("", seg, count=1).strip()


def _abbreviate_country_token(token: str, *, whole_segment: bool) -> str | None:
    key = " ".join(str(token or "").strip().lower().split())
    if not key:
        return None
    upper = key.upper()
    if whole_segment and upper in _COUNTRY_ALPHA3_TO_ISO2:
        return _COUNTRY_ALPHA3_TO_ISO2[upper]
    if whole_segment and upper == "GB":
        return "UK"
    if key in _COUNTRY_LABEL_TO_ABBREV:
        abbrev = _COUNTRY_LABEL_TO_ABBREV[key]
        if not whole_segment and abbrev in US_STATE_CODES:
            return None
        return abbrev
    if key == "canada" and whole_segment:
        return "CA"
    return None


def _abbreviate_state_token(token: str) -> str | None:
    raw = str(token or "").strip()
    if not raw:
        return None
    upper = raw.upper()
    if upper in US_STATE_CODES:
        return upper
    mapped = US_STATE_NAME_TO_CODE.get(raw.lower())
    if mapped:
        return mapped
    if upper in CANADA_PROVINCE_CODES:
        return upper
    return CANADA_PROVINCE_NAME_TO_CODE.get(raw.lower())


def _abbreviate_location_segment(segment: str, *, keep_country_readable: bool = False) -> str:
    """Shorten one location segment (no slash); built-in US/state/country maps only."""
    raw = _strip_redundant_country_prefix(segment)
    deduped = dedupe_country_name_and_code_in_location(raw)
    if "," in raw and "," not in deduped:
        seg = abbreviate_geo_region_label(deduped)
        return seg
    seg = abbreviate_geo_region_label(deduped)
    if not seg:
        return seg
    if _WASHINGTON_DC_SEGMENT_RE.match(seg):
        return "DC"
    if "," not in seg:
        if keep_country_readable and _part_is_country_name(seg):
            return seg
        state = _abbreviate_state_token(seg)
        if state:
            return state
        country_only = _abbreviate_country_token(seg, whole_segment=True)
        if country_only:
            return country_only
        return seg
    parts = [p.strip() for p in seg.split(",") if p.strip()]
    if not parts:
        return seg
    if len(parts) >= 2:
        last_key = " ".join(parts[-1].lower().replace(".", "").split())
        if last_key in {"united states", "usa", "us", "u s a", "u s"} and len(parts) >= 3:
            first_lower = parts[0].lower()
            if not first_lower.startswith("work at home") and not location_name_is_remoteish(
                parts[0]
            ):
                if any(_abbreviate_state_token(p) for p in parts[:-1]):
                    parts = parts[:-1]
    if len(parts) == 2 and parts[0].lower() == "washington":
        tail = parts[1].lower().replace(".", "").replace(" ", "")
        if tail in {"dc", "districtofcolumbia"}:
            return "DC"
    out: list[str] = []
    last_idx = len(parts) - 1
    for i, part in enumerate(parts):
        is_last = i == last_idx
        state = _abbreviate_state_token(part)
        if state:
            if not is_last and i + 1 < len(parts):
                next_abbrev = _abbreviate_state_token(parts[i + 1])
                if next_abbrev and state == next_abbrev:
                    out.append(part)
                    continue
            out.append(state)
            continue
        if is_last:
            if part.lower() in {"romania", "india"}:
                out.append(part)
                continue
            country = _abbreviate_country_token(part, whole_segment=False)
            if country:
                out.append(country)
                continue
        out.append(part)
    result = ", ".join(out)
    result_parts = [p.strip() for p in result.split(",") if p.strip()]
    if len(result_parts) == 2:
        abbrev = _resolve_country_abbrev_token(result_parts[1])
        city_key = " ".join(result_parts[0].lower().split())
        country_name = _lookup_country_name_for_abbrev(result_parts[1])
        if abbrev == "TP" and country_name and city_key != country_name:
            return result_parts[0]
    return result


def abbreviate_location_label(text: str, *, company_name: str = "") -> str:
    """Shorten long geographic labels for display; classification uses full text."""
    original = str(text or "").strip()
    raw = strip_company_prefix_from_location(original, company_name)
    raw = normalize_location_display_label(raw, for_badge=False)
    raw = dedupe_duplicate_city_in_location(raw)
    if not raw:
        return raw
    if raw == NATIONWIDE_REMOTE_US_LABEL or location_text_is_remote_us_nationwide(raw):
        return NATIONWIDE_REMOTE_US_LABEL
    keep_readable = location_has_remote_marker(original)
    lines = stacked_location_lines(raw, keep_country_readable=keep_readable)
    if len(lines) > 1:
        if location_display_prefers_stacked_lines(raw):
            return "\n".join(lines)
        return " / ".join(lines)
    return lines[0] if lines else _abbreviate_location_segment(
        raw, keep_country_readable=keep_readable
    )


def stacked_location_lines(text: str, *, keep_country_readable: bool = False) -> list[str]:
    """Abbreviated location segments, one entry per line when multi-site."""
    abbrev = lambda seg: _abbreviate_location_segment(
        seg, keep_country_readable=keep_country_readable
    )
    gh_lines = greenhouse_multi_segment_display_lines(text)
    if len(gh_lines) >= 2:
        return gh_lines
    hybrid_cities = extract_hybrid_any_office_cities(text)
    if len(hybrid_cities) >= 2:
        return hybrid_cities
    chained = split_chained_city_state_locations(text)
    if len(chained) >= 2:
        return chained
    bare_cities = split_bare_multi_city_label(text)
    if len(bare_cities) >= 2:
        return bare_cities
    multi_places = split_comma_separated_multi_place_label(text)
    if len(multi_places) >= 2:
        return multi_places
    if "\n" in str(text or ""):
        lines = [ln.strip() for ln in str(text).splitlines() if ln.strip()]
        if len(lines) >= 2:
            return [abbrev(ln) for ln in lines]
    segments = split_location_display_segments(text)
    if len(segments) <= 1:
        single = segments[0] if segments else str(text or "").strip()
        return [abbrev(single)] if single else []
    return [abbrev(s) for s in segments]

def stacked_location_html(text: str, *, line_class: str = "loc-line") -> str:
    lines = stacked_location_lines(text)
    if not lines:
        return ""
    if len(lines) == 1:
        return esc(lines[0])
    cls = f' class="{line_class}"' if line_class else ""
    return "<br>".join(f"<span{cls}>{esc(line)}</span>" for line in lines)


def loc_badge_span(job: Job, css_class: str, display: str) -> str:
    tooltip = loc_badge_tooltip_label(job, display)
    lines = stacked_location_lines(display)
    stack = len(lines) > 1 and location_display_prefers_stacked_lines(display)
    multi_cls = " badge-loc-multi" if stack else ""
    collapsible = stack and len(lines) >= LOC_BADGE_COLLAPSE_THRESHOLD
    if stack:
        inner = stacked_location_html(display)
    elif len(lines) > 1:
        inner = esc(" / ".join(lines))
    else:
        inner = esc(
            lines[0]
            if lines
            else abbreviate_location_label(
                display, company_name=getattr(job, "company_name", "")
            )
        )
    attrs = ""
    if tooltip:
        attrs = f' title="{esc(tooltip)}" aria-label="{esc(tooltip)}"'
    collapse_cls = " is-loc-collapsed" if collapsible else ""
    badge_html = (
        f'<span class="badge badge-loc {css_class}{multi_cls}{collapse_cls}"{attrs}>'
        f"{inner}</span>"
    )
    if collapsible:
        return (
            f'<div class="badge-loc-wrap badge-loc-wrap-collapsible">'
            f"{badge_html}{loc_badge_toggle_button()}</div>"
        )
    return badge_html


def badge_loc(job: Job, local_badge: str) -> str:
    nationwide_us = _job_location_text_is_remote_nationwide(job)
    if job.loc == "excluded":
        geo = geographic_loc_badge_label(job)
        if not geo and nationwide_us:
            geo = "US"
        if geo:
            return loc_badge_span(job, "badge-loc-excluded", geo)
    if job.loc_verify:
        return loc_badge_span(job, "badge-loc-verify", "Verify remote")
    if job.loc == "remote":
        geo = geographic_loc_badge_label(job)
        if not geo and nationwide_us:
            geo = "US"
        if (
            geo
            and not location_text_is_work_model_only(geo)
            and not location_text_is_remote_us_nationwide(geo)
        ):
            return loc_badge_span(job, "badge-loc-remote", geo)
        return ""
    if job.loc == "remote-intl":
        geo = geographic_loc_badge_label(job)
        if geo:
            return loc_badge_span(job, "badge-loc-remote-intl", geo)
        return loc_badge_span(job, "badge-loc-remote-intl", "INTL REMOTE")
    if job.loc == "local":
        geo = geographic_loc_badge_label(job) or local_badge
        return loc_badge_span(job, "badge-loc-local", geo)
    return ""


def badge_work_model(job: Job, cfg: dict[str, Any] | None = None) -> str:
    if job_is_nationwide_us_remote(job, cfg):
        return (
            f'<span class="badge badge-work-model badge-work-model-remote">'
            f"{esc(NATIONWIDE_REMOTE_US_LABEL)}</span>"
        )
    mode = str(job.work_model or "").strip().lower()
    if not mode:
        mode = infer_work_model(
            job.loc_label or "",
            job.description_text,
            job.title,
        ) or ""
        mode = str(mode).strip().lower()
    if not mode and job.loc in {"remote", "remote-intl"}:
        mode = "remote"
    if not mode:
        return ""
    if mode in {"remote", "distributed", "work from home", "flexible"} and loc_badge_communicates_remote_us(job):
        return ""
    label = {"in-office": "In Person", "onsite": "In Person", "hybrid": "Hybrid", "remote": "Remote"}.get(
        mode, mode.replace("-", " ").title()
    )
    css = mode.replace("_", "-")
    if css == "onsite":
        css = "in-office"
    return f'<span class="badge badge-work-model badge-work-model-{css}">{esc(label)}</span>'


def badge_employment(job: Job) -> str:
    emp = job.employment or "full-time"
    if emp == "contract":
        return '<span class="badge badge-emp-contract">Contract</span>'
    if emp == "search":
        return '<span class="badge badge-emp-search">Search link</span>'
    return '<span class="badge badge-emp-fte">Full-time</span>'


_SALARY_BADGE_AMOUNT_RE = re.compile(
    r"\$\s*([\d,.]+)\s*([KkMm])?(\+)?",
)


def compact_salary_badge_label(label: str, *, title: str = "") -> str:
    """Short dollar-only text for the salary badge column (no TC/median/Levels prose)."""
    raw = str(label or "").strip()
    if not raw:
        return ""
    lower = raw.lower()
    if lower in {"verify band", "pay ok", "ote high", "below floor"}:
        return raw
    if lower.startswith("below "):
        return raw if len(raw) <= 22 else raw[:22]
    range_match = re.search(
        r"(\$?\s*[\d,.]+(?:\s*[kKmM])?)\s*[-–—]\s*(\$?\s*[\d,.]+(?:\s*[kKmM])?)",
        raw,
    )
    if range_match:
        low_amt = parse_money_amount(range_match.group(1))
        high_amt = parse_money_amount(range_match.group(2))
        if low_amt > 0 and high_amt > 0:
            if low_amt > high_amt:
                low_amt, high_amt = high_amt, low_amt
            if not salary_range_plausible("base", low_amt, high_amt, title=title):
                return ""
            return f"{compact_money_label(low_amt)}\u2013{compact_money_label(high_amt)}"
    amounts = _SALARY_BADGE_AMOUNT_RE.findall(raw)
    if not amounts:
        return raw if len(raw) <= 14 else ""
    parts: list[str] = []
    for num, suffix, plus in amounts[:2]:
        num = num.replace(",", "")
        piece = f"${num}{suffix.upper()}" if suffix else f"${num}"
        if plus:
            piece += "+"
        parts.append(piece)
    if len(parts) >= 2:
        low_amt = parse_money_amount(parts[0])
        high_amt = parse_money_amount(parts[1])
        if low_amt > 0 and high_amt > 0 and low_amt > high_amt:
            parts[0], parts[1] = parts[1], parts[0]
        return f"{parts[0]}\u2013{parts[1]}"
    return parts[0]


def salary_amounts_from_label(label: str) -> tuple[int, int] | None:
    """Parse annual low/high amounts from a salary_label or badge string."""
    raw = str(label or "").strip()
    if not raw:
        return None
    range_match = re.search(
        r"(\$?\s*[\d,.]+(?:\s*[kKmM])?)\s*[-–—]\s*(\$?\s*[\d,.]+(?:\s*[kKmM])?)",
        raw,
    )
    if range_match:
        low_amt = parse_money_amount(range_match.group(1))
        high_amt = parse_money_amount(range_match.group(2))
        if low_amt > 0 and high_amt > 0:
            if low_amt > high_amt:
                low_amt, high_amt = high_amt, low_amt
            return low_amt, high_amt
    amounts = _SALARY_BADGE_AMOUNT_RE.findall(raw)
    if not amounts:
        return None
    vals: list[int] = []
    for num, suffix, _plus in amounts[:2]:
        num = num.replace(",", "")
        piece = f"${num}{suffix}" if suffix else f"${num}"
        amt = parse_money_amount(piece)
        if amt > 0:
            vals.append(amt)
    if not vals:
        return None
    if len(vals) == 1:
        return vals[0], vals[0]
    low_amt, high_amt = vals[0], vals[1]
    if low_amt > high_amt:
        low_amt, high_amt = high_amt, low_amt
    return low_amt, high_amt


def reconcile_job_salary_status(job: Job, cfg: dict[str, Any]) -> None:
    """Align job.salary with parsed label amounts and the profile salary floor."""
    amounts = salary_amounts_from_label(job.salary_label or "")
    if not amounts:
        return
    low, high = amounts
    status, _label = salary_range_status("base", low, high, cfg)
    if status == "low":
        job.salary = "low"
    elif status == "ok":
        job.salary = "ok"
    elif job.salary != "ok":
        job.salary = "maybe"


def salary_label_is_estimate(label: str) -> bool:
    """True when salary_label is a crowd/config estimate (not JD or DOL LCA)."""
    raw = str(label or "")
    if not raw:
        return False
    if re.search(r"DOL\s+LCA", raw, re.I):
        return False
    return bool(
        re.search(r"[·•]\s*est\.|Levels\.fyi|Levels\s+est\.", raw, re.I)
    )


def salary_badge_visible_label(job: Job, cfg: dict[str, Any] | None = None) -> str:
    """Dollar text shown on the salary badge; keeps a visible · est. for estimates."""
    cfg = cfg or {}
    if job.salary == "low":
        floor_label = salary_floor_label(cfg)
        if salary_label_is_estimate(job.salary_label or ""):
            compact = compact_salary_badge_label(job.salary_label or "", title=job.title)
            if compact:
                return f"{compact} · est."
        label = compact_salary_badge_label(job.salary_label or f"Below {floor_label}")
        return label or f"Below {floor_label}"
    default_label = ""
    if job.salary == "ok":
        default_label = compact_salary_badge_label(f"{salary_floor_label(cfg)}+")
    label = compact_salary_badge_label(job.salary_label or default_label, title=job.title)
    if not label:
        return ""
    if salary_label_is_estimate(job.salary_label or "") and "est." not in label.lower():
        return f"{label} · est."
    return label


def badge_salary(job: Job, cfg: dict[str, Any] | None = None) -> str:
    cfg = cfg or {}
    label = salary_badge_visible_label(job, cfg)
    if not label:
        return ""
    if job.salary == "low":
        return f'<span class="badge badge-salary-low">{esc(label)}</span>'
    cls = "badge-salary-ok" if job.salary == "ok" else "badge-salary-maybe"
    title_attr = ""
    full = str(job.salary_label or "").strip()
    if full and full != label:
        title_attr = f' title="{esc(full)}"'
    return f'<span class="badge {cls}"{title_attr}>{esc(label)}</span>'


def badge_slot(content: str) -> str:
    if content:
        return content
    return '<span class="badge-slot" aria-hidden="true"></span>'


def normalize_job_url(url: str) -> str:
    raw = str(url or "").strip()
    if not raw:
        return raw
    # Bullhorn career-portal SPA: identity lives in the hash (#/jobs/12345).
    bullhorn_hash = re.search(r"(#/jobs/\d+)\s*$", raw, re.I)
    text = raw.split("#")[0]
    if not text:
        return raw
    if _job_url_keep_query_string(text):
        normalized = text.rstrip("/")
    else:
        normalized = text.split("?")[0].rstrip("/")
    if bullhorn_hash:
        if not normalized.endswith("/"):
            normalized = f"{normalized}/"
        return f"{normalized}{bullhorn_hash.group(1)}"
    nike_key = nike_canonical_apply_key(normalized)
    if nike_key:
        return nike_key
    cisco_key = cisco_canonical_apply_key(normalized)
    if cisco_key:
        return cisco_key
    return normalized


def job_apply_key(job: Job) -> str:
    if job.url:
        return normalize_job_url(job.url)
    if job.job_id:
        rid = str(job.job_id).strip().upper()
        if rid.startswith("R-") and job.company_id in NIKE_COMPANY_IDS:
            return nike_canonical_apply_url(rid)
        if rid.isdigit() and len(rid) >= 6 and job.company_id in CISCO_COMPANY_IDS:
            return cisco_canonical_apply_url(rid)
        return f"{job.company_id}:{job.job_id}"
    return f"{job.company_id}:{job.title}"


def normalize_run_state_urls(urls: Iterable[str]) -> list[str]:
    """Collapse URL variants in scrape novelty state (Nike/Cisco Workday vs careers)."""
    normalized: set[str] = set()
    for raw in urls:
        text = str(raw or "").strip()
        if not text:
            continue
        normalized.add(normalize_job_url(text))
    return sorted(normalized)


def prev_urls_from_run_state(state: dict[str, Any] | None) -> set[str]:
    if not state:
        return set()
    urls = state.get("urls")
    if not isinstance(urls, list):
        return set()
    return set(normalize_run_state_urls(urls))


def company_names_by_id(cfg: dict[str, Any]) -> dict[str, str]:
    return {str(c["id"]): str(c.get("name", c["id"])) for c in cfg.get("companies", [])}


def job_to_pipeline_meta(job: Job, co: CompanyResult | None, cfg: dict[str, Any]) -> dict[str, str]:
    names = company_names_by_id(cfg)
    co_name = co.name if co else names.get(job.company_id, job.company_id)
    meta: dict[str, str] = {
        "title": job.title,
        "company_id": job.company_id,
        "company_name": job.company_name or co_name,
        "match": job.match,
        "loc": job.loc,
        "salary": job.salary,
        "employment": job.employment or "full-time",
    }
    if job.salary_label:
        meta["salary_label"] = job.salary_label
    if job.meta:
        meta["meta"] = job.meta
    if job.why:
        meta["why"] = job.why
    return meta


def resolve_orphan_pipeline_meta(key: str, cfg: dict[str, Any]) -> dict[str, str] | None:
    names = company_names_by_id(cfg)
    match = re.search(r"/careers/job/(\d+)(?:/|$|\?)", key)
    if match and "netflix" in key:
        pos = netflix_fetch_position(match.group(1))
        if pos:
            title = str(pos.get("name") or pos.get("posting_name") or "Netflix role")
            return {
                "title": title,
                "company_id": "netflix",
                "company_name": names.get("netflix", "Netflix"),
                "match": "good",
                "loc": "remote",
                "salary": "ok",
                "employment": "full-time",
                "meta": str(pos.get("location") or ""),
            }
    return None


def enrich_pipeline_store(
    pipeline: dict[str, dict[str, str]],
    results: list[CompanyResult],
    cfg: dict[str, Any],
) -> None:
    live: dict[str, tuple[CompanyResult, Job]] = {}
    for co in results:
        for job in co.jobs:
            live[job_apply_key(job)] = (co, job)
    names = company_names_by_id(cfg)
    for key, entry in pipeline.items():
        if key in live:
            co, job = live[key]
            apply_company_result_job_fields(co, job)
            entry.update(job_to_pipeline_meta(job, co, cfg))
        else:
            if not entry.get("title"):
                resolved = resolve_orphan_pipeline_meta(key, cfg)
                if resolved:
                    entry.update(resolved)
            cid = entry.get("company_id") or ""
            if cid and not entry.get("company_name"):
                entry["company_name"] = names.get(cid, cid)


def pipeline_entry_to_job(key: str, entry: dict[str, str], cfg: dict[str, Any]) -> Job:
    names = company_names_by_id(cfg)
    title = entry.get("title") or "Unknown role"
    company_id = entry.get("company_id") or "applied"
    company_name = entry.get("company_name") or names.get(company_id, company_id)
    url: str | None = key if key.startswith("http") else None
    meta = entry.get("meta") or "Removed from live listings · kept in pipeline history"
    return Job(
        title=title,
        company_id=company_id,
        company_name=company_name,
        url=url,
        applied=True,
        pipeline_status=str(entry.get("status") or "applied"),
        pipeline_at=str(entry.get("at") or ""),
        pipeline_applied_at=str(entry.get("applied_at") or entry.get("at") or ""),
        match=entry.get("match") or "good",
        loc=entry.get("loc") or "remote",
        salary=entry.get("salary") or "ok",
        salary_label=entry.get("salary_label") or None,
        employment=entry.get("employment") or "full-time",
        meta=meta,
        why=entry.get("why") or "",
    )


def pipeline_is_terminal(status: str) -> bool:
    return status in PIPELINE_TERMINAL


def mark_jobs_pipeline(results: list[CompanyResult], pipeline: dict[str, dict[str, str]]) -> None:
    for co in results:
        for job in co.jobs:
            key = job_apply_key(job)
            entry = pipeline.get(key, {})
            status = str(entry.get("status") or "")
            job.pipeline_status = status
            job.pipeline_at = str(entry.get("at") or "")
            job.pipeline_applied_at = str(entry.get("applied_at") or "")
            job.applied = pipeline_is_terminal(status)


def collect_applied_history_jobs(
    results: list[CompanyResult],
    pipeline: dict[str, dict[str, str]],
    cfg: dict[str, Any],
) -> list[Job]:
    """Permanent application log — every job with applied_at, including removed listings."""
    collected: list[Job] = []
    live: dict[str, tuple[CompanyResult, Job]] = {}
    for co in results:
        for job in co.jobs:
            live[job_apply_key(job)] = (co, job)

    for key in sorted(pipeline):
        entry = pipeline[key]
        applied_at = str(entry.get("applied_at") or "").strip()
        if not applied_at:
            continue
        status = str(entry.get("status") or "")
        if key in live:
            co, job = live[key]
            apply_company_result_job_fields(co, job)
            job.pipeline_status = status
            job.pipeline_at = str(entry.get("at") or "")
            job.pipeline_applied_at = applied_at
            job.applied = pipeline_is_terminal(status)
            collected.append(job)
        else:
            job = pipeline_entry_to_job(key, entry, cfg)
            job.pipeline_applied_at = applied_at
            collected.append(job)

    return sorted(
        collected,
        key=lambda j: (j.pipeline_applied_at or "", j.pipeline_at or ""),
        reverse=True,
    )


PRIMARY_BOARD_SECTIONS = frozenset({"matching", "international", "aggregated", "local"})
EMPTY_STUB_SUBSECTION = "No matches today (browse careers)"
# Lower wins when the same posting URL appears under multiple company configs.
_CROSS_COMPANY_SECTION_RANK = {
    "matching": 0,
    "international": 1,
    "local": 2,
    "aggregated": 3,
    "hubs": 4,
}


def _company_claim_priority(
    company_id: str,
    cfg_by_id: dict[str, dict[str, Any]],
    company_order: list[str],
) -> tuple[int, int]:
    company = cfg_by_id.get(company_id) or {}
    section = str(company.get("section") or "matching").lower()
    sec_rank = _CROSS_COMPANY_SECTION_RANK.get(section, 9)
    try:
        order_rank = company_order.index(company_id)
    except ValueError:
        order_rank = 999_999
    return sec_rank, order_rank


def dedupe_jobs_across_companies(
    results: list[CompanyResult],
    company_list: list[dict[str, Any]],
) -> int:
    """Keep each apply key on one company — prefer matching over hub duplicates."""
    cfg_by_id = {
        str(company.get("id") or ""): company
        for company in company_list
        if company.get("id")
    }
    company_order = [str(company.get("id") or "") for company in company_list if company.get("id")]
    winner: dict[str, str] = {}
    winner_pri: dict[str, tuple[int, int]] = {}
    for co in results:
        pri = _company_claim_priority(co.id, cfg_by_id, company_order)
        for job in co.jobs:
            key = job_apply_key(job)
            if key not in winner:
                winner[key] = co.id
                winner_pri[key] = pri
                continue
            nike_pick = _nike_family_dedupe_winner(winner[key], co.id)
            if nike_pick:
                winner[key] = nike_pick
                winner_pri[key] = _company_claim_priority(
                    nike_pick, cfg_by_id, company_order
                )
                continue
            cisco_pick = _cisco_family_dedupe_winner(winner[key], co.id)
            if cisco_pick:
                winner[key] = cisco_pick
                winner_pri[key] = _company_claim_priority(
                    cisco_pick, cfg_by_id, company_order
                )
                continue
            if pri < winner_pri[key]:
                winner[key] = co.id
                winner_pri[key] = pri
    removed = 0
    for co in results:
        kept: list[Job] = []
        for job in co.jobs:
            key = job_apply_key(job)
            if winner.get(key) == co.id:
                kept.append(job)
            else:
                removed += 1
        co.jobs = kept
    return removed
# Sidebar scrape dots use this set so counts match default board filters (Stretch is off in HTML).
SIDEBAR_DEFAULT_MATCH_LEVELS = frozenset({"strong", "good"})


def active_jobs_for_primary_sections(co: CompanyResult) -> list[Job]:
    return [job for job in sort_jobs(co.jobs) if job_is_active_in_sections(job) and job.loc != "excluded" and job.salary != "low"]


def active_jobs_for_sidebar_dot(co: CompanyResult) -> list[Job]:
    """Jobs visible with default Strong+Good match filters (Stretch unchecked)."""
    return [job for job in active_jobs_for_primary_sections(co) if job.match in SIDEBAR_DEFAULT_MATCH_LEVELS]


def active_job_match_counts(co: CompanyResult) -> dict[str, int]:
    """Primary-board jobs by match tier (sidebar dots — excludes Applied / Show Hidden)."""
    counts = {"strong": 0, "good": 0, "stretch": 0}
    seen_keys: set[str] = set()
    for job in active_jobs_for_primary_sections(co):
        key = job_apply_key(job)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        tier = job.match if job.match in counts else "stretch"
        counts[tier] += 1
    return counts


def board_ui_prefs(cfg: dict[str, Any]) -> dict[str, bool]:
    """Sidebar / empty-entry display toggles (profile.board_ui overrides)."""
    profile = cfg.get("profile") if isinstance(cfg.get("profile"), dict) else {}
    ui = cfg.get("board_ui") if isinstance(cfg.get("board_ui"), dict) else {}
    if isinstance(profile.get("board_ui"), dict):
        ui = {**ui, **profile["board_ui"]}
    return {
        "hide_zero_yield_sidebar": bool(ui.get("hide_zero_yield_sidebar", True)),
        "hide_empty_stub_entries": bool(ui.get("hide_empty_stub_entries", True)),
    }


def include_company_in_sidebar(co: CompanyResult | None, *, hide_zero_yield: bool) -> bool:
    """Job Sources lists employers with primary-board cards — omit zero-yield and excluded-only.

    Excluded/pass jobs live under Show Hidden; including them here inflated the source
    count (hundreds of blank-dot rows) while listing cards stayed at the primary set.
    """
    if not hide_zero_yield:
        return True
    if co is None:
        return False
    return bool(active_jobs_for_primary_sections(co))


def collect_empty_stub_companies(
    results: list[CompanyResult], *, hide_empty_stub_entries: bool = False
) -> list[CompanyResult]:
    """Employers with no live cards in primary sections — shown only under Show entries."""
    if hide_empty_stub_entries:
        return []
    stubs: list[CompanyResult] = []
    for co in results:
        if co.section not in PRIMARY_BOARD_SECTIONS:
            continue
        if company_result_is_hub_link(co):
            continue
        if co.jobs:
            continue
        if active_jobs_for_primary_sections(co):
            continue
        stubs.append(co)
    return sorted(stubs, key=lambda c: (c.label or c.name).lower())


def render_empty_stub_blocks(
    stubs: list[CompanyResult],
    verified: str,
    local_badge: str,
    cfg: dict[str, Any],
) -> list[str]:
    if not stubs:
        return []
    lines = [
        '      <h3 class="company-group" style="margin-top:0;color:var(--muted)" '
        'data-subsection-header="empty-stub">'
        f"{EMPTY_STUB_SUBSECTION}</h3>",
        "      <p class=\"meta\">Automated search found no matching roles (filters, unavailable "
        "Workday API, or browse-only). Expand each employer for status and careers link.</p>",
        "",
    ]
    for co in stubs:
        lines.extend(render_company_block(co, verified, local_badge, cfg, show_empty=True))
    return lines


def active_jobs_for_excluded_section(co: CompanyResult) -> list[Job]:
    return [
        job
        for job in sort_jobs(co.jobs)
        if job_is_active_in_sections(job)
        and job.pipeline_status != "pass"
        and (job.loc == "excluded" or job.salary == "low")
    ]


def collect_pass_company_results(
    results: list[CompanyResult],
    pipeline: dict[str, dict[str, str]],
    cfg: dict[str, Any],
) -> list[CompanyResult]:
    """Jobs marked Pass — collapsed in the excluded panel with filtered entries."""
    company_meta: dict[str, tuple[str, str, bool, str | None, list[dict[str, str]], str]] = {}
    for co in results:
        company_meta[co.id] = (
            co.name,
            co.label,
            co.layoff_prone,
            co.browse_url,
            list(co.footer_links),
            co.search_note,
        )
    by_company: dict[str, list[Job]] = {}
    seen_keys: set[str] = set()

    for co in results:
        for job in co.jobs:
            if job.pipeline_status != "pass":
                continue
            key = job_apply_key(job)
            seen_keys.add(key)
            apply_company_result_job_fields(co, job)
            by_company.setdefault(co.id, []).append(job)

    for key, entry in pipeline.items():
        if str(entry.get("status") or "") != "pass":
            continue
        if key in seen_keys:
            continue
        job = pipeline_entry_to_job(key, entry, cfg)
        cid = job.company_id or "unknown"
        by_company.setdefault(cid, []).append(job)

    pass_results: list[CompanyResult] = []
    for cid in sorted(by_company.keys()):
        jobs = sort_jobs(by_company[cid])
        if not jobs:
            continue
        meta = company_meta.get(cid)
        if meta:
            name, label, layoff, browse, footer, search_note = meta
        else:
            name = jobs[0].company_name or cid
            label = name
            layoff = jobs[0].layoff_prone
            browse = None
            footer = []
            search_note = ""
        pass_results.append(
            CompanyResult(
                id=cid,
                name=name,
                label=label,
                section="excluded",
                jobs=jobs,
                browse_url=browse,
                footer_links=footer,
                subsection="Hidden / not interested",
                subsection_warn=False,
                search_note=search_note,
                layoff_prone=layoff,
            )
        )
    return pass_results

def excluded_subsection_labels(jobs: list[Job], cfg: dict[str, Any]) -> tuple[str, bool]:
    has_loc_excluded = any(job.loc == "excluded" for job in jobs)
    has_low_salary = any(job.salary == "low" for job in jobs)
    if has_low_salary and not has_loc_excluded:
        return f"Below {salary_floor_label(cfg)} base or other", False
    if has_loc_excluded and not has_low_salary:
        return "Location-bound / too far", True
    return f"Below {salary_floor_label(cfg)} / location-bound", True


def collect_excluded_company_results(results: list[CompanyResult], cfg: dict[str, Any]) -> list[CompanyResult]:
    excluded_results: list[CompanyResult] = []
    cfg_by_id = {
        str(c["id"]): c
        for c in cfg.get("companies", [])
        if isinstance(c, dict) and c.get("id")
    }
    for co in results:
        layout_sec = board_layout_section(co, cfg_by_id.get(co.id))
        if layout_sec == "hubs":
            continue
        if co.section == "excluded":
            jobs = [job for job in sort_jobs(co.jobs) if job_is_active_in_sections(job)]
            subsection = co.subsection
            subsection_warn = co.subsection_warn
        else:
            jobs = active_jobs_for_excluded_section(co)
            if not jobs:
                continue
            subsection, subsection_warn = excluded_subsection_labels(jobs, cfg)
        if not jobs:
            continue
        excluded_results.append(
            CompanyResult(
                id=co.id,
                name=co.name,
                label=co.label,
                section="excluded",
                jobs=jobs,
                browse_url=co.browse_url,
                footer_links=list(co.footer_links),
                subsection=subsection,
                subsection_warn=subsection_warn,
                search_note=co.search_note,
                layoff_prone=co.layoff_prone,
            )
        )
    return excluded_results


def render_pipeline_section(
    applied_jobs: list[Job],
    results: list[CompanyResult],
    local_badge: str,
    cfg: dict[str, Any],
    lazy: LazyBoardCollector | None = None,
) -> list[str]:
    """Flat Applied list sorted by applied date (newest first) — no company headers."""
    results_by_id = {co.id: co for co in results}
    company_cfg_by_id = {
        str(c["id"]): c
        for c in cfg.get("companies", [])
        if isinstance(c, dict) and c.get("id")
    }
    # collect_applied_history_jobs already sorts newest-first; keep stable here.
    ordered = sorted(
        applied_jobs,
        key=lambda j: (j.pipeline_applied_at or "", j.pipeline_at or "", j.title or ""),
        reverse=True,
    )
    lines: list[str] = []
    for job in ordered:
        cid = job.company_id or "unknown"
        co = company_result_for_header(cid, [job], results_by_id, company_cfg_by_id, cfg)
        lines.append(
            render_job(job, local_badge, cfg, lazy, pool="applied", company=co)
        )
        lines.append("")
    return lines


def job_is_active_in_sections(job: Job) -> bool:
    return job.pipeline_status in ("", "saved")


def company_best_match_rank(co: CompanyResult) -> int:
    active = active_jobs_for_primary_sections(co) or active_jobs_for_excluded_section(co)
    if not active:
        return len(MATCH_ORDER)
    return min(MATCH_RANK.get(j.match, len(MATCH_ORDER)) for j in active)


def company_newest_posted_ts(co: CompanyResult) -> int:
    active = active_jobs_for_primary_sections(co) or active_jobs_for_excluded_section(co)
    if not active:
        return 0
    return max(j.posted_ts or 0 for j in active)


def sort_companies_for_section(companies: list[CompanyResult], section: str) -> list[CompanyResult]:
    """Alphabetical by company display name in primary job sections."""
    if section not in ("matching", "international", "aggregated", "local"):
        return companies
    return sorted(
        companies,
        key=lambda co: (company_header_display_name(co) or co.name).lower(),
    )


def job_salary_amounts(job: Job) -> tuple[int, int]:
    """Annual low/high salary in dollars from the posting label (0, 0 when unknown)."""
    amounts = salary_amounts_from_label(job.salary_label or "")
    if amounts:
        return amounts
    return 0, 0


def job_salary_high_end(job: Job) -> int:
    """High end of the salary range in annual dollars (0 when unknown)."""
    return job_salary_amounts(job)[1]


def company_best_salary_rank(co: CompanyResult) -> int:
    """Best high-end salary among active jobs; used for company-group salary sort."""
    active = (
        active_jobs_for_primary_sections(co)
        or active_jobs_for_excluded_section(co)
        or co.jobs
    )
    best = 0
    for job in active:
        best = max(best, job_salary_high_end(job))
    return best


def company_glassdoor_rating_value(co: CompanyResult, cfg: dict[str, Any]) -> float:
    gd = _company_glassdoor_meta_for_header(co, cfg)
    raw = str(gd.get("glassdoor_rating") or "").strip()
    if not raw:
        return -1.0
    try:
        return float(raw.split()[0])
    except ValueError:
        return -1.0


def company_group_sort_attrs(co: CompanyResult, cfg: dict[str, Any]) -> str:
    display = company_header_display_name(co) or co.name
    return (
        f' data-company-name="{esc(display.lower())}"'
        f' data-newest-posted="{company_newest_posted_ts(co)}"'
        f' data-glassdoor-rating="{company_glassdoor_rating_value(co, cfg)}"'
        f' data-best-salary="{company_best_salary_rank(co)}"'
    )


def company_filter_key(name: str) -> str:
    cleaned = re.sub(r"[^a-z0-9]+", "-", (name or "").lower()).strip("-")
    return cleaned or "unknown"


def job_company_filter_key(
    job: Job,
    company: CompanyResult | None = None,
    *,
    cfg: dict[str, Any] | None = None,
) -> str:
    """Canonical sidebar / lazy-index key for a job — must match checklist checkboxes."""
    if company is not None:
        name = str(company.name or company.label or company.id or "").strip()
        if name:
            return company_filter_key(name)
    if cfg:
        cid = str(job.company_id or "").strip()
        if cid:
            config_name = company_names_by_id(cfg).get(cid)
            if config_name:
                return company_filter_key(config_name)
    return company_filter_key(job.company_name or job.company_id or "unknown")


